#[cfg(target_arch = "aarch64")]
#[test]
fn native_el0_oracle_captures_scratch_memory_writes() {
    if !native_host_caps().has("sve") {
        eprintln!("[arm_diff] native EL0 oracle requires SVE signal-frame support -> skipping");
        return;
    }

    let path = native_oracle_path().expect("native EL0 oracle must build on aarch64 hosts");
    let oracle = OracleRunner::Native(path);
    let mut st = ArmState::zeroed();
    st.x[1] = 0x0123_4567_89ab_cdef;
    st.x[2] = SCRATCH_BASE;
    let outs = run_oracle(&oracle, &[(0xf900_0041, NOP, st)])
        .expect("native EL0 oracle scratch store run");
    assert_eq!(outs.len(), 1);
    assert_eq!(
        outs[0].valid, 1,
        "native EL0 oracle produced invalid store output"
    );
    assert_eq!(
        outs[0].trapped, 0,
        "native EL0 oracle trapped on scratch store"
    );
    assert_eq!(
        outs[0].st.scratch[8], 0x0123_4567_89ab_cdef,
        "native EL0 oracle did not capture scratch store"
    );
}

#[cfg(target_arch = "aarch64")]
#[test]
fn native_el0_oracle_captures_fpsimd_and_fp_status() {
    if !native_host_caps().has("fp") {
        eprintln!("[arm_diff] native EL0 oracle requires FP/SIMD support -> skipping");
        return;
    }

    let path = native_oracle_path().expect("native EL0 oracle must build on aarch64 hosts");
    let oracle = OracleRunner::Native(path);
    let mut st = ArmState::zeroed();
    st.set_vreg(1, (2.5_f64).to_bits(), 0);
    st.set_vreg(2, (4.0_f64).to_bits(), 0);
    st.fpcr = 0x00c0_0000;
    st.fpsr = 0x0800_0000;
    let outs = run_oracle3(
        &oracle,
        &[(
            0x1e62_2820, // fadd d0, d1, d2
            0xd53b_4403, // mrs  x3, fpcr
            0xd53b_4424, // mrs  x4, fpsr
            st,
        )],
    )
    .expect("native EL0 oracle FP/SIMD run");
    assert_eq!(outs.len(), 1);
    assert_eq!(
        outs[0].valid, 1,
        "native EL0 oracle produced invalid FP output"
    );
    assert_eq!(outs[0].trapped, 0, "native EL0 oracle trapped on FADD");
    assert_eq!(
        outs[0].st.vreg(0).0,
        (6.5_f64).to_bits(),
        "native EL0 oracle did not capture V0 after FADD"
    );
    assert_eq!(
        outs[0].st.x[3] as u32, 0x00c0_0000,
        "native EL0 oracle MRS FPCR"
    );
    assert_eq!(
        outs[0].st.x[4] as u32, 0x0800_0000,
        "native EL0 oracle MRS FPSR"
    );
    assert_eq!(
        outs[0].st.fpcr as u32, 0x00c0_0000,
        "native EL0 oracle captured FPCR"
    );
    assert_eq!(
        outs[0].st.fpsr as u32, 0x0800_0000,
        "native EL0 oracle captured FPSR"
    );
}

#[cfg(target_arch = "aarch64")]
#[test]
fn native_el0_oracle_executes_control_flow_slots() {
    if !native_host_caps().has("sve") {
        eprintln!("[arm_diff] native EL0 oracle requires SVE signal-frame support -> skipping");
        return;
    }

    let path = native_oracle_path().expect("native EL0 oracle must build on aarch64 hosts");
    let oracle = OracleRunner::Native(path);
    let mut eq = ArmState::zeroed();
    eq.x[1] = 7;
    eq.x[2] = 7;
    let mut ne = ArmState::zeroed();
    ne.x[1] = 9;
    ne.x[2] = 7;
    let outs = run_oracle3(
        &oracle,
        &[
            (
                0xeb02_003f, // cmp  x1, x2
                0x5400_0040, // b.eq +8, to the oracle's capture brk
                0xd280_0220, // mov  x0, #17
                eq,
            ),
            (
                0xeb02_003f, // cmp  x1, x2
                0x5400_0040, // b.eq +8, to the oracle's capture brk
                0xd280_0220, // mov  x0, #17
                ne,
            ),
        ],
    )
    .expect("native EL0 oracle control-flow run");
    assert_eq!(outs.len(), 2);
    assert_eq!(
        outs[0].valid, 1,
        "native EL0 oracle produced invalid taken output"
    );
    assert_eq!(
        outs[0].trapped, 0,
        "native EL0 oracle trapped on taken branch"
    );
    assert_eq!(
        outs[0].st.x[0], 0,
        "native EL0 oracle failed to skip slot on taken branch"
    );
    assert_eq!(
        outs[1].valid, 1,
        "native EL0 oracle produced invalid fallthrough output"
    );
    assert_eq!(
        outs[1].trapped, 0,
        "native EL0 oracle trapped on fallthrough branch"
    );
    assert_eq!(
        outs[1].st.x[0], 17,
        "native EL0 oracle failed to execute fallthrough slot"
    );
}

#[derive(Debug)]
struct HostCaps {
    flags: std::collections::BTreeSet<String>,
}

impl HostCaps {
    fn current() -> Self {
        let mut flags = std::collections::BTreeSet::new();
        if let Ok(cpuinfo) = std::fs::read_to_string("/proc/cpuinfo") {
            for line in cpuinfo.lines() {
                let Some((name, value)) = line.split_once(':') else {
                    continue;
                };
                if matches!(name.trim(), "Features" | "flags") {
                    flags.extend(value.split_whitespace().map(|s| s.to_ascii_lowercase()));
                }
            }
        }
        HostCaps { flags }
    }

    fn has(&self, flag: &str) -> bool {
        self.flags.contains(flag)
    }
}

fn native_host_caps() -> &'static HostCaps {
    static CAPS: std::sync::OnceLock<HostCaps> = std::sync::OnceLock::new();
    CAPS.get_or_init(HostCaps::current)
}

fn native_hardware_lacks_label(oracle: &OracleRunner, label: &str) -> bool {
    if !oracle.is_native() {
        return false;
    }
    let caps = native_host_caps();
    let mnemonic = label
        .split_whitespace()
        .next()
        .unwrap_or(label)
        .to_ascii_lowercase();
    let mnemonic_base = mnemonic.split('.').next().unwrap_or(&mnemonic);

    if mnemonic_base.starts_with("sm3") {
        return !caps.has("sm3");
    }
    if mnemonic_base.starts_with("sm4") {
        return !caps.has("sm4");
    }
    if mnemonic_base.starts_with("sha512") {
        return !caps.has("sha512");
    }
    if matches!(mnemonic_base, "eor3" | "bcax" | "xar" | "sha3_rax1") {
        return !caps.has("sha3");
    }
    if mnemonic_base == "fjcvtzs" {
        return !caps.has("jscvt");
    }
    if matches!(
        mnemonic_base,
        "subp" | "subps" | "irg" | "gmi" | "ldg" | "stg" | "stzg" | "st2g" | "stz2g" | "stgp"
    ) {
        return !caps.has("mte");
    }
    if mnemonic_base.starts_with("fmmla") {
        return !(caps.has("f32mm") || caps.has("svef32mm"));
    }
    if matches!(
        mnemonic_base,
        "cfinv" | "xaflag" | "axflag" | "rmif" | "setf8" | "setf16"
    ) {
        return !caps.has("flagm");
    }
    if mnemonic_base == "dit" {
        return !caps.has("dit");
    }
    if mnemonic_base == "cpuid" {
        return !caps.has("cpuid");
    }
    if mnemonic_base.starts_with("dc_cvap") {
        return !caps.has("dcpop");
    }
    if mnemonic_base.starts_with("dc_cvadp") {
        return !caps.has("dcpodp");
    }
    if mnemonic_base == "uscat" {
        return !caps.has("uscat");
    }
    if mnemonic_base == "sb" {
        return !caps.has("sb");
    }
    if mnemonic_base == "dgh" {
        return !caps.has("dgh");
    }
    if matches!(mnemonic_base, "wfet" | "wfit") {
        return !caps.has("wfxt");
    }
    if matches!(mnemonic_base, "ldapr" | "ldaprb" | "ldaprh") {
        return !caps.has("lrcpc");
    }
    if matches!(mnemonic_base, "ldtp" | "sttp" | "ldtnp" | "sttnp") {
        return !caps.has("lrcpc3");
    }
    if matches!(
        mnemonic_base,
        "ldlar" | "ldlarb" | "ldlarh" | "stllr" | "stllrb" | "stllrh"
    ) {
        return !caps.has("lor");
    }
    if mnemonic_base.contains("cntpctss") || mnemonic_base.contains("cntvctss") {
        return !caps.has("ecv");
    }

    let sve2p1 = [
        "addqv", "andqv", "eorqv", "orqv", "smaxqv", "sminqv", "umaxqv", "uminqv", "faddqv",
        "fmaxqv", "fminqv", "fmaxnmqv", "fminnmqv", "dupq", "extq", "revd", "tblq", "tbxq",
        "uzpq1", "uzpq2", "zipq1", "zipq2", "pext", "pmov", "psel", "sqcvtn", "sqcvtun", "uqcvtn",
    ];
    if sve2p1.iter().any(|m| mnemonic_base == *m) {
        return !caps.has("sve2p1");
    }

    let b16b16 = [
        "bfadd", "bfclamp", "bfmax", "bfmaxnm", "bfmin", "bfminnm", "bfmla", "bfmls", "bfmlslb",
        "bfmlslt", "bfmul", "bfsub", "fdot",
    ];
    if b16b16.iter().any(|m| mnemonic_base == *m) {
        return !caps.has("sveb16b16");
    }
    if matches!(mnemonic_base, "sdot" | "udot") && label.contains(".h") {
        return !caps.has("sveb16b16");
    }

    let faminmax_or_sve2p1 = ["fclamp", "sclamp", "uclamp"];
    if faminmax_or_sve2p1.iter().any(|m| mnemonic_base == *m) {
        return !(caps.has("faminmax") || caps.has("sve2p1"));
    }

    false
}

fn which(prog: &str) -> Option<PathBuf> {
    let path = std::env::var_os("PATH")?;
    for dir in std::env::split_paths(&path) {
        let cand = dir.join(prog);
        if cand.is_file() {
            return Some(cand);
        }
    }
    None
}

/// Run `cases` through the selected oracle; returns one `OutCase` per input.
fn run_oracle(oracle: &OracleRunner, cases: &[(u32, u32, ArmState)]) -> Option<Vec<OutCase>> {
    let cases3: Vec<(u32, u32, u32, ArmState)> = cases
        .iter()
        .map(|(insn, insn2, st)| (*insn, *insn2, NOP, *st))
        .collect();
    run_oracle3(oracle, &cases3)
}

/// Run three-instruction cases through the selected oracle.
fn run_oracle3(oracle: &OracleRunner, cases: &[(u32, u32, u32, ArmState)]) -> Option<Vec<OutCase>> {
    let cases_reserved: Vec<(u32, u32, u32, u32, ArmState)> = cases
        .iter()
        .map(|(insn, insn2, insn3, st)| (*insn, *insn2, *insn3, 0, *st))
        .collect();
    run_oracle3_reserved(oracle, &cases_reserved)
}

/// Run three-instruction cases through the selected oracle, using the wire
/// format's reserved field for oracle mode flags.
fn run_oracle3_reserved(
    oracle: &OracleRunner,
    cases: &[(u32, u32, u32, u32, ArmState)],
) -> Option<Vec<OutCase>> {
    let mut payload = Vec::with_capacity(8 + cases.len() * std::mem::size_of::<InCase>());
    payload.extend_from_slice(&WIRE_MAGIC.to_le_bytes());
    payload.extend_from_slice(&(cases.len() as u32).to_le_bytes());
    for (insn, insn2, insn3, reserved, st) in cases {
        let ic = InCase {
            insn: *insn,
            flags: *insn2,
            insn3: *insn3,
            reserved: *reserved,
            st: *st,
        };
        payload.extend_from_slice(as_bytes(&ic));
    }

    let mut child = oracle
        .command()
        .stdin(Stdio::piped())
        .stdout(Stdio::piped())
        .stderr(Stdio::null())
        .spawn()
        .ok()?;
    // The oracle interleaves reads and writes, so feeding the whole batch before
    // draining stdout would deadlock once both pipe buffers fill. Write from a
    // dedicated thread while the main thread drains stdout.
    let mut stdin = child.stdin.take().unwrap();
    let writer = std::thread::spawn(move || {
        let _ = stdin.write_all(&payload);
        // drop(stdin) closes the pipe, signalling EOF to the oracle
    });
    let mut out = Vec::new();
    child.stdout.take().unwrap().read_to_end(&mut out).ok()?;
    let _ = writer.join();
    let status = child.wait().ok()?;
    if !status.success() {
        return None;
    }
    if out.len() < 8 {
        return None;
    }
    let magic = u32::from_le_bytes([out[0], out[1], out[2], out[3]]);
    let count = u32::from_le_bytes([out[4], out[5], out[6], out[7]]) as usize;
    if magic != WIRE_MAGIC || count != cases.len() {
        return None;
    }
    let mut res = Vec::with_capacity(count);
    let mut off = 8;
    for _ in 0..count {
        res.push(read_struct::<OutCase>(&out, off));
        off += std::mem::size_of::<OutCase>();
    }
    Some(res)
}

// ---------------------------------------------------------------------------
// rax: run one instruction from an identical initial state.
// ---------------------------------------------------------------------------

/// Returns `Some(out_state)` if rax executed the instruction (CpuExit::Continue),
/// or `None` if rax treated it as undefined / errored.
fn run_rax(insn: u32, input: &ArmState) -> Option<ArmState> {
    run_rax_at_el(insn, input, 1)
}

fn run_rax_el0(insn: u32, input: &ArmState) -> Option<ArmState> {
    run_rax_at_el(insn, input, 0)
}

fn run_rax_at_el(insn: u32, input: &ArmState, initial_el: u8) -> Option<ArmState> {
    run_rax_sequence_at_el(&[insn], input, initial_el)
}

fn run_rax_sequence_at_el(insns: &[u32], input: &ArmState, initial_el: u8) -> Option<ArmState> {
    run_rax_sequence_with_trailing_at_el(insns, &[], input, initial_el)
}

fn run_rax_sequence_with_trailing_at_el(
    insns: &[u32],
    trailing: &[u32],
    input: &ArmState,
    initial_el: u8,
) -> Option<ArmState> {
    // Memory must cover both the instruction (at 0) and the scratch window.
    let mem = FlatMemory::new(0, 0x30_0000);
    let mut config = profile::config();
    config.initial_el = initial_el;
    let mut cpu = AArch64Cpu::new(config, Box::new(mem));

    for i in 0..31u8 {
        cpu.set_gpr(i, input.x[i as usize]);
    }
    cpu.set_current_sp(input.sp);
    let ps = input.pstate;
    cpu.set_nzcv(
        ps & (1 << 31) != 0,
        ps & (1 << 30) != 0,
        ps & (1 << 29) != 0,
        ps & (1 << 28) != 0,
    );
    for r in 0..32u8 {
        let (lo, hi) = input.vreg(r as usize);
        cpu.set_simd_reg(r, lo, hi).ok()?;
    }
    cpu.set_fpcr(input.fpcr as u32).ok()?;
    cpu.set_fpsr(input.fpsr as u32).ok()?;
    for r in 0..16usize {
        cpu.set_sve_pred(r, input.preg(r) as u32);
    }
    cpu.set_sve_ffr(input.ffr() as u32);

    // Install the scratch window at SCRATCH_ADDR.
    let scratch_bytes: Vec<u8> = input.scratch.iter().flat_map(|w| w.to_le_bytes()).collect();
    cpu.write_memory(SCRATCH_ADDR, &scratch_bytes).ok()?;

    for (i, insn) in insns.iter().enumerate() {
        cpu.write_memory((i as u64) * 4, &insn.to_le_bytes()).ok()?;
    }
    for (i, insn) in trailing.iter().enumerate() {
        let slot = insns.len() + i;
        cpu.write_memory((slot as u64) * 4, &insn.to_le_bytes())
            .ok()?;
    }
    cpu.set_pc(0);

    for _ in insns {
        match cpu.step() {
            Ok(CpuExit::Continue) => {}
            _ => return None,
        }
    }

    let mut out = ArmState::zeroed();
    for i in 0..31u8 {
        out.x[i as usize] = cpu.get_gpr(i);
    }
    out.sp = cpu.current_sp();
    out.pc = cpu.get_pc();
    let mut pstate = 0u64;
    if cpu.get_n() {
        pstate |= 1 << 31;
    }
    if cpu.get_z() {
        pstate |= 1 << 30;
    }
    if cpu.get_c() {
        pstate |= 1 << 29;
    }
    if cpu.get_v() {
        pstate |= 1 << 28;
    }
    out.pstate = pstate;
    out.fpcr = cpu.get_fpcr()? as u64;
    out.fpsr = cpu.get_fpsr()? as u64;
    for r in 0..32u8 {
        if let Some((lo, hi)) = cpu.get_simd_reg(r) {
            out.set_vreg(r as usize, lo, hi);
        }
    }
    // Read the scratch window back.
    for (i, w) in out.scratch.iter_mut().enumerate() {
        *w = cpu.mem_read_u64(SCRATCH_ADDR + (i as u64) * 8).ok()?;
    }
    for r in 0..16usize {
        out.set_preg(r, cpu.sve_pred(r) as u16);
    }
    out.set_ffr(cpu.sve_ffr() as u16);
    Some(out)
}

/// Run one instruction and return rax's structured exit. `None` means the
/// interpreter rejected the encoding with an execution error.
fn run_rax_exit(insn: u32, input: &ArmState) -> Option<CpuExit> {
    let mem = FlatMemory::new(0, 0x30_0000);
    let mut cpu = AArch64Cpu::new(profile::config(), Box::new(mem));

    for i in 0..31u8 {
        cpu.set_gpr(i, input.x[i as usize]);
    }
    cpu.set_current_sp(input.sp);
    let ps = input.pstate;
    cpu.set_nzcv(
        ps & (1 << 31) != 0,
        ps & (1 << 30) != 0,
        ps & (1 << 29) != 0,
        ps & (1 << 28) != 0,
    );
    for r in 0..32u8 {
        let (lo, hi) = input.vreg(r as usize);
        cpu.set_simd_reg(r, lo, hi).ok()?;
    }
    cpu.set_fpcr(input.fpcr as u32).ok()?;
    cpu.set_fpsr(input.fpsr as u32).ok()?;
    for r in 0..16usize {
        cpu.set_sve_pred(r, input.preg(r) as u32);
    }
    cpu.set_sve_ffr(input.ffr() as u32);

    cpu.write_memory(0, &insn.to_le_bytes()).ok()?;
    cpu.set_pc(0);
    cpu.step().ok()
}

/// Run one instruction with controlled words at PC+4 and PC+8. This is used
/// for PC-relative literal loads: the oracle executes those words as harmless
/// NOPs after the load, while rax only needs the bytes to be present in memory.
fn run_rax_literal(insn: u32, word1: u32, word2: u32, input: &ArmState) -> Option<ArmState> {
    let mem = FlatMemory::new(0, 0x30_0000);
    let mut cpu = AArch64Cpu::new(profile::config(), Box::new(mem));

    for i in 0..31u8 {
        cpu.set_gpr(i, input.x[i as usize]);
    }
    cpu.set_current_sp(input.sp);
    let ps = input.pstate;
    cpu.set_nzcv(
        ps & (1 << 31) != 0,
        ps & (1 << 30) != 0,
        ps & (1 << 29) != 0,
        ps & (1 << 28) != 0,
    );
    for r in 0..32u8 {
        let (lo, hi) = input.vreg(r as usize);
        cpu.set_simd_reg(r, lo, hi).ok()?;
    }
    cpu.set_fpcr(input.fpcr as u32).ok()?;
    cpu.set_fpsr(input.fpsr as u32).ok()?;
    for r in 0..16usize {
        cpu.set_sve_pred(r, input.preg(r) as u32);
    }
    cpu.set_sve_ffr(input.ffr() as u32);
    let scratch_bytes: Vec<u8> = input.scratch.iter().flat_map(|w| w.to_le_bytes()).collect();
    cpu.write_memory(SCRATCH_ADDR, &scratch_bytes).ok()?;

    cpu.write_memory(0, &insn.to_le_bytes()).ok()?;
    cpu.write_memory(4, &word1.to_le_bytes()).ok()?;
    cpu.write_memory(8, &word2.to_le_bytes()).ok()?;
    cpu.write_memory(12, &NOP.to_le_bytes()).ok()?;
    cpu.write_memory(16, &NOP.to_le_bytes()).ok()?;
    cpu.write_memory(20, &NOP.to_le_bytes()).ok()?;
    cpu.write_memory(24, &NOP.to_le_bytes()).ok()?;
    cpu.write_memory(28, &NOP.to_le_bytes()).ok()?;
    cpu.set_pc(0);
    match cpu.step() {
        Ok(CpuExit::Continue) => {}
        _ => return None,
    }

    let mut out = ArmState::zeroed();
    for i in 0..31u8 {
        out.x[i as usize] = cpu.get_gpr(i);
    }
    out.sp = cpu.current_sp();
    out.pc = cpu.get_pc();
    let mut pstate = 0u64;
    if cpu.get_n() {
        pstate |= 1 << 31;
    }
    if cpu.get_z() {
        pstate |= 1 << 30;
    }
    if cpu.get_c() {
        pstate |= 1 << 29;
    }
    if cpu.get_v() {
        pstate |= 1 << 28;
    }
    out.pstate = pstate;
    out.fpcr = cpu.get_fpcr()? as u64;
    out.fpsr = cpu.get_fpsr()? as u64;
    for r in 0..32u8 {
        if let Some((lo, hi)) = cpu.get_simd_reg(r) {
            out.set_vreg(r as usize, lo, hi);
        }
    }
    for (i, w) in out.scratch.iter_mut().enumerate() {
        *w = cpu.mem_read_u64(SCRATCH_ADDR + (i as u64) * 8).ok()?;
    }
    for r in 0..16usize {
        out.set_preg(r, cpu.sve_pred(r) as u16);
    }
    out.set_ffr(cpu.sve_ffr() as u16);
    Some(out)
}

// ---------------------------------------------------------------------------
// Comparison.
// ---------------------------------------------------------------------------

/// Description of a single divergence between rax and the oracle.
struct Mismatch {
    label: String,
    insn: u32,
    detail: String,
}

#[test]
fn pair_state_diff_reports_sp_and_fp_status() {
    let mut rax = ArmState::zeroed();
    let mut hw = ArmState::zeroed();
    rax.sp = 0x1000;
    hw.sp = 0x2000;
    rax.fpcr = 0x0100_0000;
    hw.fpcr = 0x0200_0000;
    rax.fpsr = 0;
    hw.fpsr = 0x11;

    let diffs = compare_state_diffs(&rax, &hw);
    assert!(diffs.iter().any(|d| d.starts_with("sp:")), "{diffs:?}");
    assert!(diffs.iter().any(|d| d.starts_with("fpcr:")), "{diffs:?}");
    assert!(diffs.iter().any(|d| d.starts_with("fpsr:")), "{diffs:?}");
}

#[test]
fn full_state_mismatch_pushes_pair_detail() {
    let mut rax = ArmState::zeroed();
    let mut hw = ArmState::zeroed();
    rax.sp = 0x1000;
    hw.sp = 0x2000;
    rax.fpcr = 0x0100_0000;
    hw.fpcr = 0x0200_0000;
    rax.fpsr = 0;
    hw.fpsr = 0x11;

    let mut mismatches = Vec::new();
    push_state_mismatch("pair", NOP, &rax, &hw, &mut mismatches);
    assert_eq!(mismatches.len(), 1);
    let detail = &mismatches[0].detail;
    assert!(detail.contains("sp:"), "{detail}");
    assert!(detail.contains("fpcr:"), "{detail}");
    assert!(detail.contains("fpsr:"), "{detail}");
}

#[test]
fn branch_state_diff_reports_pc_and_fp_status() {
    let mut rax = ArmState::zeroed();
    let mut hw = ArmState::zeroed();
    rax.pc = 4;
    hw.pc = 12;
    rax.fpcr = 0x0100_0000;
    hw.fpcr = 0x0200_0000;
    rax.fpsr = 0;
    hw.fpsr = 0x11;

    let diffs = compare_state_diffs_with_pc(&rax, &hw);
    assert!(diffs.iter().any(|d| d.starts_with("pc:")), "{diffs:?}");
    assert!(diffs.iter().any(|d| d.starts_with("fpcr:")), "{diffs:?}");
    assert!(diffs.iter().any(|d| d.starts_with("fpsr:")), "{diffs:?}");
}

fn compare_state_diffs(rax: &ArmState, hw: &ArmState) -> Vec<String> {
    let mut diffs = Vec::new();
    for i in 0..31 {
        if rax.x[i] != hw.x[i] {
            diffs.push(format!("x{i}: rax={:#018x} hw={:#018x}", rax.x[i], hw.x[i]));
        }
    }
    if rax.sp != hw.sp {
        diffs.push(format!("sp: rax={:#018x} hw={:#018x}", rax.sp, hw.sp));
    }
    let rax_nzcv = (rax.pstate >> 28) & 0xF;
    let hw_nzcv = (hw.pstate >> 28) & 0xF;
    if rax_nzcv != hw_nzcv {
        diffs.push(format!("nzcv: rax={:#x} hw={:#x}", rax_nzcv, hw_nzcv));
    }
    if rax.fpcr != hw.fpcr {
        diffs.push(format!("fpcr: rax={:#010x} hw={:#010x}", rax.fpcr, hw.fpcr));
    }
    if rax.fpsr != hw.fpsr {
        diffs.push(format!("fpsr: rax={:#010x} hw={:#010x}", rax.fpsr, hw.fpsr));
    }
    for r in 0..32 {
        let (rlo, rhi) = rax.vreg(r);
        let (hlo, hhi) = hw.vreg(r);
        if (rlo, rhi) != (hlo, hhi) {
            diffs.push(format!(
                "v{r}: rax={:#018x}{:016x} hw={:#018x}{:016x}",
                rhi, rlo, hhi, hlo
            ));
        }
    }
    for i in 0..32 {
        if rax.scratch[i] != hw.scratch[i] {
            diffs.push(format!(
                "scratch[{i}]: rax={:#018x} hw={:#018x}",
                rax.scratch[i], hw.scratch[i]
            ));
        }
    }
    for r in 0..16 {
        if rax.preg(r) != hw.preg(r) {
            diffs.push(format!(
                "p{r}: rax={:#06x} hw={:#06x}",
                rax.preg(r),
                hw.preg(r)
            ));
        }
    }
    if rax.ffr() != hw.ffr() {
        diffs.push(format!("ffr: rax={:#06x} hw={:#06x}", rax.ffr(), hw.ffr()));
    }
    diffs
}

fn compare_state_diffs_with_pc(rax: &ArmState, hw: &ArmState) -> Vec<String> {
    let mut diffs = compare_state_diffs(rax, hw);
    if rax.pc != hw.pc {
        diffs.push(format!("pc: rax={:#x} hw={:#x}", rax.pc, hw.pc));
    }
    diffs
}

fn push_state_mismatch(
    label: &str,
    insn: u32,
    rax: &ArmState,
    hw: &ArmState,
    mismatches: &mut Vec<Mismatch>,
) {
    let diffs = compare_state_diffs(rax, hw);
    if !diffs.is_empty() {
        mismatches.push(Mismatch {
            label: label.into(),
            insn,
            detail: diffs.join("  |  "),
        });
    }
}

/// Compare one case against the complete EL0 architectural state captured by
/// the oracle.
fn compare_case(
    label: &str,
    insn: u32,
    input: &ArmState,
    oracle: &OutCase,
    mismatches: &mut Vec<Mismatch>,
) {
    compare_case_with_runner(label, insn, input, oracle, mismatches, run_rax)
}

fn compare_case_el0(
    label: &str,
    insn: u32,
    input: &ArmState,
    oracle: &OutCase,
    mismatches: &mut Vec<Mismatch>,
) {
    compare_case_with_runner(label, insn, input, oracle, mismatches, run_rax_el0)
}

fn compare_case_with_runner(
    label: &str,
    insn: u32,
    input: &ArmState,
    oracle: &OutCase,
    mismatches: &mut Vec<Mismatch>,
    runner: fn(u32, &ArmState) -> Option<ArmState>,
) {
    let rax = runner(insn, input);
    compare_rax_outcome(label, insn, rax, oracle, mismatches);
}

fn compare_rax_outcome(
    label: &str,
    insn: u32,
    rax: Option<ArmState>,
    oracle: &OutCase,
    mismatches: &mut Vec<Mismatch>,
) {
    // Agreement on legality first.
    if oracle.trapped != 0 {
        if rax.is_some() {
            mismatches.push(Mismatch {
                label: label.into(),
                insn,
                detail: format!(
                    "hw faulted (sig {}) but rax executed the encoding",
                    oracle.trapped
                ),
            });
        }
        return; // both reject -> fine; nothing to value-compare
    }
    let rax = match rax {
        Some(s) => s,
        None => {
            mismatches.push(Mismatch {
                label: label.into(),
                insn,
                detail: "hw executed but rax rejected the encoding (undefined/err)".into(),
            });
            return;
        }
    };

    push_state_mismatch(label, insn, &rax, &oracle.st, mismatches);
}

// ---------------------------------------------------------------------------
// Deterministic pseudo-random input generation.
// ---------------------------------------------------------------------------

struct Rng(u64);
impl Rng {
    fn new(seed: u64) -> Self {
        Rng(seed ^ 0x9e37_79b9_7f4a_7c15)
    }
    fn next(&mut self) -> u64 {
        // xorshift64*
        let mut x = self.0;
        x ^= x >> 12;
        x ^= x << 25;
        x ^= x >> 27;
        self.0 = x;
        x.wrapping_mul(0x2545_F491_4F6C_DD1D)
    }
    /// A value biased toward "interesting" bit patterns.
    fn interesting(&mut self) -> u64 {
        match self.next() % 8 {
            0 => 0,
            1 => u64::MAX,
            2 => 1,
            3 => 0x8000_0000_0000_0000,
            4 => 0x0000_0000_8000_0000,
            5 => self.next() & 0xFF,
            6 => self.next() & 0xFFFF_FFFF,
            _ => self.next(),
        }
    }
}

/// Build a randomised input state. GPRs x1.. and V1.. carry operands; the
/// destination registers are also randomised so unintended clobbers show up.
fn gen_input(rng: &mut Rng) -> ArmState {
    let mut st = ArmState::zeroed();
    for i in 0..31 {
        st.x[i] = rng.interesting();
    }
    st.sp = rng.interesting() & !0xF; // keep 16-aligned-ish; sp not dereferenced
    st.pstate = (rng.next() & 0xF) << 28; // random NZCV
    st.fpcr = 0; // round-to-nearest, no flush -- matches rax default
    st.fpsr = 0;
    for r in 0..32 {
        st.set_vreg(r, rng.interesting(), rng.interesting());
    }
    st
}

// ---------------------------------------------------------------------------
// Instruction family encoders.  Register fields are fixed: Rd=0, Rn=1, Rm=2,
// Ra=3.  Inputs vary the register *values*, exercising the data path.
// ---------------------------------------------------------------------------

const RD: u32 = 0;
const RN: u32 = 1;
const RM: u32 = 2;
const RA: u32 = 3;

/// Advanced SIMD three-same (integer + FP), main encoding:
/// `0 Q U 01110 size 1 Rm opcode 1 Rn Rd`
fn enc_three_same(q: u32, u: u32, size: u32, opcode: u32) -> u32 {
    (q << 30)
        | (u << 29)
        | (0b01110 << 24)
        | (size << 22)
        | (1 << 21)
        | (RM << 16)
        | (opcode << 11)
        | (1 << 10)
        | (RN << 5)
        | RD
}

/// Advanced SIMD three-same-extra: SQRDMLAH/SQRDMLSH.
fn enc_three_same_extra(q: u32, size: u32, lo6: u32) -> u32 {
    (q << 30)
        | (1 << 29)
        | (0b01110 << 24)
        | (size << 22)
        | (RM << 16)
        | (lo6 << 10)
        | (RN << 5)
        | RD
}

fn enc_scalar_three_same_extra(size: u32, lo6: u32) -> u32 {
    (0b01 << 30)
        | (1 << 29)
        | (0b11110 << 24)
        | (size << 22)
        | (RM << 16)
        | (lo6 << 10)
        | (RN << 5)
        | RD
}

/// Advanced SIMD scalar three-same FP: `0 1 U 11110 size 1 Rm opcode 1 Rn Rd`.
fn enc_scalar_three_same(u: u32, size: u32, opcode: u32) -> u32 {
    (1 << 30)
        | (u << 29)
        | (0b11110 << 24)
        | (size << 22)
        | (1 << 21)
        | (RM << 16)
        | (opcode << 11)
        | (1 << 10)
        | (RN << 5)
        | RD
}

/// Build the full list of three-same encodings to test (over-generates; illegal
/// combos are filtered by oracle agreement).
fn three_same_cases() -> Vec<(String, u32)> {
    let mut v = Vec::new();
    for q in 0..2 {
        for u in 0..2 {
            for size in 0..4 {
                // Integer opcodes 0x00..=0x17. FP opcodes (0x18..=0x1F) are
                // exercised separately with NaN-aware comparison.
                for opcode in 0..0b11000u32 {
                    let insn = enc_three_same(q, u, size, opcode);
                    v.push((format!("3same q{q} u{u} sz{size} op{:05b}", opcode), insn));
                }
            }
        }
    }
    v
}

/// Data-processing (2 source): `sf 0 0 11010110 Rm opcode2 Rn Rd`
fn enc_dp2_regs(sf: u32, opcode2: u32, rn: u32, rm: u32, rd: u32) -> u32 {
    (sf << 31)
        | (0b0011010110 << 21)
        | ((rm & 0x1f) << 16)
        | (opcode2 << 10)
        | ((rn & 0x1f) << 5)
        | (rd & 0x1f)
}

fn enc_dp2(sf: u32, opcode2: u32) -> u32 {
    enc_dp2_regs(sf, opcode2, RN, RM, RD)
}

fn enc_crc32_x(castagnoli: bool) -> u32 {
    enc_dp2(1, if castagnoli { 0b010111 } else { 0b010011 })
}

fn dp2_cases() -> Vec<(String, u32)> {
    let mut v = Vec::new();
    // opcode2: 0010=UDIV 0011=SDIV 1000=LSLV 1001=LSRV 1010=ASRV 1011=RORV
    for &op in &[0b0010u32, 0b0011, 0b1000, 0b1001, 0b1010, 0b1011] {
        for sf in 0..2 {
            v.push((format!("dp2 sf{sf} op{:04b}", op), enc_dp2(sf, op)));
        }
    }
    v
}

/// Data-processing (1 source): `sf 1 0 11010110 00000 opcode Rn Rd`
#[cfg(all(feature = "smir-jit", target_arch = "x86_64"))]
fn enc_dp1_regs(sf: u32, opcode: u32, rn: u32, rd: u32) -> u32 {
    (sf << 31) | (0b1011010110 << 21) | (opcode << 10) | (rn << 5) | rd
}

#[cfg(all(feature = "smir-jit", target_arch = "x86_64"))]
fn enc_dp1(sf: u32, opcode: u32) -> u32 {
    enc_dp1_regs(sf, opcode, RN, RD)
}

/// Bitfield: `sf opc 100110 N immr imms Rn Rd`
#[cfg(all(feature = "smir-jit", target_arch = "x86_64"))]
fn enc_bitfield(sf: u32, opc: u32, immr: u32, imms: u32) -> u32 {
    enc_bitfield_rn(sf, opc, immr, imms, RN)
}

#[cfg(all(feature = "smir-jit", target_arch = "x86_64"))]
fn enc_bitfield_rn(sf: u32, opc: u32, immr: u32, imms: u32, rn: u32) -> u32 {
    enc_bitfield_regs(sf, opc, immr, imms, rn, RD)
}

#[cfg(all(feature = "smir-jit", target_arch = "x86_64"))]
fn enc_bitfield_regs(sf: u32, opc: u32, immr: u32, imms: u32, rn: u32, rd: u32) -> u32 {
    (sf << 31)
        | (opc << 29)
        | (0b100110 << 23)
        | (sf << 22)
        | (immr << 16)
        | (imms << 10)
        | (rn << 5)
        | rd
}

/// Logical immediate: `sf opc 100100 N immr imms Rn Rd`
#[cfg(all(feature = "smir-jit", target_arch = "x86_64"))]
fn enc_logical_imm_regs(sf: u32, opc: u32, n: u32, immr: u32, imms: u32, rn: u32, rd: u32) -> u32 {
    (sf << 31)
        | (opc << 29)
        | (0b100100 << 23)
        | (n << 22)
        | (immr << 16)
        | (imms << 10)
        | (rn << 5)
        | rd
}

#[cfg(all(feature = "smir-jit", target_arch = "x86_64"))]
fn enc_logical_imm(sf: u32, opc: u32, n: u32, immr: u32, imms: u32, rn: u32) -> u32 {
    enc_logical_imm_regs(sf, opc, n, immr, imms, rn, RD)
}

#[cfg(all(feature = "smir-jit", target_arch = "x86_64"))]
fn enc_logical_reg_n(sf: u32, opc: u32, n: u32, rd: u32, rn: u32, rm: u32) -> u32 {
    (sf << 31)
        | (opc << 29)
        | (0b01010 << 24)
        | (n << 21)
        | ((rm & 0x1f) << 16)
        | ((rn & 0x1f) << 5)
        | (rd & 0x1f)
}

/// Extract: `sf 00 100111 N 0 Rm imms Rn Rd`
#[cfg(all(feature = "smir-jit", target_arch = "x86_64"))]
fn enc_extract(sf: u32, rn: u32, rm: u32, imms: u32) -> u32 {
    (sf << 31) | (0b100111 << 23) | (sf << 22) | (rm << 16) | (imms << 10) | (rn << 5) | RD
}

/// Data-processing (3 source): `sf 00 11011 op31 Rm o0 Ra Rn Rd`
fn enc_dp3(sf: u32, op31: u32, o0: u32) -> u32 {
    enc_dp3_ra(sf, op31, o0, RA)
}

/// Same, but with an explicit Ra field (SMULH/UMULH require Ra = 31/xzr).
fn enc_dp3_ra(sf: u32, op31: u32, o0: u32, ra: u32) -> u32 {
    enc_dp3_ra_regs(sf, op31, o0, RD, RN, RM, ra)
}

fn enc_dp3_ra_regs(sf: u32, op31: u32, o0: u32, rd: u32, rn: u32, rm: u32, ra: u32) -> u32 {
    (sf << 31)
        | (0b11011 << 24)
        | (op31 << 21)
        | ((rm & 0x1f) << 16)
        | (o0 << 15)
        | ((ra & 0x1f) << 10)
        | ((rn & 0x1f) << 5)
        | (rd & 0x1f)
}

fn dp3_cases() -> Vec<(String, u32)> {
    let mut v = Vec::new();
    // MADD: op31=000 o0=0 ; MSUB: op31=000 o0=1
    v.push(("madd".into(), enc_dp3(1, 0b000, 0)));
    v.push(("msub".into(), enc_dp3(1, 0b000, 1)));
    v.push(("madd_w".into(), enc_dp3(0, 0b000, 0)));
    v.push(("msub_w".into(), enc_dp3(0, 0b000, 1)));
    // SMADDL: op31=001 o0=0 ; SMSUBL: 001 o0=1 ; UMADDL: 101 o0=0 ; UMSUBL: 101 o0=1
    v.push(("smaddl".into(), enc_dp3(1, 0b001, 0)));
    v.push(("smsubl".into(), enc_dp3(1, 0b001, 1)));
    v.push(("umaddl".into(), enc_dp3(1, 0b101, 0)));
    v.push(("umsubl".into(), enc_dp3(1, 0b101, 1)));
    // SMULH: op31=010 o0=0 ; UMULH: 110 o0=0 (Ra must be 31/xzr)
    v.push(("smulh".into(), enc_dp3_ra(1, 0b010, 0, 31)));
    v.push(("umulh".into(), enc_dp3_ra(1, 0b110, 0, 31)));
    v
}

/// Add/subtract (shifted register): `sf op S 01011 shift 0 Rm imm6 Rn Rd`
fn enc_addsub_shift_regs(
    sf: u32,
    op: u32,
    s: u32,
    shift: u32,
    imm6: u32,
    rd: u32,
    rn: u32,
    rm: u32,
) -> u32 {
    (sf << 31)
        | (op << 30)
        | (s << 29)
        | (0b01011 << 24)
        | (shift << 22)
        | ((rm & 0x1F) << 16)
        | (imm6 << 10)
        | ((rn & 0x1F) << 5)
        | (rd & 0x1F)
}

fn enc_addsub_shift(sf: u32, op: u32, s: u32, shift: u32, imm6: u32) -> u32 {
    enc_addsub_shift_regs(sf, op, s, shift, imm6, RD, RN, RM)
}

/// Add/subtract (immediate): `sf op S 10001 sh imm12 Rn Rd`.
#[cfg(all(feature = "smir-jit", target_arch = "x86_64"))]
fn enc_addsub_imm_regs(sf: u32, op: u32, s: u32, shift: u32, imm12: u32, rd: u32, rn: u32) -> u32 {
    (sf << 31)
        | (op << 30)
        | (s << 29)
        | (0b10001 << 24)
        | ((shift & 1) << 22)
        | ((imm12 & 0xfff) << 10)
        | ((rn & 0x1f) << 5)
        | (rd & 0x1f)
}

/// Add/subtract (extended register): `sf op S 01011 00 1 Rm option imm3 Rn Rd`
#[cfg(all(feature = "smir-jit", target_arch = "x86_64"))]
fn enc_addsub_ext_regs(
    sf: u32,
    op: u32,
    s: u32,
    option: u32,
    imm3: u32,
    rd: u32,
    rn: u32,
    rm: u32,
) -> u32 {
    (sf << 31)
        | (op << 30)
        | (s << 29)
        | (0b01011 << 24)
        | (1 << 21)
        | ((rm & 0x1f) << 16)
        | (option << 13)
        | (imm3 << 10)
        | ((rn & 0x1f) << 5)
        | (rd & 0x1f)
}

#[cfg(all(feature = "smir-jit", target_arch = "x86_64"))]
fn enc_addsub_ext(sf: u32, op: u32, s: u32, option: u32, imm3: u32) -> u32 {
    enc_addsub_ext_regs(sf, op, s, option, imm3, RD, RN, RM)
}

fn addsub_shift_cases() -> Vec<(String, u32)> {
    let mut v = Vec::new();
    for sf in 0..2 {
        for op in 0..2 {
            for s in 0..2 {
                for shift in 0..3 {
                    // LSL/LSR/ASR
                    let imm6s = if sf == 1 { 0..64 } else { 0..32 };
                    for imm6 in imm6s {
                        v.push((
                            format!("addsub sf{sf} op{op} s{s} sh{shift} #{imm6}"),
                            enc_addsub_shift(sf, op, s, shift, imm6),
                        ));
                    }
                }
            }
        }
    }
    v
}

/// Add/subtract with carry: `sf op S 11010000 Rm 000000 Rn Rd`
#[cfg(all(feature = "smir-jit", target_arch = "x86_64"))]
fn enc_addsub_carry(sf: u32, op: u32, s: u32) -> u32 {
    enc_addsub_carry_rn(sf, op, s, RN)
}

#[cfg(all(feature = "smir-jit", target_arch = "x86_64"))]
fn enc_addsub_carry_rn(sf: u32, op: u32, s: u32, rn: u32) -> u32 {
    enc_addsub_carry_regs(sf, op, s, RD, rn, RM)
}

#[cfg(all(feature = "smir-jit", target_arch = "x86_64"))]
fn enc_addsub_carry_regs(sf: u32, op: u32, s: u32, rd: u32, rn: u32, rm: u32) -> u32 {
    (sf << 31) | (op << 30) | (s << 29) | (0b11010000 << 21) | (rm << 16) | (rn << 5) | rd
}

#[cfg(all(feature = "smir-jit", target_arch = "x86_64"))]
fn enc_addsub_tags(op: u32, uimm6: u32, uimm4: u32) -> u32 {
    enc_addsub_tags_regs(op, uimm6, uimm4, RN, RD)
}

#[cfg(all(feature = "smir-jit", target_arch = "x86_64"))]
fn enc_addsub_tags_regs(op: u32, uimm6: u32, uimm4: u32, rn: u32, rd: u32) -> u32 {
    (1 << 31)
        | (op << 30)
        | (0b100011 << 23)
        | ((uimm6 & 0x3f) << 16)
        | ((uimm4 & 0xf) << 10)
        | ((rn & 0x1f) << 5)
        | (rd & 0x1f)
}

/// Conditional compare: `sf op 111010010 Rm/imm5 cond imm 0 Rn 0 nzcv`.
#[cfg(all(feature = "smir-jit", target_arch = "x86_64"))]
fn enc_condcmp(sf: u32, op: u32, imm: bool, rm_imm5: u32, cond: u32, nzcv: u32) -> u32 {
    (sf << 31)
        | (op << 30)
        | (0b111010010 << 21)
        | (rm_imm5 << 16)
        | (cond << 12)
        | ((imm as u32) << 11)
        | (RN << 5)
        | nzcv
}

/// Test and branch: `b5 011011 op b40 imm14 Rt`.
#[cfg(all(feature = "smir-jit", target_arch = "x86_64"))]
fn enc_test_branch_rt(op: u32, bit: u32, offset: i32, rt: u32) -> u32 {
    let b5 = (bit >> 5) & 1;
    let b40 = bit & 0x1F;
    let imm14 = ((offset >> 2) as u32) & 0x3FFF;
    (b5 << 31) | (0b011011 << 25) | (op << 24) | (b40 << 19) | (imm14 << 5) | (rt & 0x1f)
}

#[cfg(all(feature = "smir-jit", target_arch = "x86_64"))]
fn enc_test_branch(op: u32, bit: u32, offset: i32) -> u32 {
    enc_test_branch_rt(op, bit, offset, RN)
}

/// Compare and branch: `sf 011010 op imm19 Rt`.
#[cfg(all(feature = "smir-jit", target_arch = "x86_64"))]
fn enc_compare_branch(sf: u32, op: u32, rt: u32, offset: i32) -> u32 {
    let imm19 = ((offset >> 2) as u32) & 0x7FFFF;
    (sf << 31) | (0b011010 << 25) | (op << 24) | (imm19 << 5) | (rt & 0x1F)
}

/// Conditional branch: `01010100 imm19 0 cond`.
#[cfg(all(feature = "smir-jit", target_arch = "x86_64"))]
fn enc_cond_branch(cond: u32, offset: i32) -> u32 {
    let imm19 = ((offset >> 2) as u32) & 0x7FFFF;
    0x5400_0000 | (imm19 << 5) | (cond & 0xF)
}

/// Branch with link: `100101 imm26`.
#[cfg(all(feature = "smir-jit", target_arch = "x86_64"))]
fn enc_bl(offset: i32) -> u32 {
    0x9400_0000 | (((offset >> 2) as u32) & 0x03ff_ffff)
}

/// Branch to register: `1101011 0000 11111 000000 Rn 00000`.
#[cfg(all(feature = "smir-jit", target_arch = "x86_64"))]
fn enc_br(rn: u32) -> u32 {
    0xd61f_0000 | ((rn & 0x1f) << 5)
}

/// Branch with link to register.
#[cfg(all(feature = "smir-jit", target_arch = "x86_64"))]
fn enc_blr(rn: u32) -> u32 {
    0xd63f_0000 | ((rn & 0x1f) << 5)
}

/// Return from subroutine through `rn` (`rn == 30` is plain RET).
#[cfg(all(feature = "smir-jit", target_arch = "x86_64"))]
fn enc_ret(rn: u32) -> u32 {
    0xd65f_0000 | ((rn & 0x1f) << 5)
}

/// Logical (shifted register): `sf opc 01010 shift N Rm imm6 Rn Rd`
fn enc_logical_shift_regs(
    sf: u32,
    opc: u32,
    shift: u32,
    n: u32,
    imm6: u32,
    rd: u32,
    rn: u32,
    rm: u32,
) -> u32 {
    (sf << 31)
        | (opc << 29)
        | (0b01010 << 24)
        | (shift << 22)
        | (n << 21)
        | ((rm & 0x1F) << 16)
        | (imm6 << 10)
        | ((rn & 0x1F) << 5)
        | (rd & 0x1F)
}

fn enc_logical_shift(sf: u32, opc: u32, shift: u32, n: u32, imm6: u32) -> u32 {
    enc_logical_shift_regs(sf, opc, shift, n, imm6, RD, RN, RM)
}

fn enc_mov_reg(sf: u32, rd: u32, rm: u32) -> u32 {
    enc_logical_shift_regs(sf, 0b01, 0, 0, 0, rd, 31, rm)
}

fn logical_shift_cases() -> Vec<(String, u32)> {
    let mut v = Vec::new();
    for sf in 0..2 {
        for opc in 0..4 {
            // AND/ORR/EOR/ANDS
            for n in 0..2 {
                for shift in 0..4 {
                    let imm6s = if sf == 1 { 0..64 } else { 0..32 };
                    for imm6 in imm6s {
                        v.push((
                            format!("logical sf{sf} opc{opc} n{n} sh{shift} #{imm6}"),
                            enc_logical_shift(sf, opc, shift, n, imm6),
                        ));
                    }
                }
            }
        }
    }
    v
}

// ---------------------------------------------------------------------------
// Test driver.
// ---------------------------------------------------------------------------

/// Run a family of encodings, each with `n_inputs` random states, against the
/// oracle and assert no divergences.
fn run_family(name: &str, cases: Vec<(String, u32)>, n_inputs: usize, seed: u64) {
    // Build the full batch of (label, insn, state) triples.
    let mut rng = Rng::new(seed);
    let mut batch: Vec<(String, u32, ArmState)> = Vec::new();
    for (label, insn) in &cases {
        for _ in 0..n_inputs {
            let st = gen_input(&mut rng);
            batch.push((label.clone(), *insn, st));
        }
    }
    run_batch(name, batch);
}

fn parse_generated_a64_encodings(family: &str, source: &str) -> Vec<(String, u32)> {
    source
        .lines()
        .filter_map(|line| {
            let line = line.trim();
            let rest = line.strip_prefix("let encoding: u32 = ")?;
            let hex = rest.strip_suffix(';')?.strip_prefix("0x")?;
            let insn = u32::from_str_radix(hex, 16).ok()?;
            Some((format!("{family} {insn:#010x}"), insn))
        })
        .collect()
}

fn size_field_suffix(fields: &std::collections::BTreeMap<String, i32>) -> Option<&'static str> {
    match fields.get("size").copied()? {
        0 => Some(".b"),
        1 => Some(".h"),
        2 => Some(".s"),
        3 => Some(".d"),
        _ => None,
    }
}

fn parse_generated_a64_encodings_with_asm(family: &str, source: &str) -> Vec<(String, u32)> {
    let mut provenance = String::new();
    let mut fields = std::collections::BTreeMap::new();
    let mut pending: Option<(String, std::collections::BTreeMap<String, i32>, u32)> = None;
    let mut out = Vec::new();

    fn push_pending(
        out: &mut Vec<(String, u32)>,
        family: &str,
        pending: &mut Option<(String, std::collections::BTreeMap<String, i32>, u32)>,
        asm: Option<&str>,
    ) {
        let Some((provenance, fields, insn)) = pending.take() else {
            return;
        };
        let label = if let Some(asm) = asm {
            format!("{asm} [{family} {insn:#010x}]")
        } else {
            let provenance_lower = provenance.to_ascii_lowercase();
            let mnemonic =
                if let Some(rest) = provenance_lower.strip_prefix("aarch64_vector_crypto_") {
                    rest.split('_').next().unwrap_or(family).to_string()
                } else {
                    provenance
                        .split('_')
                        .next()
                        .unwrap_or(family)
                        .to_ascii_lowercase()
                };
            let suffix = size_field_suffix(&fields).unwrap_or("");
            format!("{mnemonic}{suffix} [{family} {insn:#010x}]")
        };
        out.push((label, insn));
    }

    for line in source.lines() {
        let line = line.trim();
        if let Some(rest) = line.strip_prefix("/// Provenance: ") {
            push_pending(&mut out, family, &mut pending, None);
            provenance.clear();
            provenance.push_str(rest);
            fields.clear();
            continue;
        }
        if let Some(rest) = line.strip_prefix("// Fields: ") {
            fields.clear();
            for part in rest.split(',') {
                let Some((name, value)) = part.trim().split_once('=') else {
                    continue;
                };
                if let Ok(value) = value.parse::<i32>() {
                    fields.insert(name.to_string(), value);
                }
            }
            continue;
        }
        if let Some(rest) = line.strip_prefix("let encoding: u32 = ") {
            push_pending(&mut out, family, &mut pending, None);
            let Some(hex) = rest.strip_suffix(';').and_then(|s| s.strip_prefix("0x")) else {
                continue;
            };
            if let Ok(insn) = u32::from_str_radix(hex, 16) {
                pending = Some((provenance.clone(), fields.clone(), insn));
            }
            continue;
        }
        if let Some(asm) = line.strip_prefix("// llvm-mc: ") {
            push_pending(&mut out, family, &mut pending, Some(asm.trim()));
        }
    }
    push_pending(&mut out, family, &mut pending, None);
    out
}

fn parse_generated_a64_cases_with_fields(
    family: &str,
    source: &str,
) -> Vec<(String, u32, std::collections::BTreeMap<String, i32>)> {
    let mut fields = std::collections::BTreeMap::new();
    let mut out = Vec::new();
    for line in source.lines() {
        let line = line.trim();
        if let Some(rest) = line.strip_prefix("// Fields: ") {
            fields.clear();
            for part in rest.split(',') {
                let Some((name, value)) = part.trim().split_once('=') else {
                    continue;
                };
                if let Ok(value) = value.parse::<i32>() {
                    fields.insert(name.to_string(), value);
                }
            }
            continue;
        }
        let Some(rest) = line.strip_prefix("let encoding: u32 = ") else {
            continue;
        };
        let Some(hex) = rest.strip_suffix(';').and_then(|s| s.strip_prefix("0x")) else {
            continue;
        };
        if let Ok(insn) = u32::from_str_radix(hex, 16) {
            out.push((format!("{family} {insn:#010x}"), insn, fields.clone()));
        }
    }
    out
}

fn parse_generated_a64_cases_with_fields_and_asm(
    family: &str,
    source: &str,
) -> Vec<(String, u32, std::collections::BTreeMap<String, i32>)> {
    let mut provenance = String::new();
    let mut fields = std::collections::BTreeMap::new();
    let mut pending: Option<(String, std::collections::BTreeMap<String, i32>, u32)> = None;
    let mut out = Vec::new();

    fn push_pending(
        out: &mut Vec<(String, u32, std::collections::BTreeMap<String, i32>)>,
        family: &str,
        pending: &mut Option<(String, std::collections::BTreeMap<String, i32>, u32)>,
        asm: Option<&str>,
    ) {
        let Some((provenance, fields, insn)) = pending.take() else {
            return;
        };
        let label = if let Some(asm) = asm {
            format!("{asm} [{family} {insn:#010x}]")
        } else {
            let provenance_lower = provenance.to_ascii_lowercase();
            let mnemonic =
                if let Some(rest) = provenance_lower.strip_prefix("aarch64_vector_crypto_") {
                    rest.split('_').next().unwrap_or(family).to_string()
                } else {
                    provenance
                        .split('_')
                        .next()
                        .unwrap_or(family)
                        .to_ascii_lowercase()
                };
            let suffix = size_field_suffix(&fields).unwrap_or("");
            format!("{mnemonic}{suffix} [{family} {insn:#010x}]")
        };
        out.push((label, insn, fields));
    }

    for line in source.lines() {
        let line = line.trim();
        if let Some(rest) = line.strip_prefix("/// Provenance: ") {
            push_pending(&mut out, family, &mut pending, None);
            provenance.clear();
            provenance.push_str(rest);
            fields.clear();
            continue;
        }
        if let Some(rest) = line.strip_prefix("// Fields: ") {
            fields.clear();
            for part in rest.split(',') {
                let Some((name, value)) = part.trim().split_once('=') else {
                    continue;
                };
                if let Ok(value) = value.parse::<i32>() {
                    fields.insert(name.to_string(), value);
                }
            }
            continue;
        }
        if let Some(rest) = line.strip_prefix("let encoding: u32 = ") {
            push_pending(&mut out, family, &mut pending, None);
            let Some(hex) = rest.strip_suffix(';').and_then(|s| s.strip_prefix("0x")) else {
                continue;
            };
            if let Ok(insn) = u32::from_str_radix(hex, 16) {
                pending = Some((provenance.clone(), fields.clone(), insn));
            }
            continue;
        }
        if let Some(asm) = line.strip_prefix("// llvm-mc: ") {
            push_pending(&mut out, family, &mut pending, Some(asm.trim()));
        }
    }
    push_pending(&mut out, family, &mut pending, None);
    out
}

