fn generated_system_barrier_mnemonic(insn: u32) -> Option<&'static str> {
    let l = (insn >> 21) & 1;
    let op0 = (insn >> 19) & 0x3;
    let op1 = (insn >> 16) & 0x7;
    let crn = (insn >> 12) & 0xf;
    let op2 = (insn >> 5) & 0x7;
    let rt = insn & 0x1f;
    if l != 0 || op0 != 0 || op1 != 3 || crn != 3 || rt != 31 {
        return None;
    }
    match op2 {
        0b100 => Some("dsb"),
        0b101 => Some("dmb"),
        0b110 => Some("isb"),
        0b111 => Some("sb"),
        _ => None,
    }
}

fn generated_system_barrier_cases() -> Vec<(String, u32)> {
    let source = include_str!("../../../generated/arm/a64/system/other.rs");
    let mut by_encoding = std::collections::BTreeMap::new();
    let parsed = parse_generated_a64_cases_with_fields_and_asm("system/other", source);
    for (_label, insn, fields) in parsed {
        let Some(mnemonic) = generated_system_barrier_mnemonic(insn) else {
            continue;
        };
        let crm = fields
            .get("CRm")
            .copied()
            .unwrap_or_else(|| ((insn >> 8) & 0xf) as i32);
        let label = format!("{mnemonic} crm={crm} [system/other {insn:#010x}]");
        by_encoding.entry(insn).or_insert(label);
    }
    by_encoding
        .into_iter()
        .map(|(insn, label)| (label, insn))
        .collect()
}

fn generated_system_monitor_mnemonic(insn: u32) -> Option<&'static str> {
    let l = (insn >> 21) & 1;
    let op0 = (insn >> 19) & 0x3;
    let op1 = (insn >> 16) & 0x7;
    let crn = (insn >> 12) & 0xf;
    let op2 = (insn >> 5) & 0x7;
    let rt = insn & 0x1f;
    if l == 0 && op0 == 0 && op1 == 3 && crn == 3 && op2 == 0b010 && rt == 31 {
        Some("clrex")
    } else {
        None
    }
}

