fn branch_immediate_in_tiny_program(fields: &std::collections::BTreeMap<String, i32>) -> bool {
    fields
        .get("imm26")
        .or_else(|| fields.get("imm19"))
        .or_else(|| fields.get("imm14"))
        == Some(&3)
}

fn branch_register_in_tiny_program(fields: &std::collections::BTreeMap<String, i32>) -> bool {
    if !["Z", "op", "A", "M", "Rm", "Rn"]
        .iter()
        .all(|field| fields.contains_key(*field))
    {
        return false;
    }
    if fields.get("Z").copied().unwrap_or(0) != 0
        || fields.get("A").copied().unwrap_or(0) != 0
        || fields.get("M").copied().unwrap_or(0) != 0
        || fields.get("Rm").copied().unwrap_or(0) != 0
    {
        return false;
    }
    matches!(fields.get("op").copied(), Some(0 | 1))
        && matches!(fields.get("Rn").copied(), Some(0..=30))
}

fn branch_register_unallocated(
    insn: u32,
    fields: &std::collections::BTreeMap<String, i32>,
) -> bool {
    if !["Z", "op", "A", "M", "Rm", "Rn"]
        .iter()
        .all(|field| fields.contains_key(*field))
    {
        return false;
    }
    let z = fields
        .get("Z")
        .copied()
        .unwrap_or_else(|| ((insn >> 24) & 1) as i32);
    let op = fields
        .get("op")
        .copied()
        .unwrap_or_else(|| ((insn >> 21) & 0x3) as i32);
    let a = fields
        .get("A")
        .copied()
        .unwrap_or_else(|| ((insn >> 11) & 1) as i32);
    let m = fields
        .get("M")
        .copied()
        .unwrap_or_else(|| ((insn >> 10) & 1) as i32);
    let rm = fields
        .get("Rm")
        .copied()
        .unwrap_or_else(|| (insn & 0x1f) as i32);
    !(z == 0 && a == 0 && m == 0 && rm == 0 && matches!(op, 0 | 1 | 2))
}

fn integer_address_pc_in_normalized_window(insn: u32) -> bool {
    if (insn >> 24) & 0x1f != 0b10000 {
        return false;
    }
    let op = insn >> 31;
    let immlo = (insn >> 29) & 0x3;
    let immhi = (insn >> 5) & 0x7ffff;
    let imm21 = ((immhi << 2) | immlo) as i32;
    let signed = if imm21 & (1 << 20) != 0 {
        imm21 - (1 << 21)
    } else {
        imm21
    };
    if op == 0 {
        (0..=12).contains(&signed)
    } else {
        (-2..=2).contains(&signed)
    }
}

fn integer_tag_addsub(insn: u32) -> bool {
    (insn >> 31) == 1
        && ((insn >> 29) & 1) == 0
        && ((insn >> 23) & 0x3f) == 0b100011
        && ((insn >> 22) & 1) == 0
}

fn integer_pac_strip_or_hint(insn: u32) -> bool {
    if insn == 0xd503_20ff {
        return true;
    }
    let sf = (insn >> 31) & 1;
    let opcode2 = (insn >> 16) & 0x1f;
    let opcode = (insn >> 10) & 0x3f;
    sf == 1 && opcode2 == 0b00001 && matches!(opcode, 0b010000 | 0b010001)
}

#[derive(Clone, Copy)]
enum GeneratedExceptionExit {
    Breakpoint(u32),
    Hvc(u16),
    Smc(u16),
    Halt,
}

impl GeneratedExceptionExit {
    fn matches(self, actual: Option<CpuExit>) -> bool {
        match (self, actual) {
            (GeneratedExceptionExit::Breakpoint(imm), Some(CpuExit::Breakpoint(got))) => got == imm,
            (GeneratedExceptionExit::Hvc(imm), Some(CpuExit::Hvc(got))) => got == imm,
            (GeneratedExceptionExit::Smc(imm), Some(CpuExit::Smc(got))) => got == imm,
            (GeneratedExceptionExit::Halt, Some(CpuExit::Halt)) => true,
            _ => false,
        }
    }
}

fn generated_exception_expected_exit(insn: u32) -> Option<GeneratedExceptionExit> {
    let opc = (insn >> 21) & 0x7;
    let ll = insn & 0x3;
    let imm16 = ((insn >> 5) & 0xffff) as u16;
    match (opc, ll) {
        (0b000, 0b10) => Some(GeneratedExceptionExit::Hvc(imm16)),
        (0b000, 0b11) => Some(GeneratedExceptionExit::Smc(imm16)),
        (0b001, 0b00) => Some(GeneratedExceptionExit::Breakpoint(imm16 as u32)),
        (0b010, 0b00) => Some(GeneratedExceptionExit::Halt),
        (0b101, 0b01..=0b11) => Some(GeneratedExceptionExit::Halt),
        _ => None,
    }
}

fn vector_dotprod(insn: u32) -> bool {
    let lo6 = (insn >> 10) & 0x3f;
    (insn >> 24) & 0x1f == 0b01110
        && ((insn >> 21) & 1) == 0
        && (lo6 == 0b100101 || (((insn >> 29) & 1) == 0 && lo6 == 0b100111))
}

fn vector_scalar_cmp_zero(insn: u32) -> bool {
    let opcode = (insn >> 12) & 0x1f;
    (insn >> 24) & 0x1f == 0b11110
        && ((insn >> 17) & 0x1f) == 0b10000
        && ((insn >> 10) & 0x3) == 0b10
        && matches!(opcode, 0b01000 | 0b01001 | 0b01010)
}

fn vector_scalar_shift_imm_same_size(insn: u32) -> bool {
    let opcode = (insn >> 11) & 0x1f;
    (insn >> 24) & 0x1f == 0b11111
        && ((insn >> 10) & 1) == 1
        && matches!(
            opcode,
            0b00000 | 0b00010 | 0b00100 | 0b00110 | 0b01000 | 0b01010 | 0b01100 | 0b01110
        )
}

fn vector_scalar_fp16_pairwise_maxmin(insn: u32) -> bool {
    let opcode = (insn >> 12) & 0x1f;
    (insn >> 24) & 0x1f == 0b11110
        && ((insn >> 29) & 1) == 0
        && ((insn >> 17) & 0x1f) == 0b11000
        && ((insn >> 10) & 0x3) == 0b10
        && matches!(opcode, 0b01100 | 0b01111)
}

fn vector_scalar_fp16_pairwise_add(insn: u32) -> bool {
    (insn >> 24) & 0x1f == 0b11110
        && ((insn >> 29) & 1) == 0
        && ((insn >> 17) & 0x1f) == 0b11000
        && ((insn >> 12) & 0x1f) == 0b01101
        && ((insn >> 10) & 0x3) == 0b10
}

fn vector_float_narrow(insn: u32) -> bool {
    (insn >> 24) & 0x1f == 0b01110
        && ((insn >> 17) & 0x1f) == 0b10000
        && ((insn >> 12) & 0x1f) == 0b10110
        && ((insn >> 10) & 0x3) == 0b10
}

fn vector_float_frintts(insn: u32) -> bool {
    (insn >> 24) & 0x1f == 0b01110
        && ((insn >> 23) & 1) == 0
        && ((insn >> 17) & 0x1f) == 0b10000
        && matches!((insn >> 12) & 0x1f, 0b11110 | 0b11111)
        && ((insn >> 10) & 0x3) == 0b10
}

fn vector_float_fused(insn: u32) -> bool {
    (insn >> 24) & 0x1f == 0b01110
        && ((insn >> 29) & 1) == 0
        && ((insn >> 21) & 1) == 1
        && ((insn >> 11) & 0x1f) == 0b11001
        && ((insn >> 10) & 1) == 1
}

fn vector_fmlal_three_same(insn: u32) -> bool {
    let u = (insn >> 29) & 1;
    let opcode = (insn >> 11) & 0x1f;
    (insn >> 24) & 0x1f == 0b01110
        && ((insn >> 21) & 1) == 1
        && ((insn >> 10) & 0x3) == 0b11
        && ((u == 0 && opcode == 0b11101) || (u == 1 && opcode == 0b11001))
}

fn vector_recps_rsqrts(insn: u32) -> bool {
    (matches!((insn >> 24) & 0x1f, 0b01110 | 0b11110))
        && ((insn >> 29) & 1) == 0
        && ((insn >> 21) & 1) == 1
        && ((insn >> 11) & 0x1f) == 0b11111
        && ((insn >> 10) & 0x3) == 0b11
}

fn vector_scalar_abs_neg(insn: u32) -> bool {
    (insn >> 24) & 0x1f == 0b11110
        && ((insn >> 12) & 0x1f) == 0b01011
        && ((insn >> 10) & 0x3) == 0b10
}

fn gen_memory_input(rng: &mut Rng) -> ArmState {
    let mut st = gen_input(rng);
    for i in 0..31 {
        st.x[i] = SCRATCH_BASE + 64;
    }
    st.sp = SCRATCH_BASE + 64;
    for word in &mut st.scratch {
        *word = rng.next();
    }
    st
}

fn gen_tag_addsub_input(rng: &mut Rng) -> ArmState {
    let mut st = gen_input(rng);
    for i in 0..31 {
        let tag = (rng.next() & 0xf) << 56;
        let base = 0x1000 + ((i as u64) << 8) + (rng.next() & 0xf0);
        st.x[i] = tag | base;
    }
    let tag = (rng.next() & 0xf) << 56;
    let base = GUEST_STACK_ADDR + (GUEST_STACK_SIZE / 2) + (rng.next() & 0xff0);
    st.sp = tag | (base & !0xf);
    st
}

fn gen_pac_strip_input(rng: &mut Rng) -> ArmState {
    let mut st = gen_input(rng);
    for i in 0..31 {
        st.x[i] = rng.next() & 0x0000_7fff_ffff_fff0;
    }
    st.sp = 0x10_0000 + (rng.next() & 0xffff0);
    st
}

fn gen_float_input(rng: &mut Rng) -> ArmState {
    let mut st = gen_input(rng);
    for i in 0..31 {
        st.x[i] = (rng.next() & 0xffff) as u64;
    }
    st.sp = rng.interesting() & !0xf;
    st.pstate = (rng.next() & 0xf) << 28;
    st.fpcr = 0;
    st.fpsr = 0;
    for r in 0..32 {
        st.set_vreg(r, 0x0000_0000_3f80_3c00, 0x0000_0000_3f80_3c00);
    }
    st
}

fn gen_sve_input(rng: &mut Rng) -> ArmState {
    let mut st = gen_input(rng);
    for r in 0..16 {
        st.set_preg(r, rng.next() as u16);
    }
    st
}

fn gen_sve_base_imm_memory_input(rng: &mut Rng) -> ArmState {
    let mut st = gen_sve_input(rng);
    for i in 0..31 {
        st.x[i] = SCRATCH_BASE;
    }
    st.sp = SCRATCH_BASE;
    for word in &mut st.scratch {
        *word = rng.next();
    }
    st
}

fn gen_sve_contiguous_memory_input(rng: &mut Rng) -> ArmState {
    let mut st = gen_sve_input(rng);
    for i in 0..31 {
        st.x[i] = SCRATCH_BASE + 64;
    }
    st.sp = SCRATCH_BASE + 64;
    for word in &mut st.scratch {
        *word = rng.next();
    }
    for r in 0..16 {
        st.set_preg(r, 1);
    }
    st
}

fn gen_sve_reg_offset_memory_input(rng: &mut Rng, insn: u32) -> ArmState {
    let mut st = gen_sve_input(rng);
    for i in 0..31 {
        st.x[i] = 0;
    }
    st.sp = SCRATCH_BASE + 64;
    let rn = ((insn >> 5) & 0x1f) as usize;
    let rm = ((insn >> 16) & 0x1f) as usize;
    if rn == 31 {
        st.sp = SCRATCH_BASE + 64;
    } else {
        st.x[rn] = SCRATCH_BASE + 64;
    }
    if rm != 31 {
        st.x[rm] = 0;
    }
    for word in &mut st.scratch {
        *word = rng.next();
    }
    for r in 0..16 {
        st.set_preg(r, 1);
    }
    st
}

fn gen_sve_vector_offset_memory_input(rng: &mut Rng, insn: u32) -> ArmState {
    let mut st = gen_sve_input(rng);
    for i in 0..31 {
        st.x[i] = SCRATCH_BASE + 64;
    }
    st.sp = SCRATCH_BASE + 64;
    for word in &mut st.scratch {
        *word = rng.next();
    }
    let zm = ((insn >> 16) & 0x1f) as usize;
    st.set_vreg(zm, 0, 0);
    for r in 0..16 {
        st.set_preg(r, 1);
    }
    st
}

fn gen_sve_vector_base_imm_memory_input(rng: &mut Rng, insn: u32) -> ArmState {
    let mut st = gen_sve_input(rng);
    for word in &mut st.scratch {
        *word = rng.next();
    }
    let zn = ((insn >> 5) & 0x1f) as usize;
    let top = insn >> 25;
    let store_s_form = top == 0b1110010 && ((insn >> 21) & 0x3) == 0b11;
    if top == 0b1000010 || store_s_form {
        let base = SCRATCH_ADDR as u32 as u64;
        let pair = base | (base << 32);
        st.set_vreg(zn, pair, pair);
    } else {
        st.set_vreg(zn, SCRATCH_ADDR, SCRATCH_ADDR);
    }
    for r in 0..16 {
        st.set_preg(r, 1);
    }
    st
}

fn gen_sve_replicate_memory_input(rng: &mut Rng, insn: u32) -> ArmState {
    if insn >> 25 == 0b1010010 && (insn >> 13) & 0x7 == 0 {
        return gen_sve_reg_offset_memory_input(rng, insn);
    }
    gen_sve_contiguous_memory_input(rng)
}

/// Run an explicit batch of (label, insn, input-state) triples against the
/// oracle and assert no divergences. Self-skips if the toolchain is absent.
fn run_batch(name: &str, batch: Vec<(String, u32, ArmState)>) {
    run_batch_with_runner(name, batch, run_rax);
}

fn run_batch_el0(name: &str, batch: Vec<(String, u32, ArmState)>) {
    run_batch_with_runner(name, batch, run_rax_el0);
}

fn run_batch_el0_legality(name: &str, batch: Vec<(String, u32, ArmState)>) {
    let oracle = match oracle_path() {
        Some(p) => p,
        None => {
            eprintln!("[arm_diff] {name}: native/qemu oracle unavailable -> skipping");
            return;
        }
    };

    let cases: Vec<(u32, u32, ArmState)> = batch.iter().map(|(_, i, s)| (*i, NOP, *s)).collect();
    let outs = match run_oracle(&oracle, &cases) {
        Some(o) => o,
        None => {
            if oracle.is_native() {
                panic!("[arm_diff] {name}: native oracle run failed");
            }
            eprintln!("[arm_diff] {name}: oracle run failed -> skipping");
            return;
        }
    };
    assert_eq!(outs.len(), cases.len());

    let mut mismatches = Vec::new();
    for (i, ((insn, _nop, st), out)) in cases.iter().zip(outs.iter()).enumerate() {
        if out.trapped != 0 && native_hardware_lacks_label(&oracle, &batch[i].0) {
            continue;
        }
        let rax = run_rax_el0(*insn, st);
        match (out.trapped == 0, rax.is_some()) {
            (true, true) | (false, false) => {}
            (true, false) => mismatches.push(Mismatch {
                label: batch[i].0.clone(),
                insn: *insn,
                detail: "hardware executed but rax rejected at EL0".into(),
            }),
            (false, true) => mismatches.push(Mismatch {
                label: batch[i].0.clone(),
                insn: *insn,
                detail: format!(
                    "hardware faulted with signal {} but rax executed",
                    out.trapped
                ),
            }),
        }
    }

    if !mismatches.is_empty() {
        use std::collections::BTreeMap;
        let mut by_label: BTreeMap<String, usize> = BTreeMap::new();
        for m in &mismatches {
            *by_label.entry(m.label.clone()).or_default() += 1;
        }
        eprintln!(
            "\n==== {name}: {} legality mismatches across {} cases ====",
            mismatches.len(),
            cases.len()
        );
        for (label, count) in &by_label {
            eprintln!("  {count:5}x  {label}");
        }
        for m in mismatches.iter().take(25) {
            eprintln!("  [{}] {:#010x}: {}", m.label, m.insn, m.detail);
        }
        panic!(
            "{name}: {} legality divergences vs hardware oracle",
            mismatches.len()
        );
    }
}

fn run_batch_with_runner(
    name: &str,
    batch: Vec<(String, u32, ArmState)>,
    runner: fn(u32, &ArmState) -> Option<ArmState>,
) {
    let oracle = match oracle_path() {
        Some(p) => p,
        None => {
            eprintln!("[arm_diff] {name}: native/qemu oracle unavailable -> skipping");
            return;
        }
    };

    let labels: Vec<String> = batch.iter().map(|(l, _, _)| l.clone()).collect();
    let cases: Vec<(u32, u32, ArmState)> = batch.iter().map(|(_, i, s)| (*i, NOP, *s)).collect();

    let outs = match run_oracle(&oracle, &cases) {
        Some(o) => o,
        None => {
            if oracle.is_native() {
                panic!("[arm_diff] {name}: native oracle run failed");
            }
            eprintln!("[arm_diff] {name}: oracle run failed -> skipping");
            return;
        }
    };
    assert_eq!(outs.len(), cases.len());

    let mut mismatches = Vec::new();
    for (i, ((insn, _insn2, st), out)) in cases.iter().zip(outs.iter()).enumerate() {
        if out.trapped != 0 && native_hardware_lacks_label(&oracle, &labels[i]) {
            continue;
        }
        compare_case_with_runner(&labels[i], *insn, st, out, &mut mismatches, runner);
    }

    let batch = &cases; // for the count in the summary below
    if !mismatches.is_empty() {
        // Summarise: group by label, show a few representative cases.
        use std::collections::BTreeMap;
        let mut by_label: BTreeMap<String, usize> = BTreeMap::new();
        for m in &mismatches {
            *by_label.entry(m.label.clone()).or_default() += 1;
        }
        eprintln!(
            "\n==== {name}: {} mismatches across {} cases ====",
            mismatches.len(),
            batch.len()
        );
        eprintln!("-- by encoding --");
        for (label, count) in &by_label {
            eprintln!("  {count:5}x  {label}");
        }
        eprintln!("-- first 25 examples --");
        for m in mismatches.iter().take(25) {
            eprintln!("  [{}] {:#010x}: {}", m.label, m.insn, m.detail);
        }
        panic!(
            "{name}: {} divergences vs hardware oracle",
            mismatches.len()
        );
    }
}

