    st.x[2] = 0xffff_ffff_aabb_ccdd;
    batch.push((
        "extr_w_zero_ext_crafted".into(),
        enc_extract(0, RN, RM, 7),
        st,
    ));

    let mut st = ArmState::zeroed();
    st.x[0] = 0xaaaa_bbbb_cccc_dddd;
    st.x[1] = 0x1234_5678_9abc_def0;
