    let mut st = ArmState::zeroed();
    st.x[0] = 0xaaaa_bbbb_cccc_dddd;
    st.x[1] = 0xffff_ffff_8765_4321;
    st.x[2] = 0;
    batch.push(("udiv_w_zero_ext".into(), enc_dp2(0, 0b0010), st));

    let mut st = ArmState::zeroed();
    st.x[0] = 0xaaaa_bbbb_cccc_dddd;
    st.x[1] = 0x8000_0000_0000_0000;
