#[test]
fn diff_load_literal_scalar() {
    fn ldr_literal(opc: u32, v: u32, rt: u32, offset: i32) -> u32 {
        let imm19 = ((offset >> 2) as u32) & 0x7ffff;
        (opc << 30) | (0b011 << 27) | (v << 26) | (imm19 << 5) | (rt & 0x1f)
    }

    let mut rng = Rng::new(0x5157_1001);
    let word1 = NOP;
    let word2 = NOP;
    let mut batch = Vec::new();

    for rt in [0, 5, 30, 31] {
        for (label, insn) in [
            ("ldr_lit_w", ldr_literal(0, 0, rt, 4)),
            ("ldr_lit_x", ldr_literal(1, 0, rt, 4)),
            ("ldrsw_lit_x", ldr_literal(2, 0, rt, 4)),
            ("ldr_lit_w_pc0", ldr_literal(0, 0, rt, 0)),
            ("ldr_lit_x_pc8", ldr_literal(1, 0, rt, 8)),
            ("ldrsw_lit_x_pc8", ldr_literal(2, 0, rt, 8)),
            ("prfm_lit", ldr_literal(3, 0, rt, 4)),
        ] {
            let mut st = gen_input(&mut rng);
            if rt == 31 {
                st.sp = 0x9999_9999_9999_9990;
            } else {
                st.x[rt as usize] = 0x9999_9999_9999_9999;
            }
            batch.push((format!("{label}_x{rt}"), insn, word1, word2, st));
        }
    }

    for rt in [0, 7, 31] {
        for (label, insn) in [
            ("ldr_lit_s", ldr_literal(0, 1, rt, 4)),
            ("ldr_lit_d", ldr_literal(1, 1, rt, 4)),
            ("ldr_lit_q", ldr_literal(2, 1, rt, 4)),
            ("ldr_lit_s_pc0", ldr_literal(0, 1, rt, 0)),
            ("ldr_lit_d_pc8", ldr_literal(1, 1, rt, 8)),
            ("ldr_lit_q_pc8", ldr_literal(2, 1, rt, 8)),
            ("ldr_lit_simd_unallocated", ldr_literal(3, 1, rt, 4)),
        ] {
            let mut st = gen_input(&mut rng);
            st.set_vreg(rt as usize, 0xaaaa_aaaa_aaaa_aaaa, 0xbbbb_bbbb_bbbb_bbbb);
            batch.push((format!("{label}_v{rt}"), insn, word1, word2, st));
        }
    }

    run_batch_literal("load_literal_scalar", batch);
}

#[test]
fn diff_load_literal_negative_offset() {
    fn ldr_literal(opc: u32, v: u32, rt: u32, offset: i32) -> u32 {
        let imm19 = ((offset >> 2) as u32) & 0x7ffff;
        (opc << 30) | (0b011 << 27) | (v << 26) | (imm19 << 5) | (rt & 0x1f)
    }

    let mut rng = Rng::new(0x5157_1003);
    let mut batch = Vec::new();

    for rt in [0, 5, 31] {
        for (label, insn) in [
            ("ldr_lit_w_neg4", ldr_literal(0, 0, rt, -4)),
            ("ldr_lit_x_neg4", ldr_literal(1, 0, rt, -4)),
            ("ldrsw_lit_x_neg4", ldr_literal(2, 0, rt, -4)),
            ("prfm_lit_neg4", ldr_literal(3, 0, rt, -4)),
        ] {
            let mut st = gen_input(&mut rng);
            if rt == 31 {
                st.sp = 0x9999_9999_9999_9990;
            } else {
                st.x[rt as usize] = 0x9999_9999_9999_9999;
            }
            batch.push((format!("{label}_x{rt}"), NOP, insn, st));
        }
    }

    for rt in [0, 7] {
        for (label, insn) in [
            ("ldr_lit_s_neg4", ldr_literal(0, 1, rt, -4)),
            ("ldr_lit_d_neg4", ldr_literal(1, 1, rt, -4)),
        ] {
            let mut st = gen_input(&mut rng);
            st.set_vreg(rt as usize, 0xaaaa_aaaa_aaaa_aaaa, 0xbbbb_bbbb_bbbb_bbbb);
            batch.push((format!("{label}_v{rt}"), NOP, insn, st));
        }
    }

    run_batch_el0_pair("load_literal_negative_offset", batch);
}

#[test]
fn diff_load_literal_negative_q_offset() {
    fn ldr_literal(opc: u32, v: u32, rt: u32, offset: i32) -> u32 {
        let imm19 = ((offset >> 2) as u32) & 0x7ffff;
        (opc << 30) | (0b011 << 27) | (v << 26) | (imm19 << 5) | (rt & 0x1f)
    }

    let oracle = match oracle_path() {
        Some(p) => p,
        None => {
            eprintln!(
                "[arm_diff] load_literal_negative_q_offset: native/qemu oracle unavailable -> skipping"
            );
            return;
        }
    };

    const BRK_0: u32 = 0xd420_0000;
    let mut rng = Rng::new(0x5157_1004);
    let mut batch = Vec::new();
    for rt in [0, 7, 31] {
        let mut st = gen_input(&mut rng);
        st.set_vreg(rt as usize, 0xaaaa_aaaa_aaaa_aaaa, 0xbbbb_bbbb_bbbb_bbbb);
        batch.push((
            format!("ldr_lit_q_neg8_v{rt}"),
            NOP,
            NOP,
            ldr_literal(2, 1, rt, -8),
            st,
        ));
    }

    let cases: Vec<(u32, u32, u32, ArmState)> = batch
        .iter()
        .map(|(_, insn1, insn2, insn3, st)| (*insn1, *insn2, *insn3, *st))
        .collect();
    let outs = match run_oracle3(&oracle, &cases) {
        Some(o) => o,
        None => {
            if oracle.is_native() {
                panic!("[arm_diff] load_literal_negative_q_offset: native oracle run failed");
            }
            eprintln!("[arm_diff] load_literal_negative_q_offset: oracle run failed -> skipping");
            return;
        }
    };
    assert_eq!(outs.len(), cases.len());

    let mut mismatches = Vec::new();
    for (i, ((insn1, insn2, insn3, st), out)) in cases.iter().zip(outs.iter()).enumerate() {
        let rax = run_rax_sequence_with_trailing_at_el(&[*insn1, *insn2, *insn3], &[BRK_0], st, 0);
        compare_rax_outcome(&batch[i].0, *insn3, rax, out, &mut mismatches);
    }

    if !mismatches.is_empty() {
        eprintln!(
            "\n==== load_literal_negative_q_offset: {} mismatches across {} cases ====",
            mismatches.len(),
            cases.len()
        );
        for m in mismatches.iter().take(25) {
            eprintln!("  [{}] {:#010x}: {}", m.label, m.insn, m.detail);
        }
        panic!(
            "load_literal_negative_q_offset: {} divergences vs hardware oracle",
            mismatches.len()
        );
    }
}

