#[test]
fn diff_branch_system_hints_barriers_el0() {
    fn hint(crm: u32, op2: u32) -> u32 {
        0xd503_201f | ((crm & 0xf) << 8) | ((op2 & 0x7) << 5)
    }

    fn barrier(crm: u32, op2: u32) -> u32 {
        0xd503_301f | ((crm & 0xf) << 8) | ((op2 & 0x7) << 5)
    }

    let mut rng = Rng::new(0x5157_0001);
    let mut batch = Vec::new();

    for (label, insn) in [
        ("nop", hint(0, 0)),
        ("yield", hint(0, 1)),
        ("sev", hint(0, 4)),
        ("sevl", hint(0, 5)),
        ("dgh", hint(0, 6)),
        ("esb", hint(2, 0)),
        ("psb_csync", hint(2, 1)),
        ("tsb_csync", hint(2, 2)),
        ("csdb", hint(2, 4)),
        ("bti", hint(4, 0)),
        ("bti_c", hint(4, 2)),
        ("bti_j", hint(4, 4)),
        ("bti_jc", hint(4, 6)),
        ("clrex", barrier(0, 2)),
        ("dsb_sy", barrier(0xf, 4)),
        ("dmb_sy", barrier(0xf, 5)),
        ("isb", barrier(0xf, 6)),
    ] {
        batch.push((format!("branch_system_{label}"), insn, gen_input(&mut rng)));
    }

    // WFE/WFI are architecturally hints but are modeled as blocking exits by
    // rax and can be controlled by the host kernel at EL0, so they are covered
    // by structured-exit tests rather than value-state comparison here.
    run_batch("branch_system_hints_barriers_el0", batch);
}

#[test]
fn diff_branch_system_wait_hint_structured_exits() {
    fn hint(crm: u32, op2: u32) -> u32 {
        0xd503_201f | ((crm & 0xf) << 8) | ((op2 & 0x7) << 5)
    }

    let mut rng = Rng::new(0xa64_0f16);
    let st = gen_input(&mut rng);
    assert_eq!(run_rax_exit(hint(0b0000, 0b010), &st), Some(CpuExit::Wfe));
    assert_eq!(run_rax_exit(hint(0b0000, 0b011), &st), Some(CpuExit::Wfi));

    let mut batch = Vec::new();
    for (label, first) in [
        ("sev_then_wfe", hint(0b0000, 0b100)),
        ("sevl_then_wfe", hint(0b0000, 0b101)),
    ] {
        for _ in 0..4 {
            batch.push((
                label.to_string(),
                first,
                hint(0b0000, 0b010),
                gen_input(&mut rng),
            ));
        }
    }
    run_batch_pair("branch_system_wait_hint_event_wfe", batch);
}

#[test]
fn diff_branch_system_wfxt_el0() {
    // WFET/WFIT are timed wait hints. Use an already-expired timeout value so
    // native hardware returns immediately and the architectural state is stable.
    let mut rng = Rng::new(0xa64_0f17);
    let mut batch = Vec::new();
    let mut wfet = gen_input(&mut rng);
    wfet.x[0] = 0;
    batch.push(("wfet x0".to_string(), 0xd503_1000, wfet));

    let mut wfit = gen_input(&mut rng);
    wfit.x[1] = 0;
    batch.push(("wfit x1".to_string(), 0xd503_1021, wfit));

    run_batch("branch_system_wfxt_el0", batch);
}

