fn enc_fmlal_idx(q: u32, top: u32, sub: u32, index: u32) -> u32 {
    let h = (index >> 2) & 1;
    let l = (index >> 1) & 1;
    let m = index & 1;
    (q << 30)
        | (top << 29)
        | (0b01111 << 24)
        | (0b10 << 22)
        | (l << 21)
        | (m << 20)
        | (RM << 16)
        | (top << 15)
        | (sub << 14)
        | (h << 11)
        | (RN << 5)
        | RD
}

