#[test]
fn diff_fmlal_indexed() {
    let half_values: &[u16] = &[
        0x0000, 0x8000, 0x0001, 0x03ff, 0x8001, 0x83ff, 0x3c00, 0xbc00, 0x4000, 0xc000, 0x3800,
        0xb800, 0x4400, 0xc400,
    ];
    let mut rng = Rng::new(0x1_0026);
    let mut batch: Vec<(String, u32, ArmState)> = Vec::new();

    for q in 0..2u32 {
        for top in 0..2u32 {
            for sub in 0..2u32 {
                for index in 0..8u32 {
                    let insn = enc_fmlal_idx(q, top, sub, index);
                    for _ in 0..8 {
                        let mut st = ArmState::zeroed();
                        for r in [RN as usize, RM as usize] {
                            let mut packed = 0u128;
                            for lane in 0..8 {
                                let h = half_values[(rng.next() as usize) % half_values.len()];
                                packed |= (h as u128) << (16 * lane);
                            }
                            st.set_vreg(r, packed as u64, (packed >> 64) as u64);
                        }

                        let mut acc = 0u128;
                        for lane in 0..4 {
                            let val = ((rng.next() % 33) as i64 - 16) as f32 * 0.5;
                            acc |= (val.to_bits() as u128) << (32 * lane);
                        }
                        st.set_vreg(RD as usize, acc as u64, (acc >> 64) as u64);

                        let op = if sub == 0 { "fmlal" } else { "fmlsl" };
                        let suffix = if top == 0 { "" } else { "2" };
                        batch.push((format!("{op}{suffix}_idx_q{q}_i{index}"), insn, st));
                    }
                }
            }
        }
    }

    run_batch("fmlal_indexed", batch);
}

/// AdvSIMD load/store single structure:
/// `0 Q 001101 post L R Rm opcode S size Rn Rt`. Rn=x1, Rt=v0.
fn enc_single_fields_regs(
    q: u32,
    post: u32,
    l: u32,
    r: u32,
    rm: u32,
    opcode: u32,
    s: u32,
    size: u32,
    rt: u32,
    rn: u32,
) -> u32 {
    (q << 30)
        | (0b001101 << 24)
        | (post << 23)
        | (l << 22)
        | (r << 21)
        | (rm << 16)
        | (opcode << 13)
        | (s << 12)
        | (size << 10)
        | ((rn & 0x1F) << 5)
        | (rt & 0x1F)
}

/// Single-element form for element-log2-size `esz` (0=B,1=H,2=S,3=D), structure
/// size `selem` (1-4), lane `index`, load `l`, and `post` index.
fn enc_single_regs(
    esz: u32,
    selem: u32,
    index: u32,
    l: u32,
    post: u32,
    rm: u32,
    rt: u32,
    rn: u32,
) -> u32 {
    let scale = if esz == 3 { 0b10 } else { esz };
    let lsb = ((selem - 1) >> 1) & 1;
    let r = (selem - 1) & 1;
    let opcode = (scale << 1) | lsb;
    let (q, s, size) = match esz {
        0 => ((index >> 3) & 1, (index >> 2) & 1, index & 3),
        1 => ((index >> 2) & 1, (index >> 1) & 1, (index & 1) << 1),
        2 => ((index >> 1) & 1, index & 1, 0),
        _ => (index & 1, 0, 1),
    };
    enc_single_fields_regs(q, post, l, r, rm, opcode, s, size, rt, rn)
}

fn enc_single(esz: u32, selem: u32, index: u32, l: u32, post: u32) -> u32 {
    let rm = if post == 1 { 31 } else { 0 };
    enc_single_regs(esz, selem, index, l, post, rm, RD, RN)
}

/// Replicating load LD1R-LD4R for element-log2-size `esz`, structure `selem`, Q.
fn enc_single_rep_regs(esz: u32, selem: u32, q: u32, post: u32, rm: u32, rt: u32, rn: u32) -> u32 {
    let lsb = ((selem - 1) >> 1) & 1;
    let r = (selem - 1) & 1;
    let opcode = (0b11 << 1) | lsb;
    enc_single_fields_regs(q, post, 1, r, rm, opcode, 0, esz, rt, rn)
}

fn enc_single_rep(esz: u32, selem: u32, q: u32, post: u32) -> u32 {
    let rm = if post == 1 { 31 } else { 0 };
    enc_single_rep_regs(esz, selem, q, post, rm, RD, RN)
}

#[test]
fn diff_mem_ldst_single() {
    let mut cases: Vec<(String, u32)> = Vec::new();
    for esz in 0..4u32 {
        let max_index = 16u32 >> esz; // B:16 H:8 S:4 D:2
        for selem in 1..=4u32 {
            for index in 0..max_index {
                for l in 0..2 {
                    let op = if l == 1 { "ld" } else { "st" };
                    cases.push((
                        format!("{op}{selem}_single e{esz} i{index}"),
                        enc_single(esz, selem, index, l, 0),
                    ));
                    cases.push((
                        format!("{op}{selem}_single e{esz} i{index} post"),
                        enc_single(esz, selem, index, l, 1),
                    ));
                }
            }
            // Replicating loads (LD1R-LD4R)
            for q in 0..2 {
                cases.push((
                    format!("ld{selem}r e{esz} q{q}"),
                    enc_single_rep(esz, selem, q, 0),
                ));
            }
        }
    }
    let mut rng = Rng::new(0x1_0005);
    let mut batch: Vec<(String, u32, ArmState)> = Vec::new();
    for (label, insn) in &cases {
        for _ in 0..3 {
            batch.push((label.clone(), *insn, mem_input(&mut rng)));
        }
    }
    run_batch("mem_ldst_single", batch);
}

