#[test]
fn diff_simd_fp16_frint_fpcr_rounding() {
    let values = [0xbe00u16, 0xb800, 0x3800, 0x3e00]; // -1.5, -0.5, 0.5, 1.5
    let mut batch = Vec::new();
    for &(u, a, name) in &[(1, 0, "frintx"), (1, 1, "frinti")] {
        for q in 0..2u32 {
            for rmode in 0..4u64 {
                let mut st = ArmState::zeroed();
                st.fpcr = rmode << 22;
                let lanes = if q == 0 { 4 } else { 8 };
                let mut packed = 0u128;
                for lane in 0..lanes {
                    packed |= (values[lane % values.len()] as u128) << (16 * lane);
                }
                st.set_vreg(RN as usize, packed as u64, (packed >> 64) as u64);
                batch.push((
                    format!("{name}_fp16_q{q}_rmode{rmode}"),
                    enc_fp16_2r(q, u, a, 0b11001),
                    st,
                ));
            }
        }
    }

    run_batch("simd_fp16_frint_fpcr_rounding", batch);
}

#[test]
fn diff_simd_cvtf_fpcr_rounding() {
    let mut batch: Vec<(String, u32, ArmState)> = Vec::new();
    for rmode in 0..4u64 {
        let fpcr = rmode << 22;

        let mut st = ArmState::zeroed();
        st.fpcr = fpcr;
        let h_lanes = [
            2_049u16,
            (-2_049i16) as u16,
            65_520u16,
            u16::MAX,
            2_049u16,
            (-2_049i16) as u16,
            65_520u16,
            u16::MAX,
        ];
        let mut packed = 0u128;
        for (lane, value) in h_lanes.iter().enumerate() {
            packed |= (*value as u128) << (16 * lane);
        }
        st.set_vreg(1, packed as u64, (packed >> 64) as u64);
        batch.push((
            format!("scvtf_h_rmode{rmode}"),
            enc_fp16_2r(1, 0, 0, 0b11101),
            st,
        ));
        batch.push((
            format!("ucvtf_h_rmode{rmode}"),
            enc_fp16_2r(1, 1, 0, 0b11101),
            st,
        ));

        let mut st = ArmState::zeroed();
        st.fpcr = fpcr;
        let s_lanes = [
            16_777_217u32,
            (-16_777_217i32) as u32,
            u32::MAX,
            16_777_217u32,
        ];
        let mut packed = 0u128;
        for (lane, value) in s_lanes.iter().enumerate() {
            packed |= (*value as u128) << (32 * lane);
        }
        st.set_vreg(1, packed as u64, (packed >> 64) as u64);
        batch.push((
            format!("scvtf_s_rmode{rmode}"),
            enc_two_reg(1, 0, 0, 0b11101),
            st,
        ));
        batch.push((
            format!("ucvtf_s_rmode{rmode}"),
            enc_two_reg(1, 1, 0, 0b11101),
            st,
        ));

        let mut st = ArmState::zeroed();
        st.fpcr = fpcr;
        let d_lanes = [9_007_199_254_740_993u64, (-9_007_199_254_740_993i64) as u64];
        let mut packed = 0u128;
        for (lane, value) in d_lanes.iter().enumerate() {
            packed |= (*value as u128) << (64 * lane);
        }
        st.set_vreg(1, packed as u64, (packed >> 64) as u64);
        batch.push((
            format!("scvtf_d_rmode{rmode}"),
            enc_two_reg(1, 0, 1, 0b11101),
            st,
        ));
        batch.push((
            format!("ucvtf_d_rmode{rmode}"),
            enc_two_reg(1, 1, 1, 0b11101),
            st,
        ));
    }

    run_batch("simd_cvtf_fpcr_rounding", batch);
}

