fn enc_xar(imm6: u32) -> u32 {
    0xce82_0020 | ((imm6 & 0x3f) << 10)
}

fn enc_crypto_ce(grp: u32, rm: u32, o: u32) -> u32 {
    0xCE00_0000 | ((grp & 0x7) << 21) | ((rm & 0x1F) << 16) | ((o & 0x3F) << 10) | (RN << 5) | RD
}

