#[test]
fn diff_simd_fcmla_fpcr_ah_nan_sign() {
    const FPCR_AH: u64 = 1 << 1;
    let mut batch = Vec::new();
    for (size, esz, qnan, one) in [
        (0b01u32, 2usize, 0x7e01u64, 0x3c00u64),
        (0b10, 4, 0x7fc0_2000u64, 1.0f32.to_bits() as u64),
        (0b11, 8, 0x7ff8_0000_0000_2000u64, 1.0f64.to_bits()),
    ] {
        for rot in 1..4u32 {
            let mut st = ArmState::zeroed();
            st.fpcr = FPCR_AH;
            let mut n = 0u128;
            let mut m = 0u128;
            for pair in 0..(16 / (2 * esz)) {
                let (a_re, a_im, b_re, b_im) = match rot {
                    1 => (0, one, one, qnan),
                    2 => (one, 0, qnan, qnan),
                    _ => (0, one, qnan, one),
                };
                n |= (a_re as u128) << ((2 * pair) * esz * 8);
                n |= (a_im as u128) << ((2 * pair + 1) * esz * 8);
                m |= (b_re as u128) << ((2 * pair) * esz * 8);
                m |= (b_im as u128) << ((2 * pair + 1) * esz * 8);
            }
            st.set_vreg(RD as usize, 0, 0);
            st.set_vreg(RN as usize, n as u64, (n >> 64) as u64);
            st.set_vreg(RM as usize, m as u64, (m >> 64) as u64);
            batch.push((
                format!("fcmla_s{size}_rot{rot}_ah_qnan"),
                enc_fcmla(1, size, rot),
                st,
            ));
        }
    }

    run_batch("simd_fcmla_fpcr_ah_nan_sign", batch);
}

#[test]
fn diff_simd_fcmla_f16_invalid_products() {
    fn pack_f16(lanes: [u16; 8]) -> (u64, u64) {
        let mut packed = 0u128;
        for (lane, value) in lanes.into_iter().enumerate() {
            packed |= (value as u128) << (lane * 16);
        }
        (packed as u64, (packed >> 64) as u64)
    }

    let mut batch = Vec::new();
    for q in 0..=1u32 {
        for rot in 0..4u32 {
            for (case_name, inf) in [("pos_inf", 0x7c00u16), ("neg_inf", 0xfc00)] {
                let rn = [
                    0x0000u16, 0x8000, 0x0000, 0x8000, 0x0000, 0x8000, 0x0000, 0x8000,
                ];
                let rm = [inf; 8];
                let rd = [0x3c00u16; 8];

                let mut st = ArmState::zeroed();
                let (lo, hi) = pack_f16(rd);
                st.set_vreg(RD as usize, lo, hi);
                let (lo, hi) = pack_f16(rn);
                st.set_vreg(RN as usize, lo, hi);
                let (lo, hi) = pack_f16(rm);
                st.set_vreg(RM as usize, lo, hi);
                batch.push((
                    format!("fcmla_f16_invalid_q{q}_r{rot}_{case_name}"),
                    enc_fcmla(q, 0b01, rot),
                    st,
                ));
            }
        }
    }

    run_batch("simd_fcmla_f16_invalid_products", batch);
}

#[test]
fn diff_fcmla_fpcr_ah_nan_priority_status() {
    const FPCR_AH: u64 = 1 << 1;
    let pack_pair = |re: u64, im: u64, esz: usize| -> (u64, u64) {
        let mut packed = 0u128;
        for pair in 0..(16 / (2 * esz)) {
            packed |= (re as u128) << ((2 * pair) * esz * 8);
            packed |= (im as u128) << ((2 * pair + 1) * esz * 8);
        }
        (packed as u64, (packed >> 64) as u64)
    };

    let mut batch = Vec::new();

    for &(label, simd_size, sve_size, esz, qnan, snan) in &[
        ("h", 0b01, 1, 2, 0x7e00u64, 0x7d01u64),
        ("s", 0b10, 2, 4, 0x7fc0_2000u64, 0x7fa0_0001u64),
        (
            "d",
            0b11,
            3,
            8,
            0x7ff8_0000_0000_2000u64,
            0x7ff0_0000_0000_0001u64,
        ),
    ] {
        let (lo, hi) = pack_pair(qnan, snan, esz);

        let mut st = ArmState::zeroed();
        st.fpcr = FPCR_AH;
        st.set_vreg(RD as usize, lo, hi);
        st.set_vreg(RN as usize, lo, hi);
        st.set_vreg(RM as usize, lo, hi);
        batch.push((
            format!("simd_fcmla_{label}_ah_nan_priority"),
            enc_fcmla(1, simd_size, 0),
            st,
        ));

        let mut st = ArmState::zeroed();
        st.fpcr = FPCR_AH;
        st.set_preg(0, 0xffff);
        st.set_vreg(RD as usize, lo, hi);
        st.set_vreg(RN as usize, lo, hi);
        st.set_vreg(RM as usize, lo, hi);
        batch.push((
            format!("sve_fcmla_{label}_ah_nan_priority"),
            enc_sve_fcmla(sve_size, 0),
            st,
        ));
    }

    for &(label, simd_size, sve_size, esz, qnan, snan) in &[
        ("h", 0b01, 2, 2, 0x7e00u64, 0x7d01u64),
        ("s", 0b10, 3, 4, 0x7fc0_2000u64, 0x7fa0_0001u64),
    ] {
        let (lo, hi) = pack_pair(qnan, snan, esz);

        let mut st = ArmState::zeroed();
        st.fpcr = FPCR_AH;
        st.set_vreg(RD as usize, lo, hi);
        st.set_vreg(RN as usize, lo, hi);
        st.set_vreg(RM as usize, lo, hi);
        batch.push((
            format!("simd_fcmla_idx_{label}_ah_nan_priority"),
            enc_fcmla_idx(1, simd_size, 0, 0),
            st,
        ));

        let mut st = ArmState::zeroed();
        st.fpcr = FPCR_AH;
        st.set_vreg(RD as usize, lo, hi);
        st.set_vreg(RN as usize, lo, hi);
        st.set_vreg(RM as usize, lo, hi);
        batch.push((
            format!("sve_fcmla_idx_{label}_ah_nan_priority"),
            enc_sve_fcmla_idx(sve_size, 0, RM, 0),
            st,
        ));
    }

    for &(label, simd_size, sve_size, esz, pattern) in &[
        (
            "s",
            0b10,
            2,
            4,
            0x3f80_0000_0000_0000_7f80_0000_0000_0001u128,
        ),
        (
            "d",
            0b11,
            3,
            8,
            0x3ff0_0000_0000_0000_7ff0_0000_0000_0000u128,
        ),
    ] {
        let mut st = ArmState::zeroed();
        st.fpcr = FPCR_AH;
        st.set_vreg(RD as usize, pattern as u64, (pattern >> 64) as u64);
        st.set_vreg(RN as usize, pattern as u64, (pattern >> 64) as u64);
        st.set_vreg(RM as usize, pattern as u64, (pattern >> 64) as u64);
        batch.push((
            format!("simd_fcmla_{label}_ah_subnormal_status"),
            enc_fcmla(1, simd_size, 0),
            st,
        ));

        let mut st = ArmState::zeroed();
        st.fpcr = FPCR_AH;
        st.set_preg(0, 0xffff);
        st.set_vreg(RD as usize, pattern as u64, (pattern >> 64) as u64);
        st.set_vreg(RN as usize, pattern as u64, (pattern >> 64) as u64);
        st.set_vreg(RM as usize, pattern as u64, (pattern >> 64) as u64);
        batch.push((
            format!("sve_fcmla_{label}_ah_subnormal_status"),
            enc_sve_fcmla(sve_size, 0),
            st,
        ));

        if esz == 4 {
            let mut st = ArmState::zeroed();
            st.fpcr = FPCR_AH;
            st.set_vreg(RD as usize, pattern as u64, (pattern >> 64) as u64);
            st.set_vreg(RN as usize, pattern as u64, (pattern >> 64) as u64);
            st.set_vreg(RM as usize, pattern as u64, (pattern >> 64) as u64);
            batch.push((
                "simd_fcmla_idx_s_ah_subnormal_status".to_string(),
                enc_fcmla_idx(1, simd_size, 0, 0),
                st,
            ));

            let mut st = ArmState::zeroed();
            st.fpcr = FPCR_AH;
            st.set_vreg(RD as usize, pattern as u64, (pattern >> 64) as u64);
            st.set_vreg(RN as usize, pattern as u64, (pattern >> 64) as u64);
            st.set_vreg(RM as usize, pattern as u64, (pattern >> 64) as u64);
            batch.push((
                "sve_fcmla_idx_s_ah_subnormal_status".to_string(),
                enc_sve_fcmla_idx(sve_size + 1, 0, RM, 0),
                st,
            ));
        }
    }

    run_batch("fcmla_fpcr_ah_nan_priority_status", batch);
}

