#[test]
fn diff_sve_lastx_xzr_dest() {
    let mut rng = Rng::new(0x1_0079);
    let mut batch: Vec<(String, u32, ArmState)> = Vec::new();

    fn predicate_bit(size: u32, lane: usize) -> u16 {
        1u16 << (lane * (1usize << size))
    }

    for size in 0..4u32 {
        let lasta = (0x05 << 24) | (size << 22) | (0b100000 << 16) | (0b101 << 13) | (RN << 5) | 31;
        let lastb = (0x05 << 24) | (size << 22) | (0b100001 << 16) | (0b101 << 13) | (RN << 5) | 31;
        let clasta =
            (0x05 << 24) | (size << 22) | (0b110000 << 16) | (0b101 << 13) | (RN << 5) | 31;
        let clastb =
            (0x05 << 24) | (size << 22) | (0b110001 << 16) | (0b101 << 13) | (RN << 5) | 31;
        for (name, insn) in [
            ("lasta_xzr", lasta),
            ("lastb_xzr", lastb),
            ("clasta_xzr", clasta),
            ("clastb_xzr", clastb),
        ] {
            for (i, pred) in [0xffffu16, 0x5555, 0x0001, 0x0000].into_iter().enumerate() {
                let mut st = ArmState::zeroed();
                st.sp = GUEST_STACK_ADDR + (GUEST_STACK_SIZE / 2) + 0x13000 + ((i as u64) << 4);
                st.set_vreg(RN as usize, rng.next(), rng.next());
                st.set_preg(0, pred);
                batch.push((format!("{name} sz{size}"), insn, st));
            }
            let lanes = 16usize >> size;
            let first = predicate_bit(size, 0);
            let last = predicate_bit(size, lanes - 1);
            for (case_name, pred, sp_delta) in [
                ("first", first, 0x80u64),
                ("last", last, 0x90),
                ("endpoints", first | last, 0xa0),
            ] {
                let mut st = ArmState::zeroed();
                st.sp = GUEST_STACK_ADDR
                    + (GUEST_STACK_SIZE / 2)
                    + 0x14000
                    + ((size as u64) << 8)
                    + sp_delta;
                st.set_vreg(RN as usize, 0x0123_4567_89ab_cdef, 0xfedc_ba98_7654_3210);
                st.set_preg(0, pred);
                batch.push((format!("{name}_sz{size}_{case_name}"), insn, st));
            }
        }
    }
    run_batch("sve_lastx_xzr_dest", batch);
}

#[test]
fn diff_sve_sincdecp() {
    // SQINCP/UQINCP/SQDECP/UQDECP: saturating INCP/DECP. GPR forms (32/64-bit,
    // signed/unsigned) and vector forms (per-element saturating). Seeds Xdn/Zdn
    // near the signed/unsigned limits to exercise the saturation boundaries.
    let mut rng = Rng::new(0x1_0030);
    let mut batch: Vec<(String, u32, ArmState)> = Vec::new();
    let gpr_vals: [u64; 12] = [
        0,
        1,
        u64::MAX,
        0x7FFF_FFFF,
        0x8000_0000,
        0xFFFF_FFFF,
        0x7FFF_FFFF_FFFF_FFFF,
        0x8000_0000_0000_0000,
        0xFFFF_FFFF_FFFF_FFF0,
        0x0000_0000_0000_0005,
        0xFFFF_FFFF_FFFF_FFFB,
        0x7FFF_FFFF_FFFF_FFFA,
    ];
    let vec_pats: [u64; 8] = [
        0x0000_0000_0000_0000,
        0x7FFF_7FFF_7FFF_7FFF,
        0x8000_8000_8000_8000,
        0xFFFF_FFFF_FFFF_FFFF,
        0x7FFF_FFFF_7FFF_FFFF,
        0x8000_0000_8000_0000,
        0x7FFF_FFFF_FFFF_FFFF,
        0x8000_0000_0000_0000,
    ];
    let preds = [0xFFFFu16, 0x5555, 0x0101, 0x0001, 0x0000];
    for esz in 0..4u32 {
        for d in 0..2u32 {
            for u in 0..2u32 {
                for sf64 in 0..2u32 {
                    let insn = enc_sve_sincdecp_r(esz, d, u, sf64, 1, 0);
                    let nm = format!("sincdecp_r e{esz} d{d} u{u} s{sf64}");
                    for &xv in gpr_vals.iter() {
                        for &pp in preds.iter() {
                            let mut st = ArmState::zeroed();
                            st.x[0] = xv;
                            st.set_preg(1, pp);
                            batch.push((nm.clone(), insn, st));
                        }
                    }
                    for _ in 0..4 {
                        let mut st = ArmState::zeroed();
                        st.x[0] = rng.next();
                        st.set_preg(1, rng.next() as u16);
                        batch.push((format!("{nm} rnd"), insn, st));
                    }
                }
                if esz >= 1 {
                    let insn = enc_sve_sincdecp_z(esz, d, u, 1, 0);
                    let nm = format!("sincdecp_z e{esz} d{d} u{u}");
                    for &vp in vec_pats.iter() {
                        for &pp in preds.iter() {
                            let mut st = ArmState::zeroed();
                            st.set_vreg(0, vp, vp);
                            st.set_preg(1, pp);
                            batch.push((nm.clone(), insn, st));
                        }
                    }
                    for _ in 0..4 {
                        let mut st = ArmState::zeroed();
                        st.set_vreg(0, rng.next(), rng.next());
                        st.set_preg(1, rng.next() as u16);
                        batch.push((format!("{nm} rnd"), insn, st));
                    }
                }
            }
        }
    }
    run_batch("sve_sincdecp", batch);
}

#[test]
fn diff_sve_sincdecp_xzr_dest() {
    let mut rng = Rng::new(0x1_0077);
    let mut batch: Vec<(String, u32, ArmState)> = Vec::new();

    fn predicate_bit(esz: u32, lane: usize) -> u16 {
        1u16 << (lane * (1usize << esz))
    }

    for esz in 0..4u32 {
        let lanes = 16usize >> esz;
        let last = predicate_bit(esz, lanes - 1);
        let endpoints = predicate_bit(esz, 0) | last;
        for d in 0..2u32 {
            for u in 0..2u32 {
                for sf64 in 0..2u32 {
                    let insn = enc_sve_sincdecp_r(esz, d, u, sf64, 1, 31);
                    for (i, pred) in [0xffffu16, 0x5555, 0x0001, 0x0000].into_iter().enumerate() {
                        let mut st = ArmState::zeroed();
                        st.sp =
                            GUEST_STACK_ADDR + (GUEST_STACK_SIZE / 2) + 0x11000 + ((i as u64) << 4);
                        st.set_preg(1, pred);
                        batch.push((format!("sincdecp_xzr e{esz} d{d} u{u} s{sf64}"), insn, st));
                    }
                    for (case_name, pred, sp_delta) in
                        [("last", last, 0x80u64), ("endpoints", endpoints, 0x90)]
                    {
                        let mut st = ArmState::zeroed();
                        st.sp = GUEST_STACK_ADDR
                            + (GUEST_STACK_SIZE / 2)
                            + 0x11200
                            + ((esz as u64) << 8)
                            + sp_delta;
                        st.set_preg(1, pred);
                        batch.push((
                            format!("sincdecp_xzr_e{esz}_d{d}_u{u}_s{sf64}_{case_name}"),
                            insn,
                            st,
                        ));
                    }
                    for i in 0..4 {
                        let mut st = ArmState::zeroed();
                        st.sp =
                            GUEST_STACK_ADDR + (GUEST_STACK_SIZE / 2) + 0x11100 + ((i as u64) << 4);
                        st.set_preg(1, rng.next() as u16);
                        batch.push((
                            format!("sincdecp_xzr_rnd e{esz} d{d} u{u} s{sf64}"),
                            insn,
                            st,
                        ));
                    }
                }
            }
        }
    }
    run_batch("sve_sincdecp_xzr_dest", batch);
}

#[test]
fn diff_scalar_fp_cmp() {
    // Scalar FP compares (FCMP/FCMPE incl. compare-with-zero, with the NaN ->
    // unordered NZCV), FCCMP/FCCMPE, FCSEL, half-precision arithmetic/compare/
    // FSQRT/FMADD, and more FP<->int conversions (round modes, x/w widths).
    let enc: &[u32] = &[
        0x1e212000, 0x1e612000, 0x1e212010, 0x1e202008, 0x1e602018, 0x1e210405, 0x1e21141a,
        0x1e22cc20, 0x1e62bc20, 0x1ee22820, 0x1ee20820, 0x1ee21820, 0x1ee24820, 0x1ee1c020,
        0x1ee12000, 0x1fc20c20, 0x1e780020, 0x9e390020, 0x1e280020, 0x9e710020, 0x1e240020,
        0x9e630020, 0x1e63c020, 0x1ee2c020,
    ];
    let sp: [u64; 12] = [
        0x7F800000_7F800000,
        0xFF800000_FF800000,
        0x7FC00000_7FC00000,
        0x7F800001_FF800001,
        0x00000001_80000001,
        0x80000000_00000000,
        0x3F800000_BF800000,
        0x7F7FFFFF_FF7FFFFF,
        0x7FF0000000000000,
        0x7C007E007C007E00,
        0x7FF8000000000000,
        0x4000_4000_4000_4000,
    ];
    let mut rng = Rng::new(0x1_003D);
    let mut batch: Vec<(String, u32, ArmState)> = Vec::new();
    for (k, &insn) in enc.iter().enumerate() {
        for (i, &v) in sp.iter().enumerate() {
            let mut st = ArmState::zeroed();
            st.set_vreg(0, v, 0);
            st.set_vreg(1, sp[(i + 3) % 12], 0);
            st.set_vreg(2, sp[(i + 5) % 12], 0);
            st.set_vreg(3, sp[(i + 7) % 12], 0);
            st.x[1] = v;
            st.pstate = rng.next() & 0xF000_0000;
            batch.push((format!("c{k}"), insn, st));
        }
        for _ in 0..8 {
            let mut st = ArmState::zeroed();
            for z in 0..4usize {
                st.set_vreg(z, rng.next(), rng.next());
            }
            st.x[1] = rng.next();
            st.pstate = rng.next() & 0xF000_0000;
            batch.push((format!("c{k} rnd"), insn, st));
        }
    }
    run_batch("scalar_fp_cmp", batch);
}

