/// SVE CPY immediate: `00000101 sz 01 Pg M sh imm8 Zd`. Pg=p0, Zd=z0.
fn enc_cpy_imm(sz: u32, m: u32, sh: u32, imm8: i32) -> u32 {
    (0x05 << 24)
        | (sz << 22)
        | (0b01 << 20)
        | (m << 14)
        | (sh << 13)
        | (((imm8 as u32) & 0xFF) << 5)
        | RD
}

fn enc_cpy_gpr(sz: u32, rn: u32) -> u32 {
    (0x05 << 24) | (sz << 22) | (0b101000 << 16) | (0b101 << 13) | ((rn & 0x1F) << 5) | RD
}

#[test]
fn diff_sve_cpy() {
    let mut rng = Rng::new(0x1_002D);
    let mut batch: Vec<(String, u32, ArmState)> = Vec::new();

    fn predicate_bit(sz: u32, lane: usize) -> u16 {
        1u16 << (lane * (1usize << sz))
    }

    for sz in 0..4u32 {
        // CPY immediate, merging and zeroing.
        for m in 0..2u32 {
            for sh in 0..2u32 {
                for imm8 in 0..=0xFFu32 {
                    let insn = enc_cpy_imm(sz, m, sh, imm8 as i32);
                    let mut st = ArmState::zeroed();
                    st.set_vreg(0, rng.next(), rng.next());
                    st.set_preg(0, rng.next() as u16);
                    batch.push((format!("cpyi sz{sz} m{m} sh{sh} imm{imm8:#04x}"), insn, st));
                }
            }
        }
        // CPY scalar GPR (Rn=x1) and SIMD scalar (Vn=v1), both merging.
        let cpyr = (0x05 << 24) | (sz << 22) | (0b101000 << 16) | (0b101 << 13) | (RN << 5) | RD;
        let cpyv = (0x05 << 24) | (sz << 22) | (0b100000 << 16) | (0b100 << 13) | (RN << 5) | RD;
        // DUP immediate broadcast.
        let dup = (0x25 << 24) | (sz << 22) | (0b111000 << 16) | (0b11 << 14) | (0x33 << 5) | RD;
        let dup2 = (0x25 << 24)
            | (sz << 22)
            | (0b111000 << 16)
            | (0b11 << 14)
            | (1 << 13)
            | (0xA1 << 5)
            | RD;
        for _ in 0..10 {
            let mut st = ArmState::zeroed();
            st.set_vreg(0, rng.next(), rng.next());
            st.x[1] = rng.next();
            st.set_preg(0, rng.next() as u16);
            batch.push((format!("cpyr sz{sz}"), cpyr, st));
            let mut st2 = ArmState::zeroed();
            st2.set_vreg(0, rng.next(), rng.next());
            st2.set_vreg(1, rng.next(), rng.next());
            st2.set_preg(0, rng.next() as u16);
            batch.push((format!("cpyv sz{sz}"), cpyv, st2));
            batch.push((format!("dup sz{sz}"), dup, ArmState::zeroed()));
            batch.push((format!("dup2 sz{sz}"), dup2, ArmState::zeroed()));
        }
        let lanes = 16usize >> sz;
        let first = predicate_bit(sz, 0);
        let last = predicate_bit(sz, lanes - 1);
        let masks = [
            ("all", 0xffff),
            ("first", first),
            ("last", last),
            ("inactive", 0x0000),
        ];
        for m in 0..2u32 {
            for sh in 0..2u32 {
                for imm8 in [0x00u32, 0x01, 0x7f, 0x80, 0xff] {
                    let insn = enc_cpy_imm(sz, m, sh, imm8 as i32);
                    for (mask_name, pg) in masks {
                        let mut st = ArmState::zeroed();
                        st.set_vreg(0, 0xdead_beef_dead_beef, 0xfeed_face_feed_face);
                        st.set_preg(0, pg);
                        batch.push((
                            format!("cpyi_sz{sz}_m{m}_sh{sh}_imm{imm8:02x}_{mask_name}"),
                            insn,
                            st,
                        ));
                    }
                }
            }
        }
        for (case_name, x1, v1) in [
            ("zero", 0u64, (0u64, 0u64)),
            ("ones", u64::MAX, (u64::MAX, u64::MAX)),
            (
                "sign",
                0x8000_0000_0000_0001,
                (0x8000_0000_7fff_ffff, 0xffff_0000_0000_0001),
            ),
            (
                "bytes",
                0x1122_3344_5566_7788,
                (0x0706_0504_0302_0100, 0x0f0e_0d0c_0b0a_0908),
            ),
        ] {
            for (mask_name, pg) in masks {
                let mut st = ArmState::zeroed();
                st.set_vreg(0, 0xdead_beef_dead_beef, 0xfeed_face_feed_face);
                st.x[RN as usize] = x1;
                st.set_preg(0, pg);
                batch.push((format!("cpyr_sz{sz}_{case_name}_{mask_name}"), cpyr, st));

                let mut st = ArmState::zeroed();
                st.set_vreg(0, 0xfeed_face_feed_face, 0xdead_beef_dead_beef);
                st.set_vreg(1, v1.0, v1.1);
                st.set_preg(0, pg);
                batch.push((format!("cpyv_sz{sz}_{case_name}_{mask_name}"), cpyv, st));
            }
        }
    }
    run_batch("sve_cpy", batch);
}

#[test]
fn diff_sve_cpy_sp_source() {
    let mut rng = Rng::new(0x1_0069);
    let mut batch: Vec<(String, u32, ArmState)> = Vec::new();

    fn predicate_bit(sz: u32, lane: usize) -> u16 {
        1u16 << (lane * (1usize << sz))
    }

    for sz in 0..4u32 {
        let insn = enc_cpy_gpr(sz, 31);
        for i in 0..10 {
            let mut st = ArmState::zeroed();
            st.sp = GUEST_STACK_ADDR + (GUEST_STACK_SIZE / 2) + ((i as u64) << 4);
            st.set_vreg(0, rng.next(), rng.next());
            st.set_preg(0, [0xffffu16, 0xaaaa, 0x5555, 0x1111][i % 4]);
            batch.push((format!("cpyr_sp sz{sz}"), insn, st));
        }
        let lanes = 16usize >> sz;
        let first = predicate_bit(sz, 0);
        let last = predicate_bit(sz, lanes - 1);
        for (case_name, pg, sp_delta) in [
            ("all", 0xffff, 0x00u64),
            ("first", first, 0x10),
            ("last", last, 0x20),
            ("inactive", 0x0000, 0x30),
        ] {
            let mut st = ArmState::zeroed();
            st.sp =
                GUEST_STACK_ADDR + (GUEST_STACK_SIZE / 2) + 0x18000 + ((sz as u64) << 8) + sp_delta;
            st.set_vreg(0, 0xdead_beef_dead_beef, 0xfeed_face_feed_face);
            st.set_preg(0, pg);
            batch.push((format!("cpyr_sp_sz{sz}_{case_name}"), insn, st));
        }
    }
    run_batch("sve_cpy_sp_source", batch);
}

#[test]
fn diff_sve_dup_sp_source() {
    fn dup_sp(sz: u32) -> u32 {
        (0x05 << 24) | (sz << 22) | (0b100000 << 16) | (0b001110 << 10) | (31 << 5) | RD
    }

    let mut rng = Rng::new(0x1_0075);
    let mut batch: Vec<(String, u32, ArmState)> = Vec::new();
    for sz in 0..4u32 {
        let insn = dup_sp(sz);
        for i in 0..10 {
            let mut st = ArmState::zeroed();
            st.sp = GUEST_STACK_ADDR + (GUEST_STACK_SIZE / 2) + 0xe000 + ((i as u64) << 4);
            st.set_vreg(0, rng.next(), rng.next());
            batch.push((format!("dup_sp sz{sz}"), insn, st));
        }
        for (case_name, sp_delta, z0) in [
            ("zeroish", 0x00u64, (0u64, 0u64)),
            ("ones", 0x10, (u64::MAX, u64::MAX)),
            (
                "bytes",
                0x20,
                (0x0706_0504_0302_0100, 0x0f0e_0d0c_0b0a_0908),
            ),
            ("sign", 0x30, (0x8000_0000_7fff_ffff, 0xffff_0000_0000_0001)),
        ] {
            let mut st = ArmState::zeroed();
            st.sp =
                GUEST_STACK_ADDR + (GUEST_STACK_SIZE / 2) + 0xe800 + ((sz as u64) << 8) + sp_delta;
            st.set_vreg(0, z0.0, z0.1);
            batch.push((format!("dup_sp_sz{sz}_{case_name}"), insn, st));
        }
    }
    run_batch("sve_dup_sp_source", batch);
}

#[test]
fn diff_sve_fp_unary() {
    // (top_byte, opc6, name). FABS/FNEG use 0x04; FSQRT/FRINT*/FRECPX use 0x65.
    fn pack_lanes(esize: usize, values: &[u64]) -> (u64, u64) {
        let bits = esize * 8;
        let mask = if bits == 64 {
            u64::MAX
        } else {
            (1u64 << bits) - 1
        };
        let lanes = 16 / esize;
        let mut packed = 0u128;
        for lane in 0..lanes {
            packed |= ((values[lane % values.len()] & mask) as u128) << (lane * bits);
        }
        (packed as u64, (packed >> 64) as u64)
    }

    let ops: &[(u32, u32, &str)] = &[
        (0x04, 0b011100, "fabs"),
        (0x04, 0b011101, "fneg"),
        (0x65, 0b001101, "fsqrt"),
        (0x65, 0b000000, "frintn"),
        (0x65, 0b000001, "frintp"),
        (0x65, 0b000010, "frintm"),
        (0x65, 0b000011, "frintz"),
        (0x65, 0b000100, "frinta"),
        (0x65, 0b000110, "frintx"),
        (0x65, 0b000111, "frinti"),
        (0x65, 0b001100, "frecpx"),
    ];
    let mut rng = Rng::new(0x1_002B);
    let mut batch: Vec<(String, u32, ArmState)> = Vec::new();
    for &(sz, esize) in &[(1u32, 16u32), (2, 32), (3, 64)] {
        let lanes = 128 / esize as usize;
        for &(top, opc6, name) in ops {
            let insn = (top << 24) | (sz << 22) | (opc6 << 16) | (0b101 << 13) | (RN << 5) | RD;
            for _ in 0..12 {
                let mut st = ArmState::zeroed();
                let (l0, h0) = fill_finite_fp(&mut rng, esize, lanes); // prior Zd (merge)
                let (l1, h1) = fill_finite_fp(&mut rng, esize, lanes); // source
                st.set_vreg(0, l0, h0);
                st.set_vreg(1, l1, h1);
                st.set_preg(0, rng.next() as u16);
                batch.push((format!("{name} sz{sz}"), insn, st));
            }
            let patterns: Vec<(&str, Vec<u64>)> = match sz {
                1 => vec![
                    (
                        "specials",
                        vec![
                            0x0000, 0x8000, 0x7c00, 0xfc00, 0x7e00, 0x7c01, 0x0001, 0x8001,
                        ],
                    ),
                    (
                        "finite",
                        vec![
                            0x3c00, 0xbc00, 0x4000, 0xc000, 0x3e00, 0xbe00, 0x4200, 0xc200,
                        ],
                    ),
                ],
                2 => vec![
                    (
                        "specials",
                        vec![
                            0.0f32.to_bits() as u64,
                            (-0.0f32).to_bits() as u64,
                            f32::INFINITY.to_bits() as u64,
                            f32::NEG_INFINITY.to_bits() as u64,
                        ],
                    ),
                    (
                        "nan_subnorm",
                        vec![0x7fc0_0000, 0x7f80_0001, 0x0000_0001, 0x8000_0001],
                    ),
                    (
                        "finite",
                        vec![
                            1.0f32.to_bits() as u64,
                            (-1.0f32).to_bits() as u64,
                            1.5f32.to_bits() as u64,
                            (-1.5f32).to_bits() as u64,
                        ],
                    ),
                ],
                _ => vec![
                    (
                        "specials",
                        vec![
                            0.0f64.to_bits(),
                            (-0.0f64).to_bits(),
                            f64::INFINITY.to_bits(),
                            f64::NEG_INFINITY.to_bits(),
                        ],
                    ),
                    (
                        "nan_subnorm",
                        vec![
                            0x7ff8_0000_0000_0000,
                            0x7ff0_0000_0000_0001,
                            1,
                            (1u64 << 63) | 1,
                        ],
                    ),
                    ("finite", vec![1.0f64.to_bits(), (-1.0f64).to_bits()]),
                ],
            };
            let mixed = match sz {
                1 => 0x1111,
                2 => 0x0101,
                _ => 0x0001,
            };
            for (pattern_name, values) in patterns {
                let (lo, hi) = pack_lanes(esize as usize / 8, &values);
                for (mask_name, pg) in [("all", 0xffff), ("mixed", mixed), ("inactive", 0x0000)] {
                    let mut st = ArmState::zeroed();
                    st.set_vreg(0, 0xdead_beef_dead_beef, 0xfeed_face_feed_face);
                    st.set_vreg(1, lo, hi);
                    st.set_preg(0, pg);
                    batch.push((
                        format!("{name}_sz{sz}_{pattern_name}_{mask_name}"),
                        insn,
                        st,
                    ));
                }
            }
        }
    }
    run_batch("sve_fp_unary", batch);
}

#[test]
fn diff_sve_fp_unary_unallocated_edges() {
    let invalid_ops = [(0b000101u32, "op5"), (0b001110, "op14"), (0b001111, "op15")];
    let mut rng = Rng::new(0x1_002b_1);
    let mut batch: Vec<(String, u32, ArmState)> = Vec::new();

    for size in 1..4u32 {
        for (opc6, name) in invalid_ops {
            let insn = (0x65 << 24) | (size << 22) | (opc6 << 16) | (0b101 << 13) | (RN << 5) | RD;
            for (pred_name, pred) in [("inactive", 0), ("active", u16::MAX)] {
                let mut st = gen_sve_input(&mut rng);
                st.set_preg(0, pred);
                batch.push((
                    format!("sve_fp_unary_{name}_unallocated_s{size}_{pred_name}"),
                    insn,
                    st,
                ));
            }
            for _ in 0..4 {
                batch.push((
                    format!("sve_fp_unary_{name}_unallocated_s{size}"),
                    insn,
                    gen_sve_input(&mut rng),
                ));
            }
        }
    }

    run_batch_el0_legality("sve_fp_unary_unallocated_edges", batch);
}

#[test]
fn diff_sve_frint_fpcr_rounding() {
    let mut batch = Vec::new();
    for &(opc6, name) in &[(0b000110, "frintx"), (0b000111, "frinti")] {
        for &(size, esize) in &[(1u32, 2usize), (2, 4), (3, 8)] {
            for rmode in 0..4u64 {
                let mut st = ArmState::zeroed();
                st.fpcr = rmode << 22;
                st.set_preg(0, 0xffff);
                let mut packed = 0u128;
                if esize == 2 {
                    let values = [0xbe00u16, 0xb800, 0x3800, 0x3e00];
                    for lane in 0..8 {
                        packed |= (values[lane % values.len()] as u128) << (16 * lane);
                    }
                } else if esize == 4 {
                    for (lane, value) in [-1.5f32, -0.5, 0.5, 1.5].iter().enumerate() {
                        packed |= ((*value).to_bits() as u128) << (32 * lane);
                    }
                } else {
                    for (lane, value) in [-1.5f64, 1.5].iter().enumerate() {
                        packed |= ((*value).to_bits() as u128) << (64 * lane);
                    }
                }
                st.set_vreg(RN as usize, packed as u64, (packed >> 64) as u64);
                batch.push((
                    format!("{name}_sve_size{size}_rmode{rmode}"),
                    (0x65 << 24) | (size << 22) | (opc6 << 16) | (0b101 << 13) | (RN << 5) | RD,
                    st,
                ));
            }
        }
    }

    run_batch("sve_frint_fpcr_rounding", batch);
}

#[test]
fn diff_fpcr_fiz_sve_frint_subnormal_inputs() {
    const FPCR_FIZ: u64 = 1;
    let mut batch: Vec<(String, u32, ArmState)> = Vec::new();

    for &(opc6, name) in &[(0b000001, "frintp"), (0b000110, "frintx")] {
        let mut st = ArmState::zeroed();
        st.fpcr = FPCR_FIZ;
        st.set_preg(0, 0xffff);
        let s = 0x0000_0001u32;
        let z = (s as u128) | ((s as u128) << 32) | ((s as u128) << 64) | ((s as u128) << 96);
        st.set_vreg(RN as usize, z as u64, (z >> 64) as u64);
        batch.push((
            format!("sve_{name}_s_fiz_min_subnorm"),
            (0x65 << 24) | (2 << 22) | (opc6 << 16) | (0b101 << 13) | (RN << 5) | RD,
            st,
        ));

        let mut st = ArmState::zeroed();
        st.fpcr = FPCR_FIZ;
        st.set_preg(0, 0xffff);
        let d = 0x0000_0000_0000_0001u64;
        let z = (d as u128) | ((d as u128) << 64);
        st.set_vreg(RN as usize, z as u64, (z >> 64) as u64);
        batch.push((
            format!("sve_{name}_d_fiz_min_subnorm"),
            (0x65 << 24) | (3 << 22) | (opc6 << 16) | (0b101 << 13) | (RN << 5) | RD,
            st,
        ));
    }

    run_batch("fpcr_fiz_sve_frint_subnormal_inputs", batch);
}

