/// SVE integer reduction: `00000100 sz opc6 001 Pg Zn Vd`. Zn=z1, Vd=v0, Pg=p0.
fn enc_sve_reduce(sz: u32, opc6: u32) -> u32 {
    (0x04 << 24) | (sz << 22) | (opc6 << 16) | (0b001 << 13) | (RN << 5) | RD
}

#[test]
fn diff_sve_reduce() {
    fn pack_lanes(sz: u32, values: &[u64]) -> (u64, u64) {
        let bits = 8u32 << sz;
        let mask = if bits == 64 {
            u64::MAX
        } else {
            (1u64 << bits) - 1
        };
        let mut packed = 0u128;
        for (lane, value) in values.iter().enumerate() {
            packed |= ((*value & mask) as u128) << (lane * bits as usize);
        }
        (packed as u64, (packed >> 64) as u64)
    }

    fn edge_patterns(sz: u32) -> [(&'static str, Vec<u64>); 3] {
        let bits = 8u32 << sz;
        let lanes = 16usize >> sz;
        let mask = if bits == 64 {
            u64::MAX
        } else {
            (1u64 << bits) - 1
        };
        let sign = 1u64 << (bits - 1);
        let signed = [0, 1, sign - 1, sign, mask];
        let bitmix = [
            mask & 0x5555_5555_5555_5555,
            mask & 0xaaaa_aaaa_aaaa_aaaa,
            mask & 0x0f0f_0f0f_0f0f_0f0f,
            mask & 0xf0f0_f0f0_f0f0_f0f0,
        ];
        [
            ("zeros", vec![0; lanes]),
            (
                "signed_extremes",
                (0..lanes).map(|lane| signed[lane % signed.len()]).collect(),
            ),
            (
                "bitmix",
                (0..lanes).map(|lane| bitmix[lane % bitmix.len()]).collect(),
            ),
        ]
    }

    // (opc6, name, max_sz)
    let ops: &[(u32, &str, u32)] = &[
        (0b000000, "saddv", 2),
        (0b000001, "uaddv", 3),
        (0b001000, "smaxv", 3),
        (0b001001, "umaxv", 3),
        (0b001010, "sminv", 3),
        (0b001011, "uminv", 3),
        (0b011000, "orv", 3),
        (0b011001, "eorv", 3),
        (0b011010, "andv", 3),
    ];
    let mut rng = Rng::new(0x1_0029);
    let mut batch: Vec<(String, u32, ArmState)> = Vec::new();
    for &(opc6, name, max_sz) in ops {
        for sz in 0..=max_sz {
            let insn = enc_sve_reduce(sz, opc6);
            for _ in 0..14 {
                let mut st = ArmState::zeroed();
                st.set_vreg(1, rng.next(), rng.next());
                st.set_preg(0, rng.next() as u16);
                batch.push((format!("{name} sz{sz}"), insn, st));
            }
        }
    }
    for &(opc6, name, max_sz) in ops {
        for sz in 0..=max_sz {
            let insn = enc_sve_reduce(sz, opc6);
            let mixed = match sz {
                0 => 0x5555,
                1 => 0x1111,
                2 => 0x0101,
                _ => 0x0001,
            };
            for (pattern_name, values) in edge_patterns(sz) {
                for (mask_name, pg) in [("all", 0xffff), ("mixed", mixed), ("inactive", 0x0000)] {
                    let mut st = ArmState::zeroed();
                    let (lo, hi) = pack_lanes(sz, &values);
                    st.set_vreg(1, lo, hi);
                    st.set_preg(0, pg);
                    batch.push((
                        format!("{name}_sz{sz}_{pattern_name}_{mask_name}"),
                        insn,
                        st,
                    ));
                }
            }
        }
    }
    run_batch("sve_reduce", batch);
}

/// SVE predicate-logical: `00100101 S000 Pm 01 Pg b9 Pn b4 Pd`. Pg=p1, Pm=p2,
/// Pn=p3, Pd=p0.
fn enc_sve_plog(s: u32, b9: u32, b4: u32) -> u32 {
    (0x25 << 24)
        | (s << 23)
        | (2 << 16)
        | (0b01 << 14)
        | (1 << 10)
        | (b9 << 9)
        | (3 << 5)
        | (b4 << 4)
}

#[test]
fn diff_sve_plog() {
    let ops: &[(u32, u32, u32, &str)] = &[
        (0, 0, 0, "and"),
        (0, 0, 1, "bic"),
        (0, 1, 0, "eor"),
        (1, 0, 0, "orr"),
        (1, 0, 1, "orn"),
        (1, 1, 0, "nor"),
        (1, 1, 1, "nand"),
    ];
    let mut rng = Rng::new(0x1_0028);
    let mut batch: Vec<(String, u32, ArmState)> = Vec::new();
    for &(s, b9, b4, name) in ops {
        let insn = enc_sve_plog(s, b9, b4);
        for _ in 0..16 {
            let mut st = ArmState::zeroed();
            st.set_preg(1, rng.next() as u16);
            st.set_preg(2, rng.next() as u16);
            st.set_preg(3, rng.next() as u16);
            batch.push((format!("p{name}"), insn, st));
        }
        for (case_name, pg, pm, pn) in [
            ("all_guard", 0xffff, 0x5555, 0x3333),
            ("striped_guard", 0x0f0f, 0xaaaa, 0xcccc),
            ("inactive_guard", 0x0000, 0xffff, 0x5555),
            ("singletons", 0x8421, 0x1111, 0x8888),
        ] {
            let mut st = ArmState::zeroed();
            st.set_preg(0, 0xdead);
            st.set_preg(1, pg);
            st.set_preg(2, pm);
            st.set_preg(3, pn);
            batch.push((format!("p{name}_{case_name}"), insn, st));
        }
    }
    run_batch("sve_plog", batch);
}

/// SVE predicated FP binary arith: `01100101 sz opc5 100 Pg Zm Zdn`. Zdn=z0,
/// Zm=z1, Pg=p0.
fn enc_sve_fpp(sz: u32, opc5: u32) -> u32 {
    (0x65 << 24) | (sz << 22) | (opc5 << 16) | (0b100 << 13) | (RN << 5) | RD
}

/// SVE predicated FP binary immediate: `01100101 sz opc5 100 Pg imm Zdn`.
/// Zdn=z0, Pg=p0.
fn enc_sve_fpp_imm(sz: u32, opc5: u32, imm1: u32) -> u32 {
    (0x65 << 24) | (sz << 22) | (opc5 << 16) | (0b100 << 13) | ((imm1 & 1) << 5) | RD
}

/// SVE unpredicated FADD/FSUB/FMUL: `01100101 size 0 Zm 0000 opc Zn Zd`.
/// Zn=z1(RN), Zm=z2(RM), Zd=z0(RD).
fn enc_sve_fp_arith(size: u32, opc: u32) -> u32 {
    (0x65 << 24) | (size << 22) | (RM << 16) | (opc << 10) | (RN << 5) | RD
}

#[test]
fn diff_sve_fp_arith_fpcr_rounding() {
    let mut batch: Vec<(String, u32, ArmState)> = Vec::new();
    for rmode in 0..4u64 {
        let fpcr = rmode << 22;

        for &(opc, name, lhs, rhs) in &[
            (0b00, "fadd_pos", 16_777_216.0f32, 1.0f32),
            (0b00, "fadd_neg", -16_777_216.0f32, -1.0f32),
            (0b01, "fsub_pos", 16_777_216.0f32, -1.0f32),
            (0b01, "fsub_neg", -16_777_216.0f32, 1.0f32),
        ] {
            let mut st = ArmState::zeroed();
            st.fpcr = fpcr;
            let mut n = 0u128;
            let mut m = 0u128;
            for lane in 0..4 {
                n |= (lhs.to_bits() as u128) << (32 * lane);
                m |= (rhs.to_bits() as u128) << (32 * lane);
            }
            st.set_vreg(RN as usize, n as u64, (n >> 64) as u64);
            st.set_vreg(RM as usize, m as u64, (m >> 64) as u64);
            batch.push((
                format!("{name}_s_rmode{rmode}"),
                enc_sve_fp_arith(2, opc),
                st,
            ));
        }

        let mut st = ArmState::zeroed();
        st.fpcr = fpcr;
        let lhs = f32::from_bits(0x3f80_0001);
        let rhs = f32::from_bits(0x3f80_0001);
        let mut n = 0u128;
        let mut m = 0u128;
        for lane in 0..4 {
            n |= (lhs.to_bits() as u128) << (32 * lane);
            m |= (rhs.to_bits() as u128) << (32 * lane);
        }
        st.set_vreg(RN as usize, n as u64, (n >> 64) as u64);
        st.set_vreg(RM as usize, m as u64, (m >> 64) as u64);
        batch.push((
            format!("fmul_s_rmode{rmode}"),
            enc_sve_fp_arith(2, 0b10),
            st,
        ));

        for &(opc, name, lhs, rhs) in &[
            (0b00, "fadd_pos", 9_007_199_254_740_992.0f64, 1.0f64),
            (0b00, "fadd_neg", -9_007_199_254_740_992.0f64, -1.0f64),
            (0b01, "fsub_pos", 9_007_199_254_740_992.0f64, -1.0f64),
            (0b01, "fsub_neg", -9_007_199_254_740_992.0f64, 1.0f64),
        ] {
            let mut st = ArmState::zeroed();
            st.fpcr = fpcr;
            let mut n = 0u128;
            let mut m = 0u128;
            for lane in 0..2 {
                n |= (lhs.to_bits() as u128) << (64 * lane);
                m |= (rhs.to_bits() as u128) << (64 * lane);
            }
            st.set_vreg(RN as usize, n as u64, (n >> 64) as u64);
            st.set_vreg(RM as usize, m as u64, (m >> 64) as u64);
            batch.push((
                format!("{name}_d_rmode{rmode}"),
                enc_sve_fp_arith(3, opc),
                st,
            ));
        }

        let mut st = ArmState::zeroed();
        st.fpcr = fpcr;
        let lhs = f64::from_bits(0x3ff0_0000_0000_0001);
        let rhs = f64::from_bits(0x3ff0_0000_0000_0001);
        let mut n = 0u128;
        let mut m = 0u128;
        for lane in 0..2 {
            n |= (lhs.to_bits() as u128) << (64 * lane);
            m |= (rhs.to_bits() as u128) << (64 * lane);
        }
        st.set_vreg(RN as usize, n as u64, (n >> 64) as u64);
        st.set_vreg(RM as usize, m as u64, (m >> 64) as u64);
        batch.push((
            format!("fmul_d_rmode{rmode}"),
            enc_sve_fp_arith(3, 0b10),
            st,
        ));
    }

    run_batch("sve_fp_arith_fpcr_rounding", batch);
}

