#[test]
fn diff_sve_fp_pred() {
    fn pack_lanes(esize: u32, values: &[u64]) -> (u64, u64) {
        let mut packed = 0u128;
        let mask = if esize == 64 {
            u64::MAX
        } else {
            (1u64 << esize) - 1
        };
        for (lane, value) in values.iter().enumerate() {
            packed |= ((*value & mask) as u128) << (lane * esize as usize);
        }
        (packed as u64, (packed >> 64) as u64)
    }

    let ops: &[(u32, &str)] = &[
        (0b00000, "fadd"),
        (0b00001, "fsub"),
        (0b00010, "fmul"),
        (0b00011, "fsubr"),
        (0b00100, "fmaxnm"),
        (0b00101, "fminnm"),
        (0b00110, "fmax"),
        (0b00111, "fmin"),
        (0b01000, "fabd"),
        (0b01010, "fmulx"),
        (0b01100, "fdivr"),
        (0b01101, "fdiv"),
    ];
    let mut rng = Rng::new(0x1_0027);
    let mut batch: Vec<(String, u32, ArmState)> = Vec::new();
    for &(sz, esize) in &[(1u32, 16u32), (2, 32), (3, 64)] {
        let lanes = 128 / esize as usize;
        for &(opc5, name) in ops {
            let insn = enc_sve_fpp(sz, opc5);
            for _ in 0..14 {
                let mut st = ArmState::zeroed();
                let (l0, h0) = fill_finite_fp(&mut rng, esize, lanes);
                let (l1, h1) = fill_finite_fp(&mut rng, esize, lanes);
                st.set_vreg(0, l0, h0);
                st.set_vreg(1, l1, h1);
                st.set_preg(0, rng.next() as u16);
                batch.push((format!("{name} sz{sz}"), insn, st));
            }
        }
    }
    for &(sz, esize) in &[(1u32, 16u32), (2, 32), (3, 64)] {
        let (mixed, patterns): (u16, Vec<(&str, Vec<u64>, Vec<u64>)>) = match sz {
            1 => (
                0x1111,
                vec![
                    (
                        "h_basic",
                        vec![
                            0x3c00, 0xbc00, 0x4000, 0xc000, 0x3800, 0xb800, 0x4200, 0xc200,
                        ],
                        vec![
                            0x3e00, 0xbe00, 0x4100, 0xc100, 0x3555, 0xb555, 0x4480, 0xc480,
                        ],
                    ),
                    (
                        "h_lane_mix",
                        vec![
                            0x3c00, 0x4000, 0xbc00, 0xc000, 0x3800, 0xb800, 0x4200, 0xc200,
                        ],
                        vec![
                            0x3e00, 0xbe00, 0x4100, 0xc100, 0x3555, 0xb555, 0x4480, 0xc480,
                        ],
                    ),
                ],
            ),
            2 => (
                0x0101,
                vec![
                    (
                        "s_basic",
                        vec![
                            1.0f32.to_bits() as u64,
                            (-1.0f32).to_bits() as u64,
                            2.0f32.to_bits() as u64,
                            (-2.0f32).to_bits() as u64,
                        ],
                        vec![
                            1.5f32.to_bits() as u64,
                            (-2.5f32).to_bits() as u64,
                            3.5f32.to_bits() as u64,
                            (-4.5f32).to_bits() as u64,
                        ],
                    ),
                    (
                        "s_lane_mix",
                        vec![
                            16.0f32.to_bits() as u64,
                            (-16.0f32).to_bits() as u64,
                            0.25f32.to_bits() as u64,
                            (-0.25f32).to_bits() as u64,
                        ],
                        vec![
                            0.5f32.to_bits() as u64,
                            (-0.75f32).to_bits() as u64,
                            4.0f32.to_bits() as u64,
                            (-8.0f32).to_bits() as u64,
                        ],
                    ),
                ],
            ),
            _ => (
                0x0001,
                vec![
                    (
                        "d_basic",
                        vec![1.0f64.to_bits(), (-1.0f64).to_bits()],
                        vec![1.5f64.to_bits(), (-2.5f64).to_bits()],
                    ),
                    (
                        "d_lane_mix",
                        vec![16.0f64.to_bits(), (-16.0f64).to_bits()],
                        vec![0.25f64.to_bits(), (-0.75f64).to_bits()],
                    ),
                ],
            ),
        };
        for &(opc5, name) in ops {
            let insn = enc_sve_fpp(sz, opc5);
            for (pattern_name, zdn, zm) in &patterns {
                for (mask_name, pg) in [("all", 0xffff), ("mixed", mixed), ("inactive", 0x0000)] {
                    let mut st = ArmState::zeroed();
                    let (lo, hi) = pack_lanes(esize, zdn);
                    st.set_vreg(0, lo, hi);
                    let (lo, hi) = pack_lanes(esize, zm);
                    st.set_vreg(1, lo, hi);
                    st.set_preg(0, pg);
                    batch.push((format!("{name}_{pattern_name}_{mask_name}"), insn, st));
                }
            }
        }
    }
    for &(sz, esize) in &[(1u32, 16u32), (2, 32), (3, 64)] {
        let (mixed, patterns): (u16, Vec<(&str, Vec<u64>, Vec<u64>)>) = match sz {
            1 => (
                0x1111,
                vec![
                    (
                        "h_nan_inf",
                        vec![
                            0x7c01, 0x7e00, 0x7c00, 0x8000, 0xfc01, 0xfe00, 0xfc00, 0x0000,
                        ],
                        vec![
                            0x3c00, 0xfc00, 0x7e00, 0x0000, 0xbc00, 0x7c00, 0xfc01, 0x8000,
                        ],
                    ),
                    (
                        "h_inactive_snan",
                        vec![
                            0x3c00, 0x7c01, 0xbc00, 0xfc01, 0x7c00, 0x0000, 0xfc00, 0x8000,
                        ],
                        vec![
                            0x4000, 0x7e00, 0xc000, 0xfe00, 0xfc00, 0x8000, 0x7c00, 0x0000,
                        ],
                    ),
                ],
            ),
            2 => (
                0x0101,
                vec![
                    (
                        "s_nan_inf",
                        vec![0x7f80_0001, 0x7fc0_0000, 0x7f80_0000, 0x8000_0000],
                        vec![1.0f32.to_bits() as u64, 0xff80_0000, 0x7fc0_0000, 0],
                    ),
                    (
                        "s_inactive_snan",
                        vec![
                            3.0f32.to_bits() as u64,
                            0x7f80_0001,
                            (-4.0f32).to_bits() as u64,
                            0xff80_0001,
                        ],
                        vec![0x4000_0000, 0x7fc0_0000, 0xc000_0000, 0xffc0_0000],
                    ),
                ],
            ),
            _ => (
                0x0001,
                vec![
                    (
                        "d_nan_inf",
                        vec![0x7ff0_0000_0000_0001, 0x7ff8_0000_0000_0000],
                        vec![1.0f64.to_bits(), 0xfff0_0000_0000_0000],
                    ),
                    (
                        "d_inactive_snan",
                        vec![(-4.0f64).to_bits(), 0x7ff0_0000_0000_0001],
                        vec![0x4000_0000_0000_0000, 0x7ff8_0000_0000_0000],
                    ),
                ],
            ),
        };
        for &(opc5, name) in ops {
            let insn = enc_sve_fpp(sz, opc5);
            for (pattern_name, zdn, zm) in &patterns {
                for (mask_name, pg) in [("all", 0xffff), ("mixed", mixed), ("inactive", 0x0000)] {
                    let mut st = ArmState::zeroed();
                    let (lo, hi) = pack_lanes(esize, zdn);
                    st.set_vreg(0, lo, hi);
                    let (lo, hi) = pack_lanes(esize, zm);
                    st.set_vreg(1, lo, hi);
                    st.set_preg(0, pg);
                    batch.push((format!("{name}_{pattern_name}_{mask_name}"), insn, st));
                }
            }
        }
    }
    run_batch("sve_fp_pred", batch);
}

