    let mut zn = 0u128;
    let mut zm = 0u128;
    for lane in 0..8 {
        zn |= (0x7e01u128) << (16 * lane); // positive quiet NaN
        zm |= (0x3c00u128) << (16 * lane); // 1.0
    }
    st.set_vreg(0, 0, 0);
