#[test]
fn diff_sve_bfmlal_indexed_fpcr_rounding() {
    let mut batch: Vec<(String, u32, ArmState)> = Vec::new();
    let variants = [
        ("pos", 16_777_216.0f32, 0x3f80u16),
        ("neg", -16_777_216.0f32, 0xbf80u16),
    ];

    for rmode in 0..4u64 {
        for top in 0..2u32 {
            for index in 0..8u32 {
                for (name, acc, n_bf16) in variants {
                    let mut zd = 0u128;
                    let mut zn = 0u128;
                    let mut zm = 0u128;
                    for s in 0..4 {
                        zd |= (acc.to_bits() as u128) << (s * 32);
                    }
                    for h in 0..8 {
                        zn |= (n_bf16 as u128) << (h * 16);
                        zm |= (0x3f80u128) << (h * 16);
                    }

                    let mut st = ArmState::zeroed();
                    st.fpcr = rmode << 22;
                    st.set_vreg(0, zd as u64, (zd >> 64) as u64);
                    st.set_vreg(1, zn as u64, (zn >> 64) as u64);
                    st.set_vreg(2, zm as u64, (zm >> 64) as u64);
                    batch.push((
                        format!("bfmlal_idx_t{top}_i{index}_{name}_rmode{rmode}"),
                        enc_sve_bfmlal_idx(top, index, RM),
                        st,
                    ));
                }
            }
        }
    }

    run_batch("sve_bfmlal_indexed_fpcr_rounding", batch);
}

#[test]
fn diff_fpcr_fiz_sve_bfmlal_indexed_subnormal_inputs() {
    const FPCR_FIZ: u64 = 1;
    let mut batch: Vec<(String, u32, ArmState)> = Vec::new();

    for top in 0..2u32 {
        for index in 0..8u32 {
            let mut product = ArmState::zeroed();
            product.fpcr = FPCR_FIZ;
            let mut zn = 0u128;
            let mut zm = 0u128;
            for lane in 0..8 {
                zn |= 0x0001u128 << (16 * lane);
                zm |= 0x3f80u128 << (16 * lane);
            }
            product.set_vreg(RD as usize, 0, 0);
            product.set_vreg(RN as usize, zn as u64, (zn >> 64) as u64);
            product.set_vreg(RM as usize, zm as u64, (zm >> 64) as u64);
            batch.push((
                format!("bfmlal_idx_t{top}_i{index}_product_min_subnorm"),
                enc_sve_bfmlal_idx(top, index, RM),
                product,
            ));

            let mut acc_state = ArmState::zeroed();
            acc_state.fpcr = FPCR_FIZ;
            let mut acc = 0u128;
            for lane in 0..4 {
                acc |= 0x0000_0001u128 << (32 * lane);
            }
            acc_state.set_vreg(RD as usize, acc as u64, (acc >> 64) as u64);
            acc_state.set_vreg(RN as usize, 0, 0);
            acc_state.set_vreg(RM as usize, zm as u64, (zm >> 64) as u64);
            batch.push((
                format!("bfmlal_idx_t{top}_i{index}_acc_min_subnorm"),
                enc_sve_bfmlal_idx(top, index, RM),
                acc_state,
            ));
        }
    }

    run_batch("fpcr_fiz_sve_bfmlal_indexed_subnormal_inputs", batch);
}

#[test]
fn diff_fpcr_fz_sve_bfmlal_subnormal_inputs() {
    const FPCR_FZ: u64 = 1 << 24;
    let mut batch: Vec<(String, u32, ArmState)> = Vec::new();

    for top in 0..2u32 {
        let mut product = ArmState::zeroed();
        product.fpcr = FPCR_FZ;
        let mut zn = 0u128;
        let mut zm = 0u128;
        for lane in 0..8 {
            zn |= 0x0001u128 << (16 * lane);
            zm |= 0x3f80u128 << (16 * lane);
        }
        product.set_vreg(RD as usize, 0, 0);
        product.set_vreg(RN as usize, zn as u64, (zn >> 64) as u64);
        product.set_vreg(RM as usize, zm as u64, (zm >> 64) as u64);
        batch.push((
            format!("bfmlal_t{top}_product_min_subnorm"),
            enc_sve_bfmlal(top, RM),
            product,
        ));

        let mut acc_state = ArmState::zeroed();
        acc_state.fpcr = FPCR_FZ;
        let mut acc = 0u128;
        for lane in 0..4 {
            acc |= 0x0000_0001u128 << (32 * lane);
        }
        acc_state.set_vreg(RD as usize, acc as u64, (acc >> 64) as u64);
        acc_state.set_vreg(RN as usize, 0, 0);
        acc_state.set_vreg(RM as usize, zm as u64, (zm >> 64) as u64);
        batch.push((
            format!("bfmlal_t{top}_acc_min_subnorm"),
            enc_sve_bfmlal(top, RM),
            acc_state,
        ));

        for index in 0..8u32 {
            let mut product = ArmState::zeroed();
            product.fpcr = FPCR_FZ;
            product.set_vreg(RD as usize, 0, 0);
            product.set_vreg(RN as usize, zn as u64, (zn >> 64) as u64);
            product.set_vreg(RM as usize, zm as u64, (zm >> 64) as u64);
            batch.push((
                format!("bfmlal_idx_t{top}_i{index}_product_min_subnorm"),
                enc_sve_bfmlal_idx(top, index, RM),
                product,
            ));

            let mut acc_state = ArmState::zeroed();
            acc_state.fpcr = FPCR_FZ;
            acc_state.set_vreg(RD as usize, acc as u64, (acc >> 64) as u64);
            acc_state.set_vreg(RN as usize, 0, 0);
            acc_state.set_vreg(RM as usize, zm as u64, (zm >> 64) as u64);
            batch.push((
                format!("bfmlal_idx_t{top}_i{index}_acc_min_subnorm"),
                enc_sve_bfmlal_idx(top, index, RM),
                acc_state,
            ));
        }
    }

    let mut output_tiny = ArmState::zeroed();
    output_tiny.fpcr = FPCR_FZ;
    output_tiny.set_vreg(RD as usize, 0x0000_0000_8000_0000, 0);
    output_tiny.set_vreg(RN as usize, 0x0000_0000_0d8d_3316, 0);
    output_tiny.set_vreg(RM as usize, 0x63b9_e7a3_a89b_d681, 0x0000_0000_0000_00d9);
    batch.push((
        "bfmlalt_output_tiny_fz".to_string(),
        enc_sve_bfmlal(1, RM),
        output_tiny,
    ));

    run_batch("fpcr_fz_sve_bfmlal_subnormal_inputs", batch);
}

#[test]
fn diff_sve2_fmlal_indexed() {
    // FMLALB/T and FMLSLB/T by indexed Zm.h[index] (broadcast), all indices.
    let mut rng = Rng::new(0x7_c001);
    let mut batch: Vec<(String, u32, ArmState)> = Vec::new();
    for sub in 0..2u32 {
        for top in 0..2u32 {
            for index in 0..8u32 {
                let insn = enc_sve2_fmlal_idx(sub, top, index, RM);
                for _ in 0..3 {
                    let (mut zn, mut zm, mut za) = (0u128, 0u128, 0u128);
                    for h in 0..8 {
                        zn |= (finite_fp_bits(&mut rng, 2) as u128) << (h * 16);
                        zm |= (finite_fp_bits(&mut rng, 2) as u128) << (h * 16);
                    }
                    for s in 0..4 {
                        za |= (finite_fp_bits(&mut rng, 4) as u128) << (s * 32);
                    }
                    let mut st = ArmState::zeroed();
                    st.set_vreg(1, zn as u64, (zn >> 64) as u64);
                    st.set_vreg(2, zm as u64, (zm >> 64) as u64);
                    st.set_vreg(0, za as u64, (za >> 64) as u64);
                    batch.push((format!("fmlal_idx sub{sub} t{top} i{index}"), insn, st));
                }
                let zn_lanes = [
                    0x7c01u16, 0x7e00, 0x7c00, 0xfc00, 0x0000, 0x8000, 0x3c00, 0xbc00,
                ];
                let zm_lanes = [
                    0x7c01u16, 0x7e00, 0x7c00, 0xfc00, 0x0000, 0x8000, 0x3c00, 0xbc00,
                ];
                let za_lanes = [0u32, 0x7fa0_0001, 0x7fc0_1234, 0xff80_0000];
                let mut zn = 0u128;
                let mut zm = 0u128;
                let mut za = 0u128;
                for h in 0..8 {
                    zn |= (zn_lanes[h] as u128) << (h * 16);
                    zm |= (zm_lanes[h] as u128) << (h * 16);
                }
                for s in 0..4 {
                    za |= (za_lanes[s] as u128) << (s * 32);
                }
                let mut st = ArmState::zeroed();
                st.set_vreg(RN as usize, zn as u64, (zn >> 64) as u64);
                st.set_vreg(RM as usize, zm as u64, (zm >> 64) as u64);
                st.set_vreg(RD as usize, za as u64, (za >> 64) as u64);
                batch.push((
                    format!("fmlal_idx sub{sub} t{top} i{index} nan_inf"),
                    insn,
                    st,
                ));
            }
        }
    }
    run_batch("sve2_fmlal_indexed", batch);
}

#[test]
fn diff_sve2_fmlal_indexed_fpcr_rounding() {
    let mut batch: Vec<(String, u32, ArmState)> = Vec::new();
    let variants = [
        ("fmlalb_pos", 0u32, 0u32, 16_777_216.0f32, 0x3c00u16),
        ("fmlalb_neg", 0, 0, -16_777_216.0f32, 0xbc00u16),
        ("fmlalt_pos", 0, 1, 16_777_216.0f32, 0x3c00u16),
        ("fmlalt_neg", 0, 1, -16_777_216.0f32, 0xbc00u16),
        ("fmlslb_pos", 1, 0, 16_777_216.0f32, 0xbc00u16),
        ("fmlslb_neg", 1, 0, -16_777_216.0f32, 0x3c00u16),
        ("fmlslt_pos", 1, 1, 16_777_216.0f32, 0xbc00u16),
        ("fmlslt_neg", 1, 1, -16_777_216.0f32, 0x3c00u16),
    ];

    for rmode in 0..4u64 {
        for index in 0..8u32 {
            for (name, sub, top, acc, n_half) in variants {
                let mut zn = 0u128;
                let mut zm = 0u128;
                let mut zd = 0u128;
                for h in 0..8 {
                    zn |= (n_half as u128) << (h * 16);
                    zm |= (0x3c00u128) << (h * 16);
                }
                for s in 0..4 {
                    zd |= (acc.to_bits() as u128) << (s * 32);
                }

                let mut st = ArmState::zeroed();
                st.fpcr = rmode << 22;
                st.set_vreg(1, zn as u64, (zn >> 64) as u64);
                st.set_vreg(2, zm as u64, (zm >> 64) as u64);
                st.set_vreg(0, zd as u64, (zd >> 64) as u64);
                batch.push((
                    format!("{name}_i{index}_rmode{rmode}"),
                    enc_sve2_fmlal_idx(sub, top, index, RM),
                    st,
                ));
            }
        }
    }

    run_batch("sve2_fmlal_indexed_fpcr_rounding", batch);
}

