#[test]
fn diff_sve2_fmlsl_indexed_fpcr_ah_nan_sign() {
    const FPCR_AH: u64 = 1 << 1;
    let mut st = ArmState::zeroed();
    st.fpcr = FPCR_AH;
    let mut zn = 0u128;
    let mut zm = 0u128;
    for lane in 0..8 {
        zn |= (0x7e01u128) << (16 * lane); // positive quiet NaN
        zm |= (0x3c00u128) << (16 * lane); // 1.0
    }
    st.set_vreg(0, 0, 0);
    st.set_vreg(1, zn as u64, (zn >> 64) as u64);
    st.set_vreg(2, zm as u64, (zm >> 64) as u64);

    run_batch(
        "sve2_fmlsl_indexed_fpcr_ah_nan_sign",
        vec![(
            "sve_fmlslb_idx_ah_qnan".to_string(),
            enc_sve2_fmlal_idx(1, 0, 0, RM),
            st,
        )],
    );
}

#[test]
fn diff_sve_fscale() {
    fn pack_lanes(size: u32, values: &[u64]) -> (u64, u64) {
        let bits = 8u32 << size;
        let mask = if bits == 64 {
            u64::MAX
        } else {
            (1u64 << bits) - 1
        };
        let mut packed = 0u128;
        for (lane, value) in values.iter().enumerate() {
            packed |= ((*value & mask) as u128) << (lane * bits as usize);
        }
        (packed as u64, (packed >> 64) as u64)
    }

    fn fscale_patterns(size: u32) -> Vec<(&'static str, Vec<u64>, Vec<u64>)> {
        match size {
            1 => vec![
                (
                    "h_basic",
                    vec![
                        0x3c00, 0xbc00, 0x3800, 0xb800, 0x4000, 0xc000, 0x4200, 0xc200,
                    ],
                    vec![
                        0,
                        1,
                        (-1i64) as u64,
                        2,
                        (-2i64) as u64,
                        4,
                        (-4i64) as u64,
                        8,
                    ],
                ),
                (
                    "h_lane_mix",
                    vec![
                        0x3555, 0xb555, 0x3e00, 0xbe00, 0x4100, 0xc100, 0x4480, 0xc480,
                    ],
                    vec![
                        (-8i64) as u64,
                        6,
                        (-6i64) as u64,
                        3,
                        (-3i64) as u64,
                        0,
                        1,
                        (-1i64) as u64,
                    ],
                ),
            ],
            2 => vec![
                (
                    "s_basic",
                    vec![
                        1.0f32.to_bits() as u64,
                        (-1.0f32).to_bits() as u64,
                        0.5f32.to_bits() as u64,
                        (-0.5f32).to_bits() as u64,
                    ],
                    vec![0, 1, (-1i64) as u64, 8],
                ),
                (
                    "s_lane_mix",
                    vec![
                        1.5f32.to_bits() as u64,
                        (-2.5f32).to_bits() as u64,
                        4.0f32.to_bits() as u64,
                        (-8.0f32).to_bits() as u64,
                    ],
                    vec![(-8i64) as u64, 5, (-5i64) as u64, 0],
                ),
            ],
            _ => vec![
                (
                    "d_basic",
                    vec![1.0f64.to_bits(), (-1.0f64).to_bits()],
                    vec![0, 1],
                ),
                (
                    "d_lane_mix",
                    vec![1.5f64.to_bits(), (-2.5f64).to_bits()],
                    vec![(-8i64) as u64, 8],
                ),
            ],
        }
    }

    // FSCALE multiplies each FP lane by 2^(signed Zm element). Use moderate
    // exponents (-40..40) so results stay in range and vary.
    let mut rng = Rng::new(0x8_5001);
    let mut batch: Vec<(String, u32, ArmState)> = Vec::new();
    for (size, esz) in [(1u32, 2usize), (2, 4), (3, 8)] {
        let insn = enc_sve_fscale(size);
        let emask: u64 = if esz == 8 {
            u64::MAX
        } else {
            (1u64 << (esz * 8)) - 1
        };
        for _ in 0..20 {
            let (mut zdn, mut zm) = (0u128, 0u128);
            for l in 0..(16 / esz) {
                zdn |= (finite_fp_bits(&mut rng, esz) as u128) << (l * esz * 8);
                let n = (rng.next() % 81) as i64 - 40;
                zm |= (((n as u64) & emask) as u128) << (l * esz * 8);
            }
            let mut st = ArmState::zeroed();
            st.set_vreg(0, zdn as u64, (zdn >> 64) as u64);
            st.set_vreg(1, zm as u64, (zm >> 64) as u64);
            st.set_preg(0, rng.next() as u16);
            batch.push((format!("fscale s{size}"), insn, st));
        }
        let mixed = match size {
            1 => 0x1111,
            2 => 0x0101,
            _ => 0x0001,
        };
        for (pattern_name, zdn, zm) in fscale_patterns(size) {
            for (mask_name, pg) in [("all", 0xffff), ("mixed", mixed), ("inactive", 0x0000)] {
                let mut st = ArmState::zeroed();
                let (lo, hi) = pack_lanes(size, &zdn);
                st.set_vreg(0, lo, hi);
                let (lo, hi) = pack_lanes(size, &zm);
                st.set_vreg(1, lo, hi);
                st.set_preg(0, pg);
                batch.push((
                    format!("fscale_s{size}_{pattern_name}_{mask_name}"),
                    insn,
                    st,
                ));
            }
        }
    }
    run_batch("sve_fscale", batch);
}

#[test]
fn diff_sve_fscale_fpcr_rounding() {
    let mut batch: Vec<(String, u32, ArmState)> = Vec::new();
    for rmode in 0..4u64 {
        for &(name, h, s, d) in &[
            ("pos", 0x7bffu16, f32::MAX.to_bits(), f64::MAX.to_bits()),
            (
                "neg",
                0xfbffu16,
                (-f32::MAX).to_bits(),
                (-f64::MAX).to_bits(),
            ),
        ] {
            let mut st = ArmState::zeroed();
            st.fpcr = rmode << 22;
            st.set_preg(0, 0xffff);
            let mut z = 0u128;
            let mut n = 0u128;
            for lane in 0..8 {
                z |= (h as u128) << (16 * lane);
                n |= 1u128 << (16 * lane);
            }
            st.set_vreg(RD as usize, z as u64, (z >> 64) as u64);
            st.set_vreg(RN as usize, n as u64, (n >> 64) as u64);
            batch.push((
                format!("fscale_h_{name}_rmode{rmode}"),
                enc_sve_fscale(1),
                st,
            ));

            let mut st = ArmState::zeroed();
            st.fpcr = rmode << 22;
            st.set_preg(0, 0xffff);
            let mut z = 0u128;
            let mut n = 0u128;
            for lane in 0..4 {
                z |= (s as u128) << (32 * lane);
                n |= 1u128 << (32 * lane);
            }
            st.set_vreg(RD as usize, z as u64, (z >> 64) as u64);
            st.set_vreg(RN as usize, n as u64, (n >> 64) as u64);
            batch.push((
                format!("fscale_s_{name}_rmode{rmode}"),
                enc_sve_fscale(2),
                st,
            ));

            let mut st = ArmState::zeroed();
            st.fpcr = rmode << 22;
            st.set_preg(0, 0xffff);
            let z = (d as u128) | ((d as u128) << 64);
            let n = 1u128 | (1u128 << 64);
            st.set_vreg(RD as usize, z as u64, (z >> 64) as u64);
            st.set_vreg(RN as usize, n as u64, (n >> 64) as u64);
            batch.push((
                format!("fscale_d_{name}_rmode{rmode}"),
                enc_sve_fscale(3),
                st,
            ));
        }

        for &(name, h, s, d) in &[
            (
                "tiny_pos",
                0x0001u16,
                0x0000_0001u32,
                0x0000_0000_0000_0001u64,
            ),
            (
                "tiny_neg",
                0x8001u16,
                0x8000_0001u32,
                0x8000_0000_0000_0001u64,
            ),
        ] {
            let mut st = ArmState::zeroed();
            st.fpcr = rmode << 22;
            st.set_preg(0, 0xffff);
            let mut z = 0u128;
            let mut n = 0u128;
            for lane in 0..8 {
                z |= (h as u128) << (16 * lane);
                n |= (0xffffu128) << (16 * lane);
            }
            st.set_vreg(RD as usize, z as u64, (z >> 64) as u64);
            st.set_vreg(RN as usize, n as u64, (n >> 64) as u64);
            batch.push((
                format!("fscale_h_{name}_rmode{rmode}"),
                enc_sve_fscale(1),
                st,
            ));

            let mut st = ArmState::zeroed();
            st.fpcr = rmode << 22;
            st.set_preg(0, 0xffff);
            let mut z = 0u128;
            let mut n = 0u128;
            for lane in 0..4 {
                z |= (s as u128) << (32 * lane);
                n |= (0xffff_ffffu128) << (32 * lane);
            }
            st.set_vreg(RD as usize, z as u64, (z >> 64) as u64);
            st.set_vreg(RN as usize, n as u64, (n >> 64) as u64);
            batch.push((
                format!("fscale_s_{name}_rmode{rmode}"),
                enc_sve_fscale(2),
                st,
            ));

            let mut st = ArmState::zeroed();
            st.fpcr = rmode << 22;
            st.set_preg(0, 0xffff);
            let z = (d as u128) | ((d as u128) << 64);
            let n = 0xffff_ffff_ffff_ffffu128;
            st.set_vreg(RD as usize, z as u64, (z >> 64) as u64);
            st.set_vreg(RN as usize, n as u64, (n >> 64) as u64);
            batch.push((
                format!("fscale_d_{name}_rmode{rmode}"),
                enc_sve_fscale(3),
                st,
            ));
        }
    }

    run_batch("sve_fscale_fpcr_rounding", batch);
}

#[test]
fn diff_fpcr_fiz_sve_fscale_subnormal_inputs() {
    const FPCR_FIZ: u64 = 1;
    let mut batch: Vec<(String, u32, ArmState)> = Vec::new();

    let mut st = ArmState::zeroed();
    st.fpcr = FPCR_FIZ;
    st.set_preg(0, 0xffff);
    let s = 0x0000_0001u32;
    let z = (s as u128) | ((s as u128) << 32) | ((s as u128) << 64) | ((s as u128) << 96);
    st.set_vreg(RD as usize, z as u64, (z >> 64) as u64);
    st.set_vreg(RN as usize, 0, 0);
    batch.push((
        "fscale_s_min_subnorm_by_zero".to_string(),
        enc_sve_fscale(2),
        st,
    ));

    let mut st = ArmState::zeroed();
    st.fpcr = FPCR_FIZ;
    st.set_preg(0, 0xffff);
    let d = 0x0000_0000_0000_0001u64;
    let z = (d as u128) | ((d as u128) << 64);
    st.set_vreg(RD as usize, z as u64, (z >> 64) as u64);
    st.set_vreg(RN as usize, 0, 0);
    batch.push((
        "fscale_d_min_subnorm_by_zero".to_string(),
        enc_sve_fscale(3),
        st,
    ));

    run_batch("fpcr_fiz_sve_fscale_subnormal_inputs", batch);
}

#[test]
fn diff_fpcr_ah_sve_scale_input_status() {
    const FPCR_AH: u64 = 1 << 1;
    let mut batch = Vec::new();

    for &(name, size, packed, rm) in &[
        ("s", 2, 0x3f80_0000_0000_0000_7f80_0000_0000_0001u128, 0u128),
        ("d", 3, 0x3ff0_0000_0000_0000_0000_0000_0000_0001u128, 0u128),
    ] {
        let mut st = ArmState::zeroed();
        st.fpcr = FPCR_AH;
        st.set_preg(0, 0xffff);
        st.set_vreg(RD as usize, packed as u64, (packed >> 64) as u64);
        st.set_vreg(RN as usize, rm as u64, (rm >> 64) as u64);
        batch.push((
            format!("fscale_{name}_ah_subnormal_status"),
            enc_sve_fscale(size),
            st,
        ));

        let mut st = ArmState::zeroed();
        st.fpcr = FPCR_AH;
        st.set_vreg(RN as usize, packed as u64, (packed >> 64) as u64);
        st.set_vreg(RM as usize, 0, 0);
        batch.push((
            format!("ftsmul_{name}_ah_subnormal_status"),
            enc_sve_ftsmul(size),
            st,
        ));
    }

    let mut st = ArmState::zeroed();
    st.fpcr = FPCR_AH;
    st.set_preg(0, 0xffff);
    let mixed_s = 0x0000_0000_0000_0001_7ff8_0000_0000_2000u128;
    st.set_vreg(RD as usize, mixed_s as u64, (mixed_s >> 64) as u64);
    st.set_vreg(RN as usize, mixed_s as u64, (mixed_s >> 64) as u64);
    batch.push((
        "fscale_s_ah_mixed_nan_subnormal_status".to_string(),
        enc_sve_fscale(2),
        st,
    ));

    run_batch("fpcr_ah_sve_scale_input_status", batch);
}

#[test]
fn diff_sve_fexpa() {
    // FEXPA table lookup; the source bits are arbitrary (low bits index, next
    // bits become the exponent).
    fn pack_lanes(size: u32, values: &[u64]) -> (u64, u64) {
        let bits = 8u32 << size;
        let mask = if bits == 64 {
            u64::MAX
        } else {
            (1u64 << bits) - 1
        };
        let mut packed = 0u128;
        for (lane, value) in values.iter().enumerate() {
            packed |= ((*value & mask) as u128) << (lane * bits as usize);
        }
        (packed as u64, (packed >> 64) as u64)
    }

    fn source_patterns(size: u32) -> Vec<(&'static str, Vec<u64>)> {
        let bits = 8u32 << size;
        let lanes = 16usize >> size;
        let mask = if bits == 64 {
            u64::MAX
        } else {
            (1u64 << bits) - 1
        };
        let sign = 1u64 << (bits - 1);
        let low_index_mask = match size {
            1 => 0x1f,
            2 => 0x3f,
            _ => 0x7f,
        };
        let edge_values = [
            0,
            1,
            low_index_mask,
            low_index_mask + 1,
            sign - 1,
            sign,
            sign + 1,
            mask,
        ];
        vec![
            (
                "indexes",
                (0..lanes).map(|lane| (lane as u64) & mask).collect(),
            ),
            (
                "edges",
                (0..lanes)
                    .map(|lane| edge_values[lane % edge_values.len()])
                    .collect(),
            ),
        ]
    }

    let mut rng = Rng::new(0x8_6001);
    let mut batch: Vec<(String, u32, ArmState)> = Vec::new();
    for size in 1..4u32 {
        let insn = enc_sve_fexpa(size);
        for _ in 0..16 {
            let mut st = ArmState::zeroed();
            st.set_vreg(1, rng.next(), rng.next()); // Zn
            st.set_vreg(0, rng.next(), rng.next()); // dest (overwritten)
            batch.push((format!("fexpa s{size}"), insn, st));
        }
        for (pattern_name, zn) in source_patterns(size) {
            let mut st = ArmState::zeroed();
            st.set_vreg(0, 0xdead_beef_dead_beef, 0xfeed_face_feed_face);
            let (lo, hi) = pack_lanes(size, &zn);
            st.set_vreg(1, lo, hi);
            batch.push((format!("fexpa_s{size}_{pattern_name}"), insn, st));
        }
    }
    run_batch("sve_fexpa", batch);
}

