#[test]
fn diff_sve_fp_indexed() {
    fn pack_fp(size: u32, values: &[u64]) -> (u64, u64) {
        let bits = 8u32 << size;
        let mask = if bits == 64 {
            u64::MAX
        } else {
            (1u64 << bits) - 1
        };
        let mut packed = 0u128;
        for (lane, value) in values.iter().enumerate() {
            packed |= ((*value & mask) as u128) << (lane * bits as usize);
        }
        (packed as u64, (packed >> 64) as u64)
    }

    fn indexed_patterns(size: u32) -> Vec<(&'static str, Vec<u64>, Vec<u64>, Vec<u64>)> {
        match size {
            1 => vec![
                (
                    "h_basic",
                    vec![
                        0x3c00, 0xbc00, 0x4000, 0xc000, 0x3800, 0xb800, 0x4200, 0xc200,
                    ],
                    vec![
                        0x3e00, 0xbe00, 0x4100, 0xc100, 0x3555, 0xb555, 0x4480, 0xc480,
                    ],
                    vec![
                        0x3c00, 0xbc00, 0x4000, 0xc000, 0x3800, 0xb800, 0x4200, 0xc200,
                    ],
                ),
                (
                    "h_lane_mix",
                    vec![
                        0x0000, 0x8000, 0x3c00, 0xbc00, 0x4000, 0xc000, 0x3800, 0xb800,
                    ],
                    vec![
                        0x3c00, 0x4000, 0xbc00, 0xc000, 0x3800, 0xb800, 0x4200, 0xc200,
                    ],
                    vec![
                        0x3e00, 0xbe00, 0x4100, 0xc100, 0x3555, 0xb555, 0x4480, 0xc480,
                    ],
                ),
            ],
            2 => vec![
                (
                    "s_basic",
                    vec![
                        1.0f32.to_bits() as u64,
                        (-1.0f32).to_bits() as u64,
                        2.0f32.to_bits() as u64,
                        (-2.0f32).to_bits() as u64,
                    ],
                    vec![
                        1.5f32.to_bits() as u64,
                        (-2.5f32).to_bits() as u64,
                        3.5f32.to_bits() as u64,
                        (-4.5f32).to_bits() as u64,
                    ],
                    vec![
                        0.5f32.to_bits() as u64,
                        (-0.75f32).to_bits() as u64,
                        4.0f32.to_bits() as u64,
                        (-8.0f32).to_bits() as u64,
                    ],
                ),
                (
                    "s_lane_mix",
                    vec![
                        16.0f32.to_bits() as u64,
                        (-16.0f32).to_bits() as u64,
                        0.25f32.to_bits() as u64,
                        (-0.25f32).to_bits() as u64,
                    ],
                    vec![
                        0.5f32.to_bits() as u64,
                        (-0.75f32).to_bits() as u64,
                        4.0f32.to_bits() as u64,
                        (-8.0f32).to_bits() as u64,
                    ],
                    vec![
                        1.5f32.to_bits() as u64,
                        (-2.5f32).to_bits() as u64,
                        3.5f32.to_bits() as u64,
                        (-4.5f32).to_bits() as u64,
                    ],
                ),
            ],
            _ => vec![
                (
                    "d_basic",
                    vec![1.0f64.to_bits(), (-1.0f64).to_bits()],
                    vec![1.5f64.to_bits(), (-2.5f64).to_bits()],
                    vec![0.5f64.to_bits(), (-0.75f64).to_bits()],
                ),
                (
                    "d_lane_mix",
                    vec![16.0f64.to_bits(), (-16.0f64).to_bits()],
                    vec![0.25f64.to_bits(), (-0.75f64).to_bits()],
                    vec![4.0f64.to_bits(), (-8.0f64).to_bits()],
                ),
            ],
        }
    }

    fn indexed_special_patterns(size: u32) -> Vec<(&'static str, Vec<u64>, Vec<u64>, Vec<u64>)> {
        match size {
            1 => vec![
                (
                    "h_nan_inf",
                    vec![
                        0x0000, 0x7c01, 0x7e00, 0xfc00, 0x7c00, 0x8000, 0x3c00, 0xbc00,
                    ],
                    vec![
                        0x3c00, 0xbc00, 0x7c01, 0x7e00, 0x7c00, 0xfc00, 0x0000, 0x8000,
                    ],
                    vec![
                        0x7c01, 0x7e00, 0x7c00, 0xfc00, 0x0000, 0x8000, 0x3c00, 0xbc00,
                    ],
                ),
                (
                    "h_signed_zero",
                    vec![
                        0x8000, 0x0000, 0x8000, 0x0000, 0x3c00, 0xbc00, 0x4000, 0xc000,
                    ],
                    vec![
                        0x0000, 0x8000, 0x3c00, 0xbc00, 0x0001, 0x8001, 0x7c00, 0xfc00,
                    ],
                    vec![
                        0x8000, 0x0000, 0x7e00, 0xfe00, 0x3c00, 0xbc00, 0x4000, 0xc000,
                    ],
                ),
            ],
            2 => vec![
                (
                    "s_nan_inf",
                    vec![0, 0x7f80_0001, 0x7fc0_0000, 0xff80_0000],
                    vec![
                        1.0f32.to_bits() as u64,
                        0xbf80_0000,
                        0x7f80_0001,
                        0x7fc0_0000,
                    ],
                    vec![0x7f80_0001, 0x7fc0_0000, 0x7f80_0000, 0xff80_0000],
                ),
                (
                    "s_signed_zero",
                    vec![0x8000_0000, 0, 0x3f80_0000, 0xbf80_0000],
                    vec![0, 0x8000_0000, 0x0000_0001, 0x8000_0001],
                    vec![0x8000_0000, 0, 0x7fc0_0000, 0xffc0_0000],
                ),
            ],
            _ => vec![
                (
                    "d_nan_inf",
                    vec![0, 0x7ff0_0000_0000_0001],
                    vec![1.0f64.to_bits(), 0x7ff8_0000_0000_0000],
                    vec![0x7ff0_0000_0000_0001, 0xfff0_0000_0000_0000],
                ),
                (
                    "d_signed_zero",
                    vec![0x8000_0000_0000_0000, 0],
                    vec![0, 0x8000_0000_0000_0000],
                    vec![0x8000_0000_0000_0000, 0x7ff8_0000_0000_0000],
                ),
            ],
        }
    }

    // FMLA/FMLS/FMUL by indexed FP element, all sizes and indices, finite inputs.
    let mut rng = Rng::new(0x8_3001);
    let mut batch: Vec<(String, u32, ArmState)> = Vec::new();
    for (op, name) in [
        (0b000000u32, "fmla"),
        (0b000001, "fmls"),
        (0b001000, "fmul"),
    ] {
        for (size, esz, idxn) in [(1u32, 2usize, 8u32), (2, 4, 4), (3, 8, 2)] {
            for index in 0..idxn {
                let insn = enc_sve_fp_idx(op, size, index, RM);
                for _ in 0..3 {
                    let mut st = ArmState::zeroed();
                    for r in 0..3 {
                        let mut v = 0u128;
                        for l in 0..(16 / esz) {
                            v |= (finite_fp_bits(&mut rng, esz) as u128) << (l * esz * 8);
                        }
                        st.set_vreg(r, v as u64, (v >> 64) as u64);
                    }
                    batch.push((format!("{name}_idx s{size} i{index}"), insn, st));
                }
                for (pattern_name, zd, zn, zm) in indexed_patterns(size) {
                    let mut st = ArmState::zeroed();
                    let (lo, hi) = pack_fp(size, &zd);
                    st.set_vreg(0, lo, hi);
                    let (lo, hi) = pack_fp(size, &zn);
                    st.set_vreg(1, lo, hi);
                    let (lo, hi) = pack_fp(size, &zm);
                    st.set_vreg(2, lo, hi);
                    batch.push((
                        format!("{name}_idx_s{size}_i{index}_{pattern_name}"),
                        insn,
                        st,
                    ));
                }
                for (pattern_name, zd, zn, zm) in indexed_special_patterns(size) {
                    let mut st = ArmState::zeroed();
                    let (lo, hi) = pack_fp(size, &zd);
                    st.set_vreg(0, lo, hi);
                    let (lo, hi) = pack_fp(size, &zn);
                    st.set_vreg(1, lo, hi);
                    let (lo, hi) = pack_fp(size, &zm);
                    st.set_vreg(2, lo, hi);
                    batch.push((
                        format!("{name}_idx_s{size}_i{index}_{pattern_name}"),
                        insn,
                        st,
                    ));
                }
            }
        }
    }
    run_batch("sve_fp_indexed", batch);
}

#[test]
fn diff_sve_fp_indexed_fpcr_rounding() {
    let mut batch: Vec<(String, u32, ArmState)> = Vec::new();
    for rmode in 0..4u64 {
        let fpcr = rmode << 22;

        for &(op, name, acc, n) in &[
            (0b000000, "fmla_pos", 0x6800u16, 0x3c00u16),
            (0b000000, "fmla_neg", 0xe800u16, 0xbc00u16),
            (0b000001, "fmls_pos", 0x6800u16, 0xbc00u16),
            (0b000001, "fmls_neg", 0xe800u16, 0x3c00u16),
        ] {
            let mut st = ArmState::zeroed();
            st.fpcr = fpcr;
            let mut d = 0u128;
            let mut zn = 0u128;
            let mut zm = 0u128;
            for lane in 0..8 {
                d |= (acc as u128) << (16 * lane);
                zn |= (n as u128) << (16 * lane);
                zm |= (0x3c00u128) << (16 * lane);
            }
            st.set_vreg(RD as usize, d as u64, (d >> 64) as u64);
            st.set_vreg(RN as usize, zn as u64, (zn >> 64) as u64);
            st.set_vreg(RM as usize, zm as u64, (zm >> 64) as u64);
            batch.push((
                format!("{name}_h_rmode{rmode}"),
                enc_sve_fp_idx(op, 1, 0, RM),
                st,
            ));
        }

        let mut st = ArmState::zeroed();
        st.fpcr = fpcr;
        let mut n = 0u128;
        let mut m = 0u128;
        for lane in 0..8 {
            n |= (0x3c01u128) << (16 * lane);
            m |= (0x3c01u128) << (16 * lane);
        }
        st.set_vreg(RN as usize, n as u64, (n >> 64) as u64);
        st.set_vreg(RM as usize, m as u64, (m >> 64) as u64);
        batch.push((
            format!("fmul_h_rmode{rmode}"),
            enc_sve_fp_idx(0b001000, 1, 0, RM),
            st,
        ));

        for &(op, name, acc_sign, n_sign) in &[
            (0b000000, "fmla_pos", 1.0f32, 1.0f32),
            (0b000000, "fmla_neg", -1.0f32, -1.0f32),
            (0b000001, "fmls_pos", 1.0f32, -1.0f32),
            (0b000001, "fmls_neg", -1.0f32, 1.0f32),
        ] {
            let mut st = ArmState::zeroed();
            st.fpcr = fpcr;
            let acc = 16_777_216.0f32 * acc_sign;
            let nval = 1.0f32 * n_sign;
            let mval = 1.0f32;
            let mut d = 0u128;
            let mut n = 0u128;
            let mut m = 0u128;
            for lane in 0..4 {
                d |= (acc.to_bits() as u128) << (32 * lane);
                n |= (nval.to_bits() as u128) << (32 * lane);
                m |= (mval.to_bits() as u128) << (32 * lane);
            }
            st.set_vreg(RD as usize, d as u64, (d >> 64) as u64);
            st.set_vreg(RN as usize, n as u64, (n >> 64) as u64);
            st.set_vreg(RM as usize, m as u64, (m >> 64) as u64);
            batch.push((
                format!("{name}_s_rmode{rmode}"),
                enc_sve_fp_idx(op, 2, 0, RM),
                st,
            ));
        }

        for &(op, name, acc_sign, n_sign) in &[
            (0b000000, "fmla_pos", 1.0f64, 1.0f64),
            (0b000000, "fmla_neg", -1.0f64, -1.0f64),
            (0b000001, "fmls_pos", 1.0f64, -1.0f64),
            (0b000001, "fmls_neg", -1.0f64, 1.0f64),
        ] {
            let mut st = ArmState::zeroed();
            st.fpcr = fpcr;
            let acc = 9_007_199_254_740_992.0f64 * acc_sign;
            let nval = 1.0f64 * n_sign;
            let mval = 1.0f64;
            let mut d = 0u128;
            let mut n = 0u128;
            let mut m = 0u128;
            for lane in 0..2 {
                d |= (acc.to_bits() as u128) << (64 * lane);
                n |= (nval.to_bits() as u128) << (64 * lane);
                m |= (mval.to_bits() as u128) << (64 * lane);
            }
            st.set_vreg(RD as usize, d as u64, (d >> 64) as u64);
            st.set_vreg(RN as usize, n as u64, (n >> 64) as u64);
            st.set_vreg(RM as usize, m as u64, (m >> 64) as u64);
            batch.push((
                format!("{name}_d_rmode{rmode}"),
                enc_sve_fp_idx(op, 3, 0, RM),
                st,
            ));
        }

        let mut st = ArmState::zeroed();
        st.fpcr = fpcr;
        let lhs = f32::from_bits(0x3f80_0001);
        let rhs = f32::from_bits(0x3f80_0001);
        let mut n = 0u128;
        let mut m = 0u128;
        for lane in 0..4 {
            n |= (lhs.to_bits() as u128) << (32 * lane);
            m |= (rhs.to_bits() as u128) << (32 * lane);
        }
        st.set_vreg(RN as usize, n as u64, (n >> 64) as u64);
        st.set_vreg(RM as usize, m as u64, (m >> 64) as u64);
        batch.push((
            format!("fmul_s_rmode{rmode}"),
            enc_sve_fp_idx(0b001000, 2, 0, RM),
            st,
        ));

        let mut st = ArmState::zeroed();
        st.fpcr = fpcr;
        let lhs = f64::from_bits(0x3ff0_0000_0000_0001);
        let rhs = f64::from_bits(0x3ff0_0000_0000_0001);
        let mut n = 0u128;
        let mut m = 0u128;
        for lane in 0..2 {
            n |= (lhs.to_bits() as u128) << (64 * lane);
            m |= (rhs.to_bits() as u128) << (64 * lane);
        }
        st.set_vreg(RN as usize, n as u64, (n >> 64) as u64);
        st.set_vreg(RM as usize, m as u64, (m >> 64) as u64);
        batch.push((
            format!("fmul_d_rmode{rmode}"),
            enc_sve_fp_idx(0b001000, 3, 0, RM),
            st,
        ));
    }

    run_batch("sve_fp_indexed_fpcr_rounding", batch);
}

#[test]
fn diff_fpcr_fiz_sve_indexed_fmul_subnormal_inputs() {
    const FPCR_FIZ: u64 = 1;
    let mut batch: Vec<(String, u32, ArmState)> = Vec::new();

    let mut st = ArmState::zeroed();
    st.fpcr = FPCR_FIZ;
    let mut n = 0u128;
    let mut m = 0u128;
    for lane in 0..4 {
        n |= 0x0000_0001u128 << (32 * lane);
        m |= (1.0f32.to_bits() as u128) << (32 * lane);
    }
    st.set_vreg(RN as usize, n as u64, (n >> 64) as u64);
    st.set_vreg(RM as usize, m as u64, (m >> 64) as u64);
    batch.push((
        "sve_idx_fmul_s_min_subnorm".to_string(),
        enc_sve_fp_idx(0b001000, 2, 0, RM),
        st,
    ));

    let mut st = ArmState::zeroed();
    st.fpcr = FPCR_FIZ;
    let n = 0x0000_0000_0000_0001u128;
    let n = n | (n << 64);
    let m = (1.0f64.to_bits() as u128) | ((1.0f64.to_bits() as u128) << 64);
    st.set_vreg(RN as usize, n as u64, (n >> 64) as u64);
    st.set_vreg(RM as usize, m as u64, (m >> 64) as u64);
    batch.push((
        "sve_idx_fmul_d_min_subnorm".to_string(),
        enc_sve_fp_idx(0b001000, 3, 0, RM),
        st,
    ));

    run_batch("fpcr_fiz_sve_indexed_fmul_subnormal_inputs", batch);
}

#[test]
fn diff_fpcr_fiz_sve_indexed_fmla_subnormal_inputs() {
    const FPCR_FIZ: u64 = 1;
    let mut batch: Vec<(String, u32, ArmState)> = Vec::new();

    let mut product_s = ArmState::zeroed();
    product_s.fpcr = FPCR_FIZ;
    let mut n = 0u128;
    let mut m = 0u128;
    for lane in 0..4 {
        n |= 0x0000_0001u128 << (32 * lane);
        m |= (1.0f32.to_bits() as u128) << (32 * lane);
    }
    product_s.set_vreg(RD as usize, 0, 0);
    product_s.set_vreg(RN as usize, n as u64, (n >> 64) as u64);
    product_s.set_vreg(RM as usize, m as u64, (m >> 64) as u64);
    batch.push((
        "sve_idx_fmla_s_product_min_subnorm".to_string(),
        enc_sve_fp_idx(0b000000, 2, 0, RM),
        product_s,
    ));

    let mut acc_s = ArmState::zeroed();
    acc_s.fpcr = FPCR_FIZ;
    let mut acc = 0u128;
    for lane in 0..4 {
        acc |= 0x0000_0001u128 << (32 * lane);
    }
    acc_s.set_vreg(RD as usize, acc as u64, (acc >> 64) as u64);
    acc_s.set_vreg(RN as usize, 0, 0);
    acc_s.set_vreg(RM as usize, m as u64, (m >> 64) as u64);
    batch.push((
        "sve_idx_fmla_s_acc_min_subnorm".to_string(),
        enc_sve_fp_idx(0b000000, 2, 0, RM),
        acc_s,
    ));

    let mut product_d = ArmState::zeroed();
    product_d.fpcr = FPCR_FIZ;
    let n = 0x0000_0000_0000_0001u128;
    let n = n | (n << 64);
    let m = (1.0f64.to_bits() as u128) | ((1.0f64.to_bits() as u128) << 64);
    product_d.set_vreg(RD as usize, 0, 0);
    product_d.set_vreg(RN as usize, n as u64, (n >> 64) as u64);
    product_d.set_vreg(RM as usize, m as u64, (m >> 64) as u64);
    batch.push((
        "sve_idx_fmla_d_product_min_subnorm".to_string(),
        enc_sve_fp_idx(0b000000, 3, 0, RM),
        product_d,
    ));

    let mut acc_d = ArmState::zeroed();
    acc_d.fpcr = FPCR_FIZ;
    let acc = 0x0000_0000_0000_0001u128;
    let acc = acc | (acc << 64);
    acc_d.set_vreg(RD as usize, acc as u64, (acc >> 64) as u64);
    acc_d.set_vreg(RN as usize, 0, 0);
    acc_d.set_vreg(RM as usize, m as u64, (m >> 64) as u64);
    batch.push((
        "sve_idx_fmla_d_acc_min_subnorm".to_string(),
        enc_sve_fp_idx(0b000000, 3, 0, RM),
        acc_d,
    ));

    run_batch("fpcr_fiz_sve_indexed_fmla_subnormal_inputs", batch);
}

