#[test]
fn diff_sve_fp_cmp() {
    fn pack_fp_lanes(size: u32, values: &[u64]) -> (u64, u64) {
        let bits = 8u32 << size;
        let mask = if bits == 64 {
            u64::MAX
        } else {
            (1u64 << bits) - 1
        };
        let mut packed = 0u128;
        for (lane, value) in values.iter().enumerate() {
            packed |= ((*value & mask) as u128) << (lane * bits as usize);
        }
        (packed as u64, (packed >> 64) as u64)
    }

    fn fp_cmp_patterns(size: u32) -> Vec<(&'static str, Vec<u64>, Vec<u64>)> {
        match size {
            1 => vec![
                (
                    "h_zero_inf",
                    vec![
                        0x0000, 0x8000, 0x3c00, 0xbc00, 0x7c00, 0xfc00, 0x4000, 0xc000,
                    ],
                    vec![
                        0x0000, 0x0000, 0xbc00, 0x3c00, 0xfc00, 0x7c00, 0x3c00, 0xbc00,
                    ],
                ),
                (
                    "h_nan_mix",
                    vec![
                        0x7e00, 0xfe00, 0x7d00, 0xfd00, 0x3c00, 0xbc00, 0x0000, 0x8000,
                    ],
                    vec![
                        0x3c00, 0xbc00, 0x7e00, 0xfe00, 0x7d00, 0xfd00, 0x0000, 0x8000,
                    ],
                ),
            ],
            2 => vec![
                (
                    "s_zero_inf",
                    vec![
                        0x0000_0000,
                        0x8000_0000,
                        1.0f32.to_bits() as u64,
                        (-1.0f32).to_bits() as u64,
                    ],
                    vec![
                        0x0000_0000,
                        0x0000_0000,
                        (-1.0f32).to_bits() as u64,
                        1.0f32.to_bits() as u64,
                    ],
                ),
                (
                    "s_nan_mix",
                    vec![0x7f80_0000, 0xff80_0000, 0x7fc0_0001, 0x7f80_0001],
                    vec![
                        0xff80_0000,
                        0x7f80_0000,
                        1.0f32.to_bits() as u64,
                        0x7fc0_0001,
                    ],
                ),
            ],
            _ => vec![
                (
                    "d_zero_inf",
                    vec![0.0f64.to_bits(), (-0.0f64).to_bits()],
                    vec![0.0f64.to_bits(), 0.0f64.to_bits()],
                ),
                (
                    "d_nan_mix",
                    vec![0x7ff0_0000_0000_0000, 0x7ff8_0000_0000_0001],
                    vec![0xfff0_0000_0000_0000, 0x7ff0_0000_0000_0001],
                ),
            ],
        }
    }

    // FP compare (register) and compare-with-zero -> predicate, incl. NaN/inf
    // (random bit patterns), all sizes; checks predicate result AND NZCV.
    let mut rng = Rng::new(0x9_c001);
    let mut batch: Vec<(String, u32, ArmState)> = Vec::new();
    let regconds = [
        (0b010u32, 0u32),
        (0b010, 1),
        (0b011, 0),
        (0b011, 1),
        (0b110, 0),
        (0b110, 1),
        (0b111, 1),
    ];
    let zeroconds = [
        (0b00u32, 0u32),
        (0b00, 1),
        (0b01, 0),
        (0b01, 1),
        (0b10, 0),
        (0b11, 0),
    ];
    for size in 1..4u32 {
        for (cc13, bit4) in regconds {
            let insn = enc_sve_fp_cmp(size, cc13, bit4);
            for _ in 0..6 {
                let mut st = ArmState::zeroed();
                st.set_vreg(1, rng.next(), rng.next());
                st.set_vreg(2, rng.next(), rng.next());
                st.set_preg(1, rng.next() as u16);
                batch.push((format!("fcmp s{size} c{cc13}{bit4}"), insn, st));
            }
        }
        for (sub, bit4) in zeroconds {
            let insn = enc_sve_fp_cmp0(size, sub, bit4);
            for _ in 0..6 {
                let mut st = ArmState::zeroed();
                st.set_vreg(1, rng.next(), rng.next());
                st.set_preg(1, rng.next() as u16);
                batch.push((format!("fcmp0 s{size} c{sub}{bit4}"), insn, st));
            }
        }
        let mixed = match size {
            1 => 0x1111,
            2 => 0x0101,
            _ => 0x0001,
        };
        for (pattern_name, zn, zm) in fp_cmp_patterns(size) {
            for (cc13, bit4) in regconds {
                let insn = enc_sve_fp_cmp(size, cc13, bit4);
                for (mask_name, pg) in [("all", 0xffff), ("mixed", mixed), ("inactive", 0x0000)] {
                    let mut st = ArmState::zeroed();
                    st.set_preg(0, 0xdead);
                    let (lo, hi) = pack_fp_lanes(size, &zn);
                    st.set_vreg(1, lo, hi);
                    let (lo, hi) = pack_fp_lanes(size, &zm);
                    st.set_vreg(2, lo, hi);
                    st.set_preg(1, pg);
                    batch.push((
                        format!("fcmp_s{size}_c{cc13}{bit4}_{pattern_name}_{mask_name}"),
                        insn,
                        st,
                    ));
                }
            }
            for (sub, bit4) in zeroconds {
                let insn = enc_sve_fp_cmp0(size, sub, bit4);
                for (mask_name, pg) in [("all", 0xffff), ("mixed", mixed), ("inactive", 0x0000)] {
                    let mut st = ArmState::zeroed();
                    st.set_preg(0, 0xdead);
                    let (lo, hi) = pack_fp_lanes(size, &zn);
                    st.set_vreg(1, lo, hi);
                    st.set_preg(1, pg);
                    batch.push((
                        format!("fcmp0_s{size}_c{sub}{bit4}_{pattern_name}_{mask_name}"),
                        insn,
                        st,
                    ));
                }
            }
        }
    }
    run_batch("sve_fp_cmp", batch);
}

#[test]
fn diff_fpcr_fiz_sve_fp_cmp_subnormal_inputs() {
    const FPCR_FIZ: u64 = 1;
    let mut batch: Vec<(String, u32, ArmState)> = Vec::new();

    for &(size, name, pos, neg, shift) in &[
        (0b10u32, "s", 0x0000_0001u128, 0x8000_0001u128, 32usize),
        (
            0b11u32,
            "d",
            0x0000_0000_0000_0001u128,
            0x8000_0000_0000_0001u128,
            64usize,
        ),
    ] {
        let mut zn = 0u128;
        for lane in 0..(128 / shift) {
            let bits = if lane & 1 == 0 { pos } else { neg };
            zn |= bits << (lane * shift);
        }

        for &(sub, bit4, cmp_name) in &[
            (0b00, 0, "fcmge0"),
            (0b00, 1, "fcmgt0"),
            (0b01, 0, "fcmlt0"),
            (0b01, 1, "fcmle0"),
            (0b10, 0, "fcmeq0"),
            (0b11, 0, "fcmne0"),
        ] {
            let mut st = ArmState::zeroed();
            st.fpcr = FPCR_FIZ;
            st.set_preg(1, 0xffff);
            st.set_vreg(RN as usize, zn as u64, (zn >> 64) as u64);
            batch.push((
                format!("sve_{cmp_name}_{name}_fiz_min_subnorm"),
                enc_sve_fp_cmp0(size, sub, bit4),
                st,
            ));
        }

        for &(cc13, bit4, cmp_name) in &[
            (0b010, 0, "fcmge"),
            (0b010, 1, "fcmgt"),
            (0b011, 0, "fcmeq"),
            (0b011, 1, "fcmne"),
        ] {
            let mut st = ArmState::zeroed();
            st.fpcr = FPCR_FIZ;
            st.set_preg(1, 0xffff);
            st.set_vreg(RN as usize, zn as u64, (zn >> 64) as u64);
            st.set_vreg(RM as usize, 0, 0);
            batch.push((
                format!("sve_{cmp_name}_zero_{name}_fiz_min_subnorm"),
                enc_sve_fp_cmp(size, cc13, bit4),
                st,
            ));
        }
    }

    run_batch("fpcr_fiz_sve_fp_cmp_subnormal_inputs", batch);
}

#[test]
fn diff_sve_cmp_imm() {
    fn pack_lanes(size: u32, values: &[u64]) -> (u64, u64) {
        let bits = 8u32 << size;
        let mask = if bits == 64 {
            u64::MAX
        } else {
            (1u64 << bits) - 1
        };
        let mut packed = 0u128;
        for (lane, value) in values.iter().enumerate() {
            packed |= ((*value & mask) as u128) << (lane * bits as usize);
        }
        (packed as u64, (packed >> 64) as u64)
    }

    fn cmp_imm_values(size: u32) -> Vec<u64> {
        let bits = 8u32 << size;
        let lanes = 16usize >> size;
        let mask = if bits == 64 {
            u64::MAX
        } else {
            (1u64 << bits) - 1
        };
        let sign = 1u64 << (bits - 1);
        let values = [0, 1, 15, 16, 31, sign - 1, sign, sign + 1, mask - 1, mask];
        (0..lanes).map(|lane| values[lane % values.len()]).collect()
    }

    // Integer compare with signed/unsigned immediate -> predicate + NZCV.
    let mut rng = Rng::new(0x9_d001);
    let mut batch: Vec<(String, u32, ArmState)> = Vec::new();
    let sconds = [
        (0b000u32, 0u32),
        (0b000, 1),
        (0b001, 0),
        (0b001, 1),
        (0b100, 0),
        (0b100, 1),
    ];
    for size in 0..4u32 {
        for (cc13, bit4) in sconds {
            for imm5 in 0..32u32 {
                let insn = enc_sve_cmp_imm_s(size, cc13, bit4, imm5);
                for _ in 0..3 {
                    let mut st = ArmState::zeroed();
                    st.set_vreg(1, rng.next(), rng.next());
                    st.set_preg(1, rng.next() as u16);
                    batch.push((format!("cmps s{size} c{cc13}{bit4} i{imm5}"), insn, st));
                }
            }
        }
        for (lo, hi) in [(0u32, 0u32), (0, 1), (1, 0), (1, 1)] {
            for imm7 in 0..=0x7Fu32 {
                let insn = enc_sve_cmp_imm_u(size, lo, hi, imm7);
                for _ in 0..3 {
                    let mut st = ArmState::zeroed();
                    st.set_vreg(1, rng.next(), rng.next());
                    st.set_preg(1, rng.next() as u16);
                    batch.push((format!("cmpu s{size} {lo}{hi} i{imm7}"), insn, st));
                }
            }
        }
    }
    for size in 0..4u32 {
        let mixed = match size {
            0 => 0x5555,
            1 => 0x1111,
            2 => 0x0101,
            _ => 0x0001,
        };
        let values = cmp_imm_values(size);
        for (cc13, bit4) in sconds {
            for imm5 in [0u32, 1, 15, 16, 31] {
                let insn = enc_sve_cmp_imm_s(size, cc13, bit4, imm5);
                for (mask_name, pg) in [("all", 0xffff), ("mixed", mixed), ("inactive", 0x0000)] {
                    let mut st = ArmState::zeroed();
                    st.set_preg(0, 0xdead);
                    let (lo, hi) = pack_lanes(size, &values);
                    st.set_vreg(1, lo, hi);
                    st.set_preg(1, pg);
                    batch.push((
                        format!("cmps_s{size}_c{cc13}{bit4}_i{imm5}_{mask_name}"),
                        insn,
                        st,
                    ));
                }
            }
        }
        for (lo_bit, hi_bit) in [(0u32, 0u32), (0, 1), (1, 0), (1, 1)] {
            for imm7 in [0u32, 1, 63, 64, 127] {
                let insn = enc_sve_cmp_imm_u(size, lo_bit, hi_bit, imm7);
                for (mask_name, pg) in [("all", 0xffff), ("mixed", mixed), ("inactive", 0x0000)] {
                    let mut st = ArmState::zeroed();
                    st.set_preg(0, 0xdead);
                    let (lo, hi) = pack_lanes(size, &values);
                    st.set_vreg(1, lo, hi);
                    st.set_preg(1, pg);
                    batch.push((
                        format!("cmpu_s{size}_{lo_bit}{hi_bit}_i{imm7}_{mask_name}"),
                        insn,
                        st,
                    ));
                }
            }
        }
    }
    run_batch("sve_cmp_imm", batch);
}

