#[test]
fn diff_sve_bfcvt() {
    fn pack_u16(values: [u16; 8]) -> (u64, u64) {
        let mut packed = 0u128;
        for (lane, value) in values.iter().enumerate() {
            packed |= (*value as u128) << (lane * 16);
        }
        (packed as u64, (packed >> 64) as u64)
    }

    fn pack_u32(values: [u32; 4]) -> (u64, u64) {
        let mut packed = 0u128;
        for (lane, value) in values.iter().enumerate() {
            packed |= (*value as u128) << (lane * 32);
        }
        (packed as u64, (packed >> 64) as u64)
    }

    // BFCVT f32 -> bf16, predicated merging, finite inputs.
    let insn = enc_sve_bfcvt();
    let mut rng = Rng::new(0x9_e001);
    let mut batch: Vec<(String, u32, ArmState)> = Vec::new();
    for _ in 0..40 {
        let mut zn = 0u128;
        for l in 0..4 {
            zn |= (finite_fp_bits(&mut rng, 4) as u128) << (l * 32);
        }
        let mut st = ArmState::zeroed();
        st.set_vreg(1, zn as u64, (zn >> 64) as u64);
        st.set_vreg(0, rng.next(), rng.next());
        st.set_preg(0, rng.next() as u16);
        batch.push(("bfcvt".to_string(), insn, st));
    }

    let patterns = [
        (
            "zeros",
            [0x0000_0000, 0x8000_0000, 0x0000_0000, 0x8000_0000],
            [
                0xaaaa, 0x5555, 0xaaaa, 0x5555, 0xaaaa, 0x5555, 0xaaaa, 0x5555,
            ],
            0x1111,
        ),
        (
            "round_edges",
            [0x3f80_7fff, 0x3f80_8000, 0x3f80_8001, 0xbf80_8000],
            [
                0x1111, 0x2222, 0x3333, 0x4444, 0x5555, 0x6666, 0x7777, 0x8888,
            ],
            0x1111,
        ),
        (
            "mixed_pred",
            [0x3fc0_0000, 0xc020_0000, 0x3f00_0000, 0xbe80_0000],
            [
                0x0123, 0x4567, 0x89ab, 0xcdef, 0xfedc, 0xba98, 0x7654, 0x3210,
            ],
            0x0101,
        ),
        (
            "inactive_merge",
            [0x40a0_0000, 0xc0a0_0000, 0x4120_0000, 0xc120_0000],
            [
                0x1357, 0x2468, 0x9bdf, 0xace0, 0x0ace, 0xfdb9, 0x8642, 0x7531,
            ],
            0x0000,
        ),
        (
            "small_normals",
            [0x0080_0000, 0x8080_0000, 0x0100_0000, 0x8100_0000],
            [
                0xdead, 0xbeef, 0xcafe, 0xbabe, 0x5eed, 0x600d, 0xf00d, 0xface,
            ],
            0x1111,
        ),
        (
            "nan_inf",
            [0x7fa0_0001, 0x7fc0_1234, 0x7f80_0000, 0xff80_0000],
            [
                0x1111, 0x2222, 0x3333, 0x4444, 0x5555, 0x6666, 0x7777, 0x8888,
            ],
            0x1111,
        ),
        (
            "nan_mixed_pred",
            [0x7fa0_0001, 0x7fc0_1234, 0x3f80_0001, 0xff80_0000],
            [
                0x0123, 0x4567, 0x89ab, 0xcdef, 0xfedc, 0xba98, 0x7654, 0x3210,
            ],
            0x0101,
        ),
        (
            "nan_inactive_merge",
            [0x7fa0_0001, 0x7fc0_1234, 0x7f80_0000, 0xff80_0000],
            [
                0x1357, 0x2468, 0x9bdf, 0xace0, 0x0ace, 0xfdb9, 0x8642, 0x7531,
            ],
            0x0000,
        ),
    ];
    for (name, zn, zd, pg) in patterns {
        let mut st = ArmState::zeroed();
        let (lo, hi) = pack_u32(zn);
        st.set_vreg(1, lo, hi);
        let (lo, hi) = pack_u16(zd);
        st.set_vreg(0, lo, hi);
        st.set_preg(0, pg);
        batch.push((format!("bfcvt_{name}"), insn, st));
    }
    run_batch("sve_bfcvt", batch);
}

#[test]
fn diff_sve_bfcvt_fpcr_rmode() {
    let tie_inputs = [
        0x3f80_8000u32,
        0x3f81_8000u32,
        0xbf80_8000u32,
        0xbf81_8000u32,
    ];

    let mut rng = Rng::new(0x9_e002);
    let mut batch = Vec::new();
    for rmode in 0..4u64 {
        let mut packed = 0u128;
        for (lane, bits) in tie_inputs.iter().enumerate() {
            packed |= (*bits as u128) << (32 * lane);
        }

        let mut st = ArmState::zeroed();
        st.fpcr = rmode << 22;
        st.set_preg(0, 0x1111);
        st.set_vreg(RN as usize, packed as u64, (packed >> 64) as u64);
        st.set_vreg(RD as usize, rng.next(), rng.next());
        batch.push((format!("sve_bfcvt_rmode{rmode}"), enc_sve_bfcvt(), st));
    }

    run_batch("sve_bfcvt_fpcr_rmode", batch);
}

