#[test]
fn diff_sve_dupm() {
    // DUPM logical-immediate broadcast across element sizes and patterns.
    let mut batch: Vec<(String, u32, ArmState)> = Vec::new();
    let cases = [
        (0u32, 8u32, 39u32),
        (0, 0, 0b111100),
        (1, 0, 0),
        (1, 0, 62),
        (0, 4, 0b011111),
        (0, 1, 0b110000),
        (0, 0, 0b000000),
        (1, 16, 31),
    ];
    for (n, immr, imms) in cases {
        batch.push((
            format!("dupm n{n} r{immr} s{imms}"),
            enc_sve_dupm(n, immr, imms),
            ArmState::zeroed(),
        ));
    }
    run_batch("sve_dupm", batch);
}

#[test]
fn diff_sve_frecpe() {
    fn pack_fp(size: u32, values: &[u64]) -> (u64, u64) {
        let bits = 8u32 << size;
        let mask = if bits == 64 {
            u64::MAX
        } else {
            (1u64 << bits) - 1
        };
        let mut packed = 0u128;
        for (lane, value) in values.iter().enumerate() {
            packed |= ((*value & mask) as u128) << (lane * bits as usize);
        }
        (packed as u64, (packed >> 64) as u64)
    }

    fn estimate_patterns(size: u32) -> Vec<(&'static str, Vec<u64>)> {
        match size {
            1 => vec![
                (
                    "h_zero_inf",
                    vec![
                        0x0000, 0x8000, 0x3c00, 0xbc00, 0x7c00, 0xfc00, 0x4000, 0xc000,
                    ],
                ),
                (
                    "h_nan_mix",
                    vec![
                        0x7e00, 0xfe00, 0x7d00, 0xfd00, 0x3c00, 0xbc00, 0x0000, 0x8000,
                    ],
                ),
            ],
            2 => vec![
                (
                    "s_zero_inf",
                    vec![
                        0x0000_0000,
                        0x8000_0000,
                        1.0f32.to_bits() as u64,
                        (-1.0f32).to_bits() as u64,
                    ],
                ),
                (
                    "s_nan_mix",
                    vec![0x7f80_0000, 0xff80_0000, 0x7fc0_0001, 0x7f80_0001],
                ),
            ],
            _ => vec![
                ("d_zero_inf", vec![0.0f64.to_bits(), (-0.0f64).to_bits()]),
                (
                    "d_nan_mix",
                    vec![0x7ff0_0000_0000_0000, 0x7ff8_0000_0000_0001],
                ),
            ],
        }
    }

    // FRECPE/FRSQRTE estimate, all sizes, finite inputs.
    let mut rng = Rng::new(0x9_8001);
    let mut batch: Vec<(String, u32, ArmState)> = Vec::new();
    for (size, esz) in [(1u32, 2usize), (2, 4), (3, 8)] {
        for rsqrt in 0..2u32 {
            let insn = enc_sve_frecpe(size, rsqrt);
            for _ in 0..16 {
                let mut zn = 0u128;
                for l in 0..(16 / esz) {
                    zn |= (finite_fp_bits(&mut rng, esz) as u128) << (l * esz * 8);
                }
                let mut st = ArmState::zeroed();
                st.set_vreg(1, zn as u64, (zn >> 64) as u64);
                batch.push((format!("frecpe s{size} r{rsqrt}"), insn, st));
            }
            for (pattern_name, values) in estimate_patterns(size) {
                let mut st = ArmState::zeroed();
                let (lo, hi) = pack_fp(size, &values);
                st.set_vreg(1, lo, hi);
                batch.push((format!("frecpe_s{size}_r{rsqrt}_{pattern_name}"), insn, st));
            }
        }
    }
    run_batch("sve_frecpe", batch);
}

#[test]
fn diff_fpcr_fiz_sve_frecpe_frsqrte_subnormal_inputs() {
    const FPCR_FIZ: u64 = 1;
    let mut batch: Vec<(String, u32, ArmState)> = Vec::new();

    for &(rsqrt, name) in &[(0, "frecpe"), (1, "frsqrte")] {
        let mut st = ArmState::zeroed();
        st.fpcr = FPCR_FIZ;
        let s = 0x0000_0001u32;
        let z = (s as u128) | ((s as u128) << 32) | ((s as u128) << 64) | ((s as u128) << 96);
        st.set_vreg(RN as usize, z as u64, (z >> 64) as u64);
        batch.push((
            format!("sve_{name}_s_fiz_min_subnorm"),
            enc_sve_frecpe(2, rsqrt),
            st,
        ));

        let mut st = ArmState::zeroed();
        st.fpcr = FPCR_FIZ;
        let d = 0x0000_0000_0000_0001u64;
        let z = (d as u128) | ((d as u128) << 64);
        st.set_vreg(RN as usize, z as u64, (z >> 64) as u64);
        batch.push((
            format!("sve_{name}_d_fiz_min_subnorm"),
            enc_sve_frecpe(3, rsqrt),
            st,
        ));
    }

    run_batch("fpcr_fiz_sve_frecpe_frsqrte_subnormal_inputs", batch);
}

#[test]
fn diff_sve_shift_pred_v() {
    // Predicated shift by vector incl. the reversed ASRR/LSRR/LSLR forms.
    fn pack_lanes(size: u32, values: &[u64]) -> (u64, u64) {
        let esize = 1usize << size;
        let bits = esize * 8;
        let elements = 16 / esize;
        let mask = if bits == 64 {
            u64::MAX
        } else {
            (1u64 << bits) - 1
        };
        let mut packed = 0u128;
        for lane in 0..elements {
            let value = values[lane % values.len()] & mask;
            packed |= (value as u128) << (lane * bits);
        }
        (packed as u64, (packed >> 64) as u64)
    }

    let mut batch: Vec<(String, u32, ArmState)> = Vec::new();
    let preds = [0x0000u16, 0x0001, 0x00ff, 0x5555, 0xaaaa, 0xffff];
    for size in 0..4u32 {
        let bits = 8u64 << size;
        let max = if bits == 64 {
            u64::MAX
        } else {
            (1u64 << bits) - 1
        };
        let sign = 1u64 << (bits - 1);
        let values = pack_lanes(size, &[0, 1, sign, max, max >> 1]);
        let shifts = pack_lanes(size, &[0, 1, bits - 1, bits, bits + 1]);
        let ones = pack_lanes(size, &[max]);
        for opc in [0b000u32, 0b001, 0b011, 0b100, 0b101, 0b111] {
            let insn = enc_sve_shift_pred_v(size, opc);
            for pred in preds {
                for (case, zdn, zm) in [
                    ("values_shifts", values, shifts),
                    ("shifts_values", shifts, values),
                    ("ones_shifts", ones, shifts),
                ] {
                    let mut st = ArmState::zeroed();
                    st.set_vreg(0, zdn.0, zdn.1);
                    st.set_vreg(1, zm.0, zm.1);
                    st.set_preg(0, pred);
                    batch.push((
                        format!("shift_pred s{size} op{opc:b} p{pred:04x} {case}"),
                        insn,
                        st,
                    ));
                }
            }
        }
    }
    run_batch("sve_shift_pred_v", batch);
}

#[test]
fn diff_sve_rev_rbit() {
    // REVB/REVH/REVW/RBIT reverse byte/halfword/word/bit order within elements.
    let mut batch: Vec<(String, u32, ArmState)> = Vec::new();
    let cases: &[(u32, &[u32])] = &[
        (0b00, &[1, 2, 3]),
        (0b01, &[2, 3]),
        (0b10, &[3]),
        (0b11, &[0, 1, 2, 3]),
    ];
    let preds = [0x0000u16, 0x0001, 0x00ff, 0x5555, 0xaaaa, 0xffff];
    let patterns = [
        ("zero", 0u64, 0u64),
        ("ones", u64::MAX, u64::MAX),
        ("bytes", 0x0706_0504_0302_0100, 0x0f0e_0d0c_0b0a_0908),
        ("sign", 0x8000_0000_7fff_ffff, 0xffff_0000_0000_0001),
        ("bits", 0x0123_4567_89ab_cdef, 0xfedc_ba98_7654_3210),
    ];
    for &(op, sizes) in cases {
        for &size in sizes {
            let insn = enc_sve_rev_rbit(size, op);
            for pred in preds {
                for &(pattern, lo, hi) in &patterns {
                    let mut st = ArmState::zeroed();
                    st.set_vreg(1, lo, hi);
                    st.set_vreg(0, !lo, !hi);
                    st.set_preg(0, pred);
                    batch.push((
                        format!("rev op{op:b} s{size} p{pred:04x} {pattern}"),
                        insn,
                        st,
                    ));
                }
            }
        }
    }
    run_batch("sve_rev_rbit", batch);
}

