#[test]
fn diff_sve_insr() {
    // INSR inserts a GPR or SIMD-scalar element at the bottom, shifting up.
    let mut rng = Rng::new(0x9_2001);
    let mut batch: Vec<(String, u32, ArmState)> = Vec::new();
    for size in 0..4u32 {
        for f in 0..2u32 {
            let insn = enc_sve_insr(size, f);
            for _ in 0..6 {
                let mut st = ArmState::zeroed();
                st.set_vreg(0, rng.next(), rng.next());
                st.set_vreg(1, rng.next(), rng.next());
                st.x[1] = rng.next();
                batch.push((format!("insr s{size} f{f}"), insn, st));
            }
        }
    }
    for size in 0..4u32 {
        for f in 0..2u32 {
            let insn = enc_sve_insr(size, f);
            for (case_name, z0, z1, x1) in [
                ("zero", (0u64, 0u64), (0u64, 0u64), 0u64),
                ("ones", (u64::MAX, u64::MAX), (u64::MAX, u64::MAX), u64::MAX),
                (
                    "sign",
                    (0x8000_0000_7fff_ffff, 0xffff_0000_0000_0001),
                    (0x7fff_ffff_8000_0000, 0x0001_0000_ffff_0000),
                    0x8000_0000_0000_0001,
                ),
                (
                    "bytes",
                    (0x0706_0504_0302_0100, 0x0f0e_0d0c_0b0a_0908),
                    (0xf8f9_fafb_fcfd_feff, 0xf0f1_f2f3_f4f5_f6f7),
                    0x1122_3344_5566_7788,
                ),
            ] {
                let mut st = ArmState::zeroed();
                st.set_vreg(0, z0.0, z0.1);
                st.set_vreg(1, z1.0, z1.1);
                st.x[RN as usize] = x1;
                batch.push((format!("insr_s{size}_f{f}_{case_name}"), insn, st));
            }
        }
    }
    run_batch("sve_insr", batch);
}

#[test]
fn diff_sve_insr_zero_register() {
    fn insr_gpr(size: u32, rm: u32) -> u32 {
        (0x05 << 24)
            | (size << 22)
            | (1 << 21)
            | (0b00100 << 16)
            | (0b001110 << 10)
            | ((rm & 0x1f) << 5)
            | RD
    }

    let mut rng = Rng::new(0x9_2002);
    let mut batch: Vec<(String, u32, ArmState)> = Vec::new();
    for size in 0..4u32 {
        let insn = insr_gpr(size, 31);
        for i in 0..10 {
            let mut st = ArmState::zeroed();
            st.sp = GUEST_STACK_ADDR + (GUEST_STACK_SIZE / 2) + 0x16000 + ((i as u64) << 4);
            st.set_vreg(0, rng.next(), rng.next());
            batch.push((format!("insr_xzr s{size}"), insn, st));
        }
        for (case_name, z0, sp_delta) in [
            ("zero", (0u64, 0u64), 0x00u64),
            ("ones", (u64::MAX, u64::MAX), 0x10),
            (
                "bytes",
                (0x0706_0504_0302_0100, 0x0f0e_0d0c_0b0a_0908),
                0x20,
            ),
            ("sign", (0x8000_0000_7fff_ffff, 0xffff_0000_0000_0001), 0x30),
        ] {
            let mut st = ArmState::zeroed();
            st.sp = GUEST_STACK_ADDR
                + (GUEST_STACK_SIZE / 2)
                + 0x16800
                + ((size as u64) << 8)
                + sp_delta;
            st.set_vreg(0, z0.0, z0.1);
            st.x[RN as usize] = 0x1122_3344_5566_7788;
            batch.push((format!("insr_xzr_s{size}_{case_name}"), insn, st));
        }
    }
    run_batch("sve_insr_zero_register", batch);
}

#[test]
fn diff_sve_clast_dst() {
    // CLASTA/CLASTB to vector and SIMD-scalar destinations.
    let mut rng = Rng::new(0x9_3001);
    let mut batch: Vec<(String, u32, ArmState)> = Vec::new();

    fn predicate_bit(size: u32, lane: usize) -> u16 {
        1u16 << (lane * (1usize << size))
    }

    for size in 0..4u32 {
        for scalar in 0..2u32 {
            for before in 0..2u32 {
                let insn = enc_sve_clast(size, scalar, before);
                for _ in 0..6 {
                    let mut st = ArmState::zeroed();
                    st.set_vreg(0, rng.next(), rng.next());
                    st.set_vreg(1, rng.next(), rng.next());
                    st.set_preg(0, rng.next() as u16);
                    batch.push((format!("clast s{size} sc{scalar} b{before}"), insn, st));
                }
                let lanes = 16usize >> size;
                let first = predicate_bit(size, 0);
                let last = predicate_bit(size, lanes - 1);
                for (case_name, pg) in [
                    ("first", first),
                    ("last", last),
                    ("endpoints", first | last),
                    ("inactive", 0x0000),
                ] {
                    let mut st = ArmState::zeroed();
                    st.set_vreg(0, 0xdead_beef_dead_beef, 0xfeed_face_feed_face);
                    st.set_vreg(1, 0x0706_0504_0302_0100, 0x0f0e_0d0c_0b0a_0908);
                    st.set_preg(0, pg);
                    batch.push((
                        format!("clast_s{size}_sc{scalar}_b{before}_{case_name}"),
                        insn,
                        st,
                    ));
                }
            }
        }
    }
    run_batch("sve_clast_dst", batch);
}

#[test]
fn diff_sve_fcpy_fdup() {
    // FCPY (predicated FP immediate copy) and FDUP (FP immediate broadcast).
    let mut rng = Rng::new(0x9_4001);
    let mut batch: Vec<(String, u32, ArmState)> = Vec::new();

    fn predicate_bit(size: u32, lane: usize) -> u16 {
        1u16 << (lane * (1usize << size))
    }

    for size in 1..4u32 {
        for imm8 in 0..=0xFFu32 {
            let mut st = ArmState::zeroed();
            st.set_vreg(0, rng.next(), rng.next());
            st.set_preg(0, rng.next() as u16);
            batch.push((
                format!("fcpy s{size} i{imm8:x}"),
                enc_sve_fcpy(size, imm8),
                st,
            ));
            batch.push((
                format!("fdup s{size} i{imm8:x}"),
                enc_sve_fdup(size, imm8),
                ArmState::zeroed(),
            ));
        }
        let lanes = 16usize >> size;
        let first = predicate_bit(size, 0);
        let last = predicate_bit(size, lanes - 1);
        for imm8 in [0x00u32, 0x01, 0x7f, 0x80, 0xff] {
            for (mask_name, pg) in [
                ("all", 0xffff),
                ("first", first),
                ("last", last),
                ("inactive", 0x0000),
            ] {
                let mut st = ArmState::zeroed();
                st.set_vreg(0, 0xdead_beef_dead_beef, 0xfeed_face_feed_face);
                st.set_preg(0, pg);
                batch.push((
                    format!("fcpy_s{size}_i{imm8:02x}_{mask_name}"),
                    enc_sve_fcpy(size, imm8),
                    st,
                ));
            }
            let mut st = ArmState::zeroed();
            st.set_vreg(0, 0x0123_4567_89ab_cdef, 0xfedc_ba98_7654_3210);
            batch.push((
                format!("fdup_s{size}_i{imm8:02x}_edge"),
                enc_sve_fdup(size, imm8),
                st,
            ));
        }
    }
    run_batch("sve_fcpy_fdup", batch);
}

#[test]
fn diff_sve_cterm() {
    // CTERMEQ/CTERMNE: compare two GP regs, set N/V leaving Z/C unchanged (so
    // the input NZCV matters). Mix equal and unequal operands, random flags.
    let mut rng = Rng::new(0x8_7001);
    let mut batch: Vec<(String, u32, ArmState)> = Vec::new();
    for sf in 0..2u32 {
        for ne in 0..2u32 {
            let insn = enc_sve_cterm(sf, ne);
            for _ in 0..12 {
                let mut st = ArmState::zeroed();
                let base = rng.next();
                st.x[1] = base;
                st.x[2] = if rng.next() & 1 == 0 {
                    base
                } else {
                    rng.next()
                };
                st.pstate = (rng.next() & 0xF) << 28; // random input NZCV
                batch.push((format!("cterm sf{sf} ne{ne}"), insn, st));
            }
            for (case_name, rn, rm) in [
                ("equal_zero", 0u64, 0u64),
                ("equal_sign", 0x8000_0000_8000_0000, 0x8000_0000_8000_0000),
                (
                    "high_diff_low_equal",
                    0xaaaa_0000_1234_5678,
                    0xbbbb_0000_1234_5678,
                ),
                ("low_diff", 0x0000_0000_1234_5678, 0x0000_0000_1234_5679),
            ] {
                for nzcv in [0x0u64, 0x5, 0xa, 0xf] {
                    let mut st = ArmState::zeroed();
                    st.x[RN as usize] = rn;
                    st.x[RM as usize] = rm;
                    st.pstate = nzcv << 28;
                    batch.push((
                        format!("cterm_sf{sf}_ne{ne}_{case_name}_nzcv{nzcv:x}"),
                        insn,
                        st,
                    ));
                }
            }
        }
    }
    run_batch("sve_cterm", batch);
}

#[test]
fn diff_sve_cterm_zero_registers() {
    fn cterm_regs(sf: u32, ne: u32, rn: u32, rm: u32) -> u32 {
        (0x25 << 24)
            | (1 << 23)
            | (sf << 22)
            | (1 << 21)
            | ((rm & 0x1f) << 16)
            | (0b001000 << 10)
            | ((rn & 0x1f) << 5)
            | (ne << 4)
    }

    let mut rng = Rng::new(0x8_7002);
    let mut batch: Vec<(String, u32, ArmState)> = Vec::new();
    for sf in 0..=1 {
        for ne in 0..=1 {
            for (alias, rn, rm) in [
                ("rn_xzr", 31u32, RM),
                ("rm_xzr", RN, 31),
                ("rn_rm_xzr", 31, 31),
            ] {
                for nzcv in 0..16u64 {
                    let mut st = ArmState::zeroed();
                    st.sp = GUEST_STACK_ADDR + (GUEST_STACK_SIZE / 2) + 0x14000 + (nzcv << 4);
                    st.x[RN as usize] = rng.next();
                    st.x[RM as usize] = rng.next();
                    st.pstate = nzcv << 28;
                    batch.push((
                        format!("cterm_{alias}_sf{sf}_ne{ne}_nzcv{nzcv:x}"),
                        cterm_regs(sf, ne, rn, rm),
                        st,
                    ));
                }
            }
        }
    }
    run_batch("sve_cterm_zero_registers", batch);
}

