#[test]
fn diff_sve_fmmla_fpcr_rounding() {
    let insn = enc_sve_fmmla(0b10);
    let mut batch: Vec<(String, u32, ArmState)> = Vec::new();
    for rmode in 0..4u64 {
        for &(name, acc, nval) in &[
            ("pos", 16_777_216.0f32, 1.0f32),
            ("neg", -16_777_216.0f32, -1.0f32),
        ] {
            let mut st = ArmState::zeroed();
            st.fpcr = rmode << 22;
            let zn = (nval.to_bits() as u128)
                | ((0.0f32.to_bits() as u128) << 32)
                | ((nval.to_bits() as u128) << 64)
                | ((0.0f32.to_bits() as u128) << 96);
            let zm = (1.0f32.to_bits() as u128)
                | ((0.0f32.to_bits() as u128) << 32)
                | ((1.0f32.to_bits() as u128) << 64)
                | ((0.0f32.to_bits() as u128) << 96);
            let mut za = 0u128;
            for lane in 0..4 {
                za |= (acc.to_bits() as u128) << (lane * 32);
            }
            st.set_vreg(RN as usize, zn as u64, (zn >> 64) as u64);
            st.set_vreg(RM as usize, zm as u64, (zm >> 64) as u64);
            st.set_vreg(RD as usize, za as u64, (za >> 64) as u64);
            batch.push((format!("fmmla_s_{name}_rmode{rmode}"), insn, st));
        }
    }
    run_batch("sve_fmmla_fpcr_rounding", batch);
}

#[test]
fn diff_sve_bfmmla() {
    fn pack_bf16(values: [u16; 8]) -> (u64, u64) {
        let mut packed = 0u128;
        for (lane, value) in values.iter().enumerate() {
            packed |= (*value as u128) << (lane * 16);
        }
        (packed as u64, (packed >> 64) as u64)
    }

    fn pack_f32(values: [f32; 4]) -> (u64, u64) {
        let mut packed = 0u128;
        for (lane, value) in values.iter().enumerate() {
            packed |= (value.to_bits() as u128) << (lane * 32);
        }
        (packed as u64, (packed >> 64) as u64)
    }

    // BFMMLA: bf16 2x2 matrix multiply accumulating into f32, round-to-odd.
    let insn = enc_sve_fmmla(0b01);
    let mut rng = Rng::new(0x7_3001);
    let mut batch: Vec<(String, u32, ArmState)> = Vec::new();
    for _ in 0..40 {
        let (mut zn, mut zm, mut za) = (0u128, 0u128, 0u128);
        for l in 0..8 {
            zn |= ((finite_fp_bits(&mut rng, 4) >> 16) as u128) << (l * 16); // finite bf16
            zm |= ((finite_fp_bits(&mut rng, 4) >> 16) as u128) << (l * 16);
        }
        for l in 0..4 {
            za |= (finite_fp_bits(&mut rng, 4) as u128) << (l * 32);
        }
        let mut st = ArmState::zeroed();
        st.set_vreg(1, zn as u64, (zn >> 64) as u64);
        st.set_vreg(2, zm as u64, (zm >> 64) as u64);
        st.set_vreg(0, za as u64, (za >> 64) as u64);
        batch.push(("bfmmla".to_string(), insn, st));
    }

    let patterns = [
        (
            "zeros",
            [0.0, -0.0, 0.0, -0.0],
            [
                0x0000, 0x8000, 0x0000, 0x8000, 0x0000, 0x8000, 0x0000, 0x8000,
            ],
            [0x3f80; 8],
        ),
        (
            "ones",
            [1.0, -1.0, 2.0, -2.0],
            [
                0x3f80, 0xbf80, 0x4000, 0xc000, 0x3f00, 0xbf00, 0x4080, 0xc080,
            ],
            [
                0x3f80, 0x3f80, 0xbf80, 0xbf80, 0x4000, 0xc000, 0x3f00, 0xbf00,
            ],
        ),
        (
            "lane_mix",
            [16.0, -16.0, 0.5, -0.5],
            [
                0x3f80, 0x4000, 0x4040, 0x4080, 0xbf80, 0xc000, 0xc040, 0xc080,
            ],
            [
                0x3f00, 0xbf00, 0x3fc0, 0xbfc0, 0x4020, 0xc020, 0x4060, 0xc060,
            ],
        ),
        (
            "small_normals",
            [0.0, 1.0, -1.0, 8.0],
            [
                0x0080, 0x8080, 0x0100, 0x8100, 0x3f80, 0xbf80, 0x4000, 0xc000,
            ],
            [
                0x3f80, 0xbf80, 0x0080, 0x8080, 0x3f00, 0xbf00, 0x4000, 0xc000,
            ],
        ),
        (
            "nan_inf",
            [
                0.0,
                f32::from_bits(0x7fc0_1234),
                f32::from_bits(0x7fa0_0001),
                f32::NEG_INFINITY,
            ],
            [
                0x7f81, 0x7fc0, 0x0000, 0x0000, 0x7f80, 0xff80, 0x3f80, 0xbf80,
            ],
            [
                0x3f80, 0xbf80, 0x7f80, 0x7f80, 0x0000, 0x8000, 0x7f81, 0x7fc0,
            ],
        ),
    ];
    for (pattern_name, acc, zn, zm) in patterns {
        let mut st = ArmState::zeroed();
        let (lo, hi) = pack_f32(acc);
        st.set_vreg(0, lo, hi);
        let (lo, hi) = pack_bf16(zn);
        st.set_vreg(1, lo, hi);
        let (lo, hi) = pack_bf16(zm);
        st.set_vreg(2, lo, hi);
        batch.push((format!("bfmmla_{pattern_name}"), insn, st));
    }
    run_batch("sve_bfmmla", batch);
}

#[test]
fn diff_sve_mmla() {
    // I8MM integer matrix multiply-accumulate, all three sign variants.
    let mut rng = Rng::new(0x7_1001);
    let mut batch: Vec<(String, u32, ArmState)> = Vec::new();
    for (uns, name) in [(0b00u32, "smmla"), (0b10, "usmmla"), (0b11, "ummla")] {
        let insn = enc_sve_mmla(uns);
        for _ in 0..30 {
            let mut st = ArmState::zeroed();
            st.set_vreg(1, rng.next(), rng.next());
            st.set_vreg(2, rng.next(), rng.next());
            st.set_vreg(0, rng.next(), rng.next());
            batch.push((name.to_string(), insn, st));
        }
        for (zn, zm, za, edge) in [
            (0, 0, 0, "zero"),
            (u128::MAX, u128::MAX, 0, "all_ff"),
            (
                0x8080_8080_8080_8080_8080_8080_8080_8080u128,
                0x7f7f_7f7f_7f7f_7f7f_7f7f_7f7f_7f7f_7f7fu128,
                0,
                "signed_min_max",
            ),
            (
                0x00ff_807f_55aa_aa55_0102_0304_fefd_fcfbu128,
                0xff00_7f80_aa55_55aa_0403_0201_0102_0304u128,
                0x7fff_ffff_8000_0000_ffff_ffff_0000_0001u128,
                "mixed_acc",
            ),
        ] {
            let mut st = ArmState::zeroed();
            st.set_vreg(1, zn as u64, (zn >> 64) as u64);
            st.set_vreg(2, zm as u64, (zm >> 64) as u64);
            st.set_vreg(0, za as u64, (za >> 64) as u64);
            batch.push((format!("{name}_{edge}"), insn, st));
        }
    }
    run_batch("sve_mmla", batch);
}

#[test]
fn diff_sve2_xar() {
    // XAR rotates (Zdn ^ Zm) right by an immediate, per element. Test every
    // valid amount for every element size, including full-width identity.
    fn pack_lanes(size_log: u32, values: &[u64]) -> (u64, u64) {
        let bits = 8u32 << size_log;
        let lanes = 16usize >> size_log;
        let mask = if bits == 64 {
            u64::MAX
        } else {
            (1u64 << bits) - 1
        };
        let mut packed = 0u128;
        for lane in 0..lanes {
            packed |= ((values[lane % values.len()] & mask) as u128) << (lane * bits as usize);
        }
        (packed as u64, (packed >> 64) as u64)
    }

    let mut rng = Rng::new(0x6_f001);
    let mut batch: Vec<(String, u32, ArmState)> = Vec::new();
    for size_log in 0..4u32 {
        let bits = 8u32 << size_log;
        for amount in 1..=bits {
            let insn = enc_sve2_xar(size_log, amount);
            for _ in 0..4 {
                let mut st = ArmState::zeroed();
                st.set_vreg(0, rng.next(), rng.next()); // Zdn
                st.set_vreg(1, rng.next(), rng.next()); // Zm
                batch.push((format!("xar sl{size_log} a{amount}"), insn, st));
            }
        }
        for amount in [1u32, bits / 2, bits] {
            let insn = enc_sve2_xar(size_log, amount);
            for (case_name, zdn, zm) in [
                (
                    "zero",
                    pack_lanes(size_log, &[0]),
                    pack_lanes(size_log, &[0]),
                ),
                (
                    "ones",
                    pack_lanes(size_log, &[u64::MAX]),
                    pack_lanes(size_log, &[0]),
                ),
                (
                    "checker",
                    pack_lanes(size_log, &[0x55, 0xaa, 0x33, 0xcc]),
                    pack_lanes(size_log, &[0x0f, 0xf0, 0x5a, 0xa5]),
                ),
                (
                    "edge_bits",
                    pack_lanes(size_log, &[1, 0x80, 0x8000, 0x8000_0000]),
                    pack_lanes(size_log, &[0, u64::MAX, 1, u64::MAX - 1]),
                ),
            ] {
                let mut st = ArmState::zeroed();
                st.set_vreg(0, zdn.0, zdn.1);
                st.set_vreg(1, zm.0, zm.1);
                batch.push((format!("xar_sl{size_log}_a{amount}_{case_name}"), insn, st));
            }
        }
    }
    run_batch("sve2_xar", batch);
}

