#[test]
fn diff_sve_ffr() {
    // FFR manipulation, tested as two-instruction sequences that read the FFR
    // back into a captured predicate (p0): SETFFR/WRFFR then RDFFR.
    let mut rng = Rng::new(0x4_D001);
    let mut batch: Vec<(String, u32, u32, ArmState)> = Vec::new();
    for _ in 0..8 {
        // SETFFR ; RDFFR p0  -> p0 = all-true.
        batch.push((
            "setffr+rdffr".to_string(),
            enc_setffr(),
            enc_rdffr(0),
            ArmState::zeroed(),
        ));
    }
    for _ in 0..16 {
        // WRFFR p1 ; RDFFR p0  -> p0 = p1.
        let mut st = ArmState::zeroed();
        st.set_preg(1, rng.next() as u16);
        batch.push(("wrffr+rdffr".to_string(), enc_wrffr(1), enc_rdffr(0), st));
    }
    for _ in 0..16 {
        // WRFFR p1 ; RDFFR p0, p2/Z  -> p0 = p1 & p2.
        let mut st = ArmState::zeroed();
        st.set_preg(1, rng.next() as u16);
        st.set_preg(2, rng.next() as u16);
        batch.push((
            "wrffr+rdffr_pred".to_string(),
            enc_wrffr(1),
            enc_rdffr_pred(0, 2),
            st,
        ));
    }
    {
        // SETFFR overwrites the previous FFR state; RDFFR then exposes all-true.
        let mut st = ArmState::zeroed();
        st.set_ffr(0x1357);
        st.set_preg(0, 0x2468);
        batch.push((
            "setffr+rdffr_overwrite".to_string(),
            enc_setffr(),
            enc_rdffr(0),
            st,
        ));
    }
    for &ffr in &[0x0000u16, 0x0001, 0x00ff, 0x8000, 0xaaaa, 0xffff] {
        let mut st = ArmState::zeroed();
        st.set_preg(1, ffr);
        batch.push((
            format!("wrffr+rdffr ffr={ffr:#06x}"),
            enc_wrffr(1),
            enc_rdffr(0),
            st,
        ));
    }
    for (ffr, pg) in [
        (0x0000, 0xffff),
        (0xffff, 0x0000),
        (0x0001, 0x8001),
        (0x8000, 0x8001),
        (0x00ff, 0x0f0f),
        (0xaaaa, 0x5555),
        (0x5555, 0xaaaa),
    ] {
        let mut st = ArmState::zeroed();
        st.set_preg(1, ffr);
        st.set_preg(2, pg);
        batch.push((
            format!("wrffr+rdffr_pred ffr={ffr:#06x} pg={pg:#06x}"),
            enc_wrffr(1),
            enc_rdffr_pred(0, 2),
            st,
        ));
    }
    for (ffr, pg) in [
        (0x0000, 0x0000),
        (0xffff, 0x0000),
        (0x0001, 0xffff),
        (0x8000, 0xffff),
        (0x00ff, 0x0f0f),
        (0xaaaa, 0x5555),
        (0x5555, 0xaaaa),
        (0xf00f, 0x3333),
    ] {
        // WRFFR p1 ; RDFFRS p0, p2/Z -> p0 = p1 & p2 and NZCV = PredTest(p2, p0).
        let mut st = ArmState::zeroed();
        st.pstate = (rng.next() & 0xf) << 28;
        st.set_preg(1, ffr);
        st.set_preg(2, pg);
        batch.push((
            format!("wrffr+rdffrs ffr={ffr:#06x} pg={pg:#06x}"),
            enc_wrffr(1),
            enc_rdffrs_pred(0, 2),
            st,
        ));
    }
    run_batch_pair("sve_ffr", batch);
}

#[test]
fn diff_sve_ffr_direct_state() {
    // Directly compare FFR as architectural state, rather than only through
    // an RDFFR predicate readback. This covers both oracle FFR injection and
    // signal-frame capture.
    let mut batch: Vec<(String, u32, ArmState)> = Vec::new();
    for &ffr in &[0x0000, 0x0001, 0x00ff, 0xaaaa, 0xffff] {
        let mut st = ArmState::zeroed();
        st.set_ffr(ffr);
        st.set_preg(0, !ffr);
        batch.push((format!("rdffr initial ffr={ffr:#06x}"), enc_rdffr(0), st));
    }
    for &initial in &[0x0000, 0x1234, 0xffff] {
        let mut st = ArmState::zeroed();
        st.set_ffr(initial);
        batch.push((
            format!("setffr initial ffr={initial:#06x}"),
            enc_setffr(),
            st,
        ));
    }
    for &pred in &[0x0000, 0x0001, 0x5555, 0x8000, 0xffff] {
        let mut st = ArmState::zeroed();
        st.set_ffr(!pred);
        st.set_preg(1, pred);
        batch.push((format!("wrffr p1={pred:#06x}"), enc_wrffr(1), st));
    }
    run_batch("sve_ffr_direct_state", batch);
}

#[test]
fn diff_sve_ffr_fixed_field_legality() {
    let valid = [
        ("setffr", enc_setffr()),
        ("wrffr_p0", enc_wrffr(0)),
        ("wrffr_p15", enc_wrffr(15)),
        ("rdffr_p0", enc_rdffr(0)),
        ("rdffr_p15", enc_rdffr(15)),
        ("rdffr_pred_p0_p0", enc_rdffr_pred(0, 0)),
        ("rdffr_pred_p15_p15", enc_rdffr_pred(15, 15)),
        ("rdffrs_pred_p0_p0", enc_rdffrs_pred(0, 0)),
        ("rdffrs_pred_p15_p15", enc_rdffrs_pred(15, 15)),
    ];
    let invalid = [
        ("setffr_bit0", enc_setffr() | 1),
        ("setffr_bit5", enc_setffr() | (1 << 5)),
        ("setffr_bit9", enc_setffr() | (1 << 9)),
        ("wrffr_bit0", enc_wrffr(1) | 1),
        ("wrffr_bit9", enc_wrffr(1) | (1 << 9)),
        ("wrffr_bit10", enc_wrffr(1) | (1 << 10)),
        ("rdffr_bit4", enc_rdffr(0) | (1 << 4)),
        ("rdffr_bit5", enc_rdffr(0) | (1 << 5)),
        ("rdffr_bit9", enc_rdffr(0) | (1 << 9)),
        ("rdffr_pred_bit4", enc_rdffr_pred(0, 2) | (1 << 4)),
        ("rdffr_pred_bit9", enc_rdffr_pred(0, 2) | (1 << 9)),
        ("rdffr_pred_bit10", enc_rdffr_pred(0, 2) | (1 << 10)),
        ("rdffrs_pred_bit4", enc_rdffrs_pred(0, 2) | (1 << 4)),
        ("rdffrs_pred_bit9", enc_rdffrs_pred(0, 2) | (1 << 9)),
        ("rdffrs_pred_bit10", enc_rdffrs_pred(0, 2) | (1 << 10)),
    ];

    let mut batch = Vec::new();
    for (label, insn) in valid.into_iter().chain(invalid) {
        let mut st = ArmState::zeroed();
        st.set_ffr(0x5a5a);
        st.set_preg(0, 0x3333);
        st.set_preg(1, 0x5555);
        st.set_preg(2, 0xaaaa);
        st.set_preg(15, 0xf0f0);
        batch.push((label.to_string(), insn, st));
    }

    run_batch_el0_legality("sve_ffr_fixed_field_legality", batch);
}

#[test]
fn diff_sve_ld1rq() {
    // Load-replicate quadword (at VL=128 a packed contiguous quadword load).
    let mut rng = Rng::new(0x4_C001);
    let mut batch: Vec<(String, u32, ArmState)> = Vec::new();
    for msz in 0..4u32 {
        for &imm4 in &[0i32, 1, -1] {
            let insn = enc_ld1rq_i(msz, imm4);
            for _ in 0..5 {
                let mut st = mem_input(&mut rng);
                st.set_preg(0, rng.next() as u16);
                batch.push((format!("ld1rqi m{msz} i{imm4}"), insn, st));
            }
        }
        for &xm in &[0u64, 1, 2] {
            let insn = enc_ld1rq_r(msz);
            for _ in 0..5 {
                let mut st = mem_input(&mut rng);
                st.x[2] = xm;
                st.set_preg(0, rng.next() as u16);
                batch.push((format!("ld1rqr m{msz} x{xm}"), insn, st));
            }
        }
    }
    fn deterministic_ld1rq_input(xm: u64, pg: u16) -> ArmState {
        let mut st = ArmState::zeroed();
        st.x[RN as usize] = SCRATCH_BASE;
        st.x[RM as usize] = xm;
        st.set_vreg(0, 0xdead_beef_dead_beef, 0xfeed_face_feed_face);
        st.set_preg(0, pg);
        for (idx, word) in st.scratch.iter_mut().enumerate() {
            *word = 0x807f_00ff_aa55_0102u64 ^ (idx as u64).wrapping_mul(0x1110_0908_0503_0201);
        }
        st
    }

    for msz in 0..4u32 {
        for &imm4 in &[0i32, 1, -1] {
            let insn = enc_ld1rq_i(msz, imm4);
            for (mask_name, pg) in [("all", 0xffff), ("first", 0x0001), ("inactive", 0x0000)] {
                batch.push((
                    format!("ld1rqi_m{msz}_i{imm4}_{mask_name}"),
                    insn,
                    deterministic_ld1rq_input(0, pg),
                ));
            }
        }
        let insn = enc_ld1rq_r(msz);
        for &xm in &[0u64, 2] {
            for (mask_name, pg) in [("all", 0xffff), ("first", 0x0001), ("inactive", 0x0000)] {
                batch.push((
                    format!("ld1rqr_m{msz}_x{xm}_{mask_name}"),
                    insn,
                    deterministic_ld1rq_input(xm, pg),
                ));
            }
        }
    }
    run_batch("sve_ld1rq", batch);
}

#[test]
fn diff_sve_ld1rq_sp_rm31_edges() {
    let cases: Vec<(String, u32, Option<u64>)> = vec![
        ("ld1rqi_b_sp".into(), enc_ld1rq_i_regs(0, 0, 31), None),
        ("ld1rqi_d_sp".into(), enc_ld1rq_i_regs(3, 0, 31), None),
        ("ld1rqr_b_sp".into(), enc_ld1rq_r_regs(0, RM, 31), Some(0)),
        ("ld1rqr_d_sp".into(), enc_ld1rq_r_regs(3, RM, 31), Some(0)),
        ("ld1rqr_b_rm31".into(), enc_ld1rq_r_regs(0, 31, RN), None),
        ("ld1rqr_d_rm31".into(), enc_ld1rq_r_regs(3, 31, RN), None),
    ];
    let mut rng = Rng::new(0x4_C011);
    let mut batch = Vec::new();

    for (label, insn, rm_value) in &cases {
        let offsets: &[u64] = if label.contains("_sp") { &[1, 8] } else { &[0] };
        for offset in offsets {
            let mut st = mem_input(&mut rng);
            st.sp = SCRATCH_BASE + offset;
            st.set_preg(0, 0xffff);
            st.set_vreg(0, rng.next(), rng.next());
            if let Some(value) = rm_value {
                st.x[RM as usize] = *value;
            }
            batch.push((format!("{label}_off{offset}"), *insn, st));
        }
    }

    run_batch("sve_ld1rq_sp_rm31_edges", batch);
}

#[test]
fn diff_sve_ldnt1() {
    // Non-temporal contiguous load/store (behaves like packed LD1/ST1).
    let mut rng = Rng::new(0x4_9001);
    let mut batch: Vec<(String, u32, ArmState)> = Vec::new();
    for msz in 0..4u32 {
        for &imm4 in &[0i32, 1, -1] {
            for _ in 0..6 {
                let mut s1 = mem_input(&mut rng);
                s1.set_preg(0, rng.next() as u16);
                batch.push((format!("ldnt1 m{msz} i{imm4}"), enc_ldnt1(msz, imm4), s1));
                let mut s2 = mem_input(&mut rng);
                s2.set_preg(0, rng.next() as u16);
                batch.push((format!("stnt1 m{msz} i{imm4}"), enc_stnt1(msz, imm4), s2));
            }
        }
    }
    fn deterministic_ldnt1_input(pg: u16) -> ArmState {
        let mut st = ArmState::zeroed();
        st.x[RN as usize] = SCRATCH_BASE;
        st.set_vreg(0, 0x807f_00ff_aa55_0102, 0x7f80_ff00_55aa_fefd);
        st.set_preg(0, pg);
        for (idx, word) in st.scratch.iter_mut().enumerate() {
            *word = 0x1020_4080_0102_0408u64 ^ (idx as u64).wrapping_mul(0x0f1e_2d3c_4b5a_6978);
        }
        st
    }

    for msz in 0..4u32 {
        for &imm4 in &[0i32, 1, -1] {
            for (mask_name, pg) in [("all", 0xffff), ("first", 0x0001), ("inactive", 0x0000)] {
                batch.push((
                    format!("ldnt1_m{msz}_i{imm4}_{mask_name}"),
                    enc_ldnt1(msz, imm4),
                    deterministic_ldnt1_input(pg),
                ));
                batch.push((
                    format!("stnt1_m{msz}_i{imm4}_{mask_name}"),
                    enc_stnt1(msz, imm4),
                    deterministic_ldnt1_input(pg),
                ));
            }
        }
    }
    run_batch("sve_ldnt1", batch);
}

#[test]
fn diff_sve_ldnt1_vector_base_scalar_offset() {
    fn input(offset: u64, pg: u16) -> ArmState {
        let mut st = ArmState::zeroed();
        st.x[24] = offset;
        st.set_vreg(2, SCRATCH_BASE + 0x10, SCRATCH_BASE + 0x50);
        st.set_vreg(1, 0xfeed_face_feed_face, 0xdead_beef_dead_beef);
        st.set_preg(6, pg);
        for (idx, word) in st.scratch.iter_mut().enumerate() {
            *word = 0x807f_00ff_7f80_0102u64 ^ (idx as u64).wrapping_mul(0x1122_3344_5566_7788);
        }
        st
    }

    let mut batch: Vec<(String, u32, ArmState)> = Vec::new();
    for msz in 0..4u32 {
        for unsigned in [false, true] {
            if !unsigned && msz == 3 {
                continue;
            }
            let name = if unsigned { "u" } else { "s" };
            let insn = enc_ldnt1_vs_d(msz, unsigned, 24, 6, 2, 1);
            for (mask_name, pg) in [
                ("all", 0xffff),
                ("first", 0x0001),
                ("second", 0x0100),
                ("inactive", 0),
            ] {
                batch.push((
                    format!("ldnt1_vbase_{name}_m{msz}_{mask_name}"),
                    insn,
                    input(3, pg),
                ));
            }
        }
    }
    batch.push((
        "ldnt1sb_fuzz_c4189841".into(),
        0xc418_9841,
        input(3, 0xffff),
    ));
    batch.push((
        "ldnt1sb_rm31_zero_offset".into(),
        enc_ldnt1_vs_d(0, false, 31, 6, 2, 1),
        input(0x7777, 0xffff),
    ));

    run_batch("sve_ldnt1_vector_base_scalar_offset", batch);
}

#[test]
fn diff_sve_ldn_stn() {
    // Multi-register de-interleaving loads (LD2/3/4) and interleaving stores
    // (ST2/3/4), all element sizes and structure counts.
    let mut rng = Rng::new(0x4_8001);
    let mut batch: Vec<(String, u32, ArmState)> = Vec::new();
    for msz in 0..4u32 {
        for nreg in 2..=4u32 {
            for &imm4 in &[0i32, 1] {
                let ld = enc_ldn(msz, nreg, imm4);
                let st = enc_stn(msz, nreg, imm4);
                for _ in 0..4 {
                    let mut s1 = mem_input(&mut rng);
                    s1.set_preg(0, rng.next() as u16);
                    batch.push((format!("ld{nreg} m{msz} i{imm4}"), ld, s1));
                    let mut s2 = mem_input(&mut rng);
                    s2.set_preg(0, rng.next() as u16);
                    batch.push((format!("st{nreg} m{msz} i{imm4}"), st, s2));
                }
            }
        }
    }
    fn deterministic_ldn_stn_input(nreg: u32, pg: u16) -> ArmState {
        let mut st = ArmState::zeroed();
        st.x[RN as usize] = SCRATCH_BASE;
        st.set_preg(0, pg);
        for reg in 0..nreg as usize {
            st.set_vreg(
                reg,
                0x807f_00ff_aa55_0102u64 ^ (reg as u64).wrapping_mul(0x0101_0101_0101_0101),
                0x7f80_ff00_55aa_fefdu64 ^ (reg as u64).wrapping_mul(0x1010_1010_1010_1010),
            );
        }
        for (idx, word) in st.scratch.iter_mut().enumerate() {
            *word = 0x0011_2233_4455_6677u64 ^ (idx as u64).wrapping_mul(0x1020_3040_5060_7080);
        }
        st
    }

    for msz in 0..4u32 {
        for nreg in 2..=4u32 {
            for &imm4 in &[0i32, 1] {
                let ld = enc_ldn(msz, nreg, imm4);
                let st = enc_stn(msz, nreg, imm4);
                for (mask_name, pg) in [("all", 0xffff), ("first", 0x0001), ("inactive", 0x0000)] {
                    batch.push((
                        format!("ld{nreg}_m{msz}_i{imm4}_{mask_name}"),
                        ld,
                        deterministic_ldn_stn_input(nreg, pg),
                    ));
                    batch.push((
                        format!("st{nreg}_m{msz}_i{imm4}_{mask_name}"),
                        st,
                        deterministic_ldn_stn_input(nreg, pg),
                    ));
                }
            }
        }
    }
    run_batch("sve_ldn_stn", batch);
}

#[test]
fn diff_sve_gather_ai_s() {
    // S-form vector-base gather: 4 S lanes from Zn[e]<31:0> + imm5*mbytes.
    let mut rng = Rng::new(0x4_A001);
    let mut batch: Vec<(String, u32, ArmState)> = Vec::new();
    for msz in 0..3u32 {
        for &imm5 in &[0u32, 1, 2] {
            for u in 0..2u32 {
                if u == 0 && msz == 2 {
                    continue;
                }
                let insn = enc_gather_ai_s(msz, imm5, u);
                let name = format!("gais m{msz} i{imm5} u{u}");
                for _ in 0..6 {
                    let mut st = mem_input(&mut rng);
                    let mut zn: u128 = 0;
                    for e in 0..4 {
                        let b = (SCRATCH_BASE as u32).wrapping_add((rng.next() % 16) as u32);
                        zn |= (b as u128) << (e * 32);
                    }
                    st.set_vreg(1, zn as u64, (zn >> 64) as u64);
                    st.set_preg(0, rng.next() as u16);
                    batch.push((name.clone(), insn, st));
                }
            }
        }
    }
    fn deterministic_gather_ai_s_input(pg: u16) -> ArmState {
        let mut st = ArmState::zeroed();
        st.set_vreg(0, 0xdead_beef_dead_beef, 0xfeed_face_feed_face);
        let bases = [
            SCRATCH_BASE as u32,
            (SCRATCH_BASE + 8) as u32,
            (SCRATCH_BASE + 16) as u32,
            (SCRATCH_BASE + 24) as u32,
        ];
        let mut zn = 0u128;
        for (lane, base) in bases.iter().enumerate() {
            zn |= (*base as u128) << (lane * 32);
        }
        st.set_vreg(1, zn as u64, (zn >> 64) as u64);
        st.set_preg(0, pg);
        for (idx, word) in st.scratch.iter_mut().enumerate() {
            *word = 0x807f_00ff_aa55_0102u64 ^ (idx as u64).wrapping_mul(0x0102_0408_1020_4080);
        }
        st
    }

    for msz in 0..3u32 {
        for &imm5 in &[0u32, 1, 2] {
            for u in 0..2u32 {
                if u == 0 && msz == 2 {
                    continue;
                }
                let insn = enc_gather_ai_s(msz, imm5, u);
                for (mask_name, pg) in [("all", 0xffff), ("first", 0x0001), ("inactive", 0x0000)] {
                    batch.push((
                        format!("gais_m{msz}_i{imm5}_u{u}_{mask_name}"),
                        insn,
                        deterministic_gather_ai_s_input(pg),
                    ));
                }
            }
        }
    }
    run_batch("sve_gather_ai_s", batch);
}

