#[test]
fn diff_sve_gather_x32() {
    // Unpacked gather: D lanes, 32-bit offsets from Xn + (extend(Zm[e]<31:0>,xs)
    // << scale).
    let mut rng = Rng::new(0x4_4001);
    let mut batch: Vec<(String, u32, ArmState)> = Vec::new();
    for msz in 0..4u32 {
        for xs in 0..2u32 {
            for &scaled in &[false, true] {
                if scaled && msz == 0 {
                    continue;
                }
                for u in 0..2u32 {
                    if u == 0 && msz == 3 {
                        continue;
                    }
                    let insn = enc_gather_x32(msz, xs, scaled, u);
                    let name = format!("gx m{msz} x{xs} sc{} u{u}", scaled as u32);
                    for _ in 0..6 {
                        let mut st = mem_input(&mut rng);
                        let e0 = (rng.next() % 4) as u128;
                        let e1 = (rng.next() % 4) as u128;
                        let zm = e0 | (e1 << 64);
                        st.set_vreg(2, zm as u64, (zm >> 64) as u64);
                        st.set_preg(0, rng.next() as u16);
                        batch.push((name.clone(), insn, st));
                    }
                }
            }
        }
    }
    fn deterministic_gather_x32_input(pg: u16) -> ArmState {
        let mut st = ArmState::zeroed();
        st.x[RN as usize] = SCRATCH_BASE;
        st.set_vreg(0, 0xdead_beef_dead_beef, 0xfeed_face_feed_face);
        st.set_vreg(2, 0, 4);
        st.set_preg(0, pg);
        for (idx, word) in st.scratch.iter_mut().enumerate() {
            *word = 0x807f_00ff_aa55_0102u64 ^ (idx as u64).wrapping_mul(0x1110_0908_0503_0201);
        }
        st
    }

    for msz in 0..4u32 {
        for xs in 0..2u32 {
            for &scaled in &[false, true] {
                if scaled && msz == 0 {
                    continue;
                }
                for u in 0..2u32 {
                    if u == 0 && msz == 3 {
                        continue;
                    }
                    let insn = enc_gather_x32(msz, xs, scaled, u);
                    for (mask_name, pg) in
                        [("all", 0xffff), ("first", 0x0001), ("inactive", 0x0000)]
                    {
                        batch.push((
                            format!("gx_m{msz}_x{xs}_sc{}_u{u}_{mask_name}", scaled as u32),
                            insn,
                            deterministic_gather_x32_input(pg),
                        ));
                    }
                }
            }
        }
    }
    run_batch("sve_gather_x32", batch);
}

