#[test]
fn diff_sve_adr() {
    // Vector address generation across all four forms (D+SXTW, D+UXTW, S/D
    // packed) and shift amounts.
    let mut cases: Vec<(String, u32)> = Vec::new();
    for mode in 0..4u32 {
        for msz in 0..4u32 {
            cases.push((format!("adr m{mode} s{msz}"), enc_sve_adr(mode, msz)));
        }
    }
    run_family("sve_adr", cases, 16, 0x3_7001);

    fn pack32(values: &[u32; 4]) -> (u64, u64) {
        let mut packed = 0u128;
        for (lane, value) in values.iter().enumerate() {
            packed |= (*value as u128) << (lane * 32);
        }
        (packed as u64, (packed >> 64) as u64)
    }

    fn pack64(values: &[u64; 2]) -> (u64, u64) {
        (values[0], values[1])
    }

    let patterns = [
        (
            "small",
            pack64(&[0x0000_0000_0000_1000, 0x0000_0000_0000_2000]),
            pack32(&[0, 1, 2, 3]),
        ),
        (
            "signed",
            pack64(&[0xffff_ffff_ffff_ff00, 0x0000_0000_0000_0100]),
            pack32(&[0xffff_ffff, 0x8000_0000, 0x7fff_ffff, 2]),
        ),
        (
            "carry",
            pack64(&[0xffff_ffff_ffff_fff0, 0x8000_0000_0000_0000]),
            pack32(&[0x0000_0010, 0xffff_fff0, 0x7fff_fff0, 0x8000_0010]),
        ),
    ];
    let mut batch: Vec<(String, u32, ArmState)> = Vec::new();
    for mode in 0..4u32 {
        for msz in 0..4u32 {
            let insn = enc_sve_adr(mode, msz);
            for (pattern_name, zn, zm) in patterns {
                let mut st = ArmState::zeroed();
                st.set_vreg(0, 0xdead_beef_dead_beef, 0xfeed_face_feed_face);
                st.set_vreg(1, zn.0, zn.1);
                st.set_vreg(2, zm.0, zm.1);
                batch.push((format!("adr_m{mode}_s{msz}_{pattern_name}"), insn, st));
            }
        }
    }
    run_batch("sve_adr_edges", batch);
}

#[test]
fn diff_sve_movprfx() {
    fn pack_lanes(size: u32, values: &[u64]) -> (u64, u64) {
        let bits = 8u32 << size;
        let mask = if bits == 64 {
            u64::MAX
        } else {
            (1u64 << bits) - 1
        };
        let mut packed = 0u128;
        for (lane, value) in values.iter().enumerate() {
            packed |= ((*value & mask) as u128) << (lane * bits as usize);
        }
        (packed as u64, (packed >> 64) as u64)
    }

    fn lane_patterns(size: u32) -> Vec<(&'static str, Vec<u64>, Vec<u64>)> {
        let bits = 8u32 << size;
        let lanes = 16usize >> size;
        let mask = if bits == 64 {
            u64::MAX
        } else {
            (1u64 << bits) - 1
        };
        let sign = 1u64 << (bits - 1);
        let zd_edges = [mask, mask - 1, sign + 1, sign, sign - 1, 1, 0];
        let zn_edges = [0, 1, sign - 1, sign, sign + 1, mask - 1, mask];
        vec![
            (
                "identity",
                (0..lanes)
                    .map(|lane| 0x80u64.wrapping_add(lane as u64) & mask)
                    .collect(),
                (0..lanes).map(|lane| lane as u64).collect(),
            ),
            (
                "edges",
                (0..lanes)
                    .map(|lane| zd_edges[lane % zd_edges.len()])
                    .collect(),
                (0..lanes)
                    .map(|lane| zn_edges[lane % zn_edges.len()])
                    .collect(),
            ),
        ]
    }

    // MOVPRFX standalone is a move: unpredicated copies the whole register; the
    // predicated form copies active lanes and merges/zeros the inactive ones.
    let mut rng = Rng::new(0x3_6001);
    let mut batch: Vec<(String, u32, ArmState)> = Vec::new();
    let zi = enc_movprfx_z();
    for _ in 0..12 {
        let mut st = ArmState::zeroed();
        st.set_vreg(0, rng.next(), rng.next());
        st.set_vreg(1, rng.next(), rng.next());
        batch.push(("movprfx_z".to_string(), zi, st));
    }
    for (pattern_name, _, zn) in lane_patterns(0) {
        let mut st = ArmState::zeroed();
        st.set_vreg(0, 0xdead_beef_dead_beef, 0xfeed_face_feed_face);
        let (lo, hi) = pack_lanes(0, &zn);
        st.set_vreg(1, lo, hi);
        batch.push((format!("movprfx_z_{pattern_name}"), zi, st));
    }
    for size in 0..4u32 {
        let mixed = match size {
            0 => 0x5555,
            1 => 0x1111,
            2 => 0x0101,
            _ => 0x0001,
        };
        for m in 0..2u32 {
            let insn = enc_movprfx_p(size, m);
            for _ in 0..8 {
                let mut st = ArmState::zeroed();
                st.set_vreg(0, rng.next(), rng.next()); // prior Zd (merge target)
                st.set_vreg(1, rng.next(), rng.next()); // Zn
                st.set_preg(0, rng.next() as u16);
                batch.push((format!("movprfx_p e{size} m{m}"), insn, st));
            }
            for (pattern_name, zd, zn) in lane_patterns(size) {
                for (mask_name, pg) in [("all", 0xffff), ("mixed", mixed), ("inactive", 0x0000)] {
                    let mut st = ArmState::zeroed();
                    let (lo, hi) = pack_lanes(size, &zd);
                    st.set_vreg(0, lo, hi);
                    let (lo, hi) = pack_lanes(size, &zn);
                    st.set_vreg(1, lo, hi);
                    st.set_preg(0, pg);
                    batch.push((
                        format!("movprfx_p_e{size}_m{m}_{pattern_name}_{mask_name}"),
                        insn,
                        st,
                    ));
                }
            }
        }
    }
    run_batch("sve_movprfx", batch);
}

#[test]
fn diff_sve_ld1r() {
    // Load-and-replicate: one extended memory element broadcast to active lanes.
    let mut rng = Rng::new(0x3_5001);
    let mut batch: Vec<(String, u32, ArmState)> = Vec::new();
    for dtype in 0..16u32 {
        let (dh, dl) = (dtype >> 2, dtype & 3);
        for &imm6 in &[0u32, 1, 2, 3] {
            let insn = enc_ld1r(dh, dl, imm6);
            for _ in 0..6 {
                let mut st = mem_input(&mut rng);
                st.set_preg(0, rng.next() as u16);
                batch.push((format!("ld1r dt{dtype} i{imm6}"), insn, st));
            }
        }
    }
    fn deterministic_ld1r_input(pg: u16) -> ArmState {
        let mut st = ArmState::zeroed();
        st.x[RN as usize] = SCRATCH_BASE;
        st.set_vreg(0, 0xdead_beef_dead_beef, 0xfeed_face_feed_face);
        st.set_preg(0, pg);
        for (idx, word) in st.scratch.iter_mut().enumerate() {
            *word = 0x80ff_7f00_55aa_0102u64 ^ ((idx as u64) * 0x0101_0101_0101_0101);
        }
        st
    }

    for dtype in 0..16u32 {
        let (dh, dl) = (dtype >> 2, dtype & 3);
        for &imm6 in &[0u32, 1, 2, 3] {
            let insn = enc_ld1r(dh, dl, imm6);
            for (mask_name, pg) in [("all", 0xffff), ("first", 0x0001), ("inactive", 0x0000)] {
                batch.push((
                    format!("ld1r_dt{dtype}_i{imm6}_{mask_name}"),
                    insn,
                    deterministic_ld1r_input(pg),
                ));
            }
        }
    }
    run_batch("sve_ld1r", batch);
}

#[test]
fn diff_sve_ldr_str() {
    // Whole-register fill/spill of Z and P registers (unpredicated).
    let mut rng = Rng::new(0x3_4001);
    let mut batch: Vec<(String, u32, ArmState)> = Vec::new();
    for &imm in &[0i32, 1, -1, 2] {
        let variants = [
            ("ldr_z", enc_ldstr_z(false, imm)),
            ("str_z", enc_ldstr_z(true, imm)),
            ("ldr_p", enc_ldstr_p(false, imm)),
            ("str_p", enc_ldstr_p(true, imm)),
        ];
        for (label, insn) in variants {
            for _ in 0..6 {
                let mut st = mem_input(&mut rng);
                st.set_vreg(0, rng.next(), rng.next()); // Zt source (str_z)
                st.set_preg(0, rng.next() as u16); // Pt source (str_p)
                batch.push((format!("{label} i{imm}"), insn, st));
            }
        }
    }
    fn deterministic_ldstr_input() -> ArmState {
        let mut st = ArmState::zeroed();
        st.x[RN as usize] = SCRATCH_BASE;
        st.set_vreg(0, 0x0123_4567_89ab_cdef, 0xfedc_ba98_7654_3210);
        st.set_preg(0, 0xa55a);
        for (idx, word) in st.scratch.iter_mut().enumerate() {
            *word = 0x1020_3040_5060_7080u64 ^ (idx as u64).wrapping_mul(0x1111_1111_1111_1111);
        }
        st
    }

    for &imm in &[0i32, 1, -1, 2] {
        for (label, insn) in [
            ("ldr_z_edge", enc_ldstr_z(false, imm)),
            ("str_z_edge", enc_ldstr_z(true, imm)),
            ("ldr_p_edge", enc_ldstr_p(false, imm)),
            ("str_p_edge", enc_ldstr_p(true, imm)),
        ] {
            batch.push((format!("{label}_i{imm}"), insn, deterministic_ldstr_input()));
        }
    }
    run_batch("sve_ldr_str", batch);
}

#[test]
fn diff_sve_ldst_sp_alignment_edges() {
    let cases: Vec<(String, u32, Option<u64>)> = vec![
        ("ldr_z_sp".into(), enc_ldstr_z_regs(false, 0, 31), None),
        ("str_z_sp".into(), enc_ldstr_z_regs(true, 0, 31), None),
        ("ldr_p_sp".into(), enc_ldstr_p_regs(false, 0, 31), None),
        ("str_p_sp".into(), enc_ldstr_p_regs(true, 0, 31), None),
        ("ld1r_sp".into(), enc_ld1r_regs(0, 0, 0, 31), None),
        ("ld1_sp_imm".into(), enc_sve_ld1_regs(0, 0, 31), None),
        ("st1_sp_imm".into(), enc_sve_st1_regs(0, 0, 0, 31), None),
        ("ld1_sp_reg".into(), enc_sve_ld1_ss_regs(0, 31), Some(0)),
        ("st1_sp_reg".into(), enc_sve_st1_ss_regs(0, 0, 31), Some(0)),
    ];
    let mut rng = Rng::new(0x3_4011);
    let mut batch = Vec::new();

    for (label, insn, rm_value) in &cases {
        for offset in [1u64, 8] {
            let mut st = mem_input(&mut rng);
            st.sp = SCRATCH_BASE + offset;
            st.set_preg(0, 0xffff);
            st.set_vreg(0, rng.next(), rng.next());
            if let Some(value) = rm_value {
                st.x[RM as usize] = *value;
            }
            batch.push((format!("{label}_off{offset}"), *insn, st));
        }
    }

    run_batch("sve_ldst_sp_alignment_edges", batch);
}

#[test]
fn diff_sve_ldst_scalar_scalar_rm31_legality() {
    let mut batch = Vec::new();
    for dtype in 0..=0xf {
        let mut st = ArmState::zeroed();
        st.x[RN as usize] = SCRATCH_BASE;
        st.x[RM as usize] = 0;
        st.sp = GUEST_STACK_ADDR + (GUEST_STACK_SIZE / 2);
        st.set_preg(0, 0);
        batch.push((
            format!("ld1_ss_valid_dtype{dtype:x}"),
            enc_sve_ld1_ss_base_offset_regs(dtype, RM, RN),
            st,
        ));

        let mut st = ArmState::zeroed();
        st.x[RN as usize] = SCRATCH_BASE;
        st.sp = GUEST_STACK_ADDR + (GUEST_STACK_SIZE / 2);
        st.set_preg(0, 0);
        batch.push((
            format!("ld1_ss_rm31_dtype{dtype:x}"),
            enc_sve_ld1_ss_base_offset_regs(dtype, 31, RN),
            st,
        ));
    }

    for msz in 0..=3 {
        for size in msz..=3 {
            let mut st = ArmState::zeroed();
            st.x[RN as usize] = SCRATCH_BASE;
            st.x[RM as usize] = 0;
            st.sp = GUEST_STACK_ADDR + (GUEST_STACK_SIZE / 2);
            st.set_preg(0, 0);
            batch.push((
                format!("st1_ss_valid_m{msz}_s{size}"),
                enc_sve_st1_ss_base_offset_regs(msz, size, RM, RN),
                st,
            ));

            let mut st = ArmState::zeroed();
            st.x[RN as usize] = SCRATCH_BASE;
            st.sp = GUEST_STACK_ADDR + (GUEST_STACK_SIZE / 2);
            st.set_preg(0, 0);
            batch.push((
                format!("st1_ss_rm31_m{msz}_s{size}"),
                enc_sve_st1_ss_base_offset_regs(msz, size, 31, RN),
                st,
            ));
        }
    }

    run_batch_el0_legality("sve_ldst_scalar_scalar_rm31_legality", batch);
}

#[test]
fn diff_sve_gather_scatter_sp_alignment_edges() {
    fn set_rn(insn: u32, rn: u32) -> u32 {
        (insn & !(0x1f << 5)) | ((rn & 0x1f) << 5)
    }

    let cases: Vec<(String, u32)> = vec![
        ("ld1g_d_sp".into(), set_rn(enc_gather_d(1, false, 1), 31)),
        (
            "ldff1g_d_sp".into(),
            set_rn(enc_gather_d(1, false, 1) | (1 << 13), 31),
        ),
        ("st1g_d_sp".into(), set_rn(enc_scatter_d(1, false), 31)),
        (
            "ld1g_x32_sp".into(),
            set_rn(enc_gather_x32(1, 0, false, 1), 31),
        ),
        (
            "st1g_x32_sp".into(),
            set_rn(enc_scatter_x32(1, 0, false), 31),
        ),
        ("ld1g_s_sp".into(), set_rn(enc_gather_s(1, 0, false, 1), 31)),
        ("st1g_s_sp".into(), set_rn(enc_scatter_s(1, 0, false), 31)),
    ];
    let mut rng = Rng::new(0x3_4012);
    let mut batch = Vec::new();

    for (label, insn) in &cases {
        for offset in [1u64, 8] {
            let mut st = mem_input(&mut rng);
            st.sp = SCRATCH_BASE + offset;
            st.set_preg(0, 0xffff);
            st.set_vreg(RM as usize, 0, 0);
            st.set_vreg(RD as usize, rng.next(), rng.next());
            batch.push((format!("{label}_off{offset}"), *insn, st));
        }
    }

    run_batch("sve_gather_scatter_sp_alignment_edges", batch);
}

