#[test]
fn diff_sve_cvt() {
    fn pack_src_containers(src_sz: usize, cont: usize, values: &[u64]) -> (u64, u64) {
        let bits = src_sz * 8;
        let mask = if bits == 64 {
            u64::MAX
        } else {
            (1u64 << bits) - 1
        };
        let mut packed = 0u128;
        for (lane, value) in values.iter().enumerate() {
            packed |= ((*value & mask) as u128) << (lane * cont * 8);
        }
        (packed as u64, (packed >> 64) as u64)
    }

    fn cvt_source_patterns(
        to_int: bool,
        unsigned: bool,
        fp_sz: usize,
        int_sz: usize,
        elements: usize,
    ) -> Vec<(&'static str, usize, Vec<u64>)> {
        let values = if to_int {
            match fp_sz {
                2 => vec![
                    0x0000, 0x8000, 0x3c00, 0xbc00, 0x3e00, 0xbe00, 0x4200, 0xc200,
                ],
                4 => vec![
                    0.0f32.to_bits() as u64,
                    (-0.0f32).to_bits() as u64,
                    1.0f32.to_bits() as u64,
                    (-1.0f32).to_bits() as u64,
                    1.5f32.to_bits() as u64,
                    (-1.5f32).to_bits() as u64,
                    42.0f32.to_bits() as u64,
                    (-42.0f32).to_bits() as u64,
                ],
                _ => vec![
                    0.0f64.to_bits(),
                    (-0.0f64).to_bits(),
                    1.0f64.to_bits(),
                    (-1.0f64).to_bits(),
                    1.5f64.to_bits(),
                    (-1.5f64).to_bits(),
                    42.0f64.to_bits(),
                    (-42.0f64).to_bits(),
                ],
            }
        } else if unsigned {
            vec![0, 1, 2, 42, 127, 255]
        } else {
            vec![
                0,
                1,
                (-1i64) as u64,
                42,
                (-42i64) as u64,
                127,
                (-128i64) as u64,
            ]
        };
        vec![(
            "basic",
            if to_int { fp_sz } else { int_sz },
            (0..elements)
                .map(|lane| values[lane % values.len()])
                .collect(),
        )]
    }

    // Predicated FCVTZS/FCVTZU (FP->int, trunc+saturate) and SCVTF/UCVTF
    // (int->FP, round-to-nearest). Each (opc,opc2) fixes the FP/int width pair;
    // ig1 picks the direction and int_U the signedness.
    let table = [
        (0b01u32, 0b01u32, 2usize, 2usize),
        (0b01, 0b10, 2, 4),
        (0b01, 0b11, 2, 8),
        (0b10, 0b10, 4, 4),
        (0b11, 0b10, 4, 8),
        (0b11, 0b00, 8, 4),
        (0b11, 0b11, 8, 8),
    ];
    let mut rng = Rng::new(0x3_1001);
    let mut batch: Vec<(String, u32, ArmState)> = Vec::new();
    for (opc, opc2, fp_sz, int_sz) in table {
        let cont = fp_sz.max(int_sz);
        let elements = 16 / cont;
        for (ig1, to_int) in [(0b011u32, true), (0b010u32, false)] {
            for u in 0..2u32 {
                let insn = enc_sve_cvt(opc, ig1, opc2, u);
                let name = format!(
                    "{}{}_f{}i{}",
                    if to_int { "fcvtz" } else { "cvtf" },
                    if u == 0 { "s" } else { "u" },
                    fp_sz * 8,
                    int_sz * 8
                );
                let imask: u64 = if int_sz == 8 {
                    u64::MAX
                } else {
                    (1u64 << (int_sz * 8)) - 1
                };
                for _ in 0..20 {
                    let mut st = ArmState::zeroed();
                    let mut zn: u128 = 0;
                    for e in 0..elements {
                        let bits = if to_int {
                            finite_fp_bits(&mut rng, fp_sz)
                        } else {
                            rng.next() & imask
                        };
                        zn |= (bits as u128) << (e * cont * 8);
                    }
                    st.set_vreg(1, zn as u64, (zn >> 64) as u64);
                    st.set_vreg(0, rng.next(), rng.next()); // prior Zd (merge)
                    st.set_preg(0, rng.next() as u16);
                    batch.push((name.clone(), insn, st));
                }
                let mixed = match cont {
                    2 => 0x1111,
                    4 => 0x0101,
                    _ => 0x0001,
                };
                for (pattern_name, src_sz, zn) in
                    cvt_source_patterns(to_int, u == 1, fp_sz, int_sz, elements)
                {
                    for (mask_name, pg) in [("all", 0xffff), ("mixed", mixed), ("inactive", 0x0000)]
                    {
                        let mut st = ArmState::zeroed();
                        st.set_vreg(0, 0xdead_beef_dead_beef, 0xfeed_face_feed_face);
                        let (lo, hi) = pack_src_containers(src_sz, cont, &zn);
                        st.set_vreg(1, lo, hi);
                        st.set_preg(0, pg);
                        batch.push((format!("{name}_{pattern_name}_{mask_name}"), insn, st));
                    }
                }
            }
        }
    }
    run_batch("sve_cvt", batch);
}

#[test]
fn diff_sve_dup_idx() {
    // DUP indexed broadcasts one element of Zn to all lanes; an index past the
    // end broadcasts zero. Cover every representable index for each element
    // size so the full imm2:tsz encoding is checked.
    let mut cases: Vec<(String, u32)> = Vec::new();
    for (elog, name) in [(0u32, "b"), (1, "h"), (2, "s"), (3, "d"), (4, "q")] {
        let encoded_indexes = 1u32 << (6 - elog);
        for index in 0..encoded_indexes {
            cases.push((format!("dup_idx {name}[{index}]"), enc_dup_idx(elog, index)));
        }
    }
    run_family("sve_dup_idx", cases, 4, 0x2_E001);

    fn pack_lanes(elog: u32, values: &[u64]) -> (u64, u64) {
        let bits = 8u32 << elog;
        let mask = if bits == 64 {
            u64::MAX
        } else {
            (1u64 << bits) - 1
        };
        let mut packed = 0u128;
        for (lane, value) in values.iter().enumerate() {
            packed |= ((*value & mask) as u128) << (lane * bits as usize);
        }
        (packed as u64, (packed >> 64) as u64)
    }

    fn source_patterns(elog: u32) -> Vec<(&'static str, u64, u64)> {
        if elog == 4 {
            return vec![
                ("identity", 0x0706_0504_0302_0100, 0x0f0e_0d0c_0b0a_0908),
                ("edges", 0x8000_0000_0000_0001, 0xffff_ffff_ffff_fffe),
            ];
        }
        let bits = 8u32 << elog;
        let lanes = 16usize >> elog;
        let mask = if bits == 64 {
            u64::MAX
        } else {
            (1u64 << bits) - 1
        };
        let sign = 1u64 << (bits - 1);
        let edges = [0, 1, sign - 1, sign, sign + 1, mask - 1, mask];
        let identity: Vec<u64> = (0..lanes)
            .map(|lane| 0x10u64.wrapping_add(lane as u64) & mask)
            .collect();
        let edge_values: Vec<u64> = (0..lanes).map(|lane| edges[lane % edges.len()]).collect();
        let (identity_lo, identity_hi) = pack_lanes(elog, &identity);
        let (edges_lo, edges_hi) = pack_lanes(elog, &edge_values);
        vec![
            ("identity", identity_lo, identity_hi),
            ("edges", edges_lo, edges_hi),
        ]
    }

    let mut batch: Vec<(String, u32, ArmState)> = Vec::new();
    for (elog, name) in [(0u32, "b"), (1, "h"), (2, "s"), (3, "d"), (4, "q")] {
        let encoded_indexes = 1u32 << (6 - elog);
        for index in 0..encoded_indexes {
            let insn = enc_dup_idx(elog, index);
            for (pattern_name, lo, hi) in source_patterns(elog) {
                let mut st = ArmState::zeroed();
                st.set_vreg(0, 0xdead_beef_dead_beef, 0xfeed_face_feed_face);
                st.set_vreg(1, lo, hi);
                batch.push((format!("dup_idx_{name}{index}_{pattern_name}"), insn, st));
            }
        }
    }
    run_batch("sve_dup_idx_edges", batch);
}

#[test]
fn diff_sve_compact() {
    // COMPACT packs Pg-active S/D elements of Zn to the bottom of Zd, zeroing
    // the rest. A random predicate exercises arbitrary active-element patterns.
    let mut rng = Rng::new(0x2_7001);
    let mut batch: Vec<(String, u32, ArmState)> = Vec::new();
    for sz in 0..2u32 {
        let insn = enc_sve_compact(sz);
        for _ in 0..24 {
            let mut st = ArmState::zeroed();
            st.set_vreg(1, rng.next(), rng.next());
            st.set_preg(0, rng.next() as u16);
            batch.push((format!("compact sz{sz}"), insn, st));
        }
    }

    fn pack_lanes(sz: u32, values: &[u64]) -> (u64, u64) {
        let bits = 32u32 << sz;
        let mask = if bits == 64 {
            u64::MAX
        } else {
            (1u64 << bits) - 1
        };
        let mut packed = 0u128;
        for (lane, value) in values.iter().enumerate() {
            packed |= ((*value & mask) as u128) << (lane * bits as usize);
        }
        (packed as u64, (packed >> 64) as u64)
    }

    fn predicate_bit(sz: u32, lane: usize) -> u16 {
        1u16 << (lane * (4usize << sz))
    }

    fn source_patterns(sz: u32) -> Vec<(&'static str, Vec<u64>)> {
        let bits = 32u32 << sz;
        let lanes = 4usize >> sz;
        let mask = if bits == 64 {
            u64::MAX
        } else {
            (1u64 << bits) - 1
        };
        let sign = 1u64 << (bits - 1);
        let edges = [0, 1, sign - 1, sign, sign + 1, mask - 1, mask];
        vec![
            (
                "identity",
                (0..lanes).map(|lane| 0x10u64 + lane as u64).collect(),
            ),
            (
                "edges",
                (0..lanes).map(|lane| edges[lane % edges.len()]).collect(),
            ),
        ]
    }

    for sz in 0..2u32 {
        let lanes = 4usize >> sz;
        let insn = enc_sve_compact(sz);
        let first = predicate_bit(sz, 0);
        let last = predicate_bit(sz, lanes - 1);
        let alternating = (0..lanes)
            .filter(|lane| lane % 2 == 0)
            .fold(0u16, |pg, lane| pg | predicate_bit(sz, lane));
        let middle = if lanes == 2 {
            last
        } else {
            predicate_bit(sz, 1) | predicate_bit(sz, 2)
        };
        for (pattern_name, zn) in source_patterns(sz) {
            for (mask_name, pg) in [
                ("all", 0xffff),
                ("inactive", 0x0000),
                ("first", first),
                ("last", last),
                ("alternating", alternating),
                ("middle", middle),
            ] {
                let mut st = ArmState::zeroed();
                st.set_vreg(0, 0xdead_beef_dead_beef, 0xfeed_face_feed_face);
                let (lo, hi) = pack_lanes(sz, &zn);
                st.set_vreg(1, lo, hi);
                st.set_preg(0, pg);
                batch.push((
                    format!("compact_sz{sz}_{pattern_name}_{mask_name}"),
                    insn,
                    st,
                ));
            }
        }
    }
    run_batch("sve_compact", batch);
}

#[test]
fn diff_sve_splice() {
    // SPLICE copies Zdn's active span (first..last active) to the low result,
    // then fills the remainder from Zm. Random Zdn/Zm/Pg cover the active-span,
    // wrap, and empty-predicate (result == Zm) paths.
    let mut rng = Rng::new(0x2_8001);
    let mut batch: Vec<(String, u32, ArmState)> = Vec::new();
    for sz in 0..4u32 {
        let insn = enc_sve_splice(sz);
        for _ in 0..24 {
            let mut st = ArmState::zeroed();
            st.set_vreg(0, rng.next(), rng.next()); // Zdn (source-1 + dest)
            st.set_vreg(1, rng.next(), rng.next()); // Zm
            st.set_preg(0, rng.next() as u16);
            batch.push((format!("splice sz{sz}"), insn, st));
        }
    }

    fn pack_lanes(sz: u32, values: &[u64]) -> (u64, u64) {
        let bits = 8u32 << sz;
        let mask = if bits == 64 {
            u64::MAX
        } else {
            (1u64 << bits) - 1
        };
        let mut packed = 0u128;
        for (lane, value) in values.iter().enumerate() {
            packed |= ((*value & mask) as u128) << (lane * bits as usize);
        }
        (packed as u64, (packed >> 64) as u64)
    }

    fn predicate_bit(sz: u32, lane: usize) -> u16 {
        1u16 << (lane * (1usize << sz))
    }

    let fuzz_insn = enc_sve2_splice_pair(1, 2, 10, 3);
    assert_eq!(fuzz_insn, 0x056d_8d42);
    let mut fuzz = ArmState::zeroed();
    fuzz.set_vreg(2, 0xfeed_face_feed_face, 0xdead_beef_dead_beef);
    fuzz.set_vreg(10, 0x0706_0504_0302_0100, 0x0f0e_0d0c_0b0a_0908);
    fuzz.set_vreg(11, 0x1716_1514_1312_1110, 0x1f1e_1d1c_1b1a_1918);
    fuzz.set_preg(3, predicate_bit(1, 1) | predicate_bit(1, 5));
    batch.push(("splice_pair_fuzz_056d8d42".into(), fuzz_insn, fuzz));

    for sz in 0..4u32 {
        let insn = enc_sve2_splice_pair(sz, 2, 10, 3);
        for _ in 0..12 {
            let mut st = ArmState::zeroed();
            st.set_vreg(2, rng.next(), rng.next());
            st.set_vreg(10, rng.next(), rng.next());
            st.set_vreg(11, rng.next(), rng.next());
            st.set_preg(3, rng.next() as u16);
            batch.push((format!("splice_pair sz{sz}"), insn, st));
        }

        let wrap_insn = enc_sve2_splice_pair(sz, 5, 31, 7);
        let mut wrap = ArmState::zeroed();
        wrap.set_vreg(0, rng.next(), rng.next());
        wrap.set_vreg(5, rng.next(), rng.next());
        wrap.set_vreg(31, rng.next(), rng.next());
        wrap.set_preg(7, rng.next() as u16);
        batch.push((format!("splice_pair_wrap sz{sz}"), wrap_insn, wrap));
    }

    fn splice_patterns(sz: u32) -> Vec<(&'static str, Vec<u64>, Vec<u64>)> {
        let bits = 8u32 << sz;
        let lanes = 16usize >> sz;
        let mask = if bits == 64 {
            u64::MAX
        } else {
            (1u64 << bits) - 1
        };
        let sign = 1u64 << (bits - 1);
        let zdn_edges = [0, 1, sign - 1, sign, sign + 1, mask - 1, mask];
        let zm_edges = [mask, mask - 1, sign + 1, sign, sign - 1, 1, 0];
        vec![
            (
                "identity",
                (0..lanes).map(|lane| 0x10u64 + lane as u64).collect(),
                (0..lanes)
                    .map(|lane| 0x80u64.wrapping_add(lane as u64) & mask)
                    .collect(),
            ),
            (
                "edges",
                (0..lanes)
                    .map(|lane| zdn_edges[lane % zdn_edges.len()])
                    .collect(),
                (0..lanes)
                    .map(|lane| zm_edges[lane % zm_edges.len()])
                    .collect(),
            ),
        ]
    }

    for sz in 0..4u32 {
        let lanes = 16usize >> sz;
        let insn = enc_sve_splice(sz);
        let first = predicate_bit(sz, 0);
        let last = predicate_bit(sz, lanes - 1);
        let endpoints = first | last;
        let alternating = (0..lanes)
            .filter(|lane| lane % 2 == 0)
            .fold(0u16, |pg, lane| pg | predicate_bit(sz, lane));
        let middle_span = if lanes <= 2 {
            endpoints
        } else {
            predicate_bit(sz, 1) | predicate_bit(sz, lanes - 2)
        };
        for (pattern_name, zdn, zm) in splice_patterns(sz) {
            for (mask_name, pg) in [
                ("all", 0xffff),
                ("inactive", 0x0000),
                ("first", first),
                ("last", last),
                ("endpoints", endpoints),
                ("alternating", alternating),
                ("middle_span", middle_span),
            ] {
                let mut st = ArmState::zeroed();
                let (lo, hi) = pack_lanes(sz, &zdn);
                st.set_vreg(0, lo, hi);
                let (lo, hi) = pack_lanes(sz, &zm);
                st.set_vreg(1, lo, hi);
                st.set_preg(0, pg);
                batch.push((
                    format!("splice_sz{sz}_{pattern_name}_{mask_name}"),
                    insn,
                    st,
                ));
            }
        }
    }
    run_batch("sve_splice", batch);
}

#[test]
fn diff_sve_pfirst() {
    // PFIRST sets the first Pg-active element active in Pdn and writes NZCV via
    // PredTest. Cover every Pg/Pdn register combination, including aliases.
    let mut rng = Rng::new(0x2_9001);
    let mut batch: Vec<(String, u32, ArmState)> = Vec::new();
    for pg in 0..16u32 {
        for pdn in 0..16u32 {
            let insn = enc_pfirst(pg, pdn);
            for (pdn_val, pg_val) in [
                (0x0000u16, 0x0000u16),
                (0xffff, 0xffff),
                (0x8001, 0x00f0),
                (rng.next() as u16, rng.next() as u16),
            ] {
                let mut st = ArmState::zeroed();
                st.set_preg(pdn as usize, pdn_val); // Pdn (source + dest)
                if pg != pdn {
                    st.set_preg(pg as usize, pg_val); // Pg
                }
                batch.push((format!("pfirst p{pg},p{pdn}"), insn, st));
            }
        }
    }
    for (pg, pdn, regs) in [(1u32, 0u32, "distinct"), (0, 0, "alias"), (15, 14, "high")] {
        let insn = enc_pfirst(pg, pdn);
        for (pdn_val, pg_val, pred_case) in [
            (0x0000u16, 0x0000u16, "none"),
            (0xffff, 0xffff, "all"),
            (0x0000, 0x0001, "first"),
            (0xffff, 0x8000, "last"),
            (0xaaaa, 0x5555, "alternating"),
        ] {
            for nzcv in 0..16u64 {
                let mut st = ArmState::zeroed();
                st.pstate = nzcv << 28;
                st.set_preg(pdn as usize, pdn_val);
                if pg != pdn {
                    st.set_preg(pg as usize, pg_val);
                }
                batch.push((format!("pfirst_{regs}_{pred_case}_nzcv{nzcv:x}"), insn, st));
            }
        }
    }
    run_batch("sve_pfirst", batch);
}

#[test]
fn diff_sve_pnext() {
    // PNEXT advances to the next Pg-active element after Pdn's last active one,
    // for each element size, and writes NZCV via PredTest. Cover every Pg/Pdn
    // register combination, including aliases.
    let mut rng = Rng::new(0x2_A001);
    let mut batch: Vec<(String, u32, ArmState)> = Vec::new();
    for sz in 0..4u32 {
        for pg in 0..16u32 {
            for pdn in 0..16u32 {
                let insn = enc_pnext(sz, pg, pdn);
                for (pdn_val, pg_val) in [
                    (0x0000u16, 0x0000u16),
                    (0xffff, 0xffff),
                    (0x8001, 0x00f0),
                    (rng.next() as u16, rng.next() as u16),
                ] {
                    let mut st = ArmState::zeroed();
                    st.set_preg(pdn as usize, pdn_val); // Pdn (source + dest)
                    if pg != pdn {
                        st.set_preg(pg as usize, pg_val); // Pg
                    }
                    batch.push((format!("pnext sz{sz} p{pg},p{pdn}"), insn, st));
                }
            }
        }
    }
    for sz in 0..4u32 {
        for (pg, pdn, regs) in [(1u32, 0u32, "distinct"), (0, 0, "alias"), (15, 14, "high")] {
            let insn = enc_pnext(sz, pg, pdn);
            for (pdn_val, pg_val, pred_case) in [
                (0x0000u16, 0x0000u16, "none"),
                (0xffff, 0xffff, "all"),
                (0x0001, 0xffff, "advance_first"),
                (0x8000, 0x8001, "last"),
                (0x00f0, 0x0ff0, "middle"),
                (0xaaaa, 0x5555, "alternating"),
            ] {
                for nzcv in 0..16u64 {
                    let mut st = ArmState::zeroed();
                    st.pstate = nzcv << 28;
                    st.set_preg(pdn as usize, pdn_val);
                    if pg != pdn {
                        st.set_preg(pg as usize, pg_val);
                    }
                    batch.push((
                        format!("pnext_sz{sz}_{regs}_{pred_case}_nzcv{nzcv:x}"),
                        insn,
                        st,
                    ));
                }
            }
        }
    }
    run_batch("sve_pnext", batch);
}

#[test]
fn diff_sve_brk() {
    // BRKA (break after) / BRKB (break before) the first Pn-true element, in
    // both merging/zeroing and flag-setting forms. Cover random distinct
    // operands plus predicate-register aliases.
    let mut rng = Rng::new(0x2_B001);
    let mut batch: Vec<(String, u32, ArmState)> = Vec::new();
    for b in 0..2u32 {
        for s in 0..2u32 {
            for m in 0..2u32 {
                let insn = enc_brka(b, s, m, 1, 2, 0); // Pg=p1, Pn=p2, Pd=p0
                let name = format!("brk{} s{s} m{m}", if b == 0 { "a" } else { "b" });
                for _ in 0..16 {
                    let mut st = ArmState::zeroed();
                    st.set_preg(0, rng.next() as u16); // Pd (merge source)
                    st.set_preg(1, rng.next() as u16); // Pg
                    st.set_preg(2, rng.next() as u16); // Pn
                    batch.push((name.clone(), insn, st));
                }
                for (pd, pg, pn, regs) in [
                    (0u32, 1u32, 2u32, "distinct"),
                    (0, 0, 1, "pd_pg"),
                    (0, 1, 0, "pd_pn"),
                    (0, 1, 1, "pg_pn"),
                    (0, 0, 0, "all"),
                    (15, 14, 13, "high"),
                ] {
                    let insn = enc_brka(b, s, m, pg, pn, pd);
                    let name = format!("brk{} {regs} s{s} m{m}", if b == 0 { "a" } else { "b" });
                    for (pd_val, pg_val, pn_val) in [
                        (0x0000u16, 0x0000u16, 0x0000u16),
                        (0xffff, 0xffff, 0xffff),
                        (0xaaaa, 0x0f0f, 0x00f0),
                        (rng.next() as u16, rng.next() as u16, rng.next() as u16),
                    ] {
                        let mut st = ArmState::zeroed();
                        st.set_preg(pd as usize, pd_val);
                        st.set_preg(pg as usize, pg_val);
                        st.set_preg(pn as usize, pn_val);
                        batch.push((name.clone(), insn, st));
                    }
                }
            }
        }
    }
    for b in 0..2u32 {
        for m in 0..2u32 {
            for (pd, pg, pn, regs) in [
                (0u32, 1u32, 2u32, "distinct"),
                (0, 0, 1, "pd_pg"),
                (0, 1, 0, "pd_pn"),
                (15, 14, 13, "high"),
            ] {
                let insn = enc_brka(b, 1, m, pg, pn, pd);
                let op = if b == 0 { "brka" } else { "brkb" };
                for (pd_val, pg_val, pn_val, pred_case) in [
                    (0x0000u16, 0x0000u16, 0x0000u16, "none"),
                    (0xffff, 0xffff, 0xffff, "all"),
                    (0xaaaa, 0x0f0f, 0x00f0, "middle"),
                    (0x5555, 0xffff, 0x8000, "last"),
                    (0x8001, 0x00ff, 0x0001, "first"),
                ] {
                    for nzcv in 0..16u64 {
                        let mut st = ArmState::zeroed();
                        st.pstate = nzcv << 28;
                        st.set_preg(pd as usize, pd_val);
                        st.set_preg(pg as usize, pg_val);
                        st.set_preg(pn as usize, pn_val);
                        batch.push((
                            format!("{op}_{regs}_m{m}_{pred_case}_nzcv{nzcv:x}"),
                            insn,
                            st,
                        ));
                    }
                }
            }
        }
    }
    run_batch("sve_brk", batch);
}

#[test]
fn diff_sve_brkn() {
    // BRKN: result = Pdm if the last Pg-active element of Pn is set, else 0.
    // Cover random distinct operands plus predicate-register aliases.
    let mut rng = Rng::new(0x2_C001);
    let mut batch: Vec<(String, u32, ArmState)> = Vec::new();
    for s in 0..2u32 {
        let insn = enc_brkn(s, 1, 2, 0); // Pg=p1, Pn=p2, Pdm=p0
        for _ in 0..24 {
            let mut st = ArmState::zeroed();
            st.set_preg(0, rng.next() as u16); // Pdm (source + dest)
            st.set_preg(1, rng.next() as u16); // Pg
            st.set_preg(2, rng.next() as u16); // Pn
            batch.push((format!("brkn s{s}"), insn, st));
        }
        for (pdm, pg, pn, regs) in [
            (0u32, 1u32, 2u32, "distinct"),
            (0, 0, 1, "pdm_pg"),
            (0, 1, 0, "pdm_pn"),
            (0, 1, 1, "pg_pn"),
            (0, 0, 0, "all"),
            (15, 14, 13, "high"),
        ] {
            let insn = enc_brkn(s, pg, pn, pdm);
            for (pdm_val, pg_val, pn_val) in [
                (0x0000u16, 0x0000u16, 0x0000u16),
                (0xffff, 0xffff, 0xffff),
                (0xaaaa, 0x0f0f, 0x00f0),
                (rng.next() as u16, rng.next() as u16, rng.next() as u16),
            ] {
                let mut st = ArmState::zeroed();
                st.set_preg(pdm as usize, pdm_val);
                st.set_preg(pg as usize, pg_val);
                st.set_preg(pn as usize, pn_val);
                batch.push((format!("brkn {regs} s{s}"), insn, st));
            }
        }
    }
    for (pdm, pg, pn, regs) in [
        (0u32, 1u32, 2u32, "distinct"),
        (0, 0, 1, "pdm_pg"),
        (0, 1, 0, "pdm_pn"),
        (15, 14, 13, "high"),
    ] {
        let insn = enc_brkn(1, pg, pn, pdm);
        for (pdm_val, pg_val, pn_val, pred_case) in [
            (0x0000u16, 0x0000u16, 0x0000u16, "none"),
            (0xffff, 0xffff, 0xffff, "all"),
            (0xaaaa, 0x0f0f, 0x00f0, "middle"),
            (0x5555, 0xffff, 0x8000, "last"),
            (0x8001, 0x00ff, 0x0001, "first"),
        ] {
            for nzcv in 0..16u64 {
                let mut st = ArmState::zeroed();
                st.pstate = nzcv << 28;
                st.set_preg(pdm as usize, pdm_val);
                st.set_preg(pg as usize, pg_val);
                st.set_preg(pn as usize, pn_val);
                batch.push((format!("brkn_{regs}_{pred_case}_nzcv{nzcv:x}"), insn, st));
            }
        }
    }
    run_batch("sve_brkn", batch);
}

