#[test]
fn diff_sve2_sqdmulh() {
    fn pack_lanes(esize: usize, values: &[u64]) -> (u64, u64) {
        let bits = esize * 8;
        let mask = if bits >= 64 {
            u64::MAX
        } else {
            (1u64 << bits) - 1
        };
        let mut packed = 0u128;
        for (lane, &value) in values.iter().enumerate() {
            packed |= ((value & mask) as u128) << (lane * bits);
        }
        (packed as u64, (packed >> 64) as u64)
    }

    // SVE2 SQDMULH/SQRDMULH and SQRDMLAH/SQRDMLSH (saturating doubling).
    let mut cases: Vec<(String, u32)> = Vec::new();
    for size in 0..4u32 {
        cases.push((format!("sqdmulh sz{size}"), enc_sve2_sqdmulh(size, 0)));
        cases.push((format!("sqrdmulh sz{size}"), enc_sve2_sqdmulh(size, 1)));
        cases.push((format!("sqrdmlah sz{size}"), enc_sve2_sqrdmlah(size, 0)));
        cases.push((format!("sqrdmlsh sz{size}"), enc_sve2_sqrdmlah(size, 1)));
    }
    run_family("sve2_sqdmulh", cases, 16, 0x5_9001);

    let mut batch: Vec<(String, u32, ArmState)> = Vec::new();
    for size in 0..4u32 {
        let esize = 1usize << size;
        let bits = esize * 8;
        let mask = if bits >= 64 {
            u64::MAX
        } else {
            (1u64 << bits) - 1
        };
        let sign = 1u64 << (bits - 1);
        let hi = sign - 1;
        let tie = 1u64 << (bits / 2 - 1);
        let lanes = 16 / esize;
        let patterns: [(&str, Vec<u64>, Vec<u64>, Vec<u64>); 4] = [
            (
                "small",
                (0..lanes).map(|lane| lane as u64 + 1).collect(),
                (0..lanes).map(|lane| lane as u64 + 2).collect(),
                (0..lanes).map(|lane| lane as u64 * 3).collect(),
            ),
            (
                "signed_edges",
                (0..lanes)
                    .map(|lane| [0, 1, mask, sign, hi][lane % 5])
                    .collect(),
                (0..lanes)
                    .map(|lane| [1, mask, 2, sign, hi][lane % 5])
                    .collect(),
                (0..lanes)
                    .map(|lane| [0, sign, hi, mask][lane % 4])
                    .collect(),
            ),
            (
                "min_min",
                vec![sign; lanes],
                vec![sign; lanes],
                (0..lanes)
                    .map(|lane| if lane & 1 == 0 { hi } else { sign })
                    .collect(),
            ),
            (
                "rounding_tie",
                vec![tie; lanes],
                vec![tie; lanes],
                (0..lanes)
                    .map(|lane| if lane & 1 == 0 { 0 } else { mask })
                    .collect(),
            ),
        ];
        for (pattern_name, zn_values, zm_values, acc_values) in &patterns {
            let (zn_lo, zn_hi) = pack_lanes(esize, zn_values);
            let (zm_lo, zm_hi) = pack_lanes(esize, zm_values);
            let (acc_lo, acc_hi) = pack_lanes(esize, acc_values);
            for r in 0..2u32 {
                let mut st = ArmState::zeroed();
                st.set_vreg(0, acc_lo, acc_hi);
                st.set_vreg(1, zn_lo, zn_hi);
                st.set_vreg(2, zm_lo, zm_hi);
                batch.push((
                    format!("sqdmulh_sz{size}_r{r}_{pattern_name}"),
                    enc_sve2_sqdmulh(size, r),
                    st,
                ));
            }
            for s in 0..2u32 {
                let mut st = ArmState::zeroed();
                st.set_vreg(0, acc_lo, acc_hi);
                st.set_vreg(1, zn_lo, zn_hi);
                st.set_vreg(2, zm_lo, zm_hi);
                batch.push((
                    format!("sqrdmlah_sz{size}_s{s}_{pattern_name}"),
                    enc_sve2_sqrdmlah(size, s),
                    st,
                ));
            }
        }
    }
    run_batch("sve2_sqdmulh_edges", batch);
}

#[test]
fn diff_sve2_sqrdmlsh_tie() {
    // Rounding-tie edge: every Zn/Zm .h lane = 0x0080, so the product is exactly
    // 2^14. SQRDMLSH negates the product before adding the rounding bias, giving
    // a doubling-high of 0 (result == Zda); negating the rounded SQRDMLAH result
    // would instead give -1 per lane.
    let mut rng = Rng::new(0x5_9101);
    let mut lanes = 0u128;
    for l in 0..8 {
        lanes |= 0x0080u128 << (l * 16);
    }
    let mut batch: Vec<(String, u32, ArmState)> = Vec::new();
    for s in 0..2u32 {
        let insn = enc_sve2_sqrdmlah(1, s); // .h
        let mut st = ArmState::zeroed();
        st.set_vreg(1, lanes as u64, (lanes >> 64) as u64);
        st.set_vreg(2, lanes as u64, (lanes >> 64) as u64);
        st.set_vreg(0, rng.next(), rng.next()); // Zda
        batch.push((format!("sqrdml_tie s{s}"), insn, st));
    }
    run_batch("sve2_sqrdmlsh_tie", batch);
}

/// (tsz, imm3) for a shift-left-long with source width `src_bits` and shift
/// `amount` (0..src_bits): tsz:imm3 = src_bits + amount.
fn shll_tsz_imm(src_bits: u32, amount: u32) -> (u32, u32) {
    let tszimm = src_bits + amount;
    ((tszimm >> 3) & 0x7, tszimm & 0x7)
}

