#[test]
fn diff_sve2_ssra() {
    fn pack_lanes(esize: usize, values: &[u64]) -> (u64, u64) {
        let bits = esize * 8;
        let mask = if bits >= 64 {
            u64::MAX
        } else {
            (1u64 << bits) - 1
        };
        let mut packed = 0u128;
        for (lane, &value) in values.iter().enumerate() {
            packed |= ((value & mask) as u128) << (lane * bits);
        }
        (packed as u64, (packed >> 64) as u64)
    }

    // SVE2 shift-right-accumulate (SSRA/USRA/SRSRA/URSRA) and shift-insert
    // (SRI/SLI), across element sizes and shift amounts.
    let mut cases: Vec<(String, u32)> = Vec::new();
    for &eb in &[8u32, 16, 32, 64] {
        for amt in 1..=eb {
            let (tsz, imm3) = ssra_tsz_imm(eb, amt);
            for r in 0..2u32 {
                for u in 0..2u32 {
                    cases.push((
                        format!("ssra e{eb} a{amt} r{r} u{u}"),
                        enc_sve2_ssra(tsz, imm3, r, u),
                    ));
                }
            }
            cases.push((format!("sri e{eb} a{amt}"), enc_sve2_sri(tsz, imm3, 0)));
        }
        for amt in 0..eb {
            let (tsz, imm3) = sli_tsz_imm(eb, amt);
            cases.push((format!("sli e{eb} a{amt}"), enc_sve2_sri(tsz, imm3, 1)));
        }
    }
    run_family("sve2_ssra", cases, 4, 0x5_F001);

    let mut batch: Vec<(String, u32, ArmState)> = Vec::new();
    for eb in [8u32, 16, 32, 64] {
        let esize = (eb / 8) as usize;
        let mask = if eb >= 64 { u64::MAX } else { (1u64 << eb) - 1 };
        let sign = 1u64 << (eb - 1);
        let hi = sign - 1;
        let lanes = 16 / esize;
        let patterns: [(&str, Vec<u64>, Vec<u64>); 3] = [
            (
                "small",
                (0..lanes).map(|lane| lane as u64 * 3).collect(),
                (0..lanes).map(|lane| lane as u64 + 1).collect(),
            ),
            (
                "signed_edges",
                (0..lanes)
                    .map(|lane| [0, 1, mask, sign, hi][lane % 5])
                    .collect(),
                (0..lanes)
                    .map(|lane| [mask, 2, sign, hi, 0][lane % 5])
                    .collect(),
            ),
            (
                "alternating",
                (0..lanes)
                    .map(|lane| if lane & 1 == 0 { mask } else { sign })
                    .collect(),
                (0..lanes)
                    .map(|lane| if lane & 1 == 0 { hi } else { 0 })
                    .collect(),
            ),
        ];
        for amt in [1u32, eb / 2, eb] {
            let (tsz, imm3) = ssra_tsz_imm(eb, amt);
            for (pattern_name, zd_values, zn_values) in &patterns {
                let (zd_lo, zd_hi) = pack_lanes(esize, zd_values);
                let (zn_lo, zn_hi) = pack_lanes(esize, zn_values);
                for r in 0..2u32 {
                    for u in 0..2u32 {
                        let mut st = ArmState::zeroed();
                        st.set_vreg(0, zd_lo, zd_hi);
                        st.set_vreg(1, zn_lo, zn_hi);
                        batch.push((
                            format!("ssra_e{eb}_a{amt}_r{r}_u{u}_{pattern_name}"),
                            enc_sve2_ssra(tsz, imm3, r, u),
                            st,
                        ));
                    }
                }
                let mut st = ArmState::zeroed();
                st.set_vreg(0, zd_lo, zd_hi);
                st.set_vreg(1, zn_lo, zn_hi);
                batch.push((
                    format!("sri_e{eb}_a{amt}_{pattern_name}"),
                    enc_sve2_sri(tsz, imm3, 0),
                    st,
                ));
            }
        }
        for amt in [0u32, eb / 2, eb - 1] {
            let (tsz, imm3) = sli_tsz_imm(eb, amt);
            for (pattern_name, zd_values, zn_values) in &patterns {
                let (zd_lo, zd_hi) = pack_lanes(esize, zd_values);
                let (zn_lo, zn_hi) = pack_lanes(esize, zn_values);
                let mut st = ArmState::zeroed();
                st.set_vreg(0, zd_lo, zd_hi);
                st.set_vreg(1, zn_lo, zn_hi);
                batch.push((
                    format!("sli_e{eb}_a{amt}_{pattern_name}"),
                    enc_sve2_sri(tsz, imm3, 1),
                    st,
                ));
            }
        }
    }
    run_batch("sve2_ssra_edges", batch);
}

#[test]
fn diff_sve2_fpairwise() {
    fn pack_lanes(esize: u32, values: &[u64]) -> (u64, u64) {
        let mut packed = 0u128;
        let mask = if esize == 64 {
            u64::MAX
        } else {
            (1u64 << esize) - 1
        };
        for (lane, value) in values.iter().enumerate() {
            packed |= ((*value & mask) as u128) << (lane * esize as usize);
        }
        (packed as u64, (packed >> 64) as u64)
    }

    // SVE2 FP pairwise: FADDP/FMAXNMP/FMINNMP/FMAXP/FMINP (predicated, merging).
    let ops: &[(u32, &str)] = &[
        (0b000, "faddp"),
        (0b100, "fmaxnmp"),
        (0b101, "fminnmp"),
        (0b110, "fmaxp"),
        (0b111, "fminp"),
    ];
    let mut rng = Rng::new(0x6_0001);
    let mut batch: Vec<(String, u32, ArmState)> = Vec::new();
    for size in 1..4u32 {
        let eb = 8 << size; // element bits: 16 / 32 / 64
        let lanes = (128 / eb) as usize;
        for &(opc, name) in ops {
            let insn = enc_sve2_fpairwise(size, opc);
            for _ in 0..16 {
                let mut st = ArmState::zeroed();
                let (l0, h0) = fill_finite_fp(&mut rng, eb, lanes);
                st.set_vreg(0, l0, h0);
                let (l1, h1) = fill_finite_fp(&mut rng, eb, lanes);
                st.set_vreg(1, l1, h1);
                st.set_preg(0, rng.next() as u16);
                batch.push((format!("{name} sz{size}"), insn, st));
            }
        }
    }

    for size in 1..4u32 {
        let eb = 8 << size;
        let (all_active, mixed_active, patterns): (u16, u16, Vec<(&str, Vec<u64>, Vec<u64>)>) =
            match size {
                1 => (
                    0xffff,
                    0x1111,
                    vec![
                        (
                            "h_zeros",
                            vec![
                                0x0000, 0x8000, 0x0000, 0x8000, 0x3c00, 0xbc00, 0x4000, 0xc000,
                            ],
                            vec![
                                0x3c00, 0xbc00, 0x4000, 0xc000, 0x3800, 0xb800, 0x4200, 0xc200,
                            ],
                        ),
                        (
                            "h_lane_mix",
                            vec![
                                0x3e00, 0xbe00, 0x4100, 0xc100, 0x3555, 0xb555, 0x4480, 0xc480,
                            ],
                            vec![
                                0x3c00, 0x4000, 0xbc00, 0xc000, 0x3800, 0xb800, 0x4200, 0xc200,
                            ],
                        ),
                    ],
                ),
                2 => (
                    0xffff,
                    0x0101,
                    vec![
                        (
                            "s_zeros",
                            vec![
                                0x0000_0000,
                                0x8000_0000,
                                1.0f32.to_bits() as u64,
                                (-1.0f32).to_bits() as u64,
                            ],
                            vec![
                                2.0f32.to_bits() as u64,
                                (-2.0f32).to_bits() as u64,
                                0.5f32.to_bits() as u64,
                                (-0.5f32).to_bits() as u64,
                            ],
                        ),
                        (
                            "s_lane_mix",
                            vec![
                                16.0f32.to_bits() as u64,
                                (-16.0f32).to_bits() as u64,
                                0.25f32.to_bits() as u64,
                                (-0.25f32).to_bits() as u64,
                            ],
                            vec![
                                1.5f32.to_bits() as u64,
                                (-2.5f32).to_bits() as u64,
                                3.5f32.to_bits() as u64,
                                (-4.5f32).to_bits() as u64,
                            ],
                        ),
                    ],
                ),
                _ => (
                    0xffff,
                    0x0001,
                    vec![
                        (
                            "d_zeros",
                            vec![0.0f64.to_bits(), (-0.0f64).to_bits()],
                            vec![1.0f64.to_bits(), (-1.0f64).to_bits()],
                        ),
                        (
                            "d_lane_mix",
                            vec![16.0f64.to_bits(), (-16.0f64).to_bits()],
                            vec![0.25f64.to_bits(), (-0.75f64).to_bits()],
                        ),
                    ],
                ),
            };
        for &(opc, name) in ops {
            let insn = enc_sve2_fpairwise(size, opc);
            for (pattern_name, zd, zn) in &patterns {
                let mut st = ArmState::zeroed();
                let (lo, hi) = pack_lanes(eb, zd);
                st.set_vreg(0, lo, hi);
                let (lo, hi) = pack_lanes(eb, zn);
                st.set_vreg(1, lo, hi);
                st.set_preg(0, all_active);
                batch.push((format!("{name}_{pattern_name}_all"), insn, st));

                let mut st = ArmState::zeroed();
                let (lo, hi) = pack_lanes(eb, zd);
                st.set_vreg(0, lo, hi);
                let (lo, hi) = pack_lanes(eb, zn);
                st.set_vreg(1, lo, hi);
                st.set_preg(0, mixed_active);
                batch.push((format!("{name}_{pattern_name}_mixed"), insn, st));
            }
        }
    }
    run_batch("sve2_fpairwise", batch);
}

