#[test]
fn diff_sve2_faddp_fpcr_rounding() {
    let insn = enc_sve2_fpairwise(2, 0b000);
    let variants = [
        ("pos", 16_777_216.0f32, 1.0f32),
        ("neg", -16_777_216.0f32, -1.0f32),
    ];
    let mut batch: Vec<(String, u32, ArmState)> = Vec::new();
    for rmode in 0..4u64 {
        for (name, a, b) in variants {
            let mut st = ArmState::zeroed();
            st.fpcr = rmode << 22;
            st.set_preg(0, 0x0001);
            st.set_vreg(0, (a.to_bits() as u64) | ((b.to_bits() as u64) << 32), 0);
            batch.push((format!("faddp_{name}_rmode{rmode}"), insn, st));
        }
    }
    run_batch("sve2_faddp_fpcr_rounding", batch);
}

#[test]
fn diff_fpcr_fiz_sve2_faddp_subnormal_inputs() {
    const FPCR_FIZ: u64 = 1;
    let mut batch: Vec<(String, u32, ArmState)> = Vec::new();

    let mut st = ArmState::zeroed();
    st.fpcr = FPCR_FIZ;
    st.set_preg(0, 0xffff);
    let mut v = 0u128;
    for lane in 0..4 {
        v |= 0x0000_0001u128 << (32 * lane);
    }
    st.set_vreg(RD as usize, v as u64, (v >> 64) as u64);
    st.set_vreg(RN as usize, v as u64, (v >> 64) as u64);
    batch.push((
        "sve2_faddp_s_min_subnorm".to_string(),
        enc_sve2_fpairwise(2, 0b000),
        st,
    ));

    let mut st = ArmState::zeroed();
    st.fpcr = FPCR_FIZ;
    st.set_preg(0, 0xffff);
    let v = 0x0000_0000_0000_0001u128;
    let v = v | (v << 64);
    st.set_vreg(RD as usize, v as u64, (v >> 64) as u64);
    st.set_vreg(RN as usize, v as u64, (v >> 64) as u64);
    batch.push((
        "sve2_faddp_d_min_subnorm".to_string(),
        enc_sve2_fpairwise(3, 0b000),
        st,
    ));

    run_batch("fpcr_fiz_sve2_faddp_subnormal_inputs", batch);
}

#[test]
fn diff_sve_mul() {
    fn pack_lanes(esize: usize, values: &[u64]) -> (u64, u64) {
        let bits = esize * 8;
        let mask = if bits >= 64 {
            u64::MAX
        } else {
            (1u64 << bits) - 1
        };
        let mut packed = 0u128;
        for (lane, &value) in values.iter().enumerate() {
            packed |= ((value & mask) as u128) << (lane * bits);
        }
        (packed as u64, (packed >> 64) as u64)
    }

    // SVE2 unpredicated MUL/SMULH/UMULH. SMULH/UMULH return the high half of
    // the double-width product; MUL returns the low half. Element-wise, so the
    // low 128 bits match at any VL (oracle pins VL=128).
    let mut cases: Vec<(String, u32)> = Vec::new();
    for sz in 0..4u32 {
        cases.push((format!("sve_mul sz{sz}"), enc_sve_mul(sz, 0b00)));
        cases.push((format!("sve_smulh sz{sz}"), enc_sve_mul(sz, 0b10)));
        cases.push((format!("sve_umulh sz{sz}"), enc_sve_mul(sz, 0b11)));
    }
    // PMUL (SVE2 carry-less polynomial multiply) is byte-elements only.
    cases.push(("sve_pmul".to_string(), enc_sve_mul(0, 0b01)));
    run_family("sve_mul", cases, 16, 0x2_4001);

    let mut batch: Vec<(String, u32, ArmState)> = Vec::new();
    for sz in 0..4u32 {
        let esize = 1usize << sz;
        let bits = esize * 8;
        let mask = if bits >= 64 {
            u64::MAX
        } else {
            (1u64 << bits) - 1
        };
        let sign = 1u64 << (bits - 1);
        let hi = sign - 1;
        let lanes = 16 / esize;
        let patterns: [(&str, Vec<u64>, Vec<u64>); 3] = [
            (
                "small",
                (0..lanes).map(|lane| lane as u64 + 1).collect(),
                (0..lanes).map(|lane| lane as u64 + 2).collect(),
            ),
            (
                "signed_edges",
                (0..lanes)
                    .map(|lane| [0, 1, mask, sign, hi][lane % 5])
                    .collect(),
                (0..lanes)
                    .map(|lane| [1, mask, 2, sign, hi][lane % 5])
                    .collect(),
            ),
            (
                "alternating",
                (0..lanes)
                    .map(|lane| if lane & 1 == 0 { mask } else { sign })
                    .collect(),
                (0..lanes)
                    .map(|lane| if lane & 1 == 0 { hi } else { 2 })
                    .collect(),
            ),
        ];
        for (pattern_name, zn_values, zm_values) in &patterns {
            let (zn_lo, zn_hi) = pack_lanes(esize, zn_values);
            let (zm_lo, zm_hi) = pack_lanes(esize, zm_values);
            for (opc, name) in [(0b00, "mul"), (0b10, "smulh"), (0b11, "umulh")] {
                let mut st = ArmState::zeroed();
                st.set_vreg(0, 0xaaaa_5555_ffff_0000, 0x0123_4567_89ab_cdef);
                st.set_vreg(1, zn_lo, zn_hi);
                st.set_vreg(2, zm_lo, zm_hi);
                batch.push((
                    format!("{name}_sz{sz}_{pattern_name}"),
                    enc_sve_mul(sz, opc),
                    st,
                ));
            }
        }
    }
    let pmul_patterns: [(&str, Vec<u64>, Vec<u64>); 4] = [
        ("zero", vec![0; 16], vec![0; 16]),
        ("ones", vec![0xff; 16], vec![0xff; 16]),
        (
            "ramp",
            (0..16).map(|lane| lane as u64).collect(),
            (0..16).map(|lane| 15 - lane as u64).collect(),
        ),
        (
            "poly_edges",
            vec![
                0x00, 0x01, 0x02, 0x03, 0x7f, 0x80, 0xfe, 0xff, 0x55, 0xaa, 0x11, 0x22, 0x44, 0x88,
                0xf0, 0x0f,
            ],
            vec![
                0xff, 0xfe, 0x80, 0x7f, 0x03, 0x02, 0x01, 0x00, 0x0f, 0xf0, 0x88, 0x44, 0x22, 0x11,
                0xaa, 0x55,
            ],
        ),
    ];
    for (pattern_name, zn_values, zm_values) in &pmul_patterns {
        let (zn_lo, zn_hi) = pack_lanes(1, zn_values);
        let (zm_lo, zm_hi) = pack_lanes(1, zm_values);
        let mut st = ArmState::zeroed();
        st.set_vreg(0, 0x5555_aaaa_0000_ffff, 0xfedc_ba98_7654_3210);
        st.set_vreg(1, zn_lo, zn_hi);
        st.set_vreg(2, zm_lo, zm_hi);
        batch.push((format!("pmul_{pattern_name}"), enc_sve_mul(0, 0b01), st));
    }
    run_batch("sve_mul_edges", batch);
}

