/// A finite bf16 value with a moderate exponent (so f64 dot-product sums stay
/// exact and the round-to-odd model matches hardware).
fn rand_bf16(rng: &mut Rng) -> u16 {
    let sign = (rng.next() & 1) as u16;
    let exp = (rng.next() % 11 + 122) as u16; // unbiased -5..5
    let frac = (rng.next() as u16) & 0x7F;
    (sign << 15) | (exp << 7) | frac
}

/// Fill a 128-bit vector with 8 finite bf16 lanes.
fn bf16_vec(rng: &mut Rng) -> (u64, u64) {
    let mut v: u128 = 0;
    for i in 0..8 {
        v |= (rand_bf16(rng) as u128) << (i * 16);
    }
    (v as u64, (v >> 64) as u64)
}

/// Fill a 128-bit vector with 4 finite f32 accumulator lanes.
fn f32_acc_vec(rng: &mut Rng) -> (u64, u64) {
    let mut v: u128 = 0;
    for i in 0..4 {
        let val = (((rng.next() % 4000) as f32) - 2000.0) / 200.0; // +/-10
        v |= (val.to_bits() as u128) << (i * 32);
    }
    (v as u64, (v >> 64) as u64)
}

/// BFMLALB/T (vector): `0 Q 1 01110 11 0 Rm 111111 Rn Rd`. Q=B(0)/T(1).
fn enc_bfmlal(q: u32) -> u32 {
    (q << 30)
        | (1 << 29)
        | (0b01110 << 24)
        | (0b11 << 22)
        | (RM << 16)
        | (0b111111 << 10)
        | (RN << 5)
        | RD
}

/// BFMLALB/T (by element): `0 Q 0 01111 11 L M Rm 1111 H 0 Rn Rd`. index=H:L:M.
fn enc_bfmlal_idx(q: u32, index: u32) -> u32 {
    let h = (index >> 2) & 1;
    let l = (index >> 1) & 1;
    let m = index & 1;
    (q << 30)
        | (0b01111 << 24)
        | (0b11 << 22)
        | (l << 21)
        | (m << 20)
        | (RM << 16)
        | (0b1111 << 12)
        | (h << 11)
        | (RN << 5)
        | RD
}

/// BFDOT (vector): `0 Q 1 01110 01 0 Rm 111111 Rn Rd`. Q=datasize.
fn enc_bfdot(q: u32) -> u32 {
    (q << 30)
        | (1 << 29)
        | (0b01110 << 24)
        | (0b01 << 22)
        | (RM << 16)
        | (0b111111 << 10)
        | (RN << 5)
        | RD
}

/// BFDOT (by element): `0 Q 0 01111 01 L M Rm 1111 H 0 Rn Rd`. index=H:L.
fn enc_bfdot_idx(q: u32, index: u32) -> u32 {
    let h = (index >> 1) & 1;
    let l = index & 1;
    (q << 30)
        | (0b01111 << 24)
        | (0b01 << 22)
        | (l << 21)
        | (RM << 16)
        | (0b1111 << 12)
        | (h << 11)
        | (RN << 5)
        | RD
}

/// BFMMLA: `0 1 1 01110 01 0 Rm 111011 Rn Rd`.
fn enc_bfmmla() -> u32 {
    (1 << 30)
        | (1 << 29)
        | (0b01110 << 24)
        | (0b01 << 22)
        | (RM << 16)
        | (0b111011 << 10)
        | (RN << 5)
        | RD
}

fn enc_bf16_three_same_extra(q: u32, size: u32, lo6: u32) -> u32 {
    (q << 30)
        | (1 << 29)
        | (0b01110 << 24)
        | ((size & 0x3) << 22)
        | (RM << 16)
        | ((lo6 & 0x3f) << 10)
        | (RN << 5)
        | RD
}

/// SMMLA/UMMLA/USMMLA: `0 Q U 01110 10 0 Rm op Rn Rd`.
/// `lo6` is 101001 for SMMLA/UMMLA and 101011 for USMMLA.
fn enc_simd_i8mm_mmla(q: u32, u: u32, lo6: u32) -> u32 {
    (q << 30)
        | (u << 29)
        | (0b01110 << 24)
        | (0b10 << 22)
        | (RM << 16)
        | ((lo6 & 0x3f) << 10)
        | (RN << 5)
        | RD
}

/// A varied f32 bit pattern for BFCVT testing: finite normals, tie cases,
/// overflow, signed zero, and (occasionally) inf. NaN is excluded to keep
/// payload-propagation out of the comparison.
fn rand_f32_for_bfcvt(rng: &mut Rng) -> u32 {
    match rng.next() % 12 {
        0 => 0x3F80_8000,                     // tie, bf16 lsb 0 -> rounds down
        1 => 0x3F81_8000,                     // tie, bf16 lsb 1 -> rounds up
        2 => 0x7F7F_FFFF,                     // max f32 -> overflow to bf16 inf
        3 => 0x0000_0000,                     // +0
        4 => 0x8000_0000,                     // -0
        5 => 0x7F80_0000,                     // +inf
        6 => 0xFF80_0000,                     // -inf
        7 => rng.next() as u32 & 0x0000_FFFF, // tiny / subnormal-ish low bits
        _ => {
            let sign = (rng.next() & 1) as u32;
            let exp = (rng.next() % 60 + 100) as u32; // finite normal exponents
            let mant = rng.next() as u32 & 0x7F_FFFF;
            (sign << 31) | (exp << 23) | mant
        }
    }
}

#[test]
fn diff_simd_bfcvt() {
    let bfcvt = 0x1E63_4000 | (RN << 5) | RD; // BFCVT Hd, Sn
    let bfcvtn = 0x0EA1_6800 | (RN << 5) | RD; // BFCVTN Vd.4H, Vn.4S
    let bfcvtn2 = 0x4EA1_6800 | (RN << 5) | RD; // BFCVTN2 Vd.8H, Vn.4S
    let mut rng = Rng::new(0x1_001E);
    let mut batch: Vec<(String, u32, ArmState)> = Vec::new();
    for _ in 0..200 {
        // BFCVT scalar: Sn in v1 low 32 bits.
        let mut st = ArmState::zeroed();
        st.set_vreg(1, rand_f32_for_bfcvt(&mut rng) as u64, 0);
        batch.push(("bfcvt".to_string(), bfcvt, st));

        // BFCVTN / BFCVTN2: 4 f32 lanes in Vn; seed Vd to check half handling.
        for &insn in &[bfcvtn, bfcvtn2] {
            let mut st = ArmState::zeroed();
            let lo = (rand_f32_for_bfcvt(&mut rng) as u64)
                | ((rand_f32_for_bfcvt(&mut rng) as u64) << 32);
            let hi = (rand_f32_for_bfcvt(&mut rng) as u64)
                | ((rand_f32_for_bfcvt(&mut rng) as u64) << 32);
            st.set_vreg(1, lo, hi);
            st.set_vreg(0, rng.next(), rng.next()); // Vd preset (BFCVTN2 preserves low half)
            batch.push(("bfcvtn".to_string(), insn, st));
        }
    }
    run_batch("simd_bfcvt", batch);
}

#[test]
fn diff_simd_bfcvt_fpcr_rmode() {
    let bfcvt = 0x1E63_4000 | (RN << 5) | RD;
    let bfcvtn = 0x0EA1_6800 | (RN << 5) | RD;
    let bfcvtn2 = 0x4EA1_6800 | (RN << 5) | RD;
    let tie_inputs = [
        0x3f80_8000u32, // exact half-way, bf16 LSB 0
        0x3f81_8000u32, // exact half-way, bf16 LSB 1
        0xbf80_8000u32,
        0xbf81_8000u32,
    ];

    let mut rng = Rng::new(0x1_001f);
    let mut batch = Vec::new();
    for rmode in 0..4u64 {
        let fpcr = rmode << 22;
        for &value in &tie_inputs {
            let mut st = ArmState::zeroed();
            st.fpcr = fpcr;
            st.set_vreg(RN as usize, value as u64, 0);
            batch.push((format!("bfcvt_rmode{rmode}_{value:#x}"), bfcvt, st));
        }

        for &insn in &[bfcvtn, bfcvtn2] {
            let mut st = ArmState::zeroed();
            st.fpcr = fpcr;
            let lo = (tie_inputs[0] as u64) | ((tie_inputs[1] as u64) << 32);
            let hi = (tie_inputs[2] as u64) | ((tie_inputs[3] as u64) << 32);
            st.set_vreg(RN as usize, lo, hi);
            st.set_vreg(RD as usize, rng.next(), rng.next());
            batch.push((format!("bfcvtn_rmode{rmode}_{insn:#x}"), insn, st));
        }
    }

    run_batch("simd_bfcvt_fpcr_rmode", batch);
}

#[test]
fn diff_fpcr_fiz_simd_bfcvt_subnormal_inputs() {
    const FPCR_FIZ: u64 = 1;
    let bfcvt = 0x1E63_4000 | (RN << 5) | RD;
    let bfcvtn = 0x0EA1_6800 | (RN << 5) | RD;
    let bfcvtn2 = 0x4EA1_6800 | (RN << 5) | RD;
    let mut batch: Vec<(String, u32, ArmState)> = Vec::new();

    for &(name, bits) in &[
        ("pos_max", 0x007f_ffffu64),
        ("neg_max", 0x807f_ffffu64),
        ("pos_min", 0x0000_0001u64),
        ("neg_min", 0x8000_0001u64),
    ] {
        let mut st = ArmState::zeroed();
        st.fpcr = FPCR_FIZ;
        st.set_vreg(RN as usize, bits, 0);
        batch.push((format!("bfcvt_{name}_fiz_subnorm"), bfcvt, st));
    }

    let lanes = [
        0x007f_ffffu32,
        0x807f_ffffu32,
        0x0000_0001u32,
        0x8000_0001u32,
    ];
    let mut packed = 0u128;
    for (lane, bits) in lanes.iter().enumerate() {
        packed |= (*bits as u128) << (32 * lane);
    }
    for &(name, insn) in &[("bfcvtn", bfcvtn), ("bfcvtn2", bfcvtn2)] {
        let mut st = ArmState::zeroed();
        st.fpcr = FPCR_FIZ;
        st.set_vreg(RN as usize, packed as u64, (packed >> 64) as u64);
        st.set_vreg(RD as usize, 0xaaaa_aaaa_aaaa_aaaa, 0xbbbb_bbbb_bbbb_bbbb);
        batch.push((format!("{name}_fiz_subnorm"), insn, st));
    }

    run_batch("fpcr_fiz_simd_bfcvt_subnormal_inputs", batch);
}

#[test]
fn diff_fpcr_ah_bfcvt_status() {
    const FPCR_AH: u64 = 1 << 1;
    let bfcvt = 0x1E63_4000 | (RN << 5) | RD;
    let bfcvtn = 0x0EA1_6800 | (RN << 5) | RD;
    let bfcvtn2 = 0x4EA1_6800 | (RN << 5) | RD;
    let lanes = [
        0x7fa0_0001u32,
        0x007f_ffffu32,
        0x3f80_0001u32,
        0x7f7f_ffffu32,
    ];
    let mut batch: Vec<(String, u32, ArmState)> = Vec::new();

    for &(name, bits) in &[
        ("snan", lanes[0]),
        ("subnorm", lanes[1]),
        ("inexact", lanes[2]),
        ("overflow", lanes[3]),
    ] {
        let mut st = ArmState::zeroed();
        st.fpcr = FPCR_AH;
        st.set_vreg(RN as usize, bits as u64, 0);
        batch.push((format!("bfcvt_ah_{name}"), bfcvt, st));
    }

    let mut packed = 0u128;
    for (lane, bits) in lanes.iter().enumerate() {
        packed |= (*bits as u128) << (32 * lane);
    }
    for &(name, insn) in &[("bfcvtn", bfcvtn), ("bfcvtn2", bfcvtn2)] {
        let mut st = ArmState::zeroed();
        st.fpcr = FPCR_AH;
        st.set_vreg(RN as usize, packed as u64, (packed >> 64) as u64);
        st.set_vreg(RD as usize, 0xaaaa_aaaa_aaaa_aaaa, 0xbbbb_bbbb_bbbb_bbbb);
        batch.push((format!("{name}_ah_status"), insn, st));
    }

    let mut st = ArmState::zeroed();
    st.fpcr = FPCR_AH;
    st.set_preg(0, 0xffff);
    st.set_vreg(RN as usize, packed as u64, (packed >> 64) as u64);
    batch.push(("sve_bfcvt_ah_status".to_string(), enc_sve_bfcvt(), st));

    let mut st = ArmState::zeroed();
    st.fpcr = FPCR_AH;
    st.set_preg(0, 0xffff);
    st.set_vreg(RN as usize, packed as u64, (packed >> 64) as u64);
    st.set_vreg(RD as usize, 0xaaaa_aaaa_aaaa_aaaa, 0xbbbb_bbbb_bbbb_bbbb);
    batch.push((
        "sve2_bfcvtnt_ah_status".to_string(),
        enc_sve2_fcvtx(0b10, 0b10),
        st,
    ));

    run_batch("fpcr_ah_bfcvt_status", batch);
}

#[test]
fn diff_fpcr_fz_widening_fma_subnormal_inputs() {
    const FPCR_FZ: u64 = 1 << 24;
    let bfcvtn = 0x0EA1_6800 | (RN << 5) | RD;
    let mut batch: Vec<(String, u32, ArmState)> = Vec::new();

    let pack_h = |value: u16| -> (u64, u64) {
        let mut packed = 0u128;
        for lane in 0..8 {
            packed |= (value as u128) << (16 * lane);
        }
        (packed as u64, (packed >> 64) as u64)
    };
    let pack_s = |value: u32| -> (u64, u64) {
        let mut packed = 0u128;
        for lane in 0..4 {
            packed |= (value as u128) << (32 * lane);
        }
        (packed as u64, (packed >> 64) as u64)
    };

    for &(name, insn, n_val, m_val) in &[
        (
            "fmlal_lhs_min_subnorm",
            enc_three_same(1, 0, 0b00, 0b11101),
            0x0001u16,
            0x3c00u16,
        ),
        (
            "fmlal_rhs_min_subnorm",
            enc_three_same(1, 0, 0b00, 0b11101),
            0x3c00u16,
            0x0001u16,
        ),
        (
            "fmlsl_lhs_min_subnorm",
            enc_three_same(1, 0, 0b10, 0b11101),
            0x0001u16,
            0x3c00u16,
        ),
    ] {
        let mut st = ArmState::zeroed();
        st.fpcr = FPCR_FZ;
        let (lo, hi) = pack_h(n_val);
        st.set_vreg(RN as usize, lo, hi);
        let (lo, hi) = pack_h(m_val);
        st.set_vreg(RM as usize, lo, hi);
        st.set_vreg(RD as usize, 0, 0);
        batch.push((name.to_string(), insn, st));
    }

    for &(name, insn) in &[
        ("fmlal_acc_min_subnorm", enc_three_same(1, 0, 0b00, 0b11101)),
        ("fmlsl_acc_min_subnorm", enc_three_same(1, 0, 0b10, 0b11101)),
    ] {
        let mut st = ArmState::zeroed();
        st.fpcr = FPCR_FZ;
        let (lo, hi) = pack_s(0x0000_0001);
        st.set_vreg(RD as usize, lo, hi);
        st.set_vreg(RN as usize, 0, 0);
        let (lo, hi) = pack_h(0x3c00);
        st.set_vreg(RM as usize, lo, hi);
        batch.push((name.to_string(), insn, st));
    }

    let mut st = ArmState::zeroed();
    st.fpcr = FPCR_FZ;
    let (lo, hi) = pack_s(0x0000_0001);
    st.set_vreg(RN as usize, lo, hi);
    batch.push(("bfcvtn_fz_min_subnorm".to_string(), bfcvtn, st));

    for &(name, insn, n_val, m_val) in &[
        (
            "bfmlalb_lhs_min_subnorm",
            enc_bfmlal(0),
            0x0001u16,
            0x3f80u16,
        ),
        (
            "bfmlalb_rhs_min_subnorm",
            enc_bfmlal(0),
            0x3f80u16,
            0x0001u16,
        ),
        (
            "bfmlalb_idx_lhs_min_subnorm",
            enc_bfmlal_idx(0, 0),
            0x0001u16,
            0x3f80u16,
        ),
        (
            "bfmlalb_idx_rhs_min_subnorm",
            enc_bfmlal_idx(0, 0),
            0x3f80u16,
            0x0001u16,
        ),
    ] {
        let mut st = ArmState::zeroed();
        st.fpcr = FPCR_FZ;
        st.set_vreg(RD as usize, 0, 0);
        let (lo, hi) = pack_h(n_val);
        st.set_vreg(RN as usize, lo, hi);
        let (lo, hi) = pack_h(m_val);
        st.set_vreg(RM as usize, lo, hi);
        batch.push((name.to_string(), insn, st));
    }

    let mut st = ArmState::zeroed();
    st.fpcr = FPCR_FZ;
    st.set_vreg(RD as usize, 0x0000_0000_8000_0000, 0);
    st.set_vreg(RN as usize, 0x0000_0000_0d8d_3316, 0);
    st.set_vreg(RM as usize, 0x63b9_e7a3_a89b_d681, 0x0000_0000_0000_00d9);
    batch.push(("bfmlalt_output_tiny_fz".to_string(), enc_bfmlal(1), st));

    run_batch("fpcr_fz_widening_fma_subnormal_inputs", batch);
}

#[test]
fn diff_simd_i8mm_mmla_edges() {
    let variants = [
        ("smmla", enc_simd_i8mm_mmla(1, 0, 0b101001)),
        ("ummla", enc_simd_i8mm_mmla(1, 1, 0b101001)),
        ("usmmla", enc_simd_i8mm_mmla(1, 0, 0b101011)),
    ];
    let patterns = [
        ("zero", 0u128, 0u128, 0u128),
        ("all_ff", u128::MAX, u128::MAX, 0u128),
        (
            "signed_min_max",
            0x8080_8080_8080_8080_8080_8080_8080_8080u128,
            0x7f7f_7f7f_7f7f_7f7f_7f7f_7f7f_7f7f_7f7fu128,
            0u128,
        ),
        (
            "mixed_acc",
            0x00ff_807f_55aa_aa55_0102_0304_fefd_fcfbu128,
            0xff00_7f80_aa55_55aa_0403_0201_0102_0304u128,
            0x7fff_ffff_8000_0000_ffff_ffff_0000_0001u128,
        ),
        (
            "wraparound",
            0x7f7f_7f7f_7f7f_7f7f_0101_0101_0101_0101u128,
            0x0202_0202_0202_0202_7f7f_7f7f_7f7f_7f7fu128,
            0xffff_ff00_ffff_ff80_0000_0080_0000_00ffu128,
        ),
    ];

    let mut batch = Vec::new();
    for (name, insn) in variants {
        for (pattern, zn, zm, za) in patterns {
            let mut st = ArmState::zeroed();
            st.set_vreg(RD as usize, za as u64, (za >> 64) as u64);
            st.set_vreg(RN as usize, zn as u64, (zn >> 64) as u64);
            st.set_vreg(RM as usize, zm as u64, (zm >> 64) as u64);
            batch.push((format!("{name}_{pattern}"), insn, st));
        }
    }

    for (name, insn) in [
        ("smmla_q0_unallocated", enc_simd_i8mm_mmla(0, 0, 0b101001)),
        ("ummla_q0_unallocated", enc_simd_i8mm_mmla(0, 1, 0b101001)),
        ("usmmla_q0_unallocated", enc_simd_i8mm_mmla(0, 0, 0b101011)),
    ] {
        batch.push((name.to_string(), insn, ArmState::zeroed()));
    }

    run_batch("simd_i8mm_mmla_edges", batch);
}

#[test]
fn diff_simd_bf16() {
    fn pack_bf16(values: [u16; 8]) -> (u64, u64) {
        let mut packed = 0u128;
        for (lane, value) in values.iter().enumerate() {
            packed |= (*value as u128) << (lane * 16);
        }
        (packed as u64, (packed >> 64) as u64)
    }

    fn pack_f32(values: [f32; 4]) -> (u64, u64) {
        let mut packed = 0u128;
        for (lane, value) in values.iter().enumerate() {
            packed |= (value.to_bits() as u128) << (lane * 32);
        }
        (packed as u64, (packed >> 64) as u64)
    }

    let mut rng = Rng::new(0x1_001D);
    let mut batch: Vec<(String, u32, ArmState)> = Vec::new();
    // (label, insn, vector?) — all read v0 (f32 acc), v1/v2 (bf16).
    let mut cases: Vec<(String, u32)> = Vec::new();
    for q in 0..2u32 {
        cases.push((format!("bfmlal q{q}"), enc_bfmlal(q)));
        cases.push((format!("bfdot q{q}"), enc_bfdot(q)));
        for index in 0..4u32 {
            cases.push((format!("bfdot_idx q{q} i{index}"), enc_bfdot_idx(q, index)));
        }
        for index in 0..8u32 {
            cases.push((
                format!("bfmlal_idx q{q} i{index}"),
                enc_bfmlal_idx(q, index),
            ));
        }
    }
    cases.push(("bfmmla".to_string(), enc_bfmmla()));
    for (label, insn) in &cases {
        for _ in 0..24 {
            let mut st = ArmState::zeroed();
            let (a0, b0) = f32_acc_vec(&mut rng);
            let (a1, b1) = bf16_vec(&mut rng);
            let (a2, b2) = bf16_vec(&mut rng);
            st.set_vreg(0, a0, b0);
            st.set_vreg(1, a1, b1);
            st.set_vreg(2, a2, b2);
            batch.push((label.clone(), *insn, st));
        }
    }

    let patterns = [
        (
            "zeros",
            [0.0, -0.0, 0.0, -0.0],
            [
                0x0000, 0x8000, 0x0000, 0x8000, 0x0000, 0x8000, 0x0000, 0x8000,
            ],
            [0x3f80; 8],
        ),
        (
            "ones",
            [1.0, -1.0, 2.0, -2.0],
            [
                0x3f80, 0xbf80, 0x4000, 0xc000, 0x3f00, 0xbf00, 0x4080, 0xc080,
            ],
            [
                0x3f80, 0x3f80, 0xbf80, 0xbf80, 0x4000, 0xc000, 0x3f00, 0xbf00,
            ],
        ),
        (
            "lane_mix",
            [16.0, -16.0, 0.5, -0.5],
            [
                0x3f80, 0x4000, 0x4040, 0x4080, 0xbf80, 0xc000, 0xc040, 0xc080,
            ],
            [
                0x3f00, 0xbf00, 0x3fc0, 0xbfc0, 0x4020, 0xc020, 0x4060, 0xc060,
            ],
        ),
        (
            "small_normals",
            [0.0, 1.0, -1.0, 8.0],
            [
                0x0080, 0x8080, 0x0100, 0x8100, 0x3f80, 0xbf80, 0x4000, 0xc000,
            ],
            [
                0x3f80, 0xbf80, 0x0080, 0x8080, 0x3f00, 0xbf00, 0x4000, 0xc000,
            ],
        ),
    ];
    for (label, insn) in &cases {
        for (pattern_name, acc, zn, zm) in patterns {
            let mut st = ArmState::zeroed();
            let (lo, hi) = pack_f32(acc);
            st.set_vreg(0, lo, hi);
            let (lo, hi) = pack_bf16(zn);
            st.set_vreg(1, lo, hi);
            let (lo, hi) = pack_bf16(zm);
            st.set_vreg(2, lo, hi);
            batch.push((format!("{label}_{pattern_name}"), *insn, st));
        }
    }
    run_batch("simd_bf16", batch);
}

#[test]
fn diff_simd_bf16_unallocated_edges() {
    let mut rng = Rng::new(0x1_0031);
    let mut batch: Vec<(String, u32, ArmState)> = Vec::new();

    for q in 0..2u32 {
        batch.push((
            format!("bfdot_bit31_q{q}"),
            enc_bfdot(q) | (1 << 31),
            gen_input(&mut rng),
        ));
        batch.push((
            format!("bfdot_idx_bit31_q{q}"),
            enc_bfdot_idx(q, 0) | (1 << 31),
            gen_input(&mut rng),
        ));
        batch.push((
            format!("bfmlal_idx_bit31_q{q}"),
            enc_bfmlal_idx(q, 0) | (1 << 31),
            gen_input(&mut rng),
        ));
    }
    batch.push((
        "bfmmla_bit31".to_string(),
        enc_bfmmla() | (1 << 31),
        gen_input(&mut rng),
    ));
    batch.push((
        "bfcvtn_bit31_q0".to_string(),
        (0x0EA1_6800 | (RN << 5) | RD) | (1 << 31),
        gen_input(&mut rng),
    ));

    for &size in &[0b00u32, 0b10] {
        for q in 0..2u32 {
            for _ in 0..4 {
                batch.push((
                    format!("bf_dot_mlal_reserved_size{size}_q{q}"),
                    enc_bf16_three_same_extra(q, size, 0b111111),
                    gen_input(&mut rng),
                ));
            }
        }
    }

    for q in 0..2u32 {
        for &size in &[0b00u32, 0b01, 0b10, 0b11] {
            if q == 1 && size == 0b01 {
                continue;
            }
            for _ in 0..4 {
                batch.push((
                    format!("bfmmla_reserved_size{size}_q{q}"),
                    enc_bf16_three_same_extra(q, size, 0b111011),
                    gen_input(&mut rng),
                ));
            }
        }
    }

    run_batch_el0_legality("simd_bf16_unallocated_edges", batch);
}

#[test]
fn diff_simd_bfmlal_fpcr_rounding() {
    let mut batch: Vec<(String, u32, ArmState)> = Vec::new();
    let variants = [
        ("pos", 16_777_216.0f32, 0x3f80u16),
        ("neg", -16_777_216.0f32, 0xbf80u16),
    ];

    for rmode in 0..4u64 {
        for q in 0..2u32 {
            for (name, acc, n_bf16) in variants {
                let mut zd = 0u128;
                let mut zn = 0u128;
                let mut zm = 0u128;
                for s in 0..4 {
                    zd |= (acc.to_bits() as u128) << (s * 32);
                }
                for h in 0..8 {
                    zn |= (n_bf16 as u128) << (h * 16);
                    zm |= (0x3f80u128) << (h * 16);
                }

                let mut st = ArmState::zeroed();
                st.fpcr = rmode << 22;
                st.set_vreg(0, zd as u64, (zd >> 64) as u64);
                st.set_vreg(1, zn as u64, (zn >> 64) as u64);
                st.set_vreg(2, zm as u64, (zm >> 64) as u64);
                batch.push((
                    format!("bfmlal_q{q}_{name}_rmode{rmode}"),
                    enc_bfmlal(q),
                    st,
                ));
            }
        }
    }

    run_batch("simd_bfmlal_fpcr_rounding", batch);
}

