#[test]
fn diff_fpcr_ah_fsqrt_negative_subnormal_status() {
    const FPCR_AH: u64 = 1 << 1;
    let pack_h = |value: u16| -> (u64, u64) {
        let mut packed = 0u128;
        for lane in 0..8 {
            packed |= (value as u128) << (16 * lane);
        }
        (packed as u64, (packed >> 64) as u64)
    };
    let pack_s = |value: u32| -> (u64, u64) {
        let mut packed = 0u128;
        for lane in 0..4 {
            packed |= (value as u128) << (32 * lane);
        }
        (packed as u64, (packed >> 64) as u64)
    };
    let pack_d = |value: u64| -> (u64, u64) { (value, value) };
    let enc_sve_fsqrt = |size: u32| -> u32 {
        (0x65 << 24) | (size << 22) | (0b001101 << 16) | (0b101 << 13) | (RN << 5) | RD
    };
    let mut batch = Vec::new();

    for &(label, fp_type, bits) in &[
        ("scalar_h", 0b11, 0x8001u64),
        ("scalar_s", 0b00, 0x8000_0001u64),
        ("scalar_d", 0b01, 0x8000_0000_0000_0001u64),
    ] {
        let mut st = ArmState::zeroed();
        st.fpcr = FPCR_AH;
        st.set_vreg(RN as usize, bits, 0);
        batch.push((
            format!("{label}_fsqrt_ah_negative_subnormal"),
            enc_fp1(fp_type, 0b00011),
            st,
        ));
    }

    for &(label, insn, lo, hi) in &[
        {
            let (lo, hi) = pack_h(0x8001);
            ("simd_h", enc_fp16_2r(1, 1, 1, 0b11111), lo, hi)
        },
        {
            let (lo, hi) = pack_s(0x8000_0001);
            ("simd_s", enc_two_reg(1, 1, 0b10, 0b11111), lo, hi)
        },
        (
            "simd_d",
            enc_two_reg(1, 1, 0b11, 0b11111),
            pack_d(0x8000_0000_0000_0001).0,
            pack_d(0x8000_0000_0000_0001).1,
        ),
    ] {
        let mut st = ArmState::zeroed();
        st.fpcr = FPCR_AH;
        st.set_vreg(RN as usize, lo, hi);
        batch.push((format!("{label}_fsqrt_ah_invalid_subnormal"), insn, st));
    }

    for &(label, size, lo, hi) in &[
        {
            let (lo, hi) = pack_h(0x8001);
            ("sve_h", 1, lo, hi)
        },
        {
            let (lo, hi) = pack_s(0x8000_0001);
            ("sve_s", 2, lo, hi)
        },
        (
            "sve_d",
            3,
            pack_d(0x8000_0000_0000_0001).0,
            pack_d(0x8000_0000_0000_0001).1,
        ),
    ] {
        let mut st = ArmState::zeroed();
        st.fpcr = FPCR_AH;
        st.set_preg(0, 0xffff);
        st.set_vreg(RN as usize, lo, hi);
        batch.push((
            format!("{label}_fsqrt_ah_invalid_subnormal"),
            enc_sve_fsqrt(size),
            st,
        ));
    }

    run_batch("fpcr_ah_fsqrt_negative_subnormal_status", batch);
}

#[test]
fn diff_fpcr_ah_fsqrt_frsqrte_invalid_nan_sign() {
    const FPCR_AH: u64 = 1 << 1;

    let pack_h = |value: u16| -> (u64, u64) {
        let mut packed = 0u128;
        for lane in 0..8 {
            packed |= (value as u128) << (16 * lane);
        }
        (packed as u64, (packed >> 64) as u64)
    };
    let pack_s = |value: u32| -> (u64, u64) {
        let mut packed = 0u128;
        for lane in 0..4 {
            packed |= (value as u128) << (32 * lane);
        }
        (packed as u64, (packed >> 64) as u64)
    };
    let pack_d = |value: u64| -> (u64, u64) {
        let packed = (value as u128) | ((value as u128) << 64);
        (packed as u64, (packed >> 64) as u64)
    };
    let enc_sve_fsqrt = |size: u32| -> u32 {
        (0x65 << 24) | (size << 22) | (0b001101 << 16) | (0b101 << 13) | (RN << 5) | RD
    };

    let mut batch = Vec::new();

    for &(label, fp_type, bits) in &[
        ("h", 0b11, 0xbc00u64),
        ("s", 0b00, 0xbf80_0000u64),
        ("d", 0b01, 0xbff0_0000_0000_0000u64),
    ] {
        let mut st = ArmState::zeroed();
        st.fpcr = FPCR_AH;
        st.set_vreg(RN as usize, bits, 0);
        batch.push((
            format!("scalar_fsqrt_{label}_ah_invalid_nan_sign"),
            enc_fp1(fp_type, 0b00011),
            st,
        ));
    }

    for &(label, insn, bits) in &[
        ("h", enc_fp16_2r_scalar(1, 1, 0b11101), 0xbc00u64),
        ("s", enc_scalar_two_reg(1, 0b10, 0b11101), 0xbf80_0000u64),
        (
            "d",
            enc_scalar_two_reg(1, 0b11, 0b11101),
            0xbff0_0000_0000_0000u64,
        ),
    ] {
        let mut st = ArmState::zeroed();
        st.fpcr = FPCR_AH;
        st.set_vreg(RN as usize, bits, 0);
        batch.push((
            format!("scalar_frsqrte_{label}_ah_invalid_nan_sign"),
            insn,
            st,
        ));
    }

    for &(label, fsqrt, frsqrte, lo, hi) in &[
        {
            let (lo, hi) = pack_h(0xbc00);
            (
                "h",
                enc_fp16_2r(1, 1, 1, 0b11111),
                enc_fp16_2r(1, 1, 1, 0b11101),
                lo,
                hi,
            )
        },
        {
            let (lo, hi) = pack_s(0xbf80_0000);
            (
                "s",
                enc_two_reg(1, 1, 0b10, 0b11111),
                enc_two_reg(1, 1, 0b10, 0b11101),
                lo,
                hi,
            )
        },
        {
            let (lo, hi) = pack_d(0xbff0_0000_0000_0000);
            (
                "d",
                enc_two_reg(1, 1, 0b11, 0b11111),
                enc_two_reg(1, 1, 0b11, 0b11101),
                lo,
                hi,
            )
        },
    ] {
        for &(opname, insn) in &[("fsqrt", fsqrt), ("frsqrte", frsqrte)] {
            let mut st = ArmState::zeroed();
            st.fpcr = FPCR_AH;
            st.set_vreg(RN as usize, lo, hi);
            batch.push((
                format!("simd_{opname}_{label}_ah_invalid_nan_sign"),
                insn,
                st,
            ));
        }
    }

    for &(label, size, lo, hi) in &[
        {
            let (lo, hi) = pack_h(0xbc00);
            ("h", 1, lo, hi)
        },
        {
            let (lo, hi) = pack_s(0xbf80_0000);
            ("s", 2, lo, hi)
        },
        {
            let (lo, hi) = pack_d(0xbff0_0000_0000_0000);
            ("d", 3, lo, hi)
        },
    ] {
        for &(opname, insn) in &[
            ("fsqrt", enc_sve_fsqrt(size)),
            ("frsqrte", enc_sve_frecpe(size, 1)),
        ] {
            let mut st = ArmState::zeroed();
            st.fpcr = FPCR_AH;
            st.set_preg(0, 0xffff);
            st.set_vreg(RN as usize, lo, hi);
            batch.push((
                format!("sve_{opname}_{label}_ah_invalid_nan_sign"),
                insn,
                st,
            ));
        }
    }

    run_batch("fpcr_ah_fsqrt_frsqrte_invalid_nan_sign", batch);
}

