/// CAS: `size 0010001 L 1 Rs o0 11111 Rn Rt`. Rs=x2 (compare/old), Rn=x1, Rt=x0 (new).
fn enc_cas_regs_rt2(size: u32, l: u32, o0: u32, rs: u32, rt2: u32, rt: u32, rn: u32) -> u32 {
    (size << 30)
        | (0b001000 << 24)
        | (1 << 23)
        | (l << 22)
        | (1 << 21)
        | ((rs & 0x1F) << 16)
        | (o0 << 15)
        | ((rt2 & 0x1F) << 10)
        | ((rn & 0x1F) << 5)
        | (rt & 0x1F)
}

fn enc_cas_regs(size: u32, l: u32, o0: u32, rs: u32, rt: u32, rn: u32) -> u32 {
    enc_cas_regs_rt2(size, l, o0, rs, 31, rt, rn)
}

fn enc_cas(size: u32, l: u32, o0: u32) -> u32 {
    enc_cas_regs(size, l, o0, 2, RD, RN)
}

#[test]
fn diff_mem_cas() {
    let mut cases: Vec<(String, u32)> = Vec::new();
    for size in 0..4u32 {
        for l in 0..2 {
            for o0 in 0..2 {
                cases.push((format!("cas sz{size} l{l} o0{o0}"), enc_cas(size, l, o0)));
            }
        }
    }
    let mut rng = Rng::new(0x1_0006);
    let mut batch: Vec<(String, u32, ArmState)> = Vec::new();
    for (label, insn) in &cases {
        for k in 0..12 {
            let mut st = mem_input(&mut rng);
            // Half the cases: make x2 (the comparison value) equal the memory at
            // SCRATCH_BASE so the swap succeeds; otherwise it (usually) fails.
            if k % 2 == 0 {
                st.x[2] = st.scratch[8]; // SCRATCH_BASE = SCRATCH_ADDR + 64 -> scratch[8]
            }
            batch.push((label.clone(), *insn, st));
        }
    }
    run_batch("mem_cas", batch);
}

#[test]
fn diff_mem_cas_edges() {
    let cases: &[(u64, u64, u64, &str)] = &[
        (0, 0, u64::MAX, "success_zero"),
        (u64::MAX, u64::MAX, 0, "success_ones"),
        (
            0x7fff_ffff_ffff_fffe,
            0x8000_0000_0000_0001,
            0x55aa_55aa_33cc_33cc,
            "fail_sign_bits",
        ),
        (
            0x1122_3344_5566_7788,
            0x8877_6655_4433_2211,
            0xf0f0_0f0f_aa55_55aa,
            "fail_byte_ramp",
        ),
    ];
    let mut batch = Vec::new();

    for size in 0..4u32 {
        for l in 0..2 {
            for o0 in 0..2 {
                for &(mem, compare, new_value, label) in cases {
                    let mut st = ArmState::zeroed();
                    st.x[1] = SCRATCH_BASE;
                    st.x[2] = compare;
                    st.x[RD as usize] = new_value;
                    st.scratch.fill(0xfeed_face_dead_beef);
                    st.scratch[8] = mem;
                    st.scratch[9] = !mem;
                    batch.push((
                        format!("cas_sz{size}_l{l}_o0{o0}_{label}"),
                        enc_cas(size, l, o0),
                        st,
                    ));
                }
            }
        }
    }

    run_batch("mem_cas_edges", batch);
}

