/// CASP: `0 sz 001000 0 L 1 Rs o0 11111 Rn Rt`. Rs=x2:x3 (compare/old),
/// Rt=x4:x5 (new), Rn=x1. sz selects 32-bit (0) or 64-bit (1) element pair.
fn enc_casp_regs_rt2(sz: u32, l: u32, o0: u32, rs: u32, rt2: u32, rt: u32, rn: u32) -> u32 {
    (sz << 30)
        | (0b001000 << 24)
        | (l << 22)
        | (1 << 21)
        | ((rs & 0x1F) << 16)
        | (o0 << 15)
        | ((rt2 & 0x1F) << 10)
        | ((rn & 0x1F) << 5)
        | (rt & 0x1F)
}

fn enc_casp_regs(sz: u32, l: u32, o0: u32, rs: u32, rt: u32, rn: u32) -> u32 {
    enc_casp_regs_rt2(sz, l, o0, rs, 31, rt, rn)
}

fn enc_casp(sz: u32, l: u32, o0: u32) -> u32 {
    enc_casp_regs(sz, l, o0, 2, 4, RN)
}

#[test]
fn diff_mem_casp() {
    let mut cases: Vec<(String, u32, u32)> = Vec::new();
    for sz in 0..2u32 {
        for l in 0..2 {
            for o0 in 0..2 {
                cases.push((format!("casp sz{sz} l{l} o0{o0}"), enc_casp(sz, l, o0), sz));
            }
        }
    }
    let mut rng = Rng::new(0x1_000E);
    let mut batch: Vec<(String, u32, ArmState)> = Vec::new();
    for (label, insn, sz) in &cases {
        for k in 0..12 {
            let mut st = mem_input(&mut rng);
            // Half the cases: make the compare pair (x2:x3) equal the memory pair
            // at SCRATCH_BASE (scratch[8]/scratch[9]) so the swap succeeds.
            if k % 2 == 0 {
                if *sz == 0 {
                    st.x[2] = st.scratch[8] & 0xFFFF_FFFF;
                    st.x[3] = st.scratch[8] >> 32;
                } else {
                    st.x[2] = st.scratch[8];
                    st.x[3] = st.scratch[9];
                }
            }
            batch.push((label.clone(), *insn, st));
        }
    }
    run_batch("mem_casp", batch);
}

#[test]
fn diff_mem_casp_edges() {
    let cases: &[(&str, bool, u64, u64, u64, u64)] = &[
        ("success_zero", true, 0, 0, u64::MAX, u64::MAX),
        ("success_ones", true, u64::MAX, u64::MAX, 0, 0),
        (
            "fail_sign_bits",
            false,
            0x7fff_ffff_ffff_fffe,
            0x8000_0000_0000_0001,
            0x55aa_55aa_33cc_33cc,
            0xaa55_aa55_cc33_cc33,
        ),
        (
            "fail_byte_ramp",
            false,
            0x1122_3344_5566_7788,
            0x8877_6655_4433_2211,
            0xf0f0_0f0f_aa55_55aa,
            0x0f0f_f0f0_55aa_aa55,
        ),
    ];
    let mut batch = Vec::new();

    for sz in 0..2u32 {
        for l in 0..2 {
            for o0 in 0..2 {
                for &(label, success, mem0, mem1, new0, new1) in cases {
                    let mut st = ArmState::zeroed();
                    st.x[RN as usize] = SCRATCH_BASE;
                    st.x[4] = new0;
                    st.x[5] = new1;
                    st.scratch.fill(0xfeed_face_dead_beef);
                    st.scratch[8] = mem0;
                    st.scratch[9] = mem1;

                    if sz == 0 {
                        st.x[2] = mem0 & 0xffff_ffff;
                        st.x[3] = mem0 >> 32;
                        if success {
                            st.x[2] |= 0xaaaa_aaaa_0000_0000;
                            st.x[3] |= 0x5555_5555_0000_0000;
                            st.x[4] |= 0x1111_1111_0000_0000;
                            st.x[5] |= 0xeeee_eeee_0000_0000;
                        } else {
                            st.x[2] ^= 1;
                        }
                    } else if success {
                        st.x[2] = mem0;
                        st.x[3] = mem1;
                    } else {
                        st.x[2] = mem0 ^ 1;
                        st.x[3] = mem1;
                    }

                    batch.push((
                        format!("casp_sz{sz}_l{l}_o0{o0}_{label}"),
                        enc_casp(sz, l, o0),
                        st,
                    ));
                }
            }
        }
    }

    run_batch("mem_casp_edges", batch);
}

