#[test]
fn diff_generated_memory_atomic_edges() {
    let patterns: &[(&str, u64, u64)] = &[
        ("zero", 0, 0),
        ("ones", u64::MAX, u64::MAX),
        ("sign_bits", 0x8000_0000_0000_0001, 0x7fff_ffff_ffff_fffe),
        ("alternating", 0x55aa_55aa_33cc_33cc, 0xaa55_aa55_cc33_cc33),
    ];
    let mut batch = Vec::new();

    for (label, insn) in generated_memory_atomic_cases() {
        let rs = ((insn >> 16) & 0x1f) as usize;
        let rn = ((insn >> 5) & 0x1f) as usize;
        for &(pattern, src, mem) in patterns {
            let mut st = ArmState::zeroed();
            for reg in 0..31 {
                st.x[reg] = SCRATCH_BASE + 64;
            }
            st.sp = SCRATCH_BASE + 64;
            st.scratch.fill(0xfeed_face_dead_beef);
            st.scratch[16] = mem;
            st.scratch[17] = !mem;

            if rs < 31 {
                st.x[rs] = src;
            }
            if rn < 31 {
                st.x[rn] = SCRATCH_BASE + 64;
            } else {
                st.sp = SCRATCH_BASE + 64;
            }

            batch.push((format!("{label}_{pattern}"), insn, st));
        }
    }

    run_batch("generated_memory_atomic_edges", batch);
}

/// AdvSIMD load/store multiple structures: `0 Q 0011 0 0 post L rm opcode size Rn Rt`.
fn enc_ldst_struct_regs(
    q: u32,
    post: u32,
    l: u32,
    rm: u32,
    opcode: u32,
    size: u32,
    rt: u32,
    rn: u32,
) -> u32 {
    (q << 30)
        | (0b001100 << 24)
        | (post << 23)
        | (l << 22)
        | (rm << 16)
        | (opcode << 12)
        | (size << 10)
        | ((rn & 0x1F) << 5)
        | (rt & 0x1F)
}

fn enc_ldst_struct(q: u32, post: u32, l: u32, rm: u32, opcode: u32, size: u32) -> u32 {
    enc_ldst_struct_regs(q, post, l, rm, opcode, size, RD, RN)
}

#[test]
fn diff_mem_ldst_struct() {
    // (opcode, name) -- LD1 x1/x2/x3/x4, LD2, LD3, LD4.
    let ops: &[(u32, &str)] = &[
        (0b0111, "ld1x1"),
        (0b1010, "ld1x2"),
        (0b0110, "ld1x3"),
        (0b0010, "ld1x4"),
        (0b1000, "ld2"),
        (0b0100, "ld3"),
        (0b0000, "ld4"),
    ];
    let mut cases: Vec<(String, u32)> = Vec::new();
    for &(opcode, name) in ops {
        for size in 0..4u32 {
            for q in 0..2 {
                for l in 0..2 {
                    let op = if l == 1 {
                        name.to_string()
                    } else {
                        name.replace("ld", "st")
                    };
                    // no-offset
                    cases.push((
                        format!("{op} sz{size} q{q} noff"),
                        enc_ldst_struct(q, 0, l, 0, opcode, size),
                    ));
                    // post-index, immediate increment (Rm == 31)
                    cases.push((
                        format!("{op} sz{size} q{q} post"),
                        enc_ldst_struct(q, 1, l, 31, opcode, size),
                    ));
                }
            }
        }
    }
    let mut rng = Rng::new(0x1_0003);
    let mut batch: Vec<(String, u32, ArmState)> = Vec::new();
    for (label, insn) in &cases {
        for _ in 0..6 {
            batch.push((label.clone(), *insn, mem_input(&mut rng)));
        }
    }
    run_batch("mem_ldst_struct", batch);
}

