/// Load/store pair: `opc 101 V 0 mode L imm7 Rt2 Rn Rt`.
fn enc_ldp_regs(opc: u32, v: u32, mode: u32, l: u32, imm7: u32, rt: u32, rt2: u32, rn: u32) -> u32 {
    (opc << 30)
        | (0b101 << 27)
        | (v << 26)
        | (mode << 23)
        | (l << 22)
        | ((imm7 & 0x7F) << 15)
        | ((rt2 & 0x1F) << 10)
        | ((rn & 0x1F) << 5)
        | (rt & 0x1F)
}

/// Load/store pair with the standard test registers: Rt=x0, Rt2=x2, Rn=x1.
fn enc_ldp(opc: u32, v: u32, mode: u32, l: u32, imm7: u32) -> u32 {
    enc_ldp_regs(opc, v, mode, l, imm7, RD, RM, RN)
}

#[test]
fn diff_mem_ldp_stp() {
    // (opc, V, name) for GPR (32/LDPSW/64) and SIMD (S/D/Q).
    let kinds: &[(u32, u32, bool, &str)] = &[
        (0b00, 0, false, "stp_w"),
        (0b10, 0, false, "stp_x"),
        (0b00, 1, false, "stp_s"),
        (0b01, 1, false, "stp_d"),
        (0b10, 1, false, "stp_q"),
        (0b01, 0, true, "ldpsw"), // load-only
    ];
    let imm7_cases = [0u32, 1, 2, 0x7f]; // 0x7f encodes -1.
    let imm7_label = |imm7: u32| -> i32 {
        if imm7 >= 64 {
            imm7 as i32 - 128
        } else {
            imm7 as i32
        }
    };
    let mut cases: Vec<(String, u32)> = Vec::new();
    for &(opc, v, load_only, name) in kinds {
        // modes: 10=signed offset, 01=post-index, 11=pre-index
        for &mode in &[0b10u32, 0b01, 0b11] {
            for &l in if load_only {
                &[1u32][..]
            } else {
                &[0u32, 1][..]
            } {
                for &imm7 in &imm7_cases {
                    let nm = if l == 1 && !load_only {
                        name.replace("stp", "ldp")
                    } else {
                        name.to_string()
                    };
                    cases.push((
                        format!("{nm} m{mode} #{}", imm7_label(imm7)),
                        enc_ldp(opc, v, mode, l, imm7),
                    ));
                }
            }
        }
    }
    for &mode in &[0b10u32, 0b01, 0b11] {
        for &(l, name) in &[(0u32, "sttp x"), (1, "ldtp x")] {
            for &imm7 in &imm7_cases {
                cases.push((
                    format!("{name} m{mode} #{}", imm7_label(imm7)),
                    enc_ldp(0b11, 0, mode, l, imm7),
                ));
            }
        }
    }
    let no_allocate_kinds: &[(u32, u32, &str)] = &[
        (0b00, 0, "stnp_w"),
        (0b10, 0, "stnp_x"),
        (0b00, 1, "ldnp_w"),
        (0b10, 1, "ldnp_x"),
        (0b11, 0, "sttnp x"),
        (0b11, 1, "ldtnp x"),
    ];
    for &(opc, l, name) in no_allocate_kinds {
        for &imm7 in &imm7_cases {
            cases.push((
                format!("{name} #{}", imm7_label(imm7)),
                enc_ldp(opc, 0, 0b00, l, imm7),
            ));
        }
    }
    for &imm7 in &imm7_cases {
        cases.push((
            format!("ldpsw_m0_undef #{}", imm7_label(imm7)),
            enc_ldp(0b01, 0, 0b00, 1, imm7),
        ));
    }
    let mut rng = Rng::new(0x1_0002);
    let mut batch: Vec<(String, u32, ArmState)> = Vec::new();
    for (label, insn) in &cases {
        for _ in 0..8 {
            batch.push((label.clone(), *insn, mem_input(&mut rng)));
        }
    }
    run_batch("mem_ldp_stp", batch);
}

#[test]
fn diff_mem_ldp_stp_encoding_legality_grid() {
    fn pair_label(opc: u32, v: u32, mode: u32, l: u32) -> String {
        match (v, opc, mode, l) {
            (0, 0b00, _, 0) => "stp_w".into(),
            (0, 0b00, _, 1) => "ldp_w".into(),
            (0, 0b10, _, 0) => "stp_x".into(),
            (0, 0b10, _, 1) => "ldp_x".into(),
            (0, 0b01, 0b00, 0) => "stgp_noalloc_undef".into(),
            (0, 0b01, 0b00, 1) => "ldpsw_noalloc_undef".into(),
            (0, 0b01, _, 0) => "stgp".into(),
            (0, 0b01, _, 1) => "ldpsw".into(),
            (0, 0b11, 0b00, 0) => "sttnp".into(),
            (0, 0b11, 0b00, 1) => "ldtnp".into(),
            (0, 0b11, _, 0) => "sttp".into(),
            (0, 0b11, _, 1) => "ldtp".into(),
            (1, 0b00, _, 0) => "stp_s".into(),
            (1, 0b00, _, 1) => "ldp_s".into(),
            (1, 0b01, _, 0) => "stp_d".into(),
            (1, 0b01, _, 1) => "ldp_d".into(),
            (1, 0b10, _, 0) => "stp_q".into(),
            (1, 0b10, _, 1) => "ldp_q".into(),
            (1, 0b11, _, _) => "pair_simd_opc3_undef".into(),
            _ => unreachable!(),
        }
    }

    let mut rng = Rng::new(0x1_0179);
    let mut batch = Vec::new();

    for v in 0..=1u32 {
        for opc in 0..=3u32 {
            for mode in 0..=3u32 {
                for l in 0..=1u32 {
                    let label = pair_label(opc, v, mode, l);
                    let mut st = mem_input(&mut rng);
                    st.x[RN as usize] = SCRATCH_BASE + 64;
                    st.x[RD as usize] = rng.next();
                    st.x[RM as usize] = rng.next();
                    st.set_vreg(RD as usize, rng.next(), rng.next());
                    st.set_vreg(RM as usize, rng.next(), rng.next());
                    batch.push((
                        format!("{label}_opc{opc}_v{v}_mode{mode}_l{l}"),
                        enc_ldp(opc, v, mode, l, 0),
                        st,
                    ));
                }
            }
        }
    }

    run_batch_el0_legality("mem_ldp_stp_encoding_legality_grid", batch);
}

#[test]
fn diff_mem_mte_tag_memory_edges() {
    fn tag_mem(opc: u32, imm9: i32, op2: u32, rn: u32, rt: u32) -> u32 {
        (0xD9 << 24)
            | ((opc & 0x3) << 22)
            | (1 << 21)
            | (((imm9 as u32) & 0x1ff) << 12)
            | ((op2 & 0x3) << 10)
            | ((rn & 0x1f) << 5)
            | (rt & 0x1f)
    }

    fn state(base_reg: u32, use_sp: bool) -> ArmState {
        let mut st = ArmState::zeroed();
        st.scratch.fill(0xfeed_face_dead_beef);
        for (i, word) in st.scratch.iter_mut().enumerate() {
            *word = 0x1111_0000_0000_0000 | i as u64;
        }
        let base = SCRATCH_BASE + 64;
        if use_sp {
            st.sp = base;
        } else {
            st.x[base_reg as usize] = base;
        }
        st.x[RD as usize] = 0x0a00_0000_1234_5678;
        st.x[RM as usize] = 0x0b00_0000_8765_4321;
        st
    }

    let mut batch = Vec::new();
    for &(name, insn, use_sp) in &[
        ("ldg signed_neg", tag_mem(0b01, -1, 0b00, RN, RD), false),
        ("ldg sp_signed_pos", tag_mem(0b01, 1, 0b00, 31, RD), true),
        ("stg post_neg", tag_mem(0b00, -1, 0b01, RN, RD), false),
        ("stzg signed_zero", tag_mem(0b01, 0, 0b10, RN, RD), false),
        ("st2g pre_pos", tag_mem(0b10, 1, 0b11, RN, RD), false),
        ("stz2g sp_post_neg", tag_mem(0b11, -1, 0b01, 31, RD), true),
        (
            "stgp signed_neg",
            enc_ldp_regs(0b01, 0, 0b10, 0, 0x7f, RD, RM, RN),
            false,
        ),
        (
            "stgp sp_pre_pos",
            enc_ldp_regs(0b01, 0, 0b11, 0, 1, RD, RM, 31),
            true,
        ),
        (
            "stgp noalloc_undef",
            enc_ldp_regs(0b01, 0, 0b00, 0, 0, RD, RM, RN),
            false,
        ),
    ] {
        batch.push((name.to_string(), insn, state(RN, use_sp)));
    }

    run_batch("mem_mte_tag_memory_edges", batch);
}

#[test]
fn diff_mem_mte_tag_array_flat_memory_edges() {
    fn tag_array(load: bool, rn: u32, rt: u32) -> u32 {
        (0xD9 << 24)
            | ((if load { 0b11 } else { 0b10 }) << 22)
            | (1 << 21)
            | ((rn & 0x1f) << 5)
            | (rt & 0x1f)
    }

    let mut set = ArmState::zeroed();
    set.x[RN as usize] = SCRATCH_BASE + 16;
    set.x[RD as usize] = 0xfedc_ba98_7654_3210;
    set.scratch.fill(0xaaaa_5555_dead_beef);
    let out = run_rax(tag_array(false, RN, RD), &set).expect("MCSETTAGARRAY executes");
    assert_eq!(
        out.x[RN as usize],
        SCRATCH_BASE + 32,
        "MCSETTAGARRAY writes back one flat tag granule"
    );
    assert_eq!(
        out.x[RD as usize], set.x[RD as usize],
        "MCSETTAGARRAY leaves the source data register unchanged"
    );
    assert_eq!(
        out.scratch, set.scratch,
        "MCSETTAGARRAY has no data-memory side effect without tag storage"
    );

    let mut get = ArmState::zeroed();
    get.x[RN as usize] = SCRATCH_BASE + 32;
    get.x[RD as usize] = 0x1234_5678_9abc_def0;
    let out = run_rax(tag_array(true, RN, RD), &get).expect("MCGETTAGARRAY executes");
    assert_eq!(
        out.x[RD as usize], 0,
        "MCGETTAGARRAY reads zero tag data from flat memory"
    );
    assert_eq!(
        out.x[RN as usize],
        SCRATCH_BASE + 48,
        "MCGETTAGARRAY writes back one flat tag granule"
    );

    let mut overlap = ArmState::zeroed();
    overlap.x[RN as usize] = SCRATCH_BASE + 48;
    let out = run_rax(tag_array(true, RN, RN), &overlap).expect("overlap MCGETTAGARRAY executes");
    assert_eq!(
        out.x[RN as usize], 0,
        "overlap MCGETTAGARRAY chooses writeback suppression"
    );
}

#[test]
fn diff_mte_runtime_supported_legality_edges() {
    fn addsub_tags(op: u32, rn: u32, rd: u32) -> u32 {
        (1 << 31) | (op << 30) | (0b100011 << 23) | (2 << 16) | (7 << 10) | (rn << 5) | rd
    }

    fn dp2_mte(s: u32, opcode: u32) -> u32 {
        (1 << 31) | (s << 29) | (0b0011010110 << 21) | (RM << 16) | (opcode << 10) | (RN << 5) | RD
    }

    fn tag_mem(opc: u32, op2: u32) -> u32 {
        (0xD9 << 24) | ((opc & 0x3) << 22) | (1 << 21) | ((op2 & 0x3) << 10) | (RN << 5) | RD
    }

    let oracle = match oracle_path() {
        Some(p) => p,
        None => {
            eprintln!(
                "[arm_diff] mte_runtime_supported_legality_edges: oracle unavailable -> skipping"
            );
            return;
        }
    };
    let mut rng = Rng::new(0x1_017c);
    let mut probe = gen_input(&mut rng);
    probe.x[RN as usize] = 0x0500_0000_0000_1000;
    let probe_cases = vec![(addsub_tags(0, RN, RD), NOP, probe)];
    let probe_out = match run_oracle(&oracle, &probe_cases) {
        Some(o) => o,
        None => {
            eprintln!(
                "[arm_diff] mte_runtime_supported_legality_edges: oracle probe failed -> skipping"
            );
            return;
        }
    };
    if probe_out[0].trapped != 0 {
        eprintln!(
            "[arm_diff] mte_runtime_supported_legality_edges: native MTE instructions trap -> skipping"
        );
        return;
    }

    let cases: &[(&str, u32)] = &[
        ("mte_runtime_add_tag", addsub_tags(0, RN, RD)),
        ("mte_runtime_sub_tag", addsub_tags(1, RN, RD)),
        ("mte_runtime_subp", dp2_mte(0, 0b000000)),
        ("mte_runtime_subps", dp2_mte(1, 0b000000)),
        ("mte_runtime_irg", dp2_mte(0, 0b000100)),
        ("mte_runtime_gmi", dp2_mte(0, 0b000101)),
        ("mte_runtime_ldg", tag_mem(0b01, 0b00)),
        ("mte_runtime_stg", tag_mem(0b00, 0b10)),
        (
            "mte_runtime_stgp",
            enc_ldp_regs(0b01, 0, 0b10, 0, 0, RD, RM, RN),
        ),
        (
            "mte_runtime_stgp_noalloc",
            enc_ldp_regs(0b01, 0, 0b00, 0, 0, RD, RM, RN),
        ),
    ];

    let mut batch = Vec::new();
    for (label, insn) in cases {
        for _ in 0..4 {
            let mut st = mem_input(&mut rng);
            st.x[RN as usize] = SCRATCH_BASE + 64;
            st.x[RM as usize] = rng.next();
            st.x[RD as usize] = rng.next();
            batch.push(((*label).to_string(), *insn, st));
        }
    }

    run_batch_el0_legality("mte_runtime_supported_legality_edges", batch);
}

