#[test]
fn diff_mem_ldp_stp_sp_alignment_edges() {
    let mut rng = Rng::new(0x1_016e);
    let mut batch = Vec::new();

    for &(opc, v, l, name) in &[
        (0b00u32, 0u32, 1u32, "ldp_w"),
        (0b10, 0, 1, "ldp_x"),
        (0b01, 0, 1, "ldpsw"),
        (0b00, 0, 0, "stp_w"),
        (0b10, 0, 0, "stp_x"),
        (0b00, 1, 1, "ldp_s"),
        (0b01, 1, 1, "ldp_d"),
        (0b10, 1, 1, "ldp_q"),
        (0b00, 1, 0, "stp_s"),
        (0b01, 1, 0, "stp_d"),
        (0b10, 1, 0, "stp_q"),
    ] {
        for mode in [0b10u32, 0b01, 0b11] {
            for offset in [1u64, 8] {
                let mut st = mem_input(&mut rng);
                st.sp = SCRATCH_BASE + offset;
                st.x[RD as usize] = rng.next();
                st.x[RM as usize] = rng.next();
                st.set_vreg(RD as usize, rng.next(), rng.next());
                st.set_vreg(RM as usize, rng.next(), rng.next());
                batch.push((
                    format!("{name}_sp_unaligned_m{mode}_off{offset}"),
                    enc_ldp_regs(opc, v, mode, l, 0, RD, RM, 31),
                    st,
                ));
            }
        }
    }

    run_batch("mem_ldp_stp_sp_alignment_edges", batch);
}

/// Load/store register, unsigned immediate offset:
/// `size 111 V 01 opc imm12 Rn Rt`. Rn=base (x1), Rt=Rd (x0/v0).
fn enc_ldst_uimm_regs(size: u32, v: u32, opc: u32, imm12: u32, rt: u32, rn: u32) -> u32 {
    (size << 30)
        | (0b111 << 27)
        | (v << 26)
        | (0b01 << 24)
        | (opc << 22)
        | (imm12 << 10)
        | ((rn & 0x1F) << 5)
        | (rt & 0x1F)
}

fn enc_ldst_uimm(size: u32, v: u32, opc: u32, imm12: u32) -> u32 {
    enc_ldst_uimm_regs(size, v, opc, imm12, RD, RN)
}

/// Load/store register, signed immediate offset:
/// `size 111 V 00 opc 0 imm9 mode Rn Rt`. Rn=base (x1), Rt=Rd (x0/v0).
fn enc_ldst_simm_regs(size: u32, v: u32, opc: u32, mode: u32, imm9: i32, rt: u32, rn: u32) -> u32 {
    (size << 30)
        | (0b111 << 27)
        | (v << 26)
        | (opc << 22)
        | (((imm9 as u32) & 0x1FF) << 12)
        | (mode << 10)
        | ((rn & 0x1F) << 5)
        | (rt & 0x1F)
}

fn enc_ldst_simm(size: u32, v: u32, opc: u32, mode: u32, imm9: i32) -> u32 {
    enc_ldst_simm_regs(size, v, opc, mode, imm9, RD, RN)
}

/// Load/store register offset: `size 111000 opc 1 Rm option S 10 Rn Rt`.
fn enc_ldst_reg_regs(size: u32, opc: u32, rm: u32, option: u32, s: u32, rt: u32, rn: u32) -> u32 {
    (size << 30)
        | (0b111 << 27)
        | (opc << 22)
        | (1 << 21)
        | (rm << 16)
        | (option << 13)
        | (s << 12)
        | (0b10 << 10)
        | ((rn & 0x1F) << 5)
        | (rt & 0x1F)
}

fn enc_ldst_reg(size: u32, opc: u32, rm: u32, option: u32, s: u32) -> u32 {
    enc_ldst_reg_regs(size, opc, rm, option, s, RD, RN)
}

fn enc_ldst_reg_simdfp(size: u32, opc: u32, rm: u32, option: u32, s: u32) -> u32 {
    enc_ldst_reg(size, opc, rm, option, s) | (1 << 26)
}

fn enc_ldst_reg_simdfp_regs(
    size: u32,
    opc: u32,
    rm: u32,
    option: u32,
    s: u32,
    rt: u32,
    rn: u32,
) -> u32 {
    enc_ldst_reg_regs(size, opc, rm, option, s, rt, rn) | (1 << 26)
}

/// PRFM register offset: `11 111000 0 0 1 Rm opc=10 option S 10 Rn Rt`.
fn enc_prfm_reg(rt: u32, rm: u32, option: u32, s: u32) -> u32 {
    (0b11 << 30)
        | (0b111 << 27)
        | (0b10 << 22)
        | (1 << 21)
        | (rm << 16)
        | (option << 13)
        | (s << 12)
        | (0b10 << 10)
        | (RN << 5)
        | (rt & 0x1f)
}

#[test]
fn diff_mem_ldst_single_register_encoding_legality_grid() {
    let mut rng = Rng::new(0x1_017b);
    let mut batch = Vec::new();

    for v in 0..=1u32 {
        for size in 0..=3u32 {
            for opc in 0..=3u32 {
                let mut push = |label: String, insn: u32| {
                    let mut st = mem_input(&mut rng);
                    st.x[RN as usize] = SCRATCH_BASE + 64;
                    st.x[RM as usize] = 8;
                    st.x[RD as usize] = rng.next();
                    st.set_vreg(RD as usize, rng.next(), rng.next());
                    batch.push((label, insn, st));
                };

                push(
                    format!("ldst_single_uimm_v{v}_size{size}_opc{opc}"),
                    enc_ldst_uimm_regs(size, v, opc, 0, RD, RN),
                );

                for mode in 0..=3u32 {
                    push(
                        format!("ldst_single_simm_v{v}_size{size}_opc{opc}_mode{mode}"),
                        enc_ldst_simm_regs(size, v, opc, mode, 0, RD, RN),
                    );
                }

                let insn = if v == 0 {
                    enc_ldst_reg_regs(size, opc, RM, 0b011, 0, RD, RN)
                } else {
                    enc_ldst_reg_simdfp_regs(size, opc, RM, 0b011, 0, RD, RN)
                };
                push(format!("ldst_single_reg_v{v}_size{size}_opc{opc}"), insn);
            }
        }
    }

    run_batch_el0_legality("mem_ldst_single_register_encoding_legality_grid", batch);
}

/// Build a memory-test input: base register x1 -> SCRATCH_BASE, random scratch
/// and operand registers.
fn mem_input(rng: &mut Rng) -> ArmState {
    let mut st = gen_input(rng);
    st.x[1] = SCRATCH_BASE; // Rn base pointer
    for w in st.scratch.iter_mut() {
        *w = rng.interesting();
    }
    st
}

#[test]
fn diff_mem_ldst_imm() {
    // (size, V, opc, name)
    let ops: &[(u32, u32, u32, &str)] = &[
        (3, 0, 0, "str_x"),
        (3, 0, 1, "ldr_x"),
        (2, 0, 0, "str_w"),
        (2, 0, 1, "ldr_w"),
        (0, 1, 0, "str_b"),
        (0, 1, 1, "ldr_b"),
        (1, 1, 0, "str_h"),
        (1, 1, 1, "ldr_h"),
        (2, 1, 0, "str_s"),
        (2, 1, 1, "ldr_s"),
        (3, 1, 0, "str_d"),
        (3, 1, 1, "ldr_d"),
        (0, 1, 2, "str_q"),
        (0, 1, 3, "ldr_q"),
        // sign-extending loads (GPR): opc=10 -> LDRSx to X, opc=11 -> to W
        (0, 0, 2, "ldrsb_x"),
        (1, 0, 2, "ldrsh_x"),
        (2, 0, 2, "ldrsw_x"),
        (0, 0, 1, "ldrb_w"),
        (1, 0, 1, "ldrh_w"),
    ];
    let mut cases: Vec<(String, u32)> = Vec::new();
    for &(size, v, opc, name) in ops {
        for imm12 in 0..4u32 {
            cases.push((
                format!("{name} #{imm12}"),
                enc_ldst_uimm(size, v, opc, imm12),
            ));
        }
    }
    // Custom batch with memory inputs.
    let mut rng = Rng::new(0x1_0001);
    let mut batch: Vec<(String, u32, ArmState)> = Vec::new();
    for (label, insn) in &cases {
        for _ in 0..8 {
            batch.push((label.clone(), *insn, mem_input(&mut rng)));
        }
    }
    run_batch("mem_ldst_imm", batch);
}

#[test]
fn diff_mem_ldst_imm_edges() {
    let ops: &[(u32, u32, u32, &str)] = &[
        (3, 0, 0, "str_x"),
        (3, 0, 1, "ldr_x"),
        (2, 0, 0, "str_w"),
        (2, 0, 1, "ldr_w"),
        (0, 1, 0, "str_b"),
        (0, 1, 1, "ldr_b"),
        (1, 1, 0, "str_h"),
        (1, 1, 1, "ldr_h"),
        (2, 1, 0, "str_s"),
        (2, 1, 1, "ldr_s"),
        (3, 1, 0, "str_d"),
        (3, 1, 1, "ldr_d"),
        (0, 1, 2, "str_q"),
        (0, 1, 3, "ldr_q"),
        (0, 0, 2, "ldrsb_x"),
        (1, 0, 2, "ldrsh_x"),
        (2, 0, 2, "ldrsw_x"),
        (0, 0, 1, "ldrb_w"),
        (1, 0, 1, "ldrh_w"),
    ];
    let patterns: &[(&str, [u64; 4], u64, (u64, u64))] = &[
        ("zero", [0, 0, 0, 0], 0, (0, 0)),
        (
            "ones",
            [u64::MAX, u64::MAX, u64::MAX, u64::MAX],
            u64::MAX,
            (u64::MAX, u64::MAX),
        ),
        (
            "byte_ramp",
            [
                0x8877_6655_4433_2211,
                0x1122_3344_5566_7788,
                0xf0f0_0f0f_aa55_55aa,
                0x0f0f_f0f0_55aa_aa55,
            ],
            0x0123_4567_89ab_cdef,
            (0x55aa_55aa_33cc_33cc, 0xaa55_aa55_cc33_cc33),
        ),
    ];
    let mut batch = Vec::new();

    for &(size, v, opc, name) in ops {
        for imm12 in [0u32, 1] {
            for &(pattern, mem, x_src, v_src) in patterns {
                let mut st = ArmState::zeroed();
                st.x[RN as usize] = SCRATCH_BASE;
                st.x[RD as usize] = x_src;
                st.set_vreg(RD as usize, v_src.0, v_src.1);
                st.scratch.fill(0xfeed_face_dead_beef);
                for (offset, word) in mem.iter().enumerate() {
                    st.scratch[8 + offset] = *word;
                }
                batch.push((
                    format!("{name}_imm{imm12}_{pattern}"),
                    enc_ldst_uimm(size, v, opc, imm12),
                    st,
                ));
            }
        }
    }

    run_batch("mem_ldst_imm_edges", batch);
}

