#[test]
fn diff_fp_scalar_frintts_fpsr_inexact() {
    let mut batch: Vec<(String, u32, ArmState)> = Vec::new();
    for &ft in &[0u32, 1] {
        for opcode in 0b10000..=0b10011 {
            let mut st = ArmState::zeroed();
            if ft == 0 {
                st.set_vreg(RN as usize, (1.5f32).to_bits() as u64, 0);
            } else {
                st.set_vreg(RN as usize, (1.5f64).to_bits(), 0);
            }
            batch.push((
                format!("frintts_t{ft}_op{opcode:05b}_ixc"),
                enc_fp1(ft, opcode),
                st,
            ));

            for (name, bits) in [
                (
                    "qnan",
                    if ft == 0 {
                        0x7fc0_0001
                    } else {
                        0x7ff8_0000_0000_0001
                    },
                ),
                (
                    "inf",
                    if ft == 0 {
                        0x7f80_0000
                    } else {
                        0x7ff0_0000_0000_0000
                    },
                ),
                (
                    "large",
                    if ft == 0 {
                        0x5f00_0000
                    } else {
                        0x43e0_0000_0000_0000
                    },
                ),
            ] {
                let mut st = ArmState::zeroed();
                st.set_vreg(RN as usize, bits, 0);
                batch.push((
                    format!("frintts_t{ft}_op{opcode:05b}_{name}_ioc"),
                    enc_fp1(ft, opcode),
                    st,
                ));
            }
        }
    }

    run_fpsr_batch("fp_scalar_frintts_fpsr_inexact", batch);
}

