fn diff_fpcr_ah_maxnm_pairwise_nan_priority() {
    const FPCR_AH: u64 = 1 << 1;
    let pack_h = |values: &[u16]| -> (u64, u64) {
        let mut packed = 0u128;
        for (lane, &value) in values.iter().enumerate() {
            packed |= (value as u128) << (16 * lane);
        }
        (packed as u64, (packed >> 64) as u64)
    };
    let pack_s = |values: &[u32]| -> (u64, u64) {
        let mut packed = 0u128;
        for (lane, &value) in values.iter().enumerate() {
            packed |= (value as u128) << (32 * lane);
        }
        (packed as u64, (packed >> 64) as u64)
    };

    let mut batch = Vec::new();
    let (h_lo, h_hi) = pack_h(&[
        0x7e00, 0x7d01, 0x3c00, 0x0001, 0x7e00, 0x7d01, 0x3c00, 0x0001,
    ]);
    let (s_lo, s_hi) = pack_s(&[0x7fc0_2000, 0x7fa0_0001, 0x3f80_0000, 0x0000_0001]);
    let d_nan_number = (0x7ff8_0000_0000_2000, 0x0000_0000_0000_0001);

    for &(label, insn, lo, hi) in &[
        ("simd_fmaxnmp_h", enc_fp16_3s(1, 1, 0, 0b000), h_lo, h_hi),
        ("simd_fminnmp_h", enc_fp16_3s(1, 1, 1, 0b000), h_lo, h_hi),
        (
            "simd_fmaxnmp_s",
            enc_three_same(1, 1, 0, 0b11000),
            s_lo,
            s_hi,
        ),
        (
            "simd_fminnmp_s",
            enc_three_same(1, 1, 2, 0b11000),
            s_lo,
            s_hi,
        ),
        (
            "simd_fmaxnmp_d",
            enc_three_same(1, 1, 1, 0b11000),
            d_nan_number.0,
            d_nan_number.1,
        ),
        (
            "simd_fminnmp_d",
            enc_three_same(1, 1, 3, 0b11000),
            d_nan_number.0,
            d_nan_number.1,
        ),
    ] {
        let mut st = ArmState::zeroed();
        st.fpcr = FPCR_AH;
        st.set_vreg(RN as usize, lo, hi);
        st.set_vreg(RM as usize, lo, hi);
        batch.push((format!("{label}_ah_nan_pair"), insn, st));
    }

    for &(label, insn, lo, hi) in &[
        ("sve_fmaxnmp_h", enc_sve2_fpairwise(1, 0b100), h_lo, h_hi),
        ("sve_fminnmp_h", enc_sve2_fpairwise(1, 0b101), h_lo, h_hi),
        ("sve_fmaxnmp_s", enc_sve2_fpairwise(2, 0b100), s_lo, s_hi),
        ("sve_fminnmp_s", enc_sve2_fpairwise(2, 0b101), s_lo, s_hi),
        (
            "sve_fmaxnmp_d",
            enc_sve2_fpairwise(3, 0b100),
            d_nan_number.0,
            d_nan_number.1,
        ),
        (
            "sve_fminnmp_d",
            enc_sve2_fpairwise(3, 0b101),
            d_nan_number.0,
            d_nan_number.1,
        ),
    ] {
        let mut st = ArmState::zeroed();
        st.fpcr = FPCR_AH;
        st.set_preg(0, 0xffff);
        st.set_vreg(RD as usize, lo, hi);
        st.set_vreg(RN as usize, lo, hi);
        batch.push((format!("{label}_ah_nan_pair"), insn, st));
    }

    run_batch("fpcr_ah_maxnm_pairwise_nan_priority", batch);
}

#[test]
fn diff_fpcr_ah_fneg_qnan_sign() {
    const FPCR_AH: u64 = 1 << 1;
    let pack_h = |value: u16| -> (u64, u64) {
        let mut packed = 0u128;
        for lane in 0..8 {
            packed |= (value as u128) << (16 * lane);
        }
        (packed as u64, (packed >> 64) as u64)
    };
    let pack_s = |value: u32| -> (u64, u64) {
        let mut packed = 0u128;
        for lane in 0..4 {
            packed |= (value as u128) << (32 * lane);
        }
        (packed as u64, (packed >> 64) as u64)
    };
    let pack_d = |value: u64| -> (u64, u64) { (value, value) };

    let mut batch = Vec::new();
    for &(label, fp_type, nan) in &[
        ("scalar_fneg_h", 0b11, 0x7e01u64),
        ("scalar_fneg_s", 0b00, 0x7fc0_2000),
        ("scalar_fneg_d", 0b01, 0x7ff8_0000_0000_2000),
    ] {
        let mut st = ArmState::zeroed();
        st.fpcr = FPCR_AH;
        st.set_vreg(RN as usize, nan, 0);
        batch.push((format!("{label}_ah_qnan"), enc_fp1(fp_type, 0b000010), st));
    }

    let (lo, hi) = pack_h(0x7e01);
    let mut st = ArmState::zeroed();
    st.fpcr = FPCR_AH;
    st.set_vreg(RN as usize, lo, hi);
    batch.push((
        "simd_fneg_h_ah_qnan".to_string(),
        enc_fp16_2r(1, 1, 1, 0b01111),
        st,
    ));

    let (lo, hi) = pack_s(0x7fc0_2000);
    let mut st = ArmState::zeroed();
    st.fpcr = FPCR_AH;
    st.set_vreg(RN as usize, lo, hi);
    batch.push((
        "simd_fneg_s_ah_qnan".to_string(),
        enc_two_reg(1, 1, 2, 0b01111),
        st,
    ));

    let (lo, hi) = pack_d(0x7ff8_0000_0000_2000);
    let mut st = ArmState::zeroed();
    st.fpcr = FPCR_AH;
    st.set_vreg(RN as usize, lo, hi);
    batch.push((
        "simd_fneg_d_ah_qnan".to_string(),
        enc_two_reg(1, 1, 3, 0b01111),
        st,
    ));

    run_batch("fpcr_ah_fneg_qnan_sign", batch);
}

