#[test]
fn diff_fp_scalar_fpsr_exceptions() {
    let mut batch: Vec<(String, u32, ArmState)> = Vec::new();

    for &ft in &[0u32, 1] {
        let mut push2 = |label: &str, opcode: u32, n: u64, m: u64, fpsr: u64| {
            let mut st = ArmState::zeroed();
            st.fpsr = fpsr;
            st.set_vreg(RN as usize, n, 0);
            st.set_vreg(RM as usize, m, 0);
            batch.push((
                format!("{label}_t{ft}_fpsr{fpsr:#x}"),
                enc_fp2(ft, opcode),
                st,
            ));
        };

        if ft == 0 {
            let inf = f32::INFINITY.to_bits() as u64;
            let ninf = f32::NEG_INFINITY.to_bits() as u64;
            let zero = 0.0f32.to_bits() as u64;
            let max = f32::MAX.to_bits() as u64;
            let two = 2.0f32.to_bits() as u64;
            let min_normal = f32::MIN_POSITIVE.to_bits() as u64;
            let three = 3.0f32.to_bits() as u64;
            let one = 1.0f32.to_bits() as u64;
            let tiny_addend = f32::from_bits(0x3300_0000).to_bits() as u64; // 2^-25
            push2("fadd_invalid_inf_cancel", 0b0010, inf, ninf, 0);
            push2("fmul_invalid_zero_inf", 0b0000, zero, inf, 0);
            push2("fdiv_invalid_zero_zero", 0b0001, zero, zero, 0);
            push2("fdiv_invalid_inf_inf", 0b0001, inf, inf, 0);
            push2("fmul_overflow", 0b0000, max, two, 0);
            push2("fdiv_underflow", 0b0001, min_normal, three, 0);
            push2("fadd_inexact", 0b0010, one, tiny_addend, 1);
        } else {
            let inf = f64::INFINITY.to_bits();
            let ninf = f64::NEG_INFINITY.to_bits();
            let zero = 0.0f64.to_bits();
            let max = f64::MAX.to_bits();
            let two = 2.0f64.to_bits();
            let min_normal = f64::MIN_POSITIVE.to_bits();
            let three = 3.0f64.to_bits();
            push2("fadd_invalid_inf_cancel", 0b0010, inf, ninf, 0);
            push2("fmul_invalid_zero_inf", 0b0000, zero, inf, 0);
            push2("fdiv_invalid_zero_zero", 0b0001, zero, zero, 0);
            push2("fdiv_invalid_inf_inf", 0b0001, inf, inf, 0);
            push2("fmul_overflow", 0b0000, max, two, 0);
            push2("fdiv_underflow", 0b0001, min_normal, three, 0);
        }
    }

    run_fpsr_batch("fp_scalar_fpsr_exceptions", batch);
}

/// FCCMP/FCCMPE: scalar FP conditional compare. Output is only NZCV (the flag
/// rules are deterministic even for NaN operands), so comparison is exact.
#[test]
fn diff_fp_ccmp() {
    let mut cases: Vec<(String, u32)> = Vec::new();
    for &fp_type in &[0b00u32, 0b01, 0b11] {
        for cond in 0..16u32 {
            for op in 0..2u32 {
                for &nzcv in &[0u32, 0xF, 0x5] {
                    let insn = (0b00011110u32 << 24)
                        | (fp_type << 22)
                        | (1 << 21)
                        | (RM << 16)
                        | (cond << 12)
                        | (0b01 << 10)
                        | (RN << 5)
                        | (op << 4)
                        | nzcv;
                    cases.push((
                        format!("fccmp ty{fp_type} cond{cond} op{op} nzcv{nzcv}"),
                        insn,
                    ));
                }
            }
        }
    }
    run_family("fp_ccmp", cases, 6, 0x3001);
}

/// Advanced SIMD shift-by-immediate: `0 Q U 011110 immh immb opcode 1 Rn Rd`.
fn enc_shift_imm(q: u32, u: u32, opcode: u32, immhimmb: u32) -> u32 {
    let immh = (immhimmb >> 3) & 0xF;
    let immb = immhimmb & 0x7;
    (q << 30)
        | (u << 29)
        | (0b011110 << 23)
        | (immh << 19)
        | (immb << 16)
        | (opcode << 11)
        | (1 << 10)
        | (RN << 5)
        | RD
}

fn enc_scalar_shift_imm(u: u32, opcode: u32, immhimmb: u32) -> u32 {
    let immh = (immhimmb >> 3) & 0xF;
    let immb = immhimmb & 0x7;
    (1 << 30)
        | (u << 29)
        | (0b111110 << 23)
        | (immh << 19)
        | (immb << 16)
        | (opcode << 11)
        | (1 << 10)
        | (RN << 5)
        | RD
}

/// Integer shift-by-immediate cases: same-size, widening and narrowing forms
/// across all element sizes and the full range of valid shift amounts.
fn shift_imm_int_cases() -> Vec<(String, u32)> {
    let mut v = Vec::new();
    // Same-size ops: (opcode, U-options, is_left)
    let same: &[(u32, &[u32], bool)] = &[
        (0b00000, &[0, 1], false), // SSHR/USHR
        (0b00010, &[0, 1], false), // SSRA/USRA
        (0b00100, &[0, 1], false), // SRSHR/URSHR
        (0b00110, &[0, 1], false), // SRSRA/URSRA
        (0b01000, &[1], false),    // SRI
        (0b01010, &[0, 1], true),  // SHL / SLI
        (0b01100, &[1], true),     // SQSHLU
        (0b01110, &[0, 1], true),  // SQSHL / UQSHL
    ];
    for &(opcode, us, is_left) in same {
        for &bits in &[8u32, 16, 32, 64] {
            for &u in us {
                for q in 0..2 {
                    if bits == 64 && q == 0 {
                        continue; // 1D not valid
                    }
                    let shifts: Vec<u32> = if is_left {
                        (0..bits).collect()
                    } else {
                        (1..=bits).collect()
                    };
                    for sh in shifts {
                        let immhimmb = if is_left { bits + sh } else { 2 * bits - sh };
                        v.push((
                            format!("sh same op{opcode:05b} u{u} b{bits} q{q} #{sh}"),
                            enc_shift_imm(q, u, opcode, immhimmb),
                        ));
                    }
                }
            }
        }
    }
    // Widening SSHLL/USHLL (opcode 10100), source size 8/16/32.
    for &bits in &[8u32, 16, 32] {
        for u in 0..2 {
            for q in 0..2 {
                for sh in 0..bits {
                    let immhimmb = bits + sh;
                    v.push((
                        format!("sshll u{u} b{bits} q{q} #{sh}"),
                        enc_shift_imm(q, u, 0b10100, immhimmb),
                    ));
                }
            }
        }
    }
    // Narrowing (opcode 10000/10001/10010/10011), dest size 8/16/32.
    for &opcode in &[0b10000u32, 0b10001, 0b10010, 0b10011] {
        for &bits in &[8u32, 16, 32] {
            for u in 0..2 {
                for q in 0..2 {
                    for sh in 1..=bits {
                        let immhimmb = 2 * bits - sh;
                        v.push((
                            format!("narrow op{opcode:05b} u{u} b{bits} q{q} #{sh}"),
                            enc_shift_imm(q, u, opcode, immhimmb),
                        ));
                    }
                }
            }
        }
    }
    v
}

#[test]
fn diff_simd_shift_imm() {
    run_family("simd_shift_imm", shift_imm_int_cases(), 6, 0x4001);
}

