#[test]
fn diff_simd_scalar_shift_fixedpoint() {
    fn fixed_input_bits(bits: u32, opcode: u32, unsigned: bool) -> u64 {
        match (bits, opcode, unsigned) {
            (16, 0b11100, false) => (-6i16) as u16 as u64,
            (16, 0b11100, true) => 6,
            (16, 0b11111, false) => 0xc200,
            (16, 0b11111, true) => 0x4200,
            (32, 0b11100, false) => (-6i32) as u32 as u64,
            (32, 0b11100, true) => 6,
            (32, 0b11111, false) => (-3.0f32).to_bits() as u64,
            (32, 0b11111, true) => 3.0f32.to_bits() as u64,
            (64, 0b11100, false) => (-6i64) as u64,
            (64, 0b11100, true) => 6,
            (64, 0b11111, false) => (-3.0f64).to_bits(),
            (64, 0b11111, true) => 3.0f64.to_bits(),
            _ => unreachable!(),
        }
    }

    let mut batch: Vec<(String, u32, ArmState)> = Vec::new();
    for &bits in &[16u32, 32, 64] {
        for &(opcode, opname) in &[(0b11100u32, "cvtf"), (0b11111, "fcvtz")] {
            for u in 0..2u32 {
                for &fbits in &[1u32, 4] {
                    let mut st = ArmState::zeroed();
                    st.set_vreg(RN as usize, fixed_input_bits(bits, opcode, u == 1), 0);
                    batch.push((
                        format!("scalar_{opname}_u{u}_b{bits}_f{fbits}"),
                        enc_scalar_shift_imm(u, opcode, 2 * bits - fbits),
                        st,
                    ));
                }
            }
        }
    }

    run_batch("simd_scalar_shift_fixedpoint", batch);
}

/// Fixed-point convert (SCVTF/UCVTF/FCVTZS/FCVTZU), clean finite inputs.
#[test]
fn diff_simd_shift_fixedpoint() {
    let mut cases: Vec<(String, u32)> = Vec::new();
    for &opcode in &[0b11100u32, 0b11111] {
        for &bits in &[32u32, 64] {
            for u in 0..2 {
                for q in 0..2 {
                    if bits == 64 && q == 0 {
                        continue;
                    }
                    for fbits in 1..=bits {
                        let immhimmb = 2 * bits - fbits;
                        cases.push((
                            format!("fxp op{opcode:05b} u{u} b{bits} q{q} f{fbits}"),
                            enc_shift_imm(q, u, opcode, immhimmb),
                        ));
                    }
                }
            }
        }
    }
    // Inputs: for FCVTZS/U the source lanes are floats; for SCVTF/UCVTF they are
    // integers. Use small finite magnitudes so results are exact / unambiguous.
    let mut rng = Rng::new(0x4002);
    let mut batch: Vec<(String, u32, ArmState)> = Vec::new();
    for (label, insn) in &cases {
        let is_fcvt = label.contains("11111");
        let bits64 = label.contains("b64");
        for _ in 0..4 {
            let mut st = ArmState::zeroed();
            let mut packed: u128 = 0;
            for lane in 0..4 {
                let word: u64 = if is_fcvt {
                    // small finite float values
                    let val = ((rng.next() % 41) as i64 - 20) as f64 * 0.25;
                    if bits64 {
                        val.to_bits()
                    } else {
                        (val as f32).to_bits() as u64
                    }
                } else {
                    // small signed integers
                    ((rng.next() % 4001) as i64 - 2000) as u64
                };
                if bits64 {
                    packed |= (word as u128) << (64 * lane.min(1));
                    if lane == 1 {
                        break;
                    }
                } else {
                    packed |= ((word as u32) as u128) << (32 * lane);
                }
            }
            st.set_vreg(1, packed as u64, (packed >> 64) as u64);
            batch.push((label.clone(), *insn, st));
        }
    }
    run_batch("simd_shift_fixedpoint", batch);
}

#[test]
fn diff_simd_fixed_cvtf_fpcr_rounding() {
    let mut batch: Vec<(String, u32, ArmState)> = Vec::new();
    for rmode in 0..4u64 {
        let fpcr = rmode << 22;

        let mut st = ArmState::zeroed();
        st.fpcr = fpcr;
        let h_lanes = [
            2_049u16,
            (-2_049i16) as u16,
            u16::MAX,
            2_049u16,
            2_049u16,
            (-2_049i16) as u16,
            u16::MAX,
            2_049u16,
        ];
        let mut packed = 0u128;
        for (lane, value) in h_lanes.iter().enumerate() {
            packed |= (*value as u128) << (16 * lane);
        }
        st.set_vreg(1, packed as u64, (packed >> 64) as u64);
        let h_imm = 2 * 16 - 1;
        batch.push((
            format!("scvtf_h_f1_rmode{rmode}"),
            enc_shift_imm(1, 0, 0b11100, h_imm),
            st,
        ));
        batch.push((
            format!("ucvtf_h_f1_rmode{rmode}"),
            enc_shift_imm(1, 1, 0b11100, h_imm),
            st,
        ));

        let mut st = ArmState::zeroed();
        st.fpcr = fpcr;
        let s_lanes = [
            16_777_217u32,
            (-16_777_217i32) as u32,
            u32::MAX,
            16_777_217u32,
        ];
        let mut packed = 0u128;
        for (lane, value) in s_lanes.iter().enumerate() {
            packed |= (*value as u128) << (32 * lane);
        }
        st.set_vreg(1, packed as u64, (packed >> 64) as u64);
        let s_imm = 2 * 32 - 1;
        batch.push((
            format!("scvtf_s_f1_rmode{rmode}"),
            enc_shift_imm(1, 0, 0b11100, s_imm),
            st,
        ));
        batch.push((
            format!("ucvtf_s_f1_rmode{rmode}"),
            enc_shift_imm(1, 1, 0b11100, s_imm),
            st,
        ));

        let mut st = ArmState::zeroed();
        st.fpcr = fpcr;
        let d_lanes = [9_007_199_254_740_993u64, (-9_007_199_254_740_993i64) as u64];
        let mut packed = 0u128;
        for (lane, value) in d_lanes.iter().enumerate() {
            packed |= (*value as u128) << (64 * lane);
        }
        st.set_vreg(1, packed as u64, (packed >> 64) as u64);
        let d_imm = 2 * 64 - 1;
        batch.push((
            format!("scvtf_d_f1_rmode{rmode}"),
            enc_shift_imm(1, 0, 0b11100, d_imm),
            st,
        ));
        batch.push((
            format!("ucvtf_d_f1_rmode{rmode}"),
            enc_shift_imm(1, 1, 0b11100, d_imm),
            st,
        ));
    }

    run_batch("simd_fixed_cvtf_fpcr_rounding", batch);
}

#[test]
fn diff_fpcr_fz16_simd_fixed_fp16_to_int_subnormal_inputs() {
    const FPCR_FZ16: u64 = 1 << 19;
    let mut batch: Vec<(String, u32, ArmState)> = Vec::new();

    let pack_h = |value: u16| -> (u64, u64) {
        let mut packed = 0u128;
        for lane in 0..8 {
            packed |= (value as u128) << (16 * lane);
        }
        (packed as u64, (packed >> 64) as u64)
    };

    let fbits = 16;
    let immhimmb = 2 * 16 - fbits;
    for &(name, u, value) in &[
        ("fcvtzs_h_pos_max_subnorm", 0, 0x03ffu16),
        ("fcvtzs_h_neg_max_subnorm", 0, 0x83ffu16),
        ("fcvtzu_h_pos_max_subnorm", 1, 0x03ffu16),
    ] {
        let mut st = ArmState::zeroed();
        st.fpcr = FPCR_FZ16;
        let (lo, hi) = pack_h(value);
        st.set_vreg(RN as usize, lo, hi);
        batch.push((
            format!("{name}_f{fbits}_fz16"),
            enc_shift_imm(1, u, 0b11111, immhimmb),
            st,
        ));
    }

    run_batch("fpcr_fz16_simd_fixed_fp16_to_int_subnormal_inputs", batch);
}

#[test]
fn diff_fpcr_fiz_simd_fixed_fp_to_int_subnormal_inputs() {
    const FPCR_FIZ: u64 = 1;
    let mut batch: Vec<(String, u32, ArmState)> = Vec::new();

    let pack_s = |value: u32| -> (u64, u64) {
        let mut packed = 0u128;
        for lane in 0..4 {
            packed |= (value as u128) << (32 * lane);
        }
        (packed as u64, (packed >> 64) as u64)
    };
    let pack_d = |value: u64| -> (u64, u64) {
        let packed = (value as u128) | ((value as u128) << 64);
        (packed as u64, (packed >> 64) as u64)
    };

    for &(name, u, bits) in &[
        ("fcvtzs_s_pos_min_subnorm", 0, 0x0000_0001u32),
        ("fcvtzs_s_neg_min_subnorm", 0, 0x8000_0001u32),
        ("fcvtzu_s_pos_min_subnorm", 1, 0x0000_0001u32),
    ] {
        let mut st = ArmState::zeroed();
        st.fpcr = FPCR_FIZ;
        let (lo, hi) = pack_s(bits);
        st.set_vreg(RN as usize, lo, hi);
        batch.push((
            format!("{name}_f32_fiz"),
            enc_shift_imm(1, u, 0b11111, 2 * 32 - 32),
            st,
        ));
    }

    for &(name, u, bits) in &[
        ("fcvtzs_d_pos_min_subnorm", 0, 0x0000_0000_0000_0001u64),
        ("fcvtzs_d_neg_min_subnorm", 0, 0x8000_0000_0000_0001u64),
        ("fcvtzu_d_pos_min_subnorm", 1, 0x0000_0000_0000_0001u64),
    ] {
        let mut st = ArmState::zeroed();
        st.fpcr = FPCR_FIZ;
        let (lo, hi) = pack_d(bits);
        st.set_vreg(RN as usize, lo, hi);
        batch.push((
            format!("{name}_f64_fiz"),
            enc_shift_imm(1, u, 0b11111, 2 * 64 - 64),
            st,
        ));
    }

    run_batch("fpcr_fiz_simd_fixed_fp_to_int_subnormal_inputs", batch);
}

/// Advanced SIMD three-different (widening/narrowing): `0 Q U 01110 size 1 Rm opcode 00 Rn Rd`.
fn enc_3diff(q: u32, u: u32, size: u32, opcode: u32) -> u32 {
    (q << 30)
        | (u << 29)
        | (0b01110 << 24)
        | (size << 22)
        | (1 << 21)
        | (RM << 16)
        | (opcode << 12)
        | (RN << 5)
        | RD
}

fn enc_scalar_3diff(size: u32, opcode: u32) -> u32 {
    (1 << 30)
        | (0b11110 << 24)
        | (size << 22)
        | (1 << 21)
        | (RM << 16)
        | (opcode << 12)
        | (RN << 5)
        | RD
}

#[test]
fn diff_simd_three_diff() {
    // (opcode, U-options, name)
    let ops: &[(u32, &[u32], &str)] = &[
        (0b0000, &[0, 1], "saddl_uaddl"),
        (0b0001, &[0, 1], "saddw_uaddw"),
        (0b0010, &[0, 1], "ssubl_usubl"),
        (0b0011, &[0, 1], "ssubw_usubw"),
        (0b0100, &[0, 1], "addhn_raddhn"),
        (0b0101, &[0, 1], "sabal_uabal"),
        (0b0110, &[0, 1], "subhn_rsubhn"),
        (0b0111, &[0, 1], "sabdl_uabdl"),
        (0b1000, &[0, 1], "smlal_umlal"),
        (0b1001, &[0], "sqdmlal"),
        (0b1010, &[0, 1], "smlsl_umlsl"),
        (0b1011, &[0], "sqdmlsl"),
        (0b1100, &[0, 1], "smull_umull"),
        (0b1101, &[0], "sqdmull"),
        (0b1110, &[0], "pmull"),
    ];
    let mut cases: Vec<(String, u32)> = Vec::new();
    for &(opcode, us, name) in ops {
        for &u in us {
            for size in 0..3 {
                for q in 0..2 {
                    cases.push((
                        format!("{name} sz{size} q{q}"),
                        enc_3diff(q, u, size, opcode),
                    ));
                }
            }
            // PMULL.1Q (size==3) for the polynomial op only.
            if opcode == 0b1110 {
                for q in 0..2 {
                    cases.push((format!("{name} sz3 q{q}"), enc_3diff(q, u, 3, opcode)));
                }
            }
        }
    }
    run_family("simd_three_diff", cases, 8, 0x8001);
}

#[test]
fn diff_simd_three_diff_edges() {
    let ops: &[(u32, &[u32], &str)] = &[
        (0b0000, &[0, 1], "saddl_uaddl"),
        (0b0001, &[0, 1], "saddw_uaddw"),
        (0b0010, &[0, 1], "ssubl_usubl"),
        (0b0011, &[0, 1], "ssubw_usubw"),
        (0b0100, &[0, 1], "addhn_raddhn"),
        (0b0101, &[0, 1], "sabal_uabal"),
        (0b0110, &[0, 1], "subhn_rsubhn"),
        (0b0111, &[0, 1], "sabdl_uabdl"),
        (0b1000, &[0, 1], "smlal_umlal"),
        (0b1001, &[0], "sqdmlal"),
        (0b1010, &[0, 1], "smlsl_umlsl"),
        (0b1011, &[0], "sqdmlsl"),
        (0b1100, &[0, 1], "smull_umull"),
        (0b1101, &[0], "sqdmull"),
        (0b1110, &[0], "pmull"),
    ];
    let patterns: &[(&str, [(u64, u64); 3])] = &[
        ("zero", [(0, 0), (0, 0), (0, 0)]),
        (
            "signed_bounds",
            [
                (0x7fff_ffff_8000_0000, 0xffff_ffff_0000_0001),
                (0x807f_8000_7fff_00ff, 0xff00_0100_fe01_7f80),
                (0x7f80_0080_ff00_01ff, 0x8001_feff_00ff_7f00),
            ],
        ),
        (
            "byte_ramps",
            [
                (0x0302_0100_0706_0504, 0x0b0a_0908_0f0e_0d0c),
                (0x0706_0504_0302_0100, 0x0f0e_0d0c_0b0a_0908),
                (0xf8f9_fafb_fcfd_feff, 0xf0f1_f2f3_f4f5_f6f7),
            ],
        ),
    ];

    let mut batch = Vec::new();
    for &(opcode, us, name) in ops {
        for &u in us {
            for size in 0..3 {
                for q in 0..2 {
                    for &(pattern, regs) in patterns {
                        let mut st = ArmState::zeroed();
                        for (idx, reg) in [RD, RN, RM].iter().copied().enumerate() {
                            st.set_vreg(reg as usize, regs[idx].0, regs[idx].1);
                        }
                        batch.push((
                            format!("{name}_sz{size}_q{q}_{pattern}"),
                            enc_3diff(q, u, size, opcode),
                            st,
                        ));
                    }
                }
            }
            if opcode == 0b1110 {
                for q in 0..2 {
                    for &(pattern, regs) in patterns {
                        let mut st = ArmState::zeroed();
                        for (idx, reg) in [RD, RN, RM].iter().copied().enumerate() {
                            st.set_vreg(reg as usize, regs[idx].0, regs[idx].1);
                        }
                        batch.push((
                            format!("{name}_sz3_q{q}_{pattern}"),
                            enc_3diff(q, u, 3, opcode),
                            st,
                        ));
                    }
                }
            }
        }
    }

    run_batch("simd_three_diff_edges", batch);
}

#[test]
fn diff_simd_three_diff_unallocated_edges() {
    let mut rng = Rng::new(0x1_0034);
    let mut batch: Vec<(String, u32, ArmState)> = Vec::new();

    for &(q, u) in &[(0u32, 0u32), (0, 1), (1, 1)] {
        batch.push((
            format!("three_diff_bit31_q{q}_u{u}"),
            enc_3diff(q, u, 0b00, 0b0000) | (1 << 31),
            gen_input(&mut rng),
        ));
    }

    for &(opcode, u, name) in &[
        (0b0000, 0, "saddl_size3"),
        (0b0001, 0, "saddw_size3"),
        (0b0100, 0, "addhn_size3"),
        (0b1000, 0, "smlal_size3"),
        (0b1100, 1, "umull_size3"),
    ] {
        for q in 0..2u32 {
            batch.push((
                format!("{name}_q{q}"),
                enc_3diff(q, u, 0b11, opcode),
                gen_input(&mut rng),
            ));
        }
    }

    for &(opcode, name) in &[
        (0b1001, "sqdmlal"),
        (0b1011, "sqdmlsl"),
        (0b1101, "sqdmull"),
    ] {
        for q in 0..2u32 {
            batch.push((
                format!("{name}_size0_q{q}"),
                enc_3diff(q, 0, 0b00, opcode),
                gen_input(&mut rng),
            ));
            batch.push((
                format!("{name}_unsigned_q{q}"),
                enc_3diff(q, 1, 0b01, opcode),
                gen_input(&mut rng),
            ));
        }
    }

    for &size in &[0b00u32, 0b11] {
        for q in 0..2u32 {
            batch.push((
                format!("pmull_unsigned_size{size}_q{q}"),
                enc_3diff(q, 1, size, 0b1110),
                gen_input(&mut rng),
            ));
        }
    }

    for size in 0..4u32 {
        for q in 0..2u32 {
            batch.push((
                format!("three_diff_opcode1111_size{size}_q{q}"),
                enc_3diff(q, 0, size, 0b1111),
                gen_input(&mut rng),
            ));
        }
    }

    run_batch_el0_legality("simd_three_diff_unallocated_edges", batch);
}

