#[test]
fn diff_simd_three_same_fp() {
    // (U, a, opcode, name) for the FP three-same ops. size = (a<<1)|sz.
    let ops: &[(u32, u32, u32, &str)] = &[
        (0, 0, 0b11000, "fmaxnm"),
        (0, 0, 0b11001, "fmla"),
        (0, 0, 0b11010, "fadd"),
        (0, 0, 0b11011, "fmulx"),
        (0, 0, 0b11100, "fcmeq"),
        (0, 0, 0b11110, "fmax"),
        (0, 0, 0b11111, "frecps"),
        (0, 1, 0b11000, "fminnm"),
        (0, 1, 0b11001, "fmls"),
        (0, 1, 0b11010, "fsub"),
        (0, 1, 0b11110, "fmin"),
        (0, 1, 0b11111, "frsqrts"),
        (1, 0, 0b11000, "fmaxnmp"),
        (1, 0, 0b11010, "faddp"),
        (1, 0, 0b11011, "fmul"),
        (1, 0, 0b11100, "fcmge"),
        (1, 0, 0b11101, "facge"),
        (1, 0, 0b11110, "fmaxp"),
        (1, 0, 0b11111, "fdiv"),
        (1, 1, 0b11000, "fminnmp"),
        (1, 1, 0b11010, "fabd"),
        (1, 1, 0b11100, "fcmgt"),
        (1, 1, 0b11101, "facgt"),
        (1, 1, 0b11110, "fminp"),
    ];
    let mut cases: Vec<(String, u32, bool)> = Vec::new();
    for &(u, a, opcode, name) in ops {
        for q in 0..2 {
            cases.push((
                format!("{name} f32 q{q}"),
                enc_three_same(q, u, a << 1, opcode),
                false,
            ));
        }
        cases.push((
            format!("{name} f64"),
            enc_three_same(1, u, (a << 1) | 1, opcode),
            true,
        ));
    }
    // Non-zero finite lanes (multiples of 0.25) so FDIV is well-defined and
    // products/sums stay exactly representable.
    let mut rng = Rng::new(0xE001);
    let mut batch: Vec<(String, u32, ArmState)> = Vec::new();
    for (label, insn, f64op) in &cases {
        for _ in 0..12 {
            let mut st = ArmState::zeroed();
            for r in 0..3usize {
                let mut packed: u128 = 0;
                if *f64op {
                    for lane in 0..2 {
                        let n = (rng.next() % 40) as i64 - 20;
                        let v = if n == 0 { 1 } else { n } as f64 * 0.25;
                        packed |= (v.to_bits() as u128) << (64 * lane);
                    }
                } else {
                    for lane in 0..4 {
                        let n = (rng.next() % 40) as i64 - 20;
                        let v = if n == 0 { 1 } else { n } as f32 * 0.25;
                        packed |= (v.to_bits() as u128) << (32 * lane);
                    }
                }
                st.set_vreg(r, packed as u64, (packed >> 64) as u64);
            }
            batch.push((label.clone(), *insn, st));
        }
    }
    run_batch("simd_three_same_fp", batch);
}

#[test]
fn diff_simd_three_same_fp_unallocated_edges() {
    let mut rng = Rng::new(0x1_0033);
    let mut batch: Vec<(String, u32, ArmState)> = Vec::new();

    let invalid: &[(u32, u32, u32)] = &[
        (0, 0, 0b11101),
        (0, 1, 0b11011),
        (0, 1, 0b11100),
        (0, 1, 0b11101),
        (1, 0, 0b11001),
        (1, 1, 0b11001),
        (1, 1, 0b11011),
        (1, 1, 0b11111),
    ];
    for &(u, a, opcode) in invalid {
        for sz in 0..2u32 {
            for q in 0..2u32 {
                if sz == 1 && q == 0 {
                    continue;
                }
                batch.push((
                    format!("fp3same_invalid_u{u}_a{a}_sz{sz}_q{q}_op{opcode:05b}"),
                    enc_three_same(q, u, (a << 1) | sz, opcode),
                    gen_input(&mut rng),
                ));
            }
        }
    }

    for &(u, a, opcode, name) in &[
        (0, 0, 0b11010, "fadd"),
        (0, 1, 0b11010, "fsub"),
        (1, 0, 0b11011, "fmul"),
        (1, 0, 0b11111, "fdiv"),
        (1, 1, 0b11010, "fabd"),
    ] {
        batch.push((
            format!("{name}_f64_q0"),
            enc_three_same(0, u, (a << 1) | 1, opcode),
            gen_input(&mut rng),
        ));
    }

    for &(q, u, a, opcode, name) in &[
        (0, 0, 0, 0b11010, "fadd_bit31"),
        (0, 1, 0, 0b11111, "fdiv_bit31"),
        (1, 1, 0, 0b11011, "fmul_bit31"),
    ] {
        for _ in 0..4 {
            batch.push((
                format!("{name}_q{q}_u{u}"),
                enc_three_same(q, u, a << 1, opcode) | (1 << 31),
                gen_input(&mut rng),
            ));
        }
    }

    run_batch_el0_legality("simd_three_same_fp_unallocated_edges", batch);
}

#[test]
fn diff_simd_recps_rsqrts_fpcr_rounding() {
    let mut batch: Vec<(String, u32, ArmState)> = Vec::new();
    let ops = [
        ("frecps", enc_three_same(1, 0, 0, 0b11111)),
        ("frsqrts", enc_three_same(1, 0, 2, 0b11111)),
    ];
    for rmode in 0..4u64 {
        for (name, insn) in ops {
            let mut st = ArmState::zeroed();
            st.fpcr = rmode << 22;
            let s = f32::from_bits(0x3f80_0001);
            let packed = (s.to_bits() as u64) | ((s.to_bits() as u64) << 32);
            st.set_vreg(RN as usize, packed, packed);
            st.set_vreg(RM as usize, packed, packed);
            batch.push((format!("{name}_s_rmode{rmode}"), insn, st));

            let mut st = ArmState::zeroed();
            st.fpcr = rmode << 22;
            let d = f64::from_bits(0x3ff0_0000_0000_0001);
            st.set_vreg(RN as usize, d.to_bits(), d.to_bits());
            st.set_vreg(RM as usize, d.to_bits(), d.to_bits());
            batch.push((format!("{name}_d_rmode{rmode}"), insn | 1 << 22, st));
        }
    }
    run_batch("simd_recps_rsqrts_fpcr_rounding", batch);
}

