#[test]
fn diff_fpcr_fiz_simd_recps_rsqrts_subnormal_inputs() {
    const FPCR_FIZ: u64 = 1;
    let ops = [
        ("frecps", enc_three_same(1, 0, 0, 0b11111)),
        ("frsqrts", enc_three_same(1, 0, 2, 0b11111)),
    ];
    let mut batch: Vec<(String, u32, ArmState)> = Vec::new();

    for &(name, insn) in &ops {
        let mut st = ArmState::zeroed();
        st.fpcr = FPCR_FIZ;
        let n = 0x0000_0001u32;
        let m = f32::MAX.to_bits();
        let packed_n = (n as u64) | ((n as u64) << 32);
        let packed_m = (m as u64) | ((m as u64) << 32);
        st.set_vreg(RN as usize, packed_n, packed_n);
        st.set_vreg(RM as usize, packed_m, packed_m);
        batch.push((format!("simd_{name}_s_fiz_min_subnorm"), insn, st));

        let mut st = ArmState::zeroed();
        st.fpcr = FPCR_FIZ;
        st.set_vreg(RN as usize, 0x0000_0000_0000_0001, 0x0000_0000_0000_0001);
        st.set_vreg(RM as usize, f64::MAX.to_bits(), f64::MAX.to_bits());
        batch.push((format!("simd_{name}_d_fiz_min_subnorm"), insn | 1 << 22, st));
    }

    run_batch("fpcr_fiz_simd_recps_rsqrts_subnormal_inputs", batch);
}

#[test]
fn diff_fpcr_fz_fp_estimate_step_subnormal_inputs() {
    const FPCR_FZ: u64 = 1 << 24;
    let mut batch: Vec<(String, u32, ArmState)> = Vec::new();

    let pack_s = |value: u32| -> (u64, u64) {
        let mut packed = 0u128;
        for lane in 0..4 {
            packed |= (value as u128) << (32 * lane);
        }
        (packed as u64, (packed >> 64) as u64)
    };
    let pack_d = |value: u64| -> (u64, u64) {
        let packed = (value as u128) | ((value as u128) << 64);
        (packed as u64, (packed >> 64) as u64)
    };

    for &(name, u) in &[("frecpe", 0), ("frsqrte", 1)] {
        let mut st = ArmState::zeroed();
        st.fpcr = FPCR_FZ;
        st.set_vreg(RN as usize, 0x0000_0001, 0);
        batch.push((
            format!("scalar_{name}_s_fz_min_subnorm"),
            enc_scalar_two_reg(u, 0b10, 0b11101),
            st,
        ));

        let mut st = ArmState::zeroed();
        st.fpcr = FPCR_FZ;
        st.set_vreg(RN as usize, 0x0000_0000_0000_0001, 0);
        batch.push((
            format!("scalar_{name}_d_fz_min_subnorm"),
            enc_scalar_two_reg(u, 0b11, 0b11101),
            st,
        ));

        let mut st = ArmState::zeroed();
        st.fpcr = FPCR_FZ;
        let (lo, hi) = pack_s(0x0000_0001);
        st.set_vreg(RN as usize, lo, hi);
        batch.push((
            format!("simd_{name}_s_fz_min_subnorm"),
            enc_two_reg(1, u, 0b10, 0b11101),
            st,
        ));

        let mut st = ArmState::zeroed();
        st.fpcr = FPCR_FZ;
        let (lo, hi) = pack_d(0x0000_0000_0000_0001);
        st.set_vreg(RN as usize, lo, hi);
        batch.push((
            format!("simd_{name}_d_fz_min_subnorm"),
            enc_two_reg(1, u, 0b11, 0b11101),
            st,
        ));
    }

    for &(name, size, bits) in &[
        ("s", 0b10, 0x0000_0001u64),
        ("d", 0b11, 0x0000_0000_0000_0001u64),
    ] {
        let mut st = ArmState::zeroed();
        st.fpcr = FPCR_FZ;
        st.set_vreg(RN as usize, bits, 0);
        batch.push((
            format!("scalar_frecpx_{name}_fz_min_subnorm"),
            enc_scalar_two_reg(0, size, 0b11111),
            st,
        ));
    }

    for &(name, kind_u, kind_size, kind_opcode) in &[
        ("fmulx", 0, 0, 0b11011),
        ("frecps", 0, 0, 0b11111),
        ("frsqrts", 0, 0b10, 0b11111),
    ] {
        let mut st = ArmState::zeroed();
        st.fpcr = FPCR_FZ;
        st.set_vreg(RN as usize, 0x0000_0001, 0);
        st.set_vreg(RM as usize, 1.0f32.to_bits() as u64, 0);
        batch.push((
            format!("scalar_{name}_s_fz_min_subnorm"),
            enc_scalar_three_same(kind_u, kind_size, kind_opcode),
            st,
        ));

        let mut st = ArmState::zeroed();
        st.fpcr = FPCR_FZ;
        st.set_vreg(RN as usize, 0x0000_0000_0000_0001, 0);
        st.set_vreg(RM as usize, 1.0f64.to_bits(), 0);
        batch.push((
            format!("scalar_{name}_d_fz_min_subnorm"),
            enc_scalar_three_same(kind_u, kind_size | 1, kind_opcode),
            st,
        ));

        let mut st = ArmState::zeroed();
        st.fpcr = FPCR_FZ;
        let (lo, hi) = pack_s(0x0000_0001);
        st.set_vreg(RN as usize, lo, hi);
        let (lo, hi) = pack_s(1.0f32.to_bits());
        st.set_vreg(RM as usize, lo, hi);
        batch.push((
            format!("simd_{name}_s_fz_min_subnorm"),
            enc_three_same(1, kind_u, kind_size, kind_opcode),
            st,
        ));

        let mut st = ArmState::zeroed();
        st.fpcr = FPCR_FZ;
        let (lo, hi) = pack_d(0x0000_0000_0000_0001);
        st.set_vreg(RN as usize, lo, hi);
        let (lo, hi) = pack_d(1.0f64.to_bits());
        st.set_vreg(RM as usize, lo, hi);
        batch.push((
            format!("simd_{name}_d_fz_min_subnorm"),
            enc_three_same(1, kind_u, kind_size | 1, kind_opcode),
            st,
        ));
    }

    run_batch("fpcr_fz_fp_estimate_step_subnormal_inputs", batch);
}

#[test]
fn diff_simd_f32_arith_fpcr_rounding() {
    let mut batch: Vec<(String, u32, ArmState)> = Vec::new();
    for rmode in 0..4u64 {
        let fpcr = rmode << 22;
        for &(u, opcode, name, rhs_sign) in &[
            (0, 0b11010, "fadd", 1.0f32),
            (0, 0b11010, "fadd_neg", -1.0f32),
            (0, 0b11010, "faddp", 1.0f32),
            (0, 0b11010, "faddp_neg", -1.0f32),
            (0, 0b11010, "fsub", -1.0f32),
            (0, 0b11010, "fsub_neg", 1.0f32),
        ] {
            let mut st = ArmState::zeroed();
            st.fpcr = fpcr;
            let lhs = if name.ends_with("neg") {
                -16_777_216.0f32
            } else {
                16_777_216.0f32
            };
            let mut n = 0u128;
            let mut m = 0u128;
            for lane in 0..4 {
                n |= (lhs.to_bits() as u128) << (32 * lane);
                m |= (rhs_sign.to_bits() as u128) << (32 * lane);
            }
            st.set_vreg(RN as usize, n as u64, (n >> 64) as u64);
            st.set_vreg(RM as usize, m as u64, (m >> 64) as u64);
            let (enc_u, a_bit, enc_opcode) = match name {
                "faddp" | "faddp_neg" => (1, 0, 0b11010),
                "fsub" | "fsub_neg" => (0, 1, 0b11010),
                _ => (u, 0, opcode),
            };
            batch.push((
                format!("{name}_rmode{rmode}"),
                enc_three_same(1, enc_u, a_bit << 1, enc_opcode),
                st,
            ));
        }

        let mut st = ArmState::zeroed();
        st.fpcr = fpcr;
        let lhs = f32::from_bits(0x3f80_0001);
        let rhs = f32::from_bits(0x3f80_0001);
        let mut n = 0u128;
        let mut m = 0u128;
        for lane in 0..4 {
            n |= (lhs.to_bits() as u128) << (32 * lane);
            m |= (rhs.to_bits() as u128) << (32 * lane);
        }
        st.set_vreg(RN as usize, n as u64, (n >> 64) as u64);
        st.set_vreg(RM as usize, m as u64, (m >> 64) as u64);
        batch.push((
            format!("fmul_rmode{rmode}"),
            enc_three_same(1, 1, 0, 0b11011),
            st,
        ));

        let mut st = ArmState::zeroed();
        st.fpcr = fpcr;
        let lhs = f32::from_bits(0x3f80_0001);
        let rhs = f32::from_bits(0x3f80_0001);
        let mut n = 0u128;
        let mut m = 0u128;
        for lane in 0..4 {
            n |= (lhs.to_bits() as u128) << (32 * lane);
            m |= (rhs.to_bits() as u128) << (32 * lane);
        }
        st.set_vreg(RN as usize, n as u64, (n >> 64) as u64);
        st.set_vreg(RM as usize, m as u64, (m >> 64) as u64);
        batch.push((
            format!("fmulx_rmode{rmode}"),
            enc_three_same(1, 0, 0, 0b11011),
            st,
        ));
    }

    run_batch("simd_f32_arith_fpcr_rounding", batch);
}

