#[test]
fn diff_simd_faddp_fpcr_rounding() {
    let mut batch: Vec<(String, u32, ArmState)> = Vec::new();
    for rmode in 0..4u64 {
        let fpcr = rmode << 22;

        let mut st = ArmState::zeroed();
        st.fpcr = fpcr;
        let f32_lanes = [16_777_216.0f32, 1.0f32, -16_777_216.0f32, -1.0f32];
        let mut packed = 0u128;
        for (lane, value) in f32_lanes.iter().enumerate() {
            packed |= (value.to_bits() as u128) << (32 * lane);
        }
        st.set_vreg(RN as usize, packed as u64, (packed >> 64) as u64);
        st.set_vreg(RM as usize, packed as u64, (packed >> 64) as u64);
        batch.push((
            format!("f32_rmode{rmode}"),
            enc_three_same(1, 1, 0, 0b11010),
            st,
        ));

        let mut st = ArmState::zeroed();
        st.fpcr = fpcr;
        let n = (9_007_199_254_740_992.0f64.to_bits() as u128) | ((1.0f64.to_bits() as u128) << 64);
        let m = ((-9_007_199_254_740_992.0f64).to_bits() as u128)
            | (((-1.0f64).to_bits() as u128) << 64);
        st.set_vreg(RN as usize, n as u64, (n >> 64) as u64);
        st.set_vreg(RM as usize, m as u64, (m >> 64) as u64);
        batch.push((
            format!("f64_rmode{rmode}"),
            enc_three_same(1, 1, 1, 0b11010),
            st,
        ));
    }

    run_batch("simd_faddp_fpcr_rounding", batch);
}

fn enc_simd_scalar_faddp(size: u32) -> u32 {
    0x5e30_d800 | (1 << 29) | (size << 22) | (RN << 5) | RD
}

fn enc_simd_scalar_pairwise(u: u32, size: u32, opcode: u32) -> u32 {
    (1 << 30)
        | (u << 29)
        | (0b11110 << 24)
        | (size << 22)
        | (0b11000 << 17)
        | (opcode << 12)
        | (0b10 << 10)
        | (RN << 5)
        | RD
}

#[test]
fn diff_simd_scalar_faddp_fpcr_rounding() {
    let mut batch: Vec<(String, u32, ArmState)> = Vec::new();
    for rmode in 0..4u64 {
        let fpcr = rmode << 22;

        for &(name, a, b) in &[
            ("f32_pos", 16_777_216.0f32, 1.0f32),
            ("f32_neg", -16_777_216.0f32, -1.0f32),
        ] {
            let mut st = ArmState::zeroed();
            st.fpcr = fpcr;
            st.set_vreg(
                RN as usize,
                (a.to_bits() as u64) | ((b.to_bits() as u64) << 32),
                0,
            );
            batch.push((format!("{name}_rmode{rmode}"), enc_simd_scalar_faddp(0), st));
        }

        for &(name, a, b) in &[
            ("f64_pos", 9_007_199_254_740_992.0f64, 1.0f64),
            ("f64_neg", -9_007_199_254_740_992.0f64, -1.0f64),
        ] {
            let mut st = ArmState::zeroed();
            st.fpcr = fpcr;
            let packed = (a.to_bits() as u128) | ((b.to_bits() as u128) << 64);
            st.set_vreg(RN as usize, packed as u64, (packed >> 64) as u64);
            batch.push((format!("{name}_rmode{rmode}"), enc_simd_scalar_faddp(1), st));
        }
    }

    run_batch("simd_scalar_faddp_fpcr_rounding", batch);
}

