/// Scalar Advanced SIMD three-same: `01 U 11110 size 1 Rm opcode 1 Rn Rd`.
fn enc_scalar_3same(u: u32, size: u32, opcode: u32) -> u32 {
    (0b01 << 30)
        | (u << 29)
        | (0b11110 << 24)
        | (size << 22)
        | (1 << 21)
        | (RM << 16)
        | (opcode << 11)
        | (1 << 10)
        | (RN << 5)
        | RD
}

#[test]
fn diff_simd_scalar_three_same() {
    // Integer scalar three-same opcodes (size validity is enforced by rax /
    // checked against the oracle).
    let opcodes: &[(u32, &str)] = &[
        (0b00001, "sqadd"),
        (0b00101, "sqsub"),
        (0b00110, "cmgt_cmhi"),
        (0b00111, "cmge_cmhs"),
        (0b01000, "sshl_ushl"),
        (0b01001, "sqshl_uqshl"),
        (0b01010, "srshl_urshl"),
        (0b01011, "sqrshl_uqrshl"),
        (0b10000, "add_sub"),
        (0b10001, "cmtst_cmeq"),
        (0b10110, "sqdmulh_sqrdmulh"),
    ];
    let mut cases: Vec<(String, u32)> = Vec::new();
    for &(opcode, name) in opcodes {
        for u in 0..2 {
            for size in 0..4 {
                cases.push((
                    format!("{name} u{u} sz{size}"),
                    enc_scalar_3same(u, size, opcode),
                ));
            }
        }
    }
    run_family("simd_scalar_three_same", cases, 8, 0xD001);
}

#[test]
fn diff_simd_scalar_fp_three_same_unallocated() {
    // The scalar AdvSIMD FP three-same space is much smaller than the vector
    // table: ordinary arithmetic and pairwise forms are unallocated here.
    let mut batch = Vec::new();
    let invalid: &[(u32, &[u32], &[u32])] = &[
        (0, &[0, 1, 2, 3], &[0b11000, 0b11001, 0b11010, 0b11110]),
        (1, &[0, 1], &[0b11000, 0b11010, 0b11011, 0b11110, 0b11111]),
        (1, &[2, 3], &[0b11000, 0b11110]),
    ];
    for &(u, sizes, opcodes) in invalid {
        for &size in sizes {
            for &opcode in opcodes {
                let mut st = ArmState::zeroed();
                st.set_vreg(0, 3.0f64.to_bits(), 0x8899_aabb_ccdd_eeff);
                st.set_vreg(1, 1.0f64.to_bits(), 0);
                st.set_vreg(2, 2.0f64.to_bits(), 0);
                batch.push((
                    format!("scalar_fp_3same_u{u}_size{size}_op{opcode:05b}"),
                    enc_scalar_3same(u, size, opcode),
                    st,
                ));
            }
        }
    }
    run_batch("simd_scalar_fp_three_same_unallocated", batch);
}

