/// Advanced SIMD copy: `0 Q op 01110000 imm5 0 imm4 1 Rn Rd`.
fn enc_copy(q: u32, op: u32, imm5: u32, imm4: u32) -> u32 {
    (q << 30)
        | (op << 29)
        | (0b01110 << 24)
        | (imm5 << 16)
        | (imm4 << 11)
        | (1 << 10)
        | (RN << 5)
        | RD
}

fn enc_copy_scalar(imm5: u32, imm4: u32) -> u32 {
    enc_copy_scalar_op(0, imm5, imm4)
}

fn enc_copy_scalar_op(op: u32, imm5: u32, imm4: u32) -> u32 {
    (1 << 30)
        | (op << 29)
        | (0b11110 << 24)
        | (imm5 << 16)
        | (imm4 << 11)
        | (1 << 10)
        | (RN << 5)
        | RD
}

/// imm5 for a given element size index (0=B,1=H,2=S,3=D) and lane index.
fn copy_imm5(size: u32, index: u32) -> u32 {
    (index << (size + 1)) | (1 << size)
}

#[test]
fn diff_simd_copy() {
    let mut cases: Vec<(String, u32)> = Vec::new();
    // DUP element (op0 imm4 0000), DUP general (imm4 0001), INS general (0011),
    // SMOV (0101), UMOV (0111); INS element (op1).
    for size in 0..4u32 {
        let lanes: u32 = 16u32 >> size; // lanes in 128 bits (16/8/4/2)
        for index in 0..lanes {
            for q in 0..2 {
                cases.push((
                    format!("dupelem sz{size} i{index} q{q}"),
                    enc_copy(q, 0, copy_imm5(size, index), 0b0000),
                ));
                cases.push((
                    format!("dupgen sz{size} i{index} q{q}"),
                    enc_copy(q, 0, copy_imm5(size, index), 0b0001),
                ));
                cases.push((
                    format!("smov sz{size} i{index} q{q}"),
                    enc_copy(q, 0, copy_imm5(size, index), 0b0101),
                ));
                cases.push((
                    format!("umov sz{size} i{index} q{q}"),
                    enc_copy(q, 0, copy_imm5(size, index), 0b0111),
                ));
            }
            // INS general/element are always 128-bit (Q=1 in the encoding).
            cases.push((
                format!("insgen sz{size} i{index}"),
                enc_copy(1, 0, copy_imm5(size, index), 0b0011),
            ));
            // INS element: dest index from imm5, source index from imm4 (per size).
            let src = (index + 1) % lanes;
            cases.push((
                format!("inselem sz{size} d{index} s{src}"),
                enc_copy(1, 1, copy_imm5(size, index), src << size),
            ));
        }
    }
    run_family("simd_copy", cases, 4, 0x9001);
}

#[test]
fn diff_simd_copy_scalar_dup_element() {
    let mut cases: Vec<(String, u32)> = Vec::new();

    for size in 0..4u32 {
        let lanes = 16u32 >> size;
        for index in 0..lanes {
            cases.push((
                format!("scalar_dupelem sz{size} i{index}"),
                enc_copy_scalar(copy_imm5(size, index), 0b0000),
            ));
        }
    }

    run_family("simd_copy_scalar_dup_element", cases, 8, 0x9004);
}

#[test]
fn diff_simd_copy_unallocated_edges() {
    let mut rng = Rng::new(0x9003);
    let mut batch: Vec<(String, u32, ArmState)> = Vec::new();

    for &(q, op) in &[(0u32, 0u32), (0, 1), (1, 1)] {
        batch.push((
            format!("copy_bit31_q{q}_op{op}"),
            enc_copy(q, op, copy_imm5(0, 0), 0b0000) | (1 << 31),
            gen_input(&mut rng),
        ));
    }

    for q in 0..2u32 {
        for op in 0..2u32 {
            for &imm4 in &[0b0000, 0b0001, 0b0011, 0b0101, 0b0111, 0b1111] {
                for _ in 0..4 {
                    batch.push((
                        format!("copy_imm5_zero q{q} op{op} imm4_{imm4:04b}"),
                        enc_copy(q, op, 0, imm4),
                        gen_input(&mut rng),
                    ));
                }
            }
        }
    }

    for size in 0..4u32 {
        let lanes = 16u32 >> size;
        for index in 0..lanes {
            let src = (index + 1) % lanes;
            for _ in 0..4 {
                batch.push((
                    format!("inselem_q0 sz{size} d{index} s{src}"),
                    enc_copy(0, 1, copy_imm5(size, index), src << size),
                    gen_input(&mut rng),
                ));
            }
        }
    }

    for &imm4 in &[
        0b0010, 0b0100, 0b0110, 0b1000, 0b1001, 0b1010, 0b1011, 0b1100, 0b1101, 0b1110, 0b1111,
    ] {
        for size in 0..4u32 {
            for q in 0..2u32 {
                for _ in 0..4 {
                    batch.push((
                        format!("copy_reserved_imm4_{imm4:04b} sz{size} q{q}"),
                        enc_copy(q, 0, copy_imm5(size, 0), imm4),
                        gen_input(&mut rng),
                    ));
                }
            }
        }
    }

    run_batch_el0_legality("simd_copy_unallocated_edges", batch);
}

#[test]
fn diff_simd_copy_scalar_unallocated_edges() {
    let mut rng = Rng::new(0x9005);
    let mut batch: Vec<(String, u32, ArmState)> = Vec::new();

    for &imm4 in &[
        0b0001u32, 0b0011, 0b0101, 0b0111, 0b1000, 0b1010, 0b1100, 0b1111,
    ] {
        for size in 0..4u32 {
            batch.push((
                format!("scalar_copy_reserved_imm4_{imm4:04b}_sz{size}"),
                enc_copy_scalar(copy_imm5(size, 0), imm4),
                gen_input(&mut rng),
            ));
        }
    }

    batch.push((
        "scalar_copy_imm5_zero".to_string(),
        enc_copy_scalar(0, 0),
        gen_input(&mut rng),
    ));
    batch.push((
        "scalar_copy_bit31".to_string(),
        enc_copy_scalar(copy_imm5(0, 0), 0) | (1 << 31),
        gen_input(&mut rng),
    ));

    for size in 0..4u32 {
        batch.push((
            format!("scalar_copy_reserved_op1_sz{size}"),
            enc_copy_scalar_op(1, copy_imm5(size, 0), 0),
            gen_input(&mut rng),
        ));
    }

    run_batch_el0_legality("simd_copy_scalar_unallocated_edges", batch);
}

#[test]
fn diff_simd_copy_zero_registers() {
    fn enc_copy_regs(q: u32, op: u32, imm5: u32, imm4: u32, rn: u32, rd: u32) -> u32 {
        (q << 30)
            | (op << 29)
            | (0b01110 << 24)
            | (imm5 << 16)
            | (imm4 << 11)
            | (1 << 10)
            | ((rn & 0x1f) << 5)
            | (rd & 0x1f)
    }

    let mut rng = Rng::new(0x9002);
    let mut batch: Vec<(String, u32, ArmState)> = Vec::new();
    for size in 0..4u32 {
        let lanes: u32 = 16u32 >> size;
        for index in 0..lanes {
            let imm5 = copy_imm5(size, index);
            for q in 0..2u32 {
                if q == 1 || size != 3 {
                    let mut st = gen_input(&mut rng);
                    st.sp = GUEST_STACK_ADDR + (GUEST_STACK_SIZE / 2) + 0x17000;
                    batch.push((
                        format!("dupgen_xzr sz{size} i{index} q{q}"),
                        enc_copy_regs(q, 0, imm5, 0b0001, 31, RD),
                        st,
                    ));
                }
                let smov_valid = size < 2 || (size == 2 && q == 1);
                if smov_valid {
                    let mut st = gen_input(&mut rng);
                    st.sp = GUEST_STACK_ADDR + (GUEST_STACK_SIZE / 2) + 0x17000;
                    batch.push((
                        format!("smov_xzr_dest sz{size} i{index} q{q}"),
                        enc_copy_regs(q, 0, imm5, 0b0101, RN, 31),
                        st,
                    ));
                }
                let umov_valid = (size <= 2 && q == 0) || (size == 3 && q == 1);
                if umov_valid {
                    let mut st = gen_input(&mut rng);
                    st.sp = GUEST_STACK_ADDR + (GUEST_STACK_SIZE / 2) + 0x17000;
                    batch.push((
                        format!("umov_xzr_dest sz{size} i{index} q{q}"),
                        enc_copy_regs(q, 0, imm5, 0b0111, RN, 31),
                        st,
                    ));
                }
            }

            let mut st = gen_input(&mut rng);
            st.sp = GUEST_STACK_ADDR + (GUEST_STACK_SIZE / 2) + 0x17000;
            batch.push((
                format!("insgen_xzr sz{size} i{index}"),
                enc_copy_regs(1, 0, imm5, 0b0011, 31, RD),
                st,
            ));
        }
    }
    run_batch("simd_copy_zero_registers", batch);
}

/// Advanced SIMD two-register miscellaneous: `0 Q U 01110 size 10000 opcode 10 Rn Rd`.
fn enc_two_reg(q: u32, u: u32, size: u32, opcode: u32) -> u32 {
    (q << 30)
        | (u << 29)
        | (0b01110 << 24)
        | (size << 22)
        | (0b10000 << 17)
        | (opcode << 12)
        | (0b10 << 10)
        | (RN << 5)
        | RD
}

/// Advanced SIMD scalar two-register FP misc:
/// `0 1 U 11110 size 10000 opcode 10 Rn Rd`.
fn enc_scalar_two_reg(u: u32, size: u32, opcode: u32) -> u32 {
    (1 << 30)
        | (u << 29)
        | (0b11110 << 24)
        | (size << 22)
        | (0b10000 << 17)
        | (opcode << 12)
        | (0b10 << 10)
        | (RN << 5)
        | RD
}

