#[test]
fn diff_simd_two_reg_unallocated_edges() {
    let mut rng = Rng::new(0x6004);
    let mut batch: Vec<(String, u32, ArmState)> = Vec::new();

    for size in 0..4u32 {
        for q in 0..2u32 {
            for &(u, opcode, name) in &[
                (1, 0b00001, "rev16_u1"),
                (1, 0b01010, "cmlt_u1"),
                (0, 0b10000, "reserved_10000"),
                (0, 0b10001, "reserved_10001"),
                (1, 0b10101, "reserved_10101"),
            ] {
                for _ in 0..4 {
                    batch.push((
                        format!("{name} sz{size} q{q}"),
                        enc_two_reg(q, u, size, opcode),
                        gen_input(&mut rng),
                    ));
                }
            }
        }
    }

    for size in 0..3u32 {
        for q in 0..2u32 {
            for _ in 0..4 {
                batch.push((
                    format!("shll_u0 sz{size} q{q}"),
                    enc_two_reg(q, 0, size, 0b10011),
                    gen_input(&mut rng),
                ));
            }
        }
    }

    for size in 0..2u32 {
        for q in 0..2u32 {
            for u in 0..2u32 {
                for opcode in 0b01100..=0b01110 {
                    for _ in 0..4 {
                        batch.push((
                            format!("fp_compare_low_size op{opcode:05b} u{u} sz{size} q{q}"),
                            enc_two_reg(q, u, size, opcode),
                            gen_input(&mut rng),
                        ));
                    }
                }
            }
        }
    }

    for &(u, size, opcode, name) in &[
        (1, 0, 0b00001, "scalar_rev16_u1"),
        (1, 0, 0b01010, "scalar_cmlt_u1"),
        (0, 0, 0b10000, "scalar_reserved_10000"),
        (0, 2, 0b10001, "scalar_reserved_10001"),
        (1, 2, 0b10101, "scalar_reserved_10101"),
    ] {
        for _ in 0..4 {
            batch.push((
                name.to_string(),
                enc_scalar_two_reg(u, size, opcode),
                gen_input(&mut rng),
            ));
        }
    }

    for &(q, u, size, opcode, name) in &[
        (0, 0, 0, 0b00000, "rev64_bit31"),
        (0, 1, 0, 0b00000, "rev32_bit31"),
        (1, 1, 0, 0b01011, "neg_bit31"),
        (1, 1, 2, 0b11111, "fsqrt_bit31"),
    ] {
        for _ in 0..4 {
            batch.push((
                format!("{name}_q{q}_u{u}"),
                enc_two_reg(q, u, size, opcode) | (1 << 31),
                gen_input(&mut rng),
            ));
        }
    }

    run_batch_el0_legality("simd_two_reg_unallocated_edges", batch);
}

/// Fill registers v0..v2 with finite float lanes (multiples of 0.25, so rounding
/// ties land exactly on .5). If `nonneg`, all lanes are >= 0 (for FSQRT).
fn fill_fp_lanes(st: &mut ArmState, rng: &mut Rng, f64op: bool, nonneg: bool) {
    for r in 0..3usize {
        let mut packed: u128 = 0;
        if f64op {
            for lane in 0..2 {
                let n = (rng.next() % 256) as i64;
                let iv = if nonneg { n } else { n - 128 };
                let val = iv as f64 * 0.25;
                packed |= (val.to_bits() as u128) << (64 * lane);
            }
        } else {
            for lane in 0..4 {
                let n = (rng.next() % 256) as i64;
                let iv = if nonneg { n } else { n - 128 };
                let val = iv as f32 * 0.25;
                packed |= (val.to_bits() as u128) << (32 * lane);
            }
        }
        st.set_vreg(r, packed as u64, (packed >> 64) as u64);
    }
}

/// Build FP two-reg cases for the given (u, sz_hi, opcode, name) ops, covering
/// f32 (2S/4S) and f64 (2D), then drive `n` finite inputs through each.
fn fp_two_reg_batch(
    ops: &[(u32, u32, u32, &str)],
    seed: u64,
    n: usize,
    nonneg: bool,
) -> Vec<(String, u32, ArmState)> {
    let mut cases: Vec<(String, u32, bool)> = Vec::new();
    for &(u, sz_hi, opcode, name) in ops {
        // f32: 2S (q=0) and 4S (q=1)
        for q in 0..2 {
            let size = sz_hi << 1; // sz=0
            cases.push((
                format!("{name} f32 q{q}"),
                enc_two_reg(q, u, size, opcode),
                false,
            ));
        }
        // f64: 2D (q=1 only)
        let size = (sz_hi << 1) | 1;
        cases.push((format!("{name} f64"), enc_two_reg(1, u, size, opcode), true));
    }
    let mut rng = Rng::new(seed);
    let mut batch = Vec::new();
    for (label, insn, f64op) in &cases {
        for _ in 0..n {
            let mut st = ArmState::zeroed();
            fill_fp_lanes(&mut st, &mut rng, *f64op, nonneg);
            batch.push((label.clone(), *insn, st));
        }
    }
    batch
}

