#[test]
fn diff_fpcr_fz_fp_unary_subnormal_inputs() {
    const FPCR_FZ: u64 = 1 << 24;
    let mut batch: Vec<(String, u32, ArmState)> = Vec::new();

    let pack_s = |value: u32| -> (u64, u64) {
        let mut packed = 0u128;
        for lane in 0..4 {
            packed |= (value as u128) << (32 * lane);
        }
        (packed as u64, (packed >> 64) as u64)
    };
    let pack_d = |value: u64| -> (u64, u64) {
        let packed = (value as u128) | ((value as u128) << 64);
        (packed as u64, (packed >> 64) as u64)
    };

    for &(name, opcode) in &[("frintp", 0b01001), ("fsqrt", 0b00011)] {
        let mut st = ArmState::zeroed();
        st.fpcr = FPCR_FZ;
        st.set_vreg(RN as usize, 0x0000_0001, 0);
        batch.push((
            format!("fp_scalar_{name}_s_fz_min_subnorm"),
            enc_fp1(0, opcode),
            st,
        ));

        let mut st = ArmState::zeroed();
        st.fpcr = FPCR_FZ;
        st.set_vreg(RN as usize, 0x0000_0000_0000_0001, 0);
        batch.push((
            format!("fp_scalar_{name}_d_fz_min_subnorm"),
            enc_fp1(1, opcode),
            st,
        ));
    }

    for &(name, opcode) in &[("frint32z", 0b10000), ("frint32x", 0b10001)] {
        let mut st = ArmState::zeroed();
        st.fpcr = FPCR_FZ;
        st.set_vreg(RN as usize, 0x0000_0001, 0);
        batch.push((
            format!("fp_scalar_{name}_s_fz_min_subnorm"),
            enc_fp1(0, opcode),
            st,
        ));

        let mut st = ArmState::zeroed();
        st.fpcr = FPCR_FZ;
        st.set_vreg(RN as usize, 0x0000_0000_0000_0001, 0);
        batch.push((
            format!("fp_scalar_{name}_d_fz_min_subnorm"),
            enc_fp1(1, opcode),
            st,
        ));
    }

    for &(name, u, size_hi, opcode) in &[("frintp", 0, 1, 0b11000), ("fsqrt", 1, 1, 0b11111)] {
        let mut st = ArmState::zeroed();
        st.fpcr = FPCR_FZ;
        let (lo, hi) = pack_s(0x0000_0001);
        st.set_vreg(RN as usize, lo, hi);
        batch.push((
            format!("simd_{name}_s_fz_min_subnorm"),
            enc_two_reg(1, u, size_hi << 1, opcode),
            st,
        ));

        let mut st = ArmState::zeroed();
        st.fpcr = FPCR_FZ;
        let (lo, hi) = pack_d(0x0000_0000_0000_0001);
        st.set_vreg(RN as usize, lo, hi);
        batch.push((
            format!("simd_{name}_d_fz_min_subnorm"),
            enc_two_reg(1, u, (size_hi << 1) | 1, opcode),
            st,
        ));
    }

    for &(name, u, opcode) in &[
        ("frint32z", 0, 0b11110),
        ("frint32x", 1, 0b11110),
        ("frint64z", 0, 0b11111),
        ("frint64x", 1, 0b11111),
    ] {
        let mut st = ArmState::zeroed();
        st.fpcr = FPCR_FZ;
        let (lo, hi) = pack_s(0x0000_0001);
        st.set_vreg(RN as usize, lo, hi);
        batch.push((
            format!("simd_{name}_s_fz_min_subnorm"),
            enc_two_reg(1, u, 0, opcode),
            st,
        ));

        let mut st = ArmState::zeroed();
        st.fpcr = FPCR_FZ;
        let (lo, hi) = pack_d(0x0000_0000_0000_0001);
        st.set_vreg(RN as usize, lo, hi);
        batch.push((
            format!("simd_{name}_d_fz_min_subnorm"),
            enc_two_reg(1, u, 1, opcode),
            st,
        ));
    }

    run_batch("fpcr_fz_fp_unary_subnormal_inputs", batch);
}

#[test]
fn diff_simd_two_reg_cvtf() {
    // SCVTF/UCVTF take integer source lanes.
    let ops: &[(u32, u32, u32, &str)] = &[(0, 0, 0b11101, "scvtf"), (1, 0, 0b11101, "ucvtf")];
    let mut cases: Vec<(String, u32, bool)> = Vec::new();
    for &(u, sz_hi, opcode, name) in ops {
        for q in 0..2 {
            cases.push((
                format!("{name} 32 q{q}"),
                enc_two_reg(q, u, sz_hi << 1, opcode),
                false,
            ));
        }
        cases.push((
            format!("{name} 64"),
            enc_two_reg(1, u, (sz_hi << 1) | 1, opcode),
            true,
        ));
    }
    let mut rng = Rng::new(0xA003);
    let mut batch = Vec::new();
    for (label, insn, is64) in &cases {
        for _ in 0..16 {
            let mut st = ArmState::zeroed();
            let mut packed: u128 = 0;
            if *is64 {
                for lane in 0..2 {
                    packed |= ((rng.next() as u64) as u128) << (64 * lane);
                }
            } else {
                for lane in 0..4 {
                    packed |= ((rng.next() as u32) as u128) << (32 * lane);
                }
            }
            st.set_vreg(1, packed as u64, (packed >> 64) as u64);
            batch.push((label.clone(), *insn, st));
        }
    }
    run_batch("simd_two_reg_cvtf", batch);
}

/// Advanced SIMD vector x indexed element: `0 Q U 01111 size L M Rm opcode H 0 Rn Rd`.
fn enc_indexed(q: u32, u: u32, size: u32, opcode: u32, vm: u32, index: u32) -> u32 {
    let (rm, mbit, lbit, hbit) = match size {
        0b01 => (vm & 0xF, index & 1, (index >> 1) & 1, (index >> 2) & 1),
        0b10 => (vm & 0xF, (vm >> 4) & 1, index & 1, (index >> 1) & 1),
        0b11 => (vm & 0xF, (vm >> 4) & 1, 0, index & 1),
        _ => (0, 0, 0, 0),
    };
    (q << 30)
        | (u << 29)
        | (0b01111 << 24)
        | (size << 22)
        | (lbit << 21)
        | (mbit << 20)
        | (rm << 16)
        | (opcode << 12)
        | (hbit << 11)
        | (RN << 5)
        | RD
}

fn enc_indexed_scalar(u: u32, size: u32, opcode: u32, vm: u32, index: u32) -> u32 {
    let (rm, mbit, lbit, hbit) = match size {
        0b01 => (vm & 0xF, index & 1, (index >> 1) & 1, (index >> 2) & 1),
        0b10 => (vm & 0xF, (vm >> 4) & 1, index & 1, (index >> 1) & 1),
        0b11 => (vm & 0xF, (vm >> 4) & 1, 0, index & 1),
        _ => (0, 0, 0, 0),
    };
    (1 << 30)
        | (u << 29)
        | (0b11111 << 24)
        | (size << 22)
        | (lbit << 21)
        | (mbit << 20)
        | (rm << 16)
        | (opcode << 12)
        | (hbit << 11)
        | (RN << 5)
        | RD
}

#[test]
fn diff_simd_indexed_int() {
    // (U, opcode) for the integer indexed ops; widening forms produce 2x results.
    let ops: &[(u32, u32, &str)] = &[
        (0, 0b1000, "mul"),
        (1, 0b0000, "mla"),
        (1, 0b0100, "mls"),
        (0, 0b1100, "sqdmulh"),
        (0, 0b1101, "sqrdmulh"),
        (1, 0b1101, "sqrdmlah"),
        (1, 0b1111, "sqrdmlsh"),
        (0, 0b0010, "smlal"),
        (1, 0b0010, "umlal"),
        (0, 0b0110, "smlsl"),
        (1, 0b0110, "umlsl"),
        (0, 0b1010, "smull"),
        (1, 0b1010, "umull"),
        (0, 0b0011, "sqdmlal"),
        (0, 0b0111, "sqdmlsl"),
        (0, 0b1011, "sqdmull"),
    ];
    let mut cases: Vec<(String, u32)> = Vec::new();
    for &(u, opcode, name) in ops {
        for &size in &[0b01u32, 0b10] {
            let max_index = if size == 0b01 { 8 } else { 4 };
            for q in 0..2 {
                for index in 0..max_index {
                    cases.push((
                        format!("{name} sz{size} q{q} idx{index}"),
                        enc_indexed(q, u, size, opcode, 2, index),
                    ));
                }
            }
        }
    }
    run_family("simd_indexed_int", cases, 4, 0x5001);
}

