#[test]
fn diff_simd_indexed_fp() {
    let ops: &[(u32, u32, &str)] = &[
        (0, 0b1001, "fmul"),
        (0, 0b0001, "fmla"),
        (0, 0b0101, "fmls"),
        (1, 0b1001, "fmulx"),
    ];
    let mut cases: Vec<(String, u32)> = Vec::new();
    for &(u, opcode, name) in ops {
        // size 10 = f32 (index 0..3), size 11 = f64 (index 0..1, Q must be 1)
        for &(size, qs, maxidx) in &[(0b10u32, &[0u32, 1][..], 4u32), (0b11u32, &[1u32][..], 2)] {
            for &q in qs {
                for index in 0..maxidx {
                    cases.push((
                        format!("{name} sz{size} q{q} idx{index}"),
                        enc_indexed(q, u, size, opcode, 2, index),
                    ));
                }
            }
        }
    }
    // Clean finite FP inputs in v1 (Rn), v2 (Rm), v0 (Rd accumulator).
    let mut rng = Rng::new(0x5002);
    let mut batch: Vec<(String, u32, ArmState)> = Vec::new();
    for (label, insn) in &cases {
        let f64op = label.contains("sz11");
        for _ in 0..16 {
            let mut st = ArmState::zeroed();
            for r in [0usize, 1, 2] {
                let mut packed: u128 = 0;
                if f64op {
                    for lane in 0..2 {
                        let val = ((rng.next() % 41) as i64 - 20) as f64 * 0.5;
                        packed |= (val.to_bits() as u128) << (64 * lane);
                    }
                } else {
                    for lane in 0..4 {
                        let val = ((rng.next() % 41) as i64 - 20) as f32 * 0.5;
                        packed |= (val.to_bits() as u128) << (32 * lane);
                    }
                }
                st.set_vreg(r, packed as u64, (packed >> 64) as u64);
            }
            batch.push((label.clone(), *insn, st));
        }
    }
    run_batch("simd_indexed_fp", batch);
}

#[test]
fn diff_simd_scalar_indexed_fp() {
    let ops: &[(u32, u32, &str)] = &[
        (0, 0b1001, "fmul"),
        (0, 0b0001, "fmla"),
        (0, 0b0101, "fmls"),
        (1, 0b1001, "fmulx"),
    ];
    let mut rng = Rng::new(0x5006);
    let mut batch: Vec<(String, u32, ArmState)> = Vec::new();

    for &(u, opcode, name) in ops {
        for &(size, max_index, lanes) in &[(0b10u32, 4u32, 4usize), (0b11, 2, 2)] {
            for index in 0..max_index {
                let insn = enc_indexed_scalar(u, size, opcode, RM, index);
                for _ in 0..12 {
                    let mut st = ArmState::zeroed();
                    let mut m = 0u128;
                    if size == 0b10 {
                        let d = (((rng.next() % 41) as i64 - 20) as f32 * 0.5).to_bits();
                        let n = (((rng.next() % 41) as i64 - 20) as f32 * 0.5).to_bits();
                        for lane in 0..lanes {
                            let val = (((rng.next() % 41) as i64 - 20) as f32 * 0.5).to_bits();
                            m |= (val as u128) << (32 * lane);
                        }
                        st.set_vreg(RD as usize, d as u64, 0);
                        st.set_vreg(RN as usize, n as u64, 0);
                    } else {
                        let d = (((rng.next() % 41) as i64 - 20) as f64 * 0.5).to_bits();
                        let n = (((rng.next() % 41) as i64 - 20) as f64 * 0.5).to_bits();
                        for lane in 0..lanes {
                            let val = (((rng.next() % 41) as i64 - 20) as f64 * 0.5).to_bits();
                            m |= (val as u128) << (64 * lane);
                        }
                        st.set_vreg(RD as usize, d, 0);
                        st.set_vreg(RN as usize, n, 0);
                    }
                    st.set_vreg(RM as usize, m as u64, (m >> 64) as u64);
                    batch.push((format!("{name}_scalar_size{size}_idx{index}"), insn, st));
                }
            }
        }
    }

    run_batch("simd_scalar_indexed_fp", batch);
}

