// commit ddd5a974a0a4 temp: improve aarch64 native-oracle semantics
#[test]
fn diff_fp_scalar_native_oracle_fpsr() {
    // enc_fcvt_precision is added later in this branch; define it locally so the
    // test compiles at this commit.
    fn enc_fcvt_precision(src_type: u32, dst_type: u32) -> u32 {
        (0b00011110 << 24)
            | (src_type << 22)
            | (1 << 21)
            | (0b0001 << 17)
            | (dst_type << 15)
            | (0b10000 << 10)
            | (RN << 5)
            | RD
    }
    let mut batch: Vec<(String, u32, ArmState)> = Vec::new();

    // ---- FP 1-source: fp_status_unop_f32/f64 (FSQRT opcode 0b000011, FRINTX 0b01110) ----
    {
        let mut push1 = |label: &str, opcode: u32, ft: u32, src: u64, fpsr: u64| {
            let mut st = ArmState::zeroed();
            st.fpsr = fpsr;
            st.set_vreg(RN as usize, src, 0);
            batch.push((
                format!("{label}_t{ft}_fpsr{fpsr:#x}"),
                enc_fp1(ft, opcode),
                st,
            ));
        };
        // f32
        let s_neg1 = (-1.0f32).to_bits() as u64; // FSQRT(neg) -> IOC
        let s_two = (2.0f32).to_bits() as u64; // FSQRT(2) inexact -> IXC
        let s_1p5 = (1.5f32).to_bits() as u64; // FRINTX(1.5) inexact -> IXC
        let s_snan = 0x7fa0_0001u64; // signaling NaN -> IOC
        for &fpsr in &[0u64, 0x10] {
            push1("fsqrt_invalid_neg", 0b000011, 0, s_neg1, fpsr);
            push1("fsqrt_inexact", 0b000011, 0, s_two, fpsr);
            push1("frintx_inexact", 0b01110, 0, s_1p5, fpsr);
            push1("fsqrt_snan_invalid", 0b000011, 0, s_snan, fpsr);
            push1("frintx_snan_invalid", 0b01110, 0, s_snan, fpsr);
        }
        // f64
        let d_neg1 = (-1.0f64).to_bits(); // FSQRT(neg) -> IOC
        let d_two = (2.0f64).to_bits(); // FSQRT(2) inexact -> IXC
        let d_1p5 = (1.5f64).to_bits(); // FRINTX(1.5) inexact -> IXC
        let d_snan = 0x7ff0_0000_0000_0001u64; // signaling NaN -> IOC
        for &fpsr in &[0u64, 0x10] {
            push1("fsqrt_invalid_neg", 0b000011, 1, d_neg1, fpsr);
            push1("fsqrt_inexact", 0b000011, 1, d_two, fpsr);
            push1("frintx_inexact", 0b01110, 1, d_1p5, fpsr);
            push1("fsqrt_snan_invalid", 0b000011, 1, d_snan, fpsr);
            push1("frintx_snan_invalid", 0b01110, 1, d_snan, fpsr);
        }
    }

    // ---- FP precision convert: fp_status_cvt_precision (FCVT) ----
    {
        let mut pushc = |label: &str, src_ty: u32, dst_ty: u32, src: u64| {
            let mut st = ArmState::zeroed();
            st.set_vreg(RN as usize, src, 0);
            batch.push((label.to_string(), enc_fcvt_precision(src_ty, dst_ty), st));
        };
        // double -> single (src_ty=01, dst_ty=00)
        pushc(
            "fcvt_d2s_inexact",
            0b01,
            0b00,
            (0.1f64).to_bits(), // 0.1 not representable exactly in f32 -> IXC
        );
        pushc(
            "fcvt_d2s_overflow",
            0b01,
            0b00,
            f64::MAX.to_bits(), // > f32::MAX -> OFC | IXC
        );
        pushc(
            "fcvt_d2s_snan_invalid",
            0b01,
            0b00,
            0x7ff0_0000_0000_0001u64, // sNaN -> IOC
        );
        // single -> half (src_ty=00, dst_ty=11), baseline FCVT (FEAT_FP16).
        pushc(
            "fcvt_s2h_inexact",
            0b00,
            0b11,
            (0.1f32).to_bits() as u64, // 0.1 not representable in f16 -> IXC
        );
        pushc(
            "fcvt_s2h_overflow",
            0b00,
            0b11,
            (70000.0f32).to_bits() as u64, // > f16::MAX (65504) -> OFC | IXC
        );
        pushc(
            "fcvt_s2h_snan_invalid",
            0b00,
            0b11,
            0x7fa0_0001u64, // sNaN -> IOC
        );
        // double -> half (src_ty=01, dst_ty=11)
        pushc(
            "fcvt_d2h_inexact",
            0b01,
            0b11,
            (0.1f64).to_bits(), // -> IXC
        );
    }

    // ---- FP 3-source: fp_status_fma (FMADD o1=0 o0=0, FNMADD o1=1 o0=0) ----
    {
        let mut pushf = |label: &str, ft: u32, o1: u32, o0: u32, n: u64, m: u64, a: u64| {
            let mut st = ArmState::zeroed();
            st.set_vreg(RN as usize, n, 0);
            st.set_vreg(RM as usize, m, 0);
            st.set_vreg(RA as usize, a, 0);
            batch.push((format!("{label}_t{ft}"), enc_fp3(ft, o1, o0), st));
        };
        // f32: 0 * inf + 1.0 -> invalid (IOC)
        let s_zero = (0.0f32).to_bits() as u64;
        let s_inf = f32::INFINITY.to_bits() as u64;
        let s_one = (1.0f32).to_bits() as u64;
        let s_snan = 0x7fa0_0001u64;
        pushf("fmadd_invalid_zero_inf", 0, 0, 0, s_zero, s_inf, s_one);
        pushf("fmadd_snan_addend_invalid", 0, 0, 0, s_one, s_one, s_snan);
        pushf("fnmadd_snan_op_invalid", 0, 1, 0, s_snan, s_one, s_one);
        // f64: 0 * inf + 1.0 -> invalid (IOC)
        let d_zero = (0.0f64).to_bits();
        let d_inf = f64::INFINITY.to_bits();
        let d_one = (1.0f64).to_bits();
        let d_snan = 0x7ff0_0000_0000_0001u64;
        pushf("fmadd_invalid_zero_inf", 1, 0, 0, d_zero, d_inf, d_one);
        pushf("fmadd_snan_addend_invalid", 1, 0, 0, d_one, d_one, d_snan);
        pushf("fnmadd_snan_op_invalid", 1, 1, 0, d_snan, d_one, d_one);
        // f64 FMADD overflow: MAX * 2 + 0 -> OFC | IXC
        pushf(
            "fmadd_overflow",
            1,
            0,
            0,
            f64::MAX.to_bits(),
            (2.0f64).to_bits(),
            (0.0f64).to_bits(),
        );
    }

    // ---- FP 2-source: fp_status_binop_f32/f64 (FADD 0b0010, FMUL 0b0000, FDIV 0b0001) ----
    {
        let mut push2 = |label: &str, ft: u32, opcode: u32, n: u64, m: u64| {
            let mut st = ArmState::zeroed();
            st.set_vreg(RN as usize, n, 0);
            st.set_vreg(RM as usize, m, 0);
            batch.push((format!("{label}_t{ft}"), enc_fp2(ft, opcode), st));
        };
        // f32
        push2(
            "fdiv_divzero",
            0,
            0b0001,
            (1.0f32).to_bits() as u64,
            (0.0f32).to_bits() as u64,
        ); // DZC
        push2(
            "fmul_overflow",
            0,
            0b0000,
            f32::MAX.to_bits() as u64,
            (2.0f32).to_bits() as u64,
        ); // OFC | IXC
        push2(
            "fadd_invalid_inf_cancel",
            0,
            0b0010,
            f32::INFINITY.to_bits() as u64,
            f32::NEG_INFINITY.to_bits() as u64,
        ); // IOC
        // f64
        push2(
            "fdiv_divzero",
            1,
            0b0001,
            (1.0f64).to_bits(),
            (0.0f64).to_bits(),
        ); // DZC
        push2(
            "fmul_overflow",
            1,
            0b0000,
            f64::MAX.to_bits(),
            (2.0f64).to_bits(),
        ); // OFC | IXC
        push2(
            "fadd_invalid_inf_cancel",
            1,
            0b0010,
            f64::INFINITY.to_bits(),
            f64::NEG_INFINITY.to_bits(),
        ); // IOC
    }

    run_fpsr_batch("fp_scalar_native_oracle_fpsr", batch);
}

// commit e03f27efbbaa temp: set scalar fp conversion fpsr
#[test]
fn diff_fp_scalar_conversion_fpsr() {
    // enc_fp_gpr_to_fp / enc_fp_to_gpr are added later in this branch; define
    // them locally so the test compiles at this commit.
    fn enc_fp_gpr_to_fp(sf: u32, fp_type: u32, opcode: u32) -> u32 {
        (sf << 31)
            | (0b0011110 << 24)
            | (fp_type << 22)
            | (1 << 21)
            | (opcode << 16)
            | ((RN & 0x1F) << 5)
            | (RD & 0x1F)
    }
    fn enc_fp_to_gpr(sf: u32, fp_type: u32, rmode: u32, opcode: u32) -> u32 {
        (sf << 31)
            | (0b0011110 << 24)
            | (fp_type << 22)
            | (1 << 21)
            | (rmode << 19)
            | (opcode << 16)
            | ((RN & 0x1F) << 5)
            | (RD & 0x1F)
    }
    let mut batch: Vec<(String, u32, ArmState)> = Vec::new();

    // --- int -> FP (SCVTF/UCVTF), opcode 010 (signed) / 011 (unsigned). ---
    // Integers that exceed the destination mantissa precision become inexact
    // (IXC): 2^11+1 for f16 (11 bits), 2^24+1 for f32 (24 bits), 2^53+1 for
    // f64 (53 bits). fp_status_int_to_fp_scaled detects this via
    // fp_int_scaled_exact and OR-s in FPSR_IXC.
    for &initial_fpsr in &[0u64, 0x10] {
        let mut push_cvtf = |label: &str, sf: u32, fp_type: u32, opcode: u32, raw: u64| {
            let mut st = ArmState::zeroed();
            st.fpsr = initial_fpsr;
            st.fpcr = 0;
            st.x[RN as usize] = raw;
            batch.push((
                format!("{label}_fpsr{initial_fpsr:#x}"),
                enc_fp_gpr_to_fp(sf, fp_type, opcode),
                st,
            ));
        };
        // half (ptype 0b11), 32-bit GPR source.
        push_cvtf("scvtf_h_w_2p11p1", 0, 0b11, 0b010, 2_049);
        push_cvtf("ucvtf_h_w_2p11p1", 0, 0b11, 0b011, 2_049);
        // single (ptype 0b00), 32-bit GPR source.
        push_cvtf("scvtf_s_w_2p24p1", 0, 0b00, 0b010, 16_777_217);
        push_cvtf("ucvtf_s_w_2p24p1", 0, 0b00, 0b011, 16_777_217);
        // double (ptype 0b01), 64-bit GPR source.
        push_cvtf("scvtf_d_x_2p53p1", 1, 0b01, 0b010, 9_007_199_254_740_993);
        push_cvtf("ucvtf_d_x_2p53p1", 1, 0b01, 0b011, 9_007_199_254_740_993);
    }

    // --- FP -> int (rounding/truncating), bit21==1 unscaled forms. ---
    // FCVTZS/FCVTZU use rmode 0b11 (toward zero); FCVTNS/FCVTNU use rmode 0b00.
    // opcode 000=FCVT_S signed, 001=FCVT_U unsigned.
    //   inexact (IXC): a non-integral finite value (e.g. 1.5) truncates/rounds
    //     to an integer != input -> fp_to_int_rounded_status returns FPSR_IXC.
    //   invalid (IOC): a NaN -> fp_to_int_rounded_status returns FPSR_IOC.
    let inexact: &[(u32, &str, u64)] = &[
        (0b00, "s", (1.5f32).to_bits() as u64),
        (0b01, "d", (1.5f64).to_bits()),
        (0b11, "h", 0x3E00u64), // f16 1.5
    ];
    let nan: &[(u32, &str, u64)] = &[
        (0b00, "s", f32::NAN.to_bits() as u64),
        (0b01, "d", f64::NAN.to_bits()),
        (0b11, "h", 0x7E00u64), // f16 qNaN
    ];
    for &initial_fpsr in &[0u64, 0x10] {
        for &(rmode, rname) in &[(0b11u32, "z"), (0b00, "n")] {
            for &(opcode, sname) in &[(0b000u32, "s"), (0b001, "u")] {
                for sf in 0..=1u32 {
                    let wname = if sf == 0 { "w" } else { "x" };
                    for &(fp_type, fname, bits) in inexact {
                        let mut st = ArmState::zeroed();
                        st.fpsr = initial_fpsr;
                        st.fpcr = 0;
                        st.set_vreg(RN as usize, bits, 0);
                        batch.push((
                            format!("fcvt{rname}{sname}_{fname}_{wname}_ixc_fpsr{initial_fpsr:#x}"),
                            enc_fp_to_gpr(sf, fp_type, rmode, opcode),
                            st,
                        ));
                    }
                    for &(fp_type, fname, bits) in nan {
                        let mut st = ArmState::zeroed();
                        st.fpsr = initial_fpsr;
                        st.fpcr = 0;
                        st.set_vreg(RN as usize, bits, 0);
                        batch.push((
                            format!("fcvt{rname}{sname}_{fname}_{wname}_ioc_fpsr{initial_fpsr:#x}"),
                            enc_fp_to_gpr(sf, fp_type, rmode, opcode),
                            st,
                        ));
                    }
                }
            }
        }
    }

    run_fpsr_batch("fp_scalar_conversion_fpsr", batch);
}

// commit 1a4e7cc10b04 temp: set scalar fp16 arithmetic fpsr
#[test]
fn diff_fp_scalar_fp16_arith_fpsr() {
    // fp16 bit patterns.
    const H_ZERO: u64 = 0x0000; // +0.0
    const H_ONE: u64 = 0x3C00; // 1.0
    const H_TWO: u64 = 0x4000; // 2.0
    const H_PINF: u64 = 0x7C00; // +inf
    const H_NINF: u64 = 0xFC00; // -inf
    const H_MAX: u64 = 0x7BFF; // 65504.0 (largest finite normal)

    // (opcode, a-operand, b-operand, label) — fp_type is fixed to half (0b11).
    let cases: &[(u32, u64, u64, &str)] = &[
        // FADD: inf + (-inf) -> invalid (IOC).
        (0b0010, H_PINF, H_NINF, "fadd_ioc"),
        // FADD: max + max overflows fp16 -> OFC + IXC.
        (0b0010, H_MAX, H_MAX, "fadd_ofc"),
        // FSUB: inf - inf -> invalid (IOC).
        (0b0011, H_PINF, H_PINF, "fsub_ioc"),
        // FMUL: 0 * inf -> invalid (IOC).
        (0b0000, H_ZERO, H_PINF, "fmul_ioc"),
        // FMUL: max * 2 overflows -> OFC + IXC.
        (0b0000, H_MAX, H_TWO, "fmul_ofc"),
        // FDIV: finite / 0 -> divide-by-zero (DZC).
        (0b0001, H_ONE, H_ZERO, "fdiv_dzc"),
        // FDIV: inf / inf -> invalid (IOC).
        (0b0001, H_PINF, H_PINF, "fdiv_ioc"),
    ];

    let mut batch: Vec<(String, u32, ArmState)> = Vec::new();
    for &(opcode, a, b, label) in cases {
        let insn = enc_fp2(3, opcode); // fp_type = 0b11 (half)
        for initial_fpsr in [0u64, 0x10] {
            let mut st = ArmState::zeroed();
            st.fpsr = initial_fpsr;
            st.fpcr = 0; // RN, no FTZ, no alternate handling.
            st.set_vreg(RN as usize, a, 0);
            st.set_vreg(RM as usize, b, 0);
            batch.push((format!("{label}_fpsr{initial_fpsr:#x}"), insn, st));
        }
    }
    run_fpsr_batch("fp_scalar_fp16_arith_fpsr", batch);
}

// commit c5fe37974985 temp: fix scalar fp compare invalid flag
#[test]
fn diff_fp_scalar_fcmp_qnan_invalid_fpsr() {
    // enc_fcmp_reg / enc_fcmp_zero are added later in this branch; define them
    // locally so the test compiles at this commit.
    fn enc_fcmp_reg(fp_type: u32) -> u32 {
        (0b00011110 << 24) | (fp_type << 22) | (1 << 21) | (RM << 16) | (0b1000 << 10) | (RN << 5)
    }
    fn enc_fcmp_zero(fp_type: u32) -> u32 {
        (0b00011110 << 24) | (fp_type << 22) | (1 << 21) | (0b1000 << 10) | (RN << 5) | (1 << 3)
    }
    // Quiet-NaN bit patterns (mantissa MSB set => quiet, not signaling).
    fn qnan_bits(ft: u32) -> u64 {
        match ft {
            0b00 => 0x7FC0_0000,           // f32 qNaN
            0b01 => 0x7FF8_0000_0000_0000, // f64 qNaN
            _ => 0x0000_7E00,              // f16 qNaN
        }
    }
    // 1.0 in each precision, used as the non-NaN reg operand.
    fn one_bits(ft: u32) -> u64 {
        match ft {
            0b00 => 0x3F80_0000,
            0b01 => 0x3FF0_0000_0000_0000,
            _ => 0x0000_3C00,
        }
    }

    let mut batch: Vec<(String, u32, ArmState)> = Vec::new();
    // ftype: 00=single, 01=double, 11=half.
    for &ft in &[0b00u32, 0b01, 0b11] {
        let qn = qnan_bits(ft);
        let one = one_bits(ft);
        // Four scalar compare forms. The E (signaling) bit is opcode2 bit[4].
        // Pre-fix code keyed IOC off bit[3] (cmp-with-#0.0); the fix keys it off
        // bit[4] (the E variant). For a *quiet* NaN this diverges on
        // FCMPE Fn,Fm (pre-fix no IOC) and FCMP Fn,#0.0 (pre-fix spurious IOC).
        let forms: [(u32, &str, bool); 4] = [
            (enc_fcmp_reg(ft), "fcmp_reg", true),             // qNaN in Rm
            (enc_fcmp_reg(ft) | (1 << 4), "fcmpe_reg", true), // qNaN in Rm, signaling
            (enc_fcmp_zero(ft), "fcmp_zero", false),          // FCMP Fn,#0.0
            (enc_fcmp_zero(ft) | (1 << 4), "fcmpe_zero", false), // FCMPE Fn,#0.0, signaling
        ];
        for (insn, fname, has_rm) in forms {
            for initial_fpsr in [0u64, 0x10] {
                let mut st = ArmState::zeroed();
                st.fpsr = initial_fpsr;
                st.fpcr = 0;
                // Drive a quiet-NaN operand through the compare.
                st.set_vreg(RN as usize, qn, 0);
                if has_rm {
                    st.set_vreg(RM as usize, one, 0);
                }
                batch.push((
                    format!("{fname}_t{ft:#b}_qnan_fpsr{initial_fpsr:#x}"),
                    insn,
                    st,
                ));
            }
        }
    }
    run_fpsr_batch("fp_scalar_fcmp_qnan_invalid_fpsr", batch);
}

// commit d5b1016b39f2 temp: refine scalar fp exactness fpsr
#[test]
fn diff_fp_scalar_fmul_fpsr_inexact() {
    let mut batch: Vec<(String, u32, ArmState)> = Vec::new();
    // FMUL, double precision (fp_type=01, opcode=0b0000).
    // The commit added, in fp_status_binop_f64, the rule
    //   `if matches!(kind, Mul) && !fp64_mul_exact(a, b) { return FPSR_IXC; }`
    // so a finite scalar double FMUL whose true product needs more than 53
    // significant bits now reports IXC (inexact). Pre-fix the interpreter
    // emitted fpsr=0 and diverged from the EL0 oracle (which sets IXC).
    let insn = enc_fp2(1, 0b0000);
    // Operand pairs whose exact f64 product is inexact (> 53 significant bits).
    // 1.0 + 1 ULP, taken straight from the bit pattern (1.0000000000000002).
    let one_ulp = f64::from_bits(0x3ff0000000000001u64);
    let pairs: [(f64, f64); 2] = [
        (one_ulp, one_ulp), // (1.0 + 1 ULP)^2 = 1 + 2^-51 + 2^-104, not f64-exact
        (1.1f64, 1.1f64),   // 1.1 * 1.1, not f64-exact
    ];
    for (idx, &(a, b)) in pairs.iter().enumerate() {
        for initial_fpsr in [0, 0x10] {
            let mut st = ArmState::zeroed();
            st.fpsr = initial_fpsr;
            st.fpcr = 0;
            st.set_vreg(RN as usize, a.to_bits(), 0);
            st.set_vreg(RM as usize, b.to_bits(), 0);
            batch.push((format!("fmul_d_ixc_p{idx}_fpsr{initial_fpsr:#x}"), insn, st));
        }
    }

    run_fpsr_batch("fp_scalar_fmul_fpsr_inexact", batch);
}

// commit d3ded73ca7f6 temp: set sve fp unary fpsr
#[test]
fn diff_sve_fp_unary_fpsr_exceptions() {
    // SVE FP unary (FSQRT/FRINT*): 0x65 << 24 | size<<22 | opc6<<16 | 0b101<<13
    // | Zn<<5 | Zd.  size: 1=H(esize2), 2=S(esize4), 3=D(esize8).
    // FSQRT opc6=0b001101, FRINTX opc6=0b000110. (FABS/FNEG use 0x04 and are a
    // different handler; this commit only touched the 0x65 FSQRT/FRINT path.)
    let enc_sve_fp_unary = |size: u32, opc6: u32| -> u32 {
        (0x65 << 24) | (size << 22) | (opc6 << 16) | (0b101 << 13) | (RN << 5) | RD
    };
    // Broadcast `value` (esize bytes) across all 128 bits.
    let pack = |value: u64, esize: usize| -> (u64, u64) {
        let bits = esize * 8;
        let mask: u128 = if bits == 128 {
            u128::MAX
        } else {
            (1u128 << bits) - 1
        };
        let mut packed = 0u128;
        let lanes = 16 / esize;
        for lane in 0..lanes {
            packed |= (value as u128 & mask) << (lane * bits);
        }
        (packed as u64, (packed >> 64) as u64)
    };

    let mut batch: Vec<(String, u32, ArmState)> = Vec::new();

    // (size, esize, neg-finite -> FSQRT IOC, pos non-square -> FSQRT IXC,
    //  non-integral -> FRINTX IXC). H: -4.0=0xC400, 2.0=0x4000, 1.5=0x3E00.
    let cases: &[(u32, usize, u64, u64, u64)] = &[
        (1, 2, 0xC400, 0x4000, 0x3E00),
        (
            2,
            4,
            (-4.0f32).to_bits() as u64,
            (2.0f32).to_bits() as u64,
            (1.5f32).to_bits() as u64,
        ),
        (
            3,
            8,
            (-4.0f64).to_bits(),
            (2.0f64).to_bits(),
            (1.5f64).to_bits(),
        ),
    ];

    for &(size, esize, neg, nonsq, nonint) in cases {
        for &(op, opc6, bits) in &[
            ("fsqrt_ioc", 0b001101u32, neg),     // FSQRT(-x) -> invalid (IOC)
            ("fsqrt_ixc", 0b001101u32, nonsq),   // FSQRT(2.0) -> inexact (IXC)
            ("frintx_ixc", 0b000110u32, nonint), // FRINTX(1.5) -> inexact (IXC)
        ] {
            let insn = enc_sve_fp_unary(size, opc6);
            for initial_fpsr in [0u64, 0x10] {
                let mut st = ArmState::zeroed();
                st.fpsr = initial_fpsr;
                st.fpcr = 0;
                st.set_preg(0, 0xffff); // P0 all-active at VL=128
                let (lo, hi) = pack(bits, esize);
                st.set_vreg(RN as usize, lo, hi);
                // Distinct prior Zd so a missed merge would also show.
                st.set_vreg(RD as usize, 0, 0);
                batch.push((
                    format!("sve_{op}_size{size}_fpsr{initial_fpsr:#x}"),
                    insn,
                    st,
                ));
            }
        }
    }

    run_fpsr_batch("sve_fp_unary_fpsr_exceptions", batch);
}

// commit e15fade14446 temp: set sve frsqrte invalid fpsr
#[test]
fn diff_sve_frsqrte_fpsr_invalid_negative() {
    let mut batch: Vec<(String, u32, ArmState)> = Vec::new();
    // (size, esz_bytes, negative-finite bits, negative-inf bits, positive-finite bits)
    let cases: &[(u32, usize, u64, u64, u64)] = &[
        (1, 2, 0xbc00, 0xfc00, 0x3c00), // half: -1.0, -inf, +1.0
        (
            2,
            4,
            (-1.0f32).to_bits() as u64,
            0xff80_0000,
            1.0f32.to_bits() as u64,
        ), // single
        (
            3,
            8,
            (-1.0f64).to_bits(),
            0xfff0_0000_0000_0000,
            1.0f64.to_bits(),
        ), // double
    ];
    for &(size, esz, neg, neginf, pos) in cases {
        let insn = enc_sve_frecpe(size, 1); // FRSQRTE (rsqrt=1), unpredicated
        let bits = (esz * 8) as u32;
        let mask: u128 = if bits == 64 {
            u128::from(u64::MAX)
        } else {
            (1u128 << bits) - 1
        };
        let lanes = 16 / esz;
        for initial_fpsr in [0u64, 0x10] {
            // All-negative-finite vector: every active lane raises IOC.
            let mut zn = 0u128;
            for l in 0..lanes {
                zn |= ((neg as u128) & mask) << (l * esz * 8);
            }
            let mut st = ArmState::zeroed();
            st.fpsr = initial_fpsr;
            st.fpcr = 0;
            st.set_vreg(RN as usize, zn as u64, (zn >> 64) as u64);
            batch.push((
                format!("frsqrte_neg_s{size}_fpsr{initial_fpsr:#x}"),
                insn,
                st,
            ));

            // Mixed: negative-inf, positive-finite alternating -> only neg lanes flag.
            let mut zn = 0u128;
            for l in 0..lanes {
                let v = if l % 2 == 0 { neginf } else { pos };
                zn |= ((v as u128) & mask) << (l * esz * 8);
            }
            let mut st = ArmState::zeroed();
            st.fpsr = initial_fpsr;
            st.fpcr = 0;
            st.set_vreg(RN as usize, zn as u64, (zn >> 64) as u64);
            batch.push((
                format!("frsqrte_mix_s{size}_fpsr{initial_fpsr:#x}"),
                insn,
                st,
            ));
        }
    }
    run_fpsr_batch("sve_frsqrte_fpsr_invalid_negative", batch);
}

// commit ecd9eeda1b3f temp: set sve pred fp binop fpsr
#[test]
fn diff_sve_fp_pred_binop_fpsr() {
    let mut batch: Vec<(String, u32, ArmState)> = Vec::new();

    // (sz, esize_bytes) for half, single, double. size==00 is reserved for
    // these slots, so the legal element sizes are 01/10/11 -> H/S/D.
    for &(sz, eb) in &[(1u32, 2usize), (2u32, 4usize), (3u32, 8usize)] {
        let lanes = 16 / eb;

        // Per-esize raw-bit operand sets keyed by element size. Each tuple is
        // (opc5, name, dn_bits, m_bits) where dn = Zdn (V[RD], first source =
        // FpKind operand `a`) and m = Zm (V[RN], second source = `b`). None of
        // these opc5 values is FSCALE (0b01001) or a reserved slot, so they all
        // reach the (kind, swap) match and the patched fp_status_binop() call.
        let cases: Vec<(u32, &str, u64, u64)> = match eb {
            2 => vec![
                // FADD (opc5=0b00000): +inf + -inf => IOC. inf=0x7c00, -inf=0xfc00.
                (0b00000, "fadd_ioc", 0x7c00, 0xfc00),
                // FDIV (opc5=0b01101): 1.0 / 0.0 => DZC. 1.0=0x3c00, 0.0=0x0000.
                (0b01101, "fdiv_dzc", 0x3c00, 0x0000),
                // FMUL (opc5=0b00010): max_normal * 2.0 => OFC|IXC. max=0x7bff, 2.0=0x4000.
                (0b00010, "fmul_ofc", 0x7bff, 0x4000),
                // FADD inexact: 1.0 + smallest subnormal (2^-24) => IXC.
                // 1.0=0x3c00, subnormal lsb=0x0001.
                (0b00000, "fadd_ixc", 0x3c00, 0x0001),
            ],
            4 => vec![
                (
                    0b00000,
                    "fadd_ioc",
                    f32::INFINITY.to_bits() as u64,
                    f32::NEG_INFINITY.to_bits() as u64,
                ),
                (
                    0b01101,
                    "fdiv_dzc",
                    (1.0f32).to_bits() as u64,
                    (0.0f32).to_bits() as u64,
                ),
                (
                    0b00010,
                    "fmul_ofc",
                    f32::MAX.to_bits() as u64,
                    (2.0f32).to_bits() as u64,
                ),
                // 1.0 + 2^-24 is not representable in f32 => IXC.
                (
                    0b00000,
                    "fadd_ixc",
                    (1.0f32).to_bits() as u64,
                    (2.0f32.powi(-24)).to_bits() as u64,
                ),
            ],
            _ => vec![
                (
                    0b00000,
                    "fadd_ioc",
                    f64::INFINITY.to_bits(),
                    f64::NEG_INFINITY.to_bits(),
                ),
                (0b01101, "fdiv_dzc", (1.0f64).to_bits(), (0.0f64).to_bits()),
                (0b00010, "fmul_ofc", f64::MAX.to_bits(), (2.0f64).to_bits()),
                // 1.0 + 2^-53 is not representable in f64 => IXC.
                (
                    0b00000,
                    "fadd_ixc",
                    (1.0f64).to_bits(),
                    (2.0f64.powi(-53)).to_bits(),
                ),
            ],
        };

        for (opc5, name, dn_bits, m_bits) in cases {
            for initial_fpsr in [0u64, 0x10] {
                let mut st = ArmState::zeroed();
                st.fpsr = initial_fpsr;
                st.fpcr = 0;
                // Governing predicate P0 all-active (16 byte-lanes at VL=128).
                st.set_preg(0, 0xffff);

                let mask: u128 = if eb == 8 {
                    u64::MAX as u128
                } else {
                    (1u128 << (eb * 8)) - 1
                };
                let mut d = 0u128;
                let mut n = 0u128;
                for lane in 0..lanes {
                    d |= ((dn_bits as u128) & mask) << (eb * 8 * lane);
                    n |= ((m_bits as u128) & mask) << (eb * 8 * lane);
                }
                // Zdn = V[RD] (first source / dest), Zm = V[RN] (second source).
                st.set_vreg(RD as usize, d as u64, (d >> 64) as u64);
                st.set_vreg(RN as usize, n as u64, (n >> 64) as u64);

                batch.push((
                    format!("sve_fpp_{name}_sz{sz}_fpsr{initial_fpsr:#x}"),
                    enc_sve_fpp(sz, opc5),
                    st,
                ));
            }
        }
    }

    run_fpsr_batch("sve_fp_pred_binop_fpsr", batch);
}

// commit 7a8ce502adc3 temp: set sve fscale fpsr
#[test]
fn diff_sve_fscale_fpsr() {
    let mut batch: Vec<(String, u32, ArmState)> = Vec::new();
    // (size, esz_bytes, big_normal_bits, smallest_normal_bits, over_exp, under_exp)
    let cases: &[(u32, usize, u64, u64, i64, i64)] = &[
        (1, 2, 0x7bff, 0x0400, 40, -40),                           // half
        (2, 4, f32::MAX.to_bits() as u64, 0x0080_0000, 200, -200), // single
        (3, 8, f64::MAX.to_bits(), 0x0010_0000_0000_0000, 1023, -1023), // double
    ];
    for &(size, esz, big, small, over_exp, under_exp) in cases {
        let insn = enc_sve_fscale(size);
        let emask: u64 = if esz == 8 {
            u64::MAX
        } else {
            (1u64 << (esz * 8)) - 1
        };
        let lanes = 16 / esz;
        for &(tag, val, exp) in &[("ofc", big, over_exp), ("ufc", small, under_exp)] {
            for initial_fpsr in [0u64, 0x10] {
                let mut z = 0u128;
                let mut n = 0u128;
                for l in 0..lanes {
                    z |= ((val & emask) as u128) << (l * esz * 8);
                    n |= (((exp as u64) & emask) as u128) << (l * esz * 8);
                }
                let mut st = ArmState::zeroed();
                st.fpsr = initial_fpsr;
                st.fpcr = 0;
                st.set_preg(0, 0xffff);
                st.set_vreg(RD as usize, z as u64, (z >> 64) as u64);
                st.set_vreg(RN as usize, n as u64, (n >> 64) as u64);
                batch.push((
                    format!("fscale_s{size}_{tag}_fpsr{initial_fpsr:#x}"),
                    insn,
                    st,
                ));
            }
        }
    }
    run_fpsr_batch("sve_fscale_fpsr", batch);
}

// commit c2d3228c340d temp: set sve indexed fp fpsr
#[test]
fn diff_sve_indexed_fp_fpsr_exceptions() {
    // op (bits[15:10]): FMUL=0b001000, FMLA=0b000000, FMLS=0b000001.
    // size: 1=.h, 2=.s, 3(_)=.d. index=0, Zm=RM (broadcast lane 0).
    const FMUL: u32 = 0b001000;
    const FMLA: u32 = 0b000000;
    const FMLS: u32 = 0b000001;

    // (name, inf bits, zero bits, maxnorm bits, two bits) per size.
    let h_inf = 0x7c00u64;
    let h_zero = 0x0000u64;
    let h_max = 0x7bffu64; // largest finite fp16
    let h_two = 0x4000u64; // 2.0

    let mut batch: Vec<(String, u32, ArmState)> = Vec::new();

    for &size in &[1u32, 2, 3] {
        let (inf, zero, maxn, two) = match size {
            1 => (h_inf, h_zero, h_max, h_two),
            2 => (
                f32::INFINITY.to_bits() as u64,
                0.0f32.to_bits() as u64,
                f32::MAX.to_bits() as u64,
                2.0f32.to_bits() as u64,
            ),
            _ => (
                f64::INFINITY.to_bits(),
                0.0f64.to_bits(),
                f64::MAX.to_bits(),
                2.0f64.to_bits(),
            ),
        };

        for initial_fpsr in [0u64, 0x10] {
            // --- FMUL: fp_status_binop path ---
            // invalid: inf * 0 -> IOC
            {
                let mut st = ArmState::zeroed();
                st.fpsr = initial_fpsr;
                st.fpcr = 0;
                st.set_preg(0, 0xFFFF);
                st.set_vreg(RN as usize, inf, inf); // Zn lanes = inf
                st.set_vreg(RM as usize, zero, 0); // Zm[0] = 0
                batch.push((
                    format!("sve_idx_fmul_sz{size}_ioc_fpsr{initial_fpsr:#x}"),
                    enc_sve_fp_idx(FMUL, size, 0, RM),
                    st,
                ));
            }
            // overflow + inexact: maxnorm * 2 -> OFC|IXC
            {
                let mut st = ArmState::zeroed();
                st.fpsr = initial_fpsr;
                st.fpcr = 0;
                st.set_preg(0, 0xFFFF);
                st.set_vreg(RN as usize, maxn, maxn);
                st.set_vreg(RM as usize, two, 0);
                batch.push((
                    format!("sve_idx_fmul_sz{size}_ofc_fpsr{initial_fpsr:#x}"),
                    enc_sve_fp_idx(FMUL, size, 0, RM),
                    st,
                ));
            }

            // --- FMLA: fp_status_fma path. acc(Zd)=0, op1(Zn)=inf, op2(Zm)=0
            //     -> inf*0 invalid -> IOC ---
            {
                let mut st = ArmState::zeroed();
                st.fpsr = initial_fpsr;
                st.fpcr = 0;
                st.set_preg(0, 0xFFFF);
                st.set_vreg(RD as usize, 0, 0); // accumulator = +0
                st.set_vreg(RN as usize, inf, inf);
                st.set_vreg(RM as usize, zero, 0);
                batch.push((
                    format!("sve_idx_fmla_sz{size}_ioc_fpsr{initial_fpsr:#x}"),
                    enc_sve_fp_idx(FMLA, size, 0, RM),
                    st,
                ));
            }
            // FMLA overflow: acc=0, maxnorm * 2 -> OFC|IXC
            {
                let mut st = ArmState::zeroed();
                st.fpsr = initial_fpsr;
                st.fpcr = 0;
                st.set_preg(0, 0xFFFF);
                st.set_vreg(RD as usize, 0, 0);
                st.set_vreg(RN as usize, maxn, maxn);
                st.set_vreg(RM as usize, two, 0);
                batch.push((
                    format!("sve_idx_fmla_sz{size}_ofc_fpsr{initial_fpsr:#x}"),
                    enc_sve_fp_idx(FMLA, size, 0, RM),
                    st,
                ));
            }

            // --- FMLS: fp_status_fma path (Zn negated). op1=inf, op2=0
            //     -> (-inf)*0 invalid -> IOC ---
            {
                let mut st = ArmState::zeroed();
                st.fpsr = initial_fpsr;
                st.fpcr = 0;
                st.set_preg(0, 0xFFFF);
                st.set_vreg(RD as usize, 0, 0);
                st.set_vreg(RN as usize, inf, inf);
                st.set_vreg(RM as usize, zero, 0);
                batch.push((
                    format!("sve_idx_fmls_sz{size}_ioc_fpsr{initial_fpsr:#x}"),
                    enc_sve_fp_idx(FMLS, size, 0, RM),
                    st,
                ));
            }
        }
    }

    run_fpsr_batch("sve_indexed_fp_fpsr_exceptions", batch);
}

// commit f46267387c26 temp: set sve fp reduce fpsr
#[test]
fn diff_sve_fp_reduce_fpsr() {
    // SVE FP reduce: op0=011 (top byte 0x65), size in bits[23:22], opc5 in
    // bits[20:16], group bits[15:13]=001 routes to exec_sve_fp_reduce, Pg in
    // bits[12:10] (=0 here -> P0), Zn in bits[9:5], Vd in bits[4:0].
    // opc5: FADDV=0b00000, FMAXNMV=0b00100, FADDA=0b11000.
    fn enc(sz: u32, opc5: u32) -> u32 {
        (0x65 << 24) | (sz << 22) | (opc5 << 16) | (0b001 << 13) | (RN << 5) | RD
    }
    // sNaN bit patterns (exponent all-ones, quiet-bit clear, a mantissa bit set).
    let snan32: u64 = 0x7FA0_0000;
    let snan64: u64 = 0x7FF4_0000_0000_0000;
    let pinf16: u64 = 0x7C00;
    let ninf16: u64 = 0xFC00;
    let one16: u64 = 0x3C00; // 1.0 in IEEE half
    let pinf32: u64 = f32::INFINITY.to_bits() as u64;
    let ninf32: u64 = f32::NEG_INFINITY.to_bits() as u64;
    let pinf64: u64 = f64::INFINITY.to_bits();
    let ninf64: u64 = f64::NEG_INFINITY.to_bits();

    let mut batch: Vec<(String, u32, ArmState)> = Vec::new();

    for initial_fpsr in [0u64, 0x10] {
        // ---- FADDV (tree-reduce), half precision (sz=1, esize=2) ----
        let insn = enc(1, 0b00000);
        // IOC: +Inf + -Inf in two active H lanes (byte stride 2 -> pred bits 0,1).
        let mut st = ArmState::zeroed();
        st.fpsr = initial_fpsr;
        st.set_preg(0, 0x0003);
        st.set_vreg(RN as usize, pinf16 | (ninf16 << 16), 0);
        batch.push((format!("faddv_h_ioc_fpsr{initial_fpsr:#x}"), insn, st));

        // ---- FADDV (tree-reduce), single precision (sz=2, esize=4) ----
        let insn = enc(2, 0b00000);
        // IOC: +Inf + -Inf in two active S lanes (byte stride 4 -> pred bits 0,4).
        let mut st = ArmState::zeroed();
        st.fpsr = initial_fpsr;
        st.set_preg(0, 0x0011);
        st.set_vreg(RN as usize, pinf32 | (ninf32 << 32), 0);
        batch.push((format!("faddv_s_ioc_fpsr{initial_fpsr:#x}"), insn, st));
        // IXC: 2^24 + 1.0 is not representable in f32.
        let mut st = ArmState::zeroed();
        st.fpsr = initial_fpsr;
        st.set_preg(0, 0x0011);
        st.set_vreg(
            RN as usize,
            (16_777_216.0f32.to_bits() as u64) | ((1.0f32.to_bits() as u64) << 32),
            0,
        );
        batch.push((format!("faddv_s_ixc_fpsr{initial_fpsr:#x}"), insn, st));

        // ---- FADDV (tree-reduce), double precision (sz=3, esize=8) ----
        let insn = enc(3, 0b00000);
        // IOC: +Inf + -Inf, two active D lanes (byte stride 8 -> pred bits 0,8).
        let mut st = ArmState::zeroed();
        st.fpsr = initial_fpsr;
        st.set_preg(0, 0x0101);
        st.set_vreg(RN as usize, pinf64, ninf64);
        batch.push((format!("faddv_d_ioc_fpsr{initial_fpsr:#x}"), insn, st));
        // IXC: 2^53 + 1.0 not representable in f64.
        let mut st = ArmState::zeroed();
        st.fpsr = initial_fpsr;
        st.set_preg(0, 0x0101);
        st.set_vreg(
            RN as usize,
            9_007_199_254_740_992.0f64.to_bits(),
            1.0f64.to_bits(),
        );
        batch.push((format!("faddv_d_ixc_fpsr{initial_fpsr:#x}"), insn, st));

        // ---- FMAXNMV (tree-reduce) IOC via sNaN ----
        let insn = enc(2, 0b00100);
        let mut st = ArmState::zeroed();
        st.fpsr = initial_fpsr;
        st.set_preg(0, 0x0011);
        st.set_vreg(RN as usize, snan32 | (1.0f32.to_bits() as u64) << 32, 0);
        batch.push((format!("fmaxnmv_s_ioc_fpsr{initial_fpsr:#x}"), insn, st));
        let insn = enc(3, 0b00100);
        let mut st = ArmState::zeroed();
        st.fpsr = initial_fpsr;
        st.set_preg(0, 0x0101);
        st.set_vreg(RN as usize, snan64, 1.0f64.to_bits());
        batch.push((format!("fmaxnmv_d_ioc_fpsr{initial_fpsr:#x}"), insn, st));

        // ---- FADDA (strict ordered accumulate) ----
        // acc seeded from Vdn[0] (=Vd=RD); addend lanes from Zm (=Zn field=RN).
        // IOC (half): acc=+Inf, first active addend=-Inf.
        let insn = enc(1, 0b11000);
        let mut st = ArmState::zeroed();
        st.fpsr = initial_fpsr;
        st.set_preg(0, 0x0001); // H lane 0 active
        st.set_vreg(RD as usize, pinf16, 0); // acc seed = Vdn[0]
        st.set_vreg(RN as usize, ninf16, 0); // Zm[0] = -Inf
        batch.push((format!("fadda_h_ioc_fpsr{initial_fpsr:#x}"), insn, st));
        // IXC (half): acc=2048 (2^11), addend=1.0 -> 2049 not representable in f16.
        let mut st = ArmState::zeroed();
        st.fpsr = initial_fpsr;
        st.set_preg(0, 0x0001);
        st.set_vreg(RD as usize, 0x6800, 0); // 2048.0 in half
        st.set_vreg(RN as usize, one16, 0);
        batch.push((format!("fadda_h_ixc_fpsr{initial_fpsr:#x}"), insn, st));

        // IOC (single): acc=+Inf, first active addend=-Inf.
        let insn = enc(2, 0b11000);
        let mut st = ArmState::zeroed();
        st.fpsr = initial_fpsr;
        st.set_preg(0, 0x0001); // S lane 0 active
        st.set_vreg(RD as usize, pinf32, 0);
        st.set_vreg(RN as usize, ninf32, 0);
        batch.push((format!("fadda_s_ioc_fpsr{initial_fpsr:#x}"), insn, st));
        // IXC (single): acc=2^24, addend=1.0 -> 2^24+1 not representable.
        let mut st = ArmState::zeroed();
        st.fpsr = initial_fpsr;
        st.set_preg(0, 0x0001);
        st.set_vreg(RD as usize, 16_777_216.0f32.to_bits() as u64, 0);
        st.set_vreg(RN as usize, 1.0f32.to_bits() as u64, 0);
        batch.push((format!("fadda_s_ixc_fpsr{initial_fpsr:#x}"), insn, st));

        // IOC (double): acc=+Inf, first active addend=-Inf.
        let insn = enc(3, 0b11000);
        let mut st = ArmState::zeroed();
        st.fpsr = initial_fpsr;
        st.set_preg(0, 0x0001); // D lane 0 active
        st.set_vreg(RD as usize, pinf64, 0);
        st.set_vreg(RN as usize, ninf64, 0);
        batch.push((format!("fadda_d_ioc_fpsr{initial_fpsr:#x}"), insn, st));
        // IXC (double): acc=2^53, addend=1.0 -> 2^53+1 not representable.
        let mut st = ArmState::zeroed();
        st.fpsr = initial_fpsr;
        st.set_preg(0, 0x0001);
        st.set_vreg(RD as usize, 9_007_199_254_740_992.0f64.to_bits(), 0);
        st.set_vreg(RN as usize, 1.0f64.to_bits(), 0);
        batch.push((format!("fadda_d_ixc_fpsr{initial_fpsr:#x}"), insn, st));
    }

    run_fpsr_batch("sve_fp_reduce_fpsr", batch);
}

// commit ddd6bc6b4055 temp: set sve pred fp fma fpsr
#[test]
fn diff_sve_pred_fp_fma_fpsr() {
    let mut batch: Vec<(String, u32, ArmState)> = Vec::new();

    // size: 1=half(esz 2), 2=single(esz 4), 3=double(esz 8). size==0 is #UD.
    // (size, snan_bits, inf_bits, one_bits, lane_bytes)
    let cases: [(u32, u64, u64, u64, usize); 3] = [
        (1, 0x7D00, 0x7C00, 0x3C00, 2),                // half
        (2, 0x7FA0_0000, 0x7F80_0000, 0x3F80_0000, 4), // single
        (
            3,
            0x7FF4_0000_0000_0000,
            0x7FF0_0000_0000_0000,
            0x3FF0_0000_0000_0000,
            8,
        ), // double
    ];

    for &(size, snan, inf, one, lanebytes) in &cases {
        let insn = enc_sve_fp_fma(size, 0b000); // FMLA: Zd=addend, Zn=RN, Zm=RM, Pg=P0
        let lanes = 16 / lanebytes;

        // Broadcast a value across all lanes of a 128-bit register.
        let broadcast = |v: u64| -> u128 {
            let mut acc = 0u128;
            for lane in 0..lanes {
                acc |= (v as u128) << (lane * lanebytes * 8);
            }
            acc
        };

        for &initial_fpsr in &[0u64, 0x10] {
            // (1) signaling NaN multiplicand -> IOC from fp_status_fma.
            let mut st = ArmState::zeroed();
            st.fpsr = initial_fpsr;
            st.fpcr = 0;
            st.set_preg(0, 0xFFFF);
            let n = broadcast(snan);
            let m = broadcast(one);
            st.set_vreg(RD as usize, 0, 0); // addend Za = +0.0
            st.set_vreg(RN as usize, n as u64, (n >> 64) as u64);
            st.set_vreg(RM as usize, m as u64, (m >> 64) as u64);
            batch.push((
                format!("sve_fmla_snan_ioc_sz{size}_fpsr{initial_fpsr:#x}"),
                insn,
                st,
            ));

            // (2) 0 * inf invalid product -> IOC from fp_status_fma.
            let mut st2 = ArmState::zeroed();
            st2.fpsr = initial_fpsr;
            st2.fpcr = 0;
            st2.set_preg(0, 0xFFFF);
            let n2 = broadcast(0); // +0.0
            let m2 = broadcast(inf); // +inf
            st2.set_vreg(RD as usize, 0, 0); // addend Za = +0.0
            st2.set_vreg(RN as usize, n2 as u64, (n2 >> 64) as u64);
            st2.set_vreg(RM as usize, m2 as u64, (m2 >> 64) as u64);
            batch.push((
                format!("sve_fmla_zero_inf_ioc_sz{size}_fpsr{initial_fpsr:#x}"),
                insn,
                st2,
            ));
        }
    }

    run_fpsr_batch("sve_pred_fp_fma_fpsr", batch);
}

// commit bd9b610f2ca8 temp: set sve fcvt fpsr
#[test]
fn diff_sve_fcvt_fpsr() {
    let mut batch: Vec<(String, u32, ArmState)> = Vec::new();
    // Narrowing FCVT forms only (dst smaller than src -> can be inexact/overflow).
    // (opc, opc2, src_sz, dst_sz, name)
    let convs = [
        (0b10u32, 0b00u32, 4usize, 2usize, "s2h"), // single -> half
        (0b11, 0b00, 8, 2, "d2h"),                 // double -> half
        (0b11, 0b10, 8, 4, "d2s"),                 // double -> single
    ];
    for (opc, opc2, src_sz, dst_sz, name) in convs {
        let insn = enc_sve_fcvt(opc, opc2);
        let cont = src_sz.max(dst_sz);
        let elements = 16 / cont;
        // (case-name, per-lane source bits in the source width) chosen so every
        // active lane raises a flag in the destination precision.
        let cases: Vec<(&str, u64)> = match src_sz {
            4 => vec![
                // 0.1f32 is not representable in half -> IXC
                ("inexact", 0.1f32.to_bits() as u64),
                // 70000 > 65504 (max normal half) -> OFC|IXC
                ("overflow", 70000.0f32.to_bits() as u64),
                // single sNaN -> IOC
                ("snan", 0x7F80_0001u64),
            ],
            _ => match dst_sz {
                2 => vec![
                    // 0.1f64 not representable in half -> IXC
                    ("inexact", 0.1f64.to_bits()),
                    // 1e6 > max half -> OFC|IXC
                    ("overflow", 1.0e6f64.to_bits()),
                    // double sNaN -> IOC
                    ("snan", 0x7FF0_0000_0000_0001u64),
                ],
                _ => vec![
                    // 0.1f64 not representable in single -> IXC
                    ("inexact", 0.1f64.to_bits()),
                    // 1e300 overflows single -> OFC|IXC
                    ("overflow", 1.0e300f64.to_bits()),
                    // double sNaN -> IOC
                    ("snan", 0x7FF0_0000_0000_0001u64),
                ],
            },
        };
        for (case, bits) in cases {
            for initial_fpsr in [0u64, 0x10] {
                let mut st = ArmState::zeroed();
                st.fpsr = initial_fpsr;
                st.fpcr = 0; // RNE, no flush-to-zero, no alternate handling
                // Pack the triggering value into every lane of the source Zn (=V1).
                let mut zn: u128 = 0;
                for e in 0..elements {
                    zn |= (bits as u128) << (e * cont * 8);
                }
                st.set_vreg(RN as usize, zn as u64, (zn >> 64) as u64);
                st.set_vreg(RD as usize, 0xdead_beef_dead_beef, 0xfeed_face_feed_face); // merge target
                st.set_preg(0, 0xFFFF); // P0 all-active
                batch.push((
                    format!("fcvt_{name}_{case}_fpsr{initial_fpsr:#x}"),
                    insn,
                    st,
                ));
            }
        }
    }
    run_fpsr_batch("sve_fcvt_fpsr", batch);
}

// commit 12d4b2044ba4 temp: set sve fp-int cvt fpsr
#[test]
fn diff_sve_fp_int_cvt_fpsr_excs() {
    // (opc, opc2, fp_sz, int_sz) per exec_sve_fp_int_cvt's width table.
    let table = [
        (0b01u32, 0b01u32, 2usize, 2usize), // fp16 <-> int16
        (0b01, 0b10, 2, 4),                 // fp16 <-> int32
        (0b01, 0b11, 2, 8),                 // fp16 <-> int64
        (0b10, 0b10, 4, 4),                 // f32  <-> int32
        (0b11, 0b10, 4, 8),                 // f32  <-> int64
        (0b11, 0b00, 8, 4),                 // f64  <-> int32
        (0b11, 0b11, 8, 8),                 // f64  <-> int64
    ];
    let mut batch: Vec<(String, u32, ArmState)> = Vec::new();
    for (opc, opc2, fp_sz, int_sz) in table {
        let cont = fp_sz.max(int_sz);
        let elements = 16 / cont;
        // FP source: +Inf in the fp_sz field -> fp_to_int_status returns IOC.
        let inf_bits: u64 = match fp_sz {
            2 => 0x7C00, // fp16 +Inf
            4 => f32::INFINITY.to_bits() as u64,
            _ => f64::INFINITY.to_bits(),
        };
        // Integer source: smallest int that is not exactly representable in the
        // destination FP precision (11/24/53 bits) -> fp_status_int_to_fp_scaled
        // returns IXC. Each value fits the signed range of int_sz.
        let inexact_int: u64 = match fp_sz {
            2 => 2_049,                 // 2^11 + 1 (fits i16)
            4 => 16_777_217,            // 2^24 + 1 (fits i32)
            _ => 9_007_199_254_740_993, // 2^53 + 1 (fits i64)
        };

        // FCVTZ direction (ig1=0b011): FP -> int, expect IOC from +Inf.
        for u in 0..2u32 {
            let insn = enc_sve_cvt(opc, 0b011, opc2, u);
            for initial_fpsr in [0u64, 0x10] {
                let mut st = ArmState::zeroed();
                st.fpsr = initial_fpsr;
                let mut zn: u128 = 0;
                for e in 0..elements {
                    zn |= (inf_bits as u128) << (e * cont * 8);
                }
                st.set_vreg(RN as usize, zn as u64, (zn >> 64) as u64);
                st.set_preg(0, 0xFFFF);
                batch.push((
                    format!(
                        "fcvtz{}_f{}i{}_ioc_fpsr{initial_fpsr:#x}",
                        if u == 0 { "s" } else { "u" },
                        fp_sz * 8,
                        int_sz * 8
                    ),
                    insn,
                    st,
                ));
            }
        }

        // CVTF direction (ig1=0b010): int -> FP, expect IXC from inexact integer.
        for u in 0..2u32 {
            let insn = enc_sve_cvt(opc, 0b010, opc2, u);
            for initial_fpsr in [0u64, 0x01] {
                let mut st = ArmState::zeroed();
                st.fpsr = initial_fpsr;
                let imask: u64 = if int_sz == 8 {
                    u64::MAX
                } else {
                    (1u64 << (int_sz * 8)) - 1
                };
                let mut zn: u128 = 0;
                for e in 0..elements {
                    zn |= ((inexact_int & imask) as u128) << (e * cont * 8);
                }
                st.set_vreg(RN as usize, zn as u64, (zn >> 64) as u64);
                st.set_preg(0, 0xFFFF);
                batch.push((
                    format!(
                        "cvtf{}_f{}i{}_ixc_fpsr{initial_fpsr:#x}",
                        if u == 0 { "s" } else { "u" },
                        fp_sz * 8,
                        int_sz * 8
                    ),
                    insn,
                    st,
                ));
            }
        }
    }
    run_fpsr_batch("sve_fp_int_cvt_fpsr_excs", batch);
}

// commit 51e735894441 temp: set sve fp compare fpsr
#[test]
fn diff_sve_fp_cmp_fpsr_invalid() {
    let mut batch: Vec<(String, u32, ArmState)> = Vec::new();

    // Per-size NaN bit patterns. size field: 1=half(16), 2=single(32),
    // 3=double(64). esz = (1<<size) bytes -> 2/4/8.
    // (size, name, element bit-width, sNaN bits, qNaN bits)
    let sizes: [(u32, &str, usize, u64, u64); 3] = [
        (1, "h", 16, 0x7C01, 0x7E00),
        (2, "s", 32, 0x7F80_0001, 0x7FC0_0000),
        (3, "d", 64, 0x7FF0_0000_0000_0001, 0x7FF8_0000_0000_0000),
    ];

    // Fill all 128 bits with `pat` replicated across `bits`-wide lanes.
    fn fill(bits: usize, pat: u64) -> (u64, u64) {
        let mut v: u128 = 0;
        let lanes = 128 / bits;
        for lane in 0..lanes {
            v |= (pat as u128) << (lane * bits);
        }
        (v as u64, (v >> 64) as u64)
    }

    for &(size, sname, bits, snan, qnan) in &sizes {
        // Register-compare conditions (bits[15:13]=cc13, bit4). The 51e73589
        // fix raises FPSR.IOC when either operand is an sNaN (every condition),
        // and additionally when cc.0 (==cc13) == 0b010 (FCMGE/FCMGT) and either
        // operand is a qNaN. Only those qNaN cases are part of this commit, so
        // qNaN inputs are exercised solely on cc13==0b010.
        // (cc13, bit4, name, qnan_raises_ioc)
        let reg_conds: [(u32, u32, &str, bool); 7] = [
            (0b010, 0, "fcmge", true),
            (0b010, 1, "fcmgt", true),
            (0b011, 0, "fcmeq", false),
            (0b011, 1, "fcmne", false),
            (0b110, 0, "fcmuo", false),
            (0b110, 1, "facge", false),
            (0b111, 1, "facgt", false),
        ];
        for &(cc13, bit4, cname, qnan_active) in &reg_conds {
            let insn = enc_sve_fp_cmp(size, cc13, bit4);
            // sNaN input on Vn: IOC for every valid condition.
            for &initial_fpsr in &[0u64, 0x10] {
                let mut st = ArmState::zeroed();
                st.fpsr = initial_fpsr;
                st.fpcr = 0;
                st.set_preg(1, 0xFFFF); // Pg = P1, all-active at VL=128
                let (lo, hi) = fill(bits, snan);
                st.set_vreg(RN as usize, lo, hi);
                // Vm = finite -0.0 so only the sNaN drives IOC.
                let (lo, hi) = fill(bits, 1u64 << (bits - 1));
                st.set_vreg(RM as usize, lo, hi);
                batch.push((
                    format!("sve_{cname}_{sname}_snan_fpsr{initial_fpsr:#x}"),
                    insn,
                    st,
                ));
            }
            // qNaN-only input on the conditions whose 51e73589 path raises IOC
            // for qNaN (cc13 == 0b010).
            if qnan_active {
                let mut st = ArmState::zeroed();
                st.fpsr = 0;
                st.fpcr = 0;
                st.set_preg(1, 0xFFFF);
                let (lo, hi) = fill(bits, qnan);
                st.set_vreg(RN as usize, lo, hi);
                let (lo, hi) = fill(bits, 1u64 << (bits - 1)); // -0.0, finite
                st.set_vreg(RM as usize, lo, hi);
                batch.push((format!("sve_{cname}_{sname}_qnan"), insn, st));
            }
        }

        // Compare-with-zero conditions (bits[17:16]=sub, bit4). The 51e73589
        // fix raises FPSR.IOC for these forms ONLY on sNaN inputs (no qNaN
        // path for zero-compares in this commit). Valid forms:
        // (00,0)GE (00,1)GT (01,0)LT (01,1)LE (10,0)EQ (11,0)NE.
        let zero_conds: [(u32, u32, &str); 6] = [
            (0b00, 0, "fcmge0"),
            (0b00, 1, "fcmgt0"),
            (0b01, 0, "fcmlt0"),
            (0b01, 1, "fcmle0"),
            (0b10, 0, "fcmeq0"),
            (0b11, 0, "fcmne0"),
        ];
        for &(sub, bit4, cname) in &zero_conds {
            let insn = enc_sve_fp_cmp0(size, sub, bit4);
            for &initial_fpsr in &[0u64, 0x10] {
                let mut st = ArmState::zeroed();
                st.fpsr = initial_fpsr;
                st.fpcr = 0;
                st.set_preg(1, 0xFFFF);
                let (lo, hi) = fill(bits, snan);
                st.set_vreg(RN as usize, lo, hi);
                batch.push((
                    format!("sve_{cname}_{sname}_snan_fpsr{initial_fpsr:#x}"),
                    insn,
                    st,
                ));
            }
        }
    }

    run_fpsr_batch("sve_fp_cmp_fpsr_invalid", batch);
}

// commit 3050e8c62aaf temp: set sve bfcvt fpsr
#[test]
fn diff_sve_bfcvt_fpsr_exceptions() {
    fn pack_u32(values: [u32; 4]) -> (u64, u64) {
        let mut packed = 0u128;
        for (lane, value) in values.iter().enumerate() {
            packed |= (*value as u128) << (lane * 32);
        }
        (packed as u64, (packed >> 64) as u64)
    }

    let insn = enc_sve_bfcvt(); // BFCVT Zd.H, Pg/M, Zn.S ; Zn=Z1, Zd=Z0, Pg=P0
    let patterns: [(&str, [u32; 4]); 4] = [
        // Plain inexact: 1.0 with extra low mantissa bits that don't fit bf16 -> IXC.
        ("ixc", [0x3F80_8001, 0x3F80_8001, 0x3F80_8001, 0x3F80_8001]),
        // sNaN inputs (exp all-ones, MSB of mantissa clear, nonzero) -> IOC.
        (
            "ioc_snan",
            [0x7FA0_0001, 0x7FA0_0001, 0x7FA0_0001, 0x7FA0_0001],
        ),
        // Max finite f32 rounds up to bf16 infinity -> OFC|IXC.
        ("ofc", [0x7F7F_FFFF, 0xFF7F_FFFF, 0x7F7F_FFFF, 0xFF7F_FFFF]),
        // Mixed: snan, inexact-normal, overflow, finite-exact for cross coverage.
        (
            "mixed",
            [0x7FA0_0001, 0x3F80_8001, 0x7F7F_FFFF, 0x3F80_0000],
        ),
    ];

    let mut batch: Vec<(String, u32, ArmState)> = Vec::new();
    for (name, lanes) in patterns {
        for initial_fpsr in [0u64, 0x10] {
            let mut st = ArmState::zeroed();
            st.fpsr = initial_fpsr;
            st.fpcr = 0; // round-to-nearest, no FTZ/AH: baseline semantics
            let (lo, hi) = pack_u32(lanes);
            st.set_vreg(RN as usize, lo, hi);
            st.set_vreg(RD as usize, 0, 0);
            st.set_preg(0, 0xFFFF); // all lanes active at VL=128
            batch.push((format!("sve_bfcvt_{name}_fpsr{initial_fpsr:#x}"), insn, st));
        }
    }
    run_fpsr_batch("sve_bfcvt_fpsr_exceptions", batch);
}

// commit b8f4f24bd766 temp: set simd bfcvt fpsr
#[test]
fn diff_simd_bfcvt_fpsr() {
    let bfcvt = 0x1E63_4000 | (RN << 5) | RD; // BFCVT Hd, Sn
    let bfcvtn = 0x0EA1_6800 | (RN << 5) | RD; // BFCVTN Vd.4H, Vn.4S
    let bfcvtn2 = 0x4EA1_6800 | (RN << 5) | RD; // BFCVTN2 Vd.8H, Vn.4S

    // f32 source patterns, each chosen to drive a distinct fp_status_bfcvt branch:
    //   sNaN          -> IOC (exponent all-1, mantissa MSB clear, nonzero)
    //   1.0 + 1ulp    -> IXC (low 16 mantissa bits dropped, inexact)
    //   FLT_MAX       -> OFC|IXC (rounds up to bf16 +Inf, result_abs==0x7F80)
    //   tiny normal   -> UFC|IXC (rounds to bf16 zero, result exponent bits==0)
    let triggers: [(&str, u32); 4] = [
        ("ioc_snan", 0x7F80_0001),
        ("ixc_inexact", 0x3F80_0001),
        ("ofc_max", 0x7F7F_FFFF),
        ("ufc_tiny", 0x0000_8000),
    ];

    let mut batch: Vec<(String, u32, ArmState)> = Vec::new();
    for &(name, src) in &triggers {
        for initial_fpsr in [0u64, 0x10] {
            // Scalar BFCVT: single f32 in Vn low 32 bits.
            let mut st = ArmState::zeroed();
            st.fpsr = initial_fpsr;
            st.fpcr = 0;
            st.set_vreg(RN as usize, src as u64, 0);
            batch.push((format!("bfcvt_{name}_fpsr{initial_fpsr:#x}"), bfcvt, st));

            // Vector BFCVTN / BFCVTN2: same trigger in all four f32 lanes of Vn.
            let lo = (src as u64) | ((src as u64) << 32);
            let hi = (src as u64) | ((src as u64) << 32);
            for &(vname, insn) in &[("bfcvtn", bfcvtn), ("bfcvtn2", bfcvtn2)] {
                let mut st = ArmState::zeroed();
                st.fpsr = initial_fpsr;
                st.fpcr = 0;
                st.set_vreg(RN as usize, lo, hi);
                // Preset Vd so BFCVTN2's preserved low half is observable.
                st.set_vreg(RD as usize, 0xDEAD_BEEF_CAFE_F00D, 0x0123_4567_89AB_CDEF);
                batch.push((format!("{vname}_{name}_fpsr{initial_fpsr:#x}"), insn, st));
            }
        }
    }
    run_fpsr_batch("simd_bfcvt_fpsr", batch);
}

// commit d7c21eed0c5e temp: set sve flogb fpsr
#[test]
fn diff_sve_flogb_fpsr() {
    let mut batch: Vec<(String, u32, ArmState)> = Vec::new();
    // size field (insn[18:17]); interp computes esz = 1 << size:
    //   1 => esz 2 (half), 2 => esz 4 (single), 3 => esz 8 (double).
    // size 0 is reserved (#UD), so it is omitted.
    let cases: &[(u32, &str, &[u64])] = &[
        (
            1,
            "h",
            &[
                0x0000, // +0   -> FPSR_IOC
                0x8000, // -0   -> FPSR_IOC
                0x7E00, // qNaN -> FPSR_IOC
                0x7C01, // sNaN -> FPSR_IOC
            ],
        ),
        (
            2,
            "s",
            &[
                0x0000_0000, // +0
                0x8000_0000, // -0
                0x7FC0_0000, // qNaN
                0x7F80_0001, // sNaN
            ],
        ),
        (
            3,
            "d",
            &[
                0x0000_0000_0000_0000, // +0
                0x8000_0000_0000_0000, // -0
                0x7FF8_0000_0000_0000, // qNaN
                0x7FF0_0000_0000_0001, // sNaN
            ],
        ),
    ];
    for &(size, name, inputs) in cases {
        let insn = enc_sve_flogb(size);
        let esz = match size {
            1 => 2usize,
            2 => 4,
            _ => 8,
        };
        let lanes = 16 / esz;
        for &bits in inputs {
            for initial_fpsr in [0u64, 0x10] {
                let mut st = ArmState::zeroed();
                st.fpsr = initial_fpsr;
                st.fpcr = 0;
                // Broadcast the IOC-triggering pattern across every lane.
                let mut zn: u128 = 0;
                for l in 0..lanes {
                    zn |= (bits as u128) << (l * esz * 8);
                }
                st.set_vreg(RN as usize, zn as u64, (zn >> 64) as u64);
                // All-active governing predicate P0 so every lane is processed.
                st.set_preg(0, 0xFFFF);
                batch.push((
                    format!("flogb_{name}_ioc_{bits:#x}_fpsr{initial_fpsr:#x}"),
                    insn,
                    st,
                ));
            }
        }
    }
    run_fpsr_batch("sve_flogb_fpsr", batch);
}

// commit f5d9f8780dc1 temp: set sve2 fcvt fpsr
#[test]
fn diff_sve2_fcvt_narrow_fpsr() {
    let mut batch: Vec<(String, u32, ArmState)> = Vec::new();

    // (opc, opc2, src_sz, dst_sz, bf, name)
    let convs: &[(u32, u32, usize, usize, bool, &str)] = &[
        (0b10, 0b00, 4, 2, false, "fcvtnt_s2h"),  // f32 -> f16 (top)
        (0b11, 0b10, 8, 4, false, "fcvtnt_d2s"),  // f64 -> f32 (top)
        (0b00, 0b10, 8, 4, false, "fcvtxnt_d2s"), // f64 -> f32 round-to-odd (top)
        (0b10, 0b10, 4, 2, true, "bfcvtnt_s2bf16"), // f32 -> bf16 (top)
    ];

    for &(opc, opc2, src_sz, dst_sz, bf, name) in convs {
        let insn = enc_sve2_fcvtx(opc, opc2);
        let cont = src_sz.max(dst_sz); // container = wider element
        let containers = 16 / cont;

        // Special source values chosen to drive each new flag-emitting path.
        // For narrow non-bf: inexact (IXC), overflow (OFC|IXC), sNaN (IOC).
        // For bf (BFCVTNT): inexact mantissa truncation (IXC).
        let specials: &[u64] = if bf {
            // f32 with nonzero low-16 mantissa bits -> inexact bf16 narrowing.
            &[0x3f80_8000, 0x4049_1234, 0xbf80_0001, 0x3fc0_5555]
        } else {
            match src_sz {
                4 => &[
                    (2049.0f32).to_bits() as u64,  // not representable in f16 -> IXC
                    (70000.0f32).to_bits() as u64, // > f16 max -> OFC | IXC
                    0x7fa0_0001,                   // sNaN f32 -> IOC
                    (3.14159f32).to_bits() as u64, // inexact -> IXC
                ],
                _ => &[
                    (16_777_217.0f64).to_bits(), // not representable in f32 -> IXC
                    (1.0e300f64).to_bits(),      // > f32 max -> OFC | IXC
                    0x7ff0_0000_0000_0001,       // sNaN f64 -> IOC
                    (2.718281828f64).to_bits(),  // inexact -> IXC
                ],
            }
        };

        for initial_fpsr in [0u64, 0x10] {
            let mut zn = 0u128;
            for c in 0..containers {
                let bits = specials[c % specials.len()] as u128;
                // Narrow forms read the source from the whole (low) container.
                zn |= bits << ((c * cont) * 8);
            }
            let mut st = ArmState::zeroed();
            st.fpsr = initial_fpsr;
            st.fpcr = 0; // round-to-nearest, no FZ/AH: baseline FPSR semantics
            st.set_vreg(RN as usize, zn as u64, (zn >> 64) as u64);
            // Preserved (bottom) halves of the destination.
            st.set_vreg(RD as usize, 0x0123_4567_89ab_cdef, 0xfedc_ba98_7654_3210);
            st.set_preg(0, 0xffff); // all containers active
            batch.push((format!("{name}_fpsr{initial_fpsr:#x}"), insn, st));
        }
    }

    run_fpsr_batch("sve2_fcvt_narrow_fpsr", batch);
}

// commit 4f178c517a7a temp: set sve fpairwise fpsr
#[test]
fn diff_sve2_fpairwise_faddp_fpsr() {
    // The commit makes the SVE FP pairwise path OR fp_status_binop(esize, kind, ..)
    // into FPSR for each active even/odd pair. The dispatch maps opc=0b000 to
    // FpKind::Add, so the FADDP form is the one whose pairwise adds actually feed
    // the helper a status (FMAXP/FMINP map to Max/Min, which return 0). Before the
    // fix the pairwise path produced the result but never updated FPSR, so any
    // inexact / invalid / overflow pair diverges from the hardware oracle.
    //
    // enc_sve2_fpairwise(size, opc): size 1=H, 2=S, 3=D (size==00 reserved);
    // opc 0b000 => FADDP (kind Add). Encoding places Zdn=z0 (RD), Zm=z1 (RN).
    // Even lane of each pair comes from Zdn, odd lane from Zm; both halves of the
    // 128-bit reg are filled so every active pair trips a flag. Pg=p0 all-active.
    let mut batch: Vec<(String, u32, ArmState)> = Vec::new();

    // ---- half precision (size=1) ----
    // 1.0h = 0x3c00; 0x1000 = 2^-11 (half a ULP at 1.0) so 1.0h + 2^-11 rounds
    // back to 1.0 -> IXC. inf + -inf -> IOC. 0x7bff (largest finite half) added to
    // itself overflows to inf -> OFC|IXC.
    {
        let h_one: u16 = 0x3c00;
        let h_tiny: u16 = 0x1000; // 2^-11, lost when added to 1.0 -> IXC
        let h_inf: u16 = 0x7c00;
        let h_ninf: u16 = 0xfc00;
        let h_max: u16 = 0x7bff; // largest finite half; max+max -> inf -> OFC|IXC
        let pack_h = |l0: u16, l1: u16, l2: u16, l3: u16| -> u64 {
            (l0 as u64) | ((l1 as u64) << 16) | ((l2 as u64) << 32) | ((l3 as u64) << 48)
        };
        // Zdn pairs: (1.0,tiny)=IXC, (inf,-inf)=IOC, (max,max)=OFC|IXC, (1.0,tiny)=IXC.
        let lo = pack_h(h_one, h_tiny, h_inf, h_ninf);
        let hi = pack_h(h_max, h_max, h_one, h_tiny);
        let insn = enc_sve2_fpairwise(1, 0b000);
        for initial_fpsr in [0u64, 0x10] {
            let mut st = ArmState::zeroed();
            st.fpsr = initial_fpsr;
            st.fpcr = 0;
            st.set_preg(0, 0xFFFF);
            st.set_vreg(RD as usize, lo, hi); // Zdn
            st.set_vreg(RN as usize, lo, hi); // Zm
            batch.push((format!("faddp_h_fpsr{initial_fpsr:#x}"), insn, st));
        }
    }

    // ---- single precision (size=2) ----
    {
        let one = 1.0f32.to_bits() as u64;
        let tiny = 0x3380_0000u64; // 2^-24, half a ULP at 1.0 -> lost -> IXC
        let inf = f32::INFINITY.to_bits() as u64;
        let ninf = f32::NEG_INFINITY.to_bits() as u64;
        let maxf = f32::MAX.to_bits() as u64; // MAX+MAX -> inf -> OFC|IXC
        let pack_s = |l0: u64, l1: u64| -> u64 { l0 | (l1 << 32) };
        let lo = pack_s(one, tiny); // pair0: 1.0+2^-24 -> IXC
        let hi = pack_s(inf, ninf); // pair1: inf + -inf -> IOC
        let lo2 = pack_s(maxf, maxf); // pair: MAX+MAX -> OFC|IXC
        let hi2 = pack_s(one, tiny); // pair: IXC
        let insn = enc_sve2_fpairwise(2, 0b000);
        for initial_fpsr in [0u64, 0x10] {
            let mut st = ArmState::zeroed();
            st.fpsr = initial_fpsr;
            st.fpcr = 0;
            st.set_preg(0, 0xFFFF);
            st.set_vreg(RD as usize, lo, hi); // Zdn: IXC pair + IOC pair
            st.set_vreg(RN as usize, lo2, hi2); // Zm: OFC|IXC pair + IXC pair
            batch.push((format!("faddp_s_fpsr{initial_fpsr:#x}"), insn, st));
        }
    }

    // ---- double precision (size=3) ----
    // 2 D lanes => one pair per 128-bit reg.
    {
        let one = 1.0f64.to_bits();
        let tiny = 0x3C90_0000_0000_0000u64; // 2^-54, half a ULP at 1.0 -> lost -> IXC
        let inf = f64::INFINITY.to_bits();
        let ninf = f64::NEG_INFINITY.to_bits();
        let maxf = f64::MAX.to_bits(); // MAX+MAX -> inf -> OFC|IXC
        let insn = enc_sve2_fpairwise(3, 0b000);
        for initial_fpsr in [0u64, 0x10] {
            let mut st = ArmState::zeroed();
            st.fpsr = initial_fpsr;
            st.fpcr = 0;
            st.set_preg(0, 0xFFFF);
            st.set_vreg(RD as usize, one, tiny); // Zdn pair: 1.0+2^-54 -> IXC
            st.set_vreg(RN as usize, inf, ninf); // Zm pair: inf + -inf -> IOC
            batch.push((format!("faddp_d_ixc_ioc_fpsr{initial_fpsr:#x}"), insn, st));

            let mut st2 = ArmState::zeroed();
            st2.fpsr = initial_fpsr;
            st2.fpcr = 0;
            st2.set_preg(0, 0xFFFF);
            st2.set_vreg(RD as usize, maxf, maxf); // Zdn pair: MAX+MAX -> OFC|IXC
            st2.set_vreg(RN as usize, one, tiny); // Zm pair: IXC
            batch.push((format!("faddp_d_ofc_fpsr{initial_fpsr:#x}"), insn, st2));
        }
    }

    run_fpsr_batch("sve2_fpairwise_faddp_fpsr", batch);
}

// commit 0d477d7c0f17 temp: set sve fcadd fpsr
#[test]
fn diff_sve_fcadd_fpsr() {
    let mut batch: Vec<(String, u32, ArmState)> = Vec::new();
    // (size field, +inf bit pattern, big, small) for H/S/D.
    // big/small drive the inexact (IXC) case; ignored for H (skipped).
    let cfgs: [(u32, u64, u64, u64); 3] = [
        // H: +inf=0x7C00 (IXC row skipped, big/small unused).
        (1, 0x7C00, 0, 0),
        // S: +inf; 1.0 + 2^-25 not representable in f32 => IXC.
        (
            2,
            0x7F80_0000,
            (1.0f32).to_bits() as u64,
            (2.0f32.powi(-25)).to_bits() as u64,
        ),
        // D: +inf; 1.0 + 2^-54 not representable in f64 => IXC.
        (
            3,
            0x7FF0_0000_0000_0000,
            (1.0f64).to_bits(),
            (2.0f64.powi(-54)).to_bits(),
        ),
    ];
    for &(size, inf, big, small) in &cfgs {
        for rot in 0..2u32 {
            let insn = enc_sve_fcadd(size, rot);
            let bits = 8u32 << size;
            let nlane = 128 / bits as usize;
            // Invalid (IOC): every lane of both Zdn and Zm = +inf. For each
            // complex pair one of the two internal adds is inf + (-inf) for
            // either rotation (rot0: re=Zdn_re+(-Zm_im); rot1: im=Zdn_im+(-Zm_re)).
            {
                let mut a = 0u128;
                for l in 0..nlane {
                    a |= (inf as u128) << (l * bits as usize);
                }
                for &initial_fpsr in &[0u64, 0x10] {
                    let mut st = ArmState::zeroed();
                    st.fpsr = initial_fpsr;
                    st.fpcr = 0;
                    st.set_vreg(RD as usize, a as u64, (a >> 64) as u64); // Zdn
                    st.set_vreg(RN as usize, a as u64, (a >> 64) as u64); // Zm
                    st.set_preg(0, 0xFFFF);
                    batch.push((
                        format!("fcadd_ioc_s{size}_r{rot}_f{initial_fpsr:#x}"),
                        insn,
                        st,
                    ));
                }
            }
            // Inexact (IXC): big in Zdn, small in Zm; one internal sum is
            // not representable. Skip H (no meaningful half-precision pair set).
            if size != 1 {
                let mut dn = 0u128;
                let mut zm = 0u128;
                for l in 0..nlane {
                    dn |= (big as u128) << (l * bits as usize);
                    zm |= (small as u128) << (l * bits as usize);
                }
                let mut st = ArmState::zeroed();
                st.fpsr = 0;
                st.fpcr = 0;
                st.set_vreg(RD as usize, dn as u64, (dn >> 64) as u64); // Zdn
                st.set_vreg(RN as usize, zm as u64, (zm >> 64) as u64); // Zm
                st.set_preg(0, 0xFFFF);
                batch.push((format!("fcadd_ixc_s{size}_r{rot}"), insn, st));
            }
        }
    }
    run_fpsr_batch("sve_fcadd_fpsr", batch);
}

// commit 7934f4d598f2 temp: set sve fcmla fpsr
#[test]
fn diff_sve_fcmla_fpsr() {
    let mut batch: Vec<(String, u32, ArmState)> = Vec::new();
    // size: 01=H(esz2), 10=S(esz4), 11=D(esz8). size==00 is reserved (#UD).
    for &size in &[1u32, 2, 3] {
        // rot=0 selects (x=a_re, y=b_re) for the real lane, so an inf real in Zn
        // times a zero real in Zm yields the invalid-product IOC.
        for &rot in &[0u32, 1, 2, 3] {
            let insn = enc_sve_fcmla(size, rot);
            for initial_fpsr in [0u64, 0x10] {
                let mut st = ArmState::zeroed();
                st.fpsr = initial_fpsr;
                st.fpcr = 0;
                // Zn = all +inf, Zm = all +0.0, acc (Zda) = finite (1.0).
                let (zn_lo, zn_hi, zm_lo, zm_hi, acc_lo, acc_hi): (u64, u64, u64, u64, u64, u64) =
                    match size {
                        1 => {
                            // half: 8 lanes of 0x7C00 (inf) / 0x0000 (zero) / 0x3C00 (1.0)
                            let inf = 0x7C00u16;
                            let one = 0x3C00u16;
                            let mut zn: u128 = 0;
                            let mut acc: u128 = 0;
                            for l in 0..8 {
                                zn |= (inf as u128) << (l * 16);
                                acc |= (one as u128) << (l * 16);
                            }
                            (
                                zn as u64,
                                (zn >> 64) as u64,
                                0,
                                0,
                                acc as u64,
                                (acc >> 64) as u64,
                            )
                        }
                        2 => {
                            // single: 4 lanes
                            let inf = (f32::INFINITY).to_bits();
                            let one = (1.0f32).to_bits();
                            let mut zn: u128 = 0;
                            let mut acc: u128 = 0;
                            for l in 0..4 {
                                zn |= (inf as u128) << (l * 32);
                                acc |= (one as u128) << (l * 32);
                            }
                            (
                                zn as u64,
                                (zn >> 64) as u64,
                                0,
                                0,
                                acc as u64,
                                (acc >> 64) as u64,
                            )
                        }
                        _ => {
                            // double: 2 lanes
                            let inf = (f64::INFINITY).to_bits();
                            let one = (1.0f64).to_bits();
                            (inf, inf, 0, 0, one, one)
                        }
                    };
                st.set_vreg(RN as usize, zn_lo, zn_hi); // Zn
                st.set_vreg(RM as usize, zm_lo, zm_hi); // Zm
                st.set_vreg(RD as usize, acc_lo, acc_hi); // Zda (accumulator)
                st.set_preg(0, 0xFFFF); // P0 all-active (pg=0 for this encoding)
                batch.push((
                    format!("sve_fcmla_sz{size}_rot{rot}_ioc_fpsr{initial_fpsr:#x}"),
                    insn,
                    st,
                ));
            }
        }
    }
    run_fpsr_batch("sve_fcmla_fpsr", batch);
}

// commit 5424a4f3739a temp: set sve fcmla indexed fpsr
#[test]
fn diff_sve_fcmla_indexed_fpsr() {
    let mut batch: Vec<(String, u32, ArmState)> = Vec::new();
    // Indexed FCMLA supports .h (size=2, esize=2) and .s (size=3, esize=4) only.
    for &(size, esz) in &[(2u32, 2usize), (3u32, 4usize)] {
        // sNaN, +inf, +0.0, 1.0, and a sub-half-ULP "tiny" value, per element size.
        let (snan, pinf, pzero, one, tiny): (u64, u64, u64, u64, u64) = if esz == 2 {
            // half: sNaN=0x7c01, +inf=0x7c00, +0=0, 1.0=0x3c00,
            // tiny=0x0400 (2^-14, smallest normal; far below the 2^-10 ULP at 1.0).
            (0x7c01, 0x7c00, 0x0000, 0x3c00, 0x0400)
        } else {
            // single: sNaN=0x7fa00000, +inf=0x7f800000, +0=0, 1.0,
            // tiny=2^-24 (half-ULP at 1.0 -> inexact when added to 1.0).
            (
                0x7fa0_0000,
                0x7f80_0000,
                0x0000_0000,
                (1.0f32).to_bits() as u64,
                (2.0f32.powi(-24)).to_bits() as u64,
            )
        };
        let pack = |lanes: &[u64]| -> u128 {
            let mut out = 0u128;
            for (l, &v) in lanes.iter().enumerate() {
                out |= (v as u128) << (l * esz * 8);
            }
            out
        };
        let nlanes = 16 / esz;
        // index=0 selects the Zm complex pair at lanes [0]=real,[1]=imag. rot=0:
        // flip=0, no negate, so dr = acc_re + Zn_re * Zm_re, di = acc_im + Zn_im * Zm_im.
        let index = 0u32;
        let rot = 0u32;
        let insn = enc_sve_fcmla_idx(size, index, RM, rot);

        // Case 1: sNaN in the accumulator -> fp_status_fma returns IOC for both FMAs.
        {
            let mut st = ArmState::zeroed();
            st.fpcr = 0;
            st.set_preg(0, 0xFFFF);
            let acc: Vec<u64> = (0..nlanes).map(|_| snan).collect();
            let zn: Vec<u64> = (0..nlanes).map(|_| one).collect();
            let zm: Vec<u64> = (0..nlanes).map(|_| one).collect();
            let za = pack(&acc);
            let zn = pack(&zn);
            let zm = pack(&zm);
            st.set_vreg(RD as usize, za as u64, (za >> 64) as u64);
            st.set_vreg(RN as usize, zn as u64, (zn >> 64) as u64);
            st.set_vreg(RM as usize, zm as u64, (zm >> 64) as u64);
            batch.push((format!("fcmla_idx_s{size}_snan_acc"), insn, st));
        }

        // Case 2: inf * 0 invalid product -> IOC. Zn lanes = +inf, Zm pair = +0.
        for initial_fpsr in [0u64, 0x10] {
            let mut st = ArmState::zeroed();
            st.fpcr = 0;
            st.fpsr = initial_fpsr;
            st.set_preg(0, 0xFFFF);
            let acc: Vec<u64> = (0..nlanes).map(|_| one).collect();
            let zn: Vec<u64> = (0..nlanes).map(|_| pinf).collect();
            let zm: Vec<u64> = (0..nlanes).map(|_| pzero).collect();
            let za = pack(&acc);
            let zn = pack(&zn);
            let zm = pack(&zm);
            st.set_vreg(RD as usize, za as u64, (za >> 64) as u64);
            st.set_vreg(RN as usize, zn as u64, (zn >> 64) as u64);
            st.set_vreg(RM as usize, zm as u64, (zm >> 64) as u64);
            batch.push((
                format!("fcmla_idx_s{size}_inf0_ioc_fpsr{initial_fpsr:#x}"),
                insn,
                st,
            ));
        }

        // Case 3: inexact finite accumulate -> IXC. dr = 1.0 + 1.0 * tiny, not representable.
        {
            let mut st = ArmState::zeroed();
            st.fpcr = 0;
            st.set_preg(0, 0xFFFF);
            let acc: Vec<u64> = (0..nlanes).map(|_| one).collect();
            let zn: Vec<u64> = (0..nlanes).map(|_| one).collect();
            let zm: Vec<u64> = (0..nlanes).map(|_| tiny).collect();
            let za = pack(&acc);
            let zn = pack(&zn);
            let zm = pack(&zm);
            st.set_vreg(RD as usize, za as u64, (za >> 64) as u64);
            st.set_vreg(RN as usize, zn as u64, (zn >> 64) as u64);
            st.set_vreg(RM as usize, zm as u64, (zm >> 64) as u64);
            batch.push((format!("fcmla_idx_s{size}_inexact_ixc"), insn, st));
        }
    }
    run_fpsr_batch("sve_fcmla_indexed_fpsr", batch);
}

// commit e4473ffb2628 temp: set sve fmlal fpsr
#[test]
fn diff_sve_fmlal_fpsr_exceptions() {
    // sNaN f16 (exp=0x1F, top mantissa bit clear, nonzero payload), replicated
    // across all 8 halfword lanes; 1.0 (0x3c00) for the other operand. When
    // widened to f32 the sNaN stays an f32 sNaN (0x7FA02000), so the
    // commit's fp_status_fma(4,..) returns FPSR_IOC for every lane. Without the
    // fix FPSR stays 0 and diverges from the oracle.
    let snan_h: u64 = 0x7D01_7D01_7D01_7D01;
    let one_h: u64 = 0x3C00_3C00_3C00_3C00;

    let mut batch: Vec<(String, u32, ArmState)> = Vec::new();

    // Non-indexed FMLALB/T and FMLSLB/T: sub=bit13, top=bit10.
    for &sub in &[0u32, 1] {
        for &top in &[0u32, 1] {
            let insn = enc_sve2_fmlal(sub, top);
            for initial_fpsr in [0u64, 0x10] {
                let mut st = ArmState::zeroed();
                st.fpsr = initial_fpsr;
                st.fpcr = 0;
                st.set_preg(0, 0xFFFF);
                // Zn (RN) carries the sNaN, Zm (RM) carries 1.0, Zda (RD)=0.
                st.set_vreg(RN as usize, snan_h, snan_h);
                st.set_vreg(RM as usize, one_h, one_h);
                st.set_vreg(RD as usize, 0, 0);
                batch.push((
                    format!("sve_fmlal_snan_sub{sub}_top{top}_fpsr{initial_fpsr:#x}"),
                    insn,
                    st,
                ));
            }
        }
    }

    // Indexed FMLALB/T and FMLSLB/T: Zm restricted to z0..z7 (RM=2), index=3.
    for &sub in &[0u32, 1] {
        for &top in &[0u32, 1] {
            let insn = enc_sve2_fmlal_idx(sub, top, 3, RM);
            let mut st = ArmState::zeroed();
            st.fpsr = 0;
            st.fpcr = 0;
            st.set_preg(0, 0xFFFF);
            st.set_vreg(RN as usize, snan_h, snan_h);
            st.set_vreg(RM as usize, one_h, one_h);
            st.set_vreg(RD as usize, 0, 0);
            batch.push((format!("sve_fmlal_idx_snan_sub{sub}_top{top}"), insn, st));
        }
    }

    run_fpsr_batch("sve_fmlal_fpsr_exceptions", batch);
}

// commit 15630f3b5c9f temp: set simd bfmlal fpsr
#[test]
fn diff_simd_bfmlal_fpsr() {
    let mut batch: Vec<(String, u32, ArmState)> = Vec::new();
    // q: 0 = BFMLALB (reads bf16 even lanes 0,2,..), 1 = BFMLALT (odd lanes 1,3,..).
    // For output f32 lane e, the impl reads bf16 lane (2*e + q) of Vn/Vm and the
    // f32 addend from Vd lane e. The commit added
    //   self.fpsr |= fp_status_fma(4, a, b1<<16, b2<<16, r)
    // per f32 lane, so BFMLALB/BFMLALT must raise IOC (inf*0 invalid-fma) and
    // IXC (lossy single-rounded accumulate) like the HW oracle. fpcr=0 keeps
    // the standard (AH-off) path so bfmlal_ah_result()==None and fp_status_fma
    // is the flag source.
    for &q in &[0u32, 1u32] {
        let bf_lane = q as usize; // bf16 lane feeding output f32 lane 0
        let insn = enc_bfmlal(q);

        // bf16 bit patterns (high 16 bits of the widened f32, since b<<16).
        let bf_inf: u16 = 0x7F80; // +inf
        let bf_one: u16 = 0x3F80; // 1.0

        for initial_fpsr in [0u64, 0x10] {
            // --- IOC: inf * 0 invalid-fma, addend +0.0 (f32 lane 0). ---
            let mut st = ArmState::zeroed();
            st.fpsr = initial_fpsr;
            st.fpcr = 0;
            st.set_vreg(RN as usize, (bf_inf as u64) << (16 * bf_lane), 0);
            st.set_vreg(RM as usize, 0, 0); // bf16 +0.0 in lane bf_lane
            st.set_vreg(RD as usize, 0, 0); // f32 addend lane 0 = +0.0
            batch.push((format!("bfmlal_q{q}_ioc_fpsr{initial_fpsr:#x}"), insn, st));

            // --- IXC: 1.0*1.0 added to a 2^24 accumulator -> 2^24+1 not
            //     representable in f32, rounds -> inexact. ---
            let mut st = ArmState::zeroed();
            st.fpsr = initial_fpsr;
            st.fpcr = 0;
            st.set_vreg(RN as usize, (bf_one as u64) << (16 * bf_lane), 0);
            st.set_vreg(RM as usize, (bf_one as u64) << (16 * bf_lane), 0);
            st.set_vreg(RD as usize, (2.0f32).powi(24).to_bits() as u64, 0);
            batch.push((format!("bfmlal_q{q}_ixc_fpsr{initial_fpsr:#x}"), insn, st));
        }
    }
    run_fpsr_batch("simd_bfmlal_fpsr", batch);
}

// commit 71deeb5bdf41 temp: set simd fmlal fpsr
#[test]
fn diff_simd_fmlal_fpsr_exceptions() {
    // FP16 bit patterns (fpcr=0: round-to-nearest, no FTZ, no AH).
    const H_ZERO: u64 = 0x0000; // +0.0
    const H_ONE: u64 = 0x3C00; // +1.0
    const H_INF: u64 = 0x7C00; // +inf
    // F32 accumulator = 2^24 (exactly representable); 2^24 + 1*1 is not -> IXC.
    const F32_2P24: u64 = 0x4B80_0000;

    // FEAT_FHM vector forms decoded by exec_fmlal(indexed=false):
    //   FMLAL/FMLSL : U==0, opcode 0b11101; sub (FMLSL) = bit23.
    //   FMLAL2/FMLSL2: U==1, opcode 0b11001; sub (FMLSL2) = bit23.
    // enc_three_same places `size` at bits[23:22], so size bit1 (=0b10) sets
    // bit23 = the sub bit. The decode rejects bit22 (size&1) -> keep it clear.
    // (u, size, opcode, top, name)
    let forms: &[(u32, u32, u32, bool, &str)] = &[
        (0, 0b00, 0b11101, false, "fmlal"),
        (0, 0b10, 0b11101, false, "fmlsl"),
        (1, 0b00, 0b11001, true, "fmlal2"),
        (1, 0b10, 0b11001, true, "fmlsl2"),
    ];

    let mut batch: Vec<(String, u32, ArmState)> = Vec::new();
    for &(u, size, opcode, top, name) in forms {
        // q=0 -> 2 FP32 result lanes; "2" forms read FP16 source lanes [2..],
        // non-"2" forms read FP16 source lanes [0..]. The FP32 accumulator is
        // always read from the low result lanes regardless of the "2" variant.
        let insn = enc_three_same(0, u, size, opcode);
        let lane_shift: u32 = if top { 16 * 2 } else { 0 };
        for initial_fpsr in [0u64, 0x10] {
            // Invalid: product 0 * inf -> IOC via fp_invalid_fma_default_nan.
            let mut st_ioc = ArmState::zeroed();
            st_ioc.fpsr = initial_fpsr;
            st_ioc.set_vreg(RN as usize, H_ZERO << lane_shift, 0);
            st_ioc.set_vreg(RM as usize, H_INF << lane_shift, 0);
            st_ioc.set_vreg(RD as usize, 0, 0); // FP32 accumulator lane 0 = +0.0
            batch.push((
                format!("{name}_ioc_zero_times_inf_fpsr{initial_fpsr:#x}"),
                insn,
                st_ioc,
            ));

            // Inexact: acc(2^24) + 1.0*1.0 -> 2^24+1 not representable -> IXC.
            let mut st_ixc = ArmState::zeroed();
            st_ixc.fpsr = initial_fpsr;
            st_ixc.set_vreg(RN as usize, H_ONE << lane_shift, 0);
            st_ixc.set_vreg(RM as usize, H_ONE << lane_shift, 0);
            st_ixc.set_vreg(RD as usize, F32_2P24, 0); // FP32 accumulator lane 0
            batch.push((
                format!("{name}_ixc_acc_2p24_fpsr{initial_fpsr:#x}"),
                insn,
                st_ixc,
            ));
        }
    }
    run_fpsr_batch("simd_fmlal_fpsr_exceptions", batch);
}

// commit d48c0c245648 temp: set simd fdiv fpsr
#[test]
fn diff_simd_fdiv_fpsr_exceptions() {
    let mut batch: Vec<(String, u32, ArmState)> = Vec::new();

    // size=0 -> FDIV Vd.4S (single); size=1 -> FDIV Vd.2D (double).
    // enc_three_same(q=1, u=1, size, opcode=0b11111): (u=1,a=0,op=0b11111)=>Div,
    // with size==0b00 -> single (a=0,sz=0), size==0b01 -> double (a=0,sz=1).
    for &(size, name) in &[(0u32, "s"), (1u32, "d")] {
        let insn = enc_three_same(1, 1, size, 0b11111);

        // (numerator_bits, denominator_bits, cause) per exception class.
        let s_cases: [(u32, u32, &str); 4] = [
            (1.0f32.to_bits(), 0.0f32.to_bits(), "dzc"), // 1/0 -> DZC
            (0.0f32.to_bits(), 0.0f32.to_bits(), "ioc"), // 0/0 -> IOC
            (f32::MAX.to_bits(), (1e-30f32).to_bits(), "ofc"), // MAX/tiny -> OFC|IXC
            (1.0f32.to_bits(), (3.0f32).to_bits(), "ixc"), // 1/3 -> IXC
        ];
        let d_cases: [(u64, u64, &str); 4] = [
            (1.0f64.to_bits(), 0.0f64.to_bits(), "dzc"),
            (0.0f64.to_bits(), 0.0f64.to_bits(), "ioc"),
            (f64::MAX.to_bits(), (1e-300f64).to_bits(), "ofc"),
            (1.0f64.to_bits(), (3.0f64).to_bits(), "ixc"),
        ];

        for case in 0..4 {
            let (cause, n128, m128) = if size == 0 {
                let (n, m, cause) = s_cases[case];
                let mut nn = 0u128;
                let mut mm = 0u128;
                for lane in 0..4 {
                    nn |= (n as u128) << (32 * lane);
                    mm |= (m as u128) << (32 * lane);
                }
                (cause, nn, mm)
            } else {
                let (n, m, cause) = d_cases[case];
                let nn = (n as u128) | ((n as u128) << 64);
                let mm = (m as u128) | ((m as u128) << 64);
                (cause, nn, mm)
            };

            for initial_fpsr in [0, 0x10] {
                let mut st = ArmState::zeroed();
                st.fpsr = initial_fpsr;
                st.fpcr = 0;
                st.set_vreg(RN as usize, n128 as u64, (n128 >> 64) as u64);
                st.set_vreg(RM as usize, m128 as u64, (m128 >> 64) as u64);
                batch.push((
                    format!("simd_fdiv_{name}_{cause}_fpsr{initial_fpsr:#x}"),
                    insn,
                    st,
                ));
            }
        }
    }

    run_fpsr_batch("simd_fdiv_fpsr_exceptions", batch);
}

// commit 1a6cb0054330 temp: set simd cvtf fpsr
#[test]
fn diff_simd_cvtf_fpsr_inexact() {
    // enc_scalar_two_reg is added later in this branch; define it locally so the
    // test compiles at this commit.
    fn enc_scalar_two_reg(u: u32, size: u32, opcode: u32) -> u32 {
        (1 << 30)
            | (u << 29)
            | (0b11110 << 24)
            | (size << 22)
            | (0b10000 << 17)
            | (opcode << 12)
            | (0b10 << 10)
            | (RN << 5)
            | RD
    }
    let mut batch: Vec<(String, u32, ArmState)> = Vec::new();
    // (u, name) for SCVTF (signed) and UCVTF (unsigned).
    for &(u, op) in &[(0u32, "scvtf"), (1u32, "ucvtf")] {
        for initial_fpsr in [0u64, 0x10] {
            // S form: 24-bit mantissa, 2^24+1 = 16_777_217 is not representable.
            // Vector Q (4x32): enc_two_reg(q=1, u, size=0b00, opcode=0b11101).
            {
                let mut st = ArmState::zeroed();
                st.fpsr = initial_fpsr;
                let lane = 16_777_217u32;
                let mut packed = 0u128;
                for i in 0..4 {
                    packed |= (lane as u128) << (32 * i);
                }
                st.set_vreg(RN as usize, packed as u64, (packed >> 64) as u64);
                batch.push((
                    format!("{op}_vec_s_ixc_fpsr{initial_fpsr:#x}"),
                    enc_two_reg(1, u, 0b00, 0b11101),
                    st,
                ));
            }
            // S form scalar: enc_scalar_two_reg(u, size=0b00, opcode=0b11101).
            {
                let mut st = ArmState::zeroed();
                st.fpsr = initial_fpsr;
                st.set_vreg(RN as usize, 16_777_217u32 as u64, 0);
                batch.push((
                    format!("{op}_scl_s_ixc_fpsr{initial_fpsr:#x}"),
                    enc_scalar_two_reg(u, 0b00, 0b11101),
                    st,
                ));
            }
            // D form: 53-bit mantissa, 2^53+1 = 9_007_199_254_740_993 inexact.
            // Vector Q (2x64): enc_two_reg(q=1, u, size=0b01, opcode=0b11101).
            {
                let mut st = ArmState::zeroed();
                st.fpsr = initial_fpsr;
                let lane = 9_007_199_254_740_993u64;
                st.set_vreg(RN as usize, lane, lane);
                batch.push((
                    format!("{op}_vec_d_ixc_fpsr{initial_fpsr:#x}"),
                    enc_two_reg(1, u, 0b01, 0b11101),
                    st,
                ));
            }
            // D form scalar: enc_scalar_two_reg(u, size=0b01, opcode=0b11101).
            {
                let mut st = ArmState::zeroed();
                st.fpsr = initial_fpsr;
                st.set_vreg(RN as usize, 9_007_199_254_740_993u64, 0);
                batch.push((
                    format!("{op}_scl_d_ixc_fpsr{initial_fpsr:#x}"),
                    enc_scalar_two_reg(u, 0b01, 0b11101),
                    st,
                ));
            }
        }
    }
    run_fpsr_batch("simd_cvtf_fpsr_inexact", batch);
}

// commit 0adee55efb47 temp: set simd two-reg unary fpsr
#[test]
fn diff_simd_two_reg_unary_fpsr() {
    let mut batch: Vec<(String, u32, ArmState)> = Vec::new();
    // size field is {sz_hi, sz}: 0b10=FSQRT.f32, 0b11=FSQRT.f64,
    // 0b00=FRINTX.f32, 0b01=FRINTX.f64.
    for initial_fpsr in [0u64, 0x10] {
        // FSQRT f32 (U=1, size=0b10, opcode=0b11111): negative finite -> IOC.
        {
            let insn = enc_two_reg(1, 1, 0b10, 0b11111);
            let mut st = ArmState::zeroed();
            st.fpsr = initial_fpsr;
            let n = (-4.0f32).to_bits() as u64;
            let lane = n | (n << 32);
            st.set_vreg(RN as usize, lane, lane);
            batch.push((format!("fsqrt_s_ioc_fpsr{initial_fpsr:#x}"), insn, st));
        }
        // FSQRT f64 (U=1, size=0b11, opcode=0b11111): negative finite -> IOC.
        {
            let insn = enc_two_reg(1, 1, 0b11, 0b11111);
            let mut st = ArmState::zeroed();
            st.fpsr = initial_fpsr;
            let n = (-4.0f64).to_bits();
            st.set_vreg(RN as usize, n, n);
            batch.push((format!("fsqrt_d_ioc_fpsr{initial_fpsr:#x}"), insn, st));
        }
        // FRINTX f32 (U=1, size=0b00, opcode=0b11001): non-integral -> IXC.
        {
            let insn = enc_two_reg(1, 1, 0b00, 0b11001);
            let mut st = ArmState::zeroed();
            st.fpsr = initial_fpsr;
            let n = (1.5f32).to_bits() as u64;
            let lane = n | (n << 32);
            st.set_vreg(RN as usize, lane, lane);
            batch.push((format!("frintx_s_ixc_fpsr{initial_fpsr:#x}"), insn, st));
        }
        // FRINTX f64 (U=1, size=0b01, opcode=0b11001): non-integral -> IXC.
        {
            let insn = enc_two_reg(1, 1, 0b01, 0b11001);
            let mut st = ArmState::zeroed();
            st.fpsr = initial_fpsr;
            let n = (1.5f64).to_bits();
            st.set_vreg(RN as usize, n, n);
            batch.push((format!("frintx_d_ixc_fpsr{initial_fpsr:#x}"), insn, st));
        }
    }
    run_fpsr_batch("simd_two_reg_unary_fpsr", batch);
}

// commit a581e39bda99 temp: set simd fp-to-int fpsr
#[test]
fn diff_simd_fp_to_int_fpsr_exceptions() {
    // (name, u, sz_hi, opcode) for each vector fp->int convert kind. These match
    // the (u, sz_hi, opcode) -> TwoRegFp::Cvt* table in exec_simd_two_reg_fp.
    let kinds: &[(&str, u32, u32, u32)] = &[
        ("fcvtns", 0, 0, 0b11010),
        ("fcvtnu", 1, 0, 0b11010),
        ("fcvtms", 0, 0, 0b11011),
        ("fcvtmu", 1, 0, 0b11011),
        ("fcvtps", 0, 1, 0b11010),
        ("fcvtpu", 1, 1, 0b11010),
        ("fcvtzs", 0, 1, 0b11011),
        ("fcvtzu", 1, 1, 0b11011),
        ("fcvtas", 0, 0, 0b11100),
        ("fcvtau", 1, 0, 0b11100),
    ];

    // f32 / f64 inputs that drive the new fp_status_fp_to_int_unop path to a
    // nonzero flag:
    //   1.5  -> non-integral, in range  => IXC (inexact; input != rounded)
    //   NaN  -> => IOC (invalid; input.is_nan())
    //   1e30 -> out of signed/unsigned 32/64-bit range after rounding => IOC
    let f32_inputs: &[(&str, u32)] = &[
        ("ixc", (1.5f32).to_bits()),
        ("ioc_nan", f32::NAN.to_bits()),
        ("ioc_oor", (1e30f32).to_bits()),
    ];
    let f64_inputs: &[(&str, u64)] = &[
        ("ixc", (1.5f64).to_bits()),
        ("ioc_nan", f64::NAN.to_bits()),
        ("ioc_oor", (1e30f64).to_bits()),
    ];

    let pack_s = |value: u32| -> (u64, u64) {
        let mut packed = 0u128;
        for lane in 0..4 {
            packed |= (value as u128) << (32 * lane);
        }
        (packed as u64, (packed >> 64) as u64)
    };
    let pack_d = |value: u64| -> (u64, u64) {
        let packed = (value as u128) | ((value as u128) << 64);
        (packed as u64, (packed >> 64) as u64)
    };

    let mut batch: Vec<(String, u32, ArmState)> = Vec::new();
    for &(kname, u, sz_hi, opcode) in kinds {
        // S (sz=0) and D (sz=1). The encoding size field is {sz_hi, sz}: bit23
        // (sz_hi) selects the Cvt* variant, bit22 (sz) selects f32/f64 esize.
        for &sz in &[0u32, 1] {
            let size = (sz_hi << 1) | sz;
            let insn = enc_two_reg(1, u, size, opcode); // Q=1 (full 128-bit vector)
            for &initial_fpsr in &[0u64, 0x10] {
                if sz == 0 {
                    for &(iname, bits) in f32_inputs {
                        let (lo, hi) = pack_s(bits);
                        let mut st = ArmState::zeroed();
                        st.fpsr = initial_fpsr;
                        st.fpcr = 0;
                        st.set_vreg(RN as usize, lo, hi);
                        batch.push((format!("{kname}_s_{iname}_fpsr{initial_fpsr:#x}"), insn, st));
                    }
                } else {
                    for &(iname, bits) in f64_inputs {
                        let (lo, hi) = pack_d(bits);
                        let mut st = ArmState::zeroed();
                        st.fpsr = initial_fpsr;
                        st.fpcr = 0;
                        st.set_vreg(RN as usize, lo, hi);
                        batch.push((format!("{kname}_d_{iname}_fpsr{initial_fpsr:#x}"), insn, st));
                    }
                }
            }
        }
    }
    run_fpsr_batch("simd_fp_to_int_fpsr_exceptions", batch);
}

// commit 21939b27dea3 temp: set simd complex fpsr
#[test]
fn diff_simd_complex_fpsr_exceptions() {
    // inf / zero bit patterns per element size (16/32/64).
    let inf = |esize: u32| -> u64 {
        match esize {
            16 => 0x7C00u64,
            32 => 0x7F80_0000u64,
            _ => 0x7FF0_0000_0000_0000u64,
        }
    };
    let neg_inf = |esize: u32| -> u64 {
        let s: u64 = 1u64 << (esize - 1);
        inf(esize) | s
    };

    let mut batch: Vec<(String, u32, ArmState)> = Vec::new();
    // (size, esize): 01=f16, 10=f32, 11=f64.
    for &(size, esize) in &[(0b01u32, 16u32), (0b10, 32), (0b11, 64)] {
        for q in 0..2u32 {
            if esize == 64 && q == 0 {
                continue; // a 64-bit complex pair needs the full 128 bits
            }
            for initial_fpsr in [0u64, 0x10] {
                // pack identical (re, im) values into every lane of the 128-bit reg.
                let pack = |re: u64, im: u64| -> (u64, u64) {
                    let mut lo: u128 = 0;
                    let mut hi: u128 = 0;
                    let datasize = if q == 1 { 128usize } else { 64 };
                    let lanes = datasize / esize as usize; // total real+imag slots
                    let mask: u128 = if esize == 64 {
                        u64::MAX as u128
                    } else {
                        ((1u128) << esize) - 1
                    };
                    for slot in 0..lanes {
                        let v = if slot % 2 == 0 { re } else { im } as u128 & mask;
                        let bitpos = slot * esize as usize;
                        if bitpos < 64 {
                            lo |= v << bitpos;
                        } else {
                            hi |= v << (bitpos - 64);
                        }
                    }
                    (lo as u64, hi as u64)
                };

                // FCADD (1-bit rotation). rot==0: re = a_re + (-b_im).
                // a_re = +inf, b_im = +inf  =>  +inf + (-inf) => IOC invalid.
                {
                    let insn = enc_fcadd(q, size, 0);
                    let mut st = ArmState::zeroed();
                    st.fpsr = initial_fpsr;
                    st.fpcr = 0;
                    let (n_lo, n_hi) = pack(inf(esize), neg_inf(esize)); // a_re=+inf, a_im=-inf
                    let (m_lo, m_hi) = pack(inf(esize), inf(esize)); // b_re=+inf, b_im=+inf
                    st.set_vreg(RN as usize, n_lo, n_hi);
                    st.set_vreg(RM as usize, m_lo, m_hi);
                    batch.push((
                        format!("fcadd_ioc_e{esize}_q{q}_fpsr{initial_fpsr:#x}"),
                        insn,
                        st,
                    ));
                }

                // FCMLA (2-bit rotation). rot==0: r_re = d_re + a_re * b_re.
                // a_re = 0, b_re = +inf  =>  0 * inf => IOC invalid on the FMA path.
                {
                    let insn = enc_fcmla(q, size, 0);
                    let mut st = ArmState::zeroed();
                    st.fpsr = initial_fpsr;
                    st.fpcr = 0;
                    let (n_lo, n_hi) = pack(0, 0); // a_re=0, a_im=0
                    let (m_lo, m_hi) = pack(inf(esize), inf(esize)); // b_re=+inf, b_im=+inf
                    st.set_vreg(RN as usize, n_lo, n_hi);
                    st.set_vreg(RM as usize, m_lo, m_hi);
                    // d (accumulator in Vd) = 0 by default.
                    batch.push((
                        format!("fcmla_ioc_e{esize}_q{q}_fpsr{initial_fpsr:#x}"),
                        insn,
                        st,
                    ));
                }
            }
        }
    }
    run_fpsr_batch("simd_complex_fpsr_exceptions", batch);
}

// commit e55c1634f025 temp: set simd indexed complex fpsr
#[test]
fn diff_simd_fcmla_indexed_fpsr_exceptions() {
    let mut batch: Vec<(String, u32, ArmState)> = Vec::new();

    // sNaN bit patterns: exponent all ones, mantissa MSB clear, low bit set.
    let snan16: u64 = 0x7D00; // f16 signaling NaN
    let snan32: u64 = 0x7FA0_0000; // f32 signaling NaN
    let fmax32: u64 = 0x7F7F_FFFF; // f32 FLT_MAX

    for &(size, esize, q) in &[(0b01u32, 16u32, 1u32), (0b10u32, 32u32, 1u32)] {
        let datasize = if q == 1 { 128 } else { 64 };
        let lanes = datasize / esize as usize;
        let max_index = if size == 0b10 { 2 } else { 4 };
        for rot in 0..4u32 {
            for index in 0..max_index {
                let insn = enc_fcmla_idx(q, size, rot, index);

                // --- IOC case: Vn (the multiplicand operand) is all sNaN. ---
                for initial_fpsr in [0u64, 0x10] {
                    let mut st = ArmState::zeroed();
                    st.fpcr = 0;
                    st.fpsr = initial_fpsr;
                    let snan = if esize == 16 { snan16 } else { snan32 };
                    // Pack `lanes` copies of snan into the 128-bit V register.
                    let mut lo = 0u64;
                    let mut hi = 0u64;
                    for l in 0..lanes {
                        let bit = l * esize as usize;
                        if bit < 64 {
                            lo |= snan << bit;
                        } else {
                            hi |= snan << (bit - 64);
                        }
                    }
                    st.set_vreg(RN as usize, lo, hi);
                    // Vm (indexed operand) and Vd (accumulator) finite/nonzero.
                    let one: u64 = if esize == 16 { 0x3C00 } else { 0x3F80_0000 };
                    let mut mlo = 0u64;
                    let mut mhi = 0u64;
                    for l in 0..lanes {
                        let bit = l * esize as usize;
                        if bit < 64 {
                            mlo |= one << bit;
                        } else {
                            mhi |= one << (bit - 64);
                        }
                    }
                    st.set_vreg(RM as usize, mlo, mhi);
                    st.set_vreg(RD as usize, mlo, mhi);
                    batch.push((
                        format!("fcmla_idx_snan_e{esize}_r{rot}_i{index}_fpsr{initial_fpsr:#x}"),
                        insn,
                        st,
                    ));
                }

                // --- OFC|IXC case (f32 only): FLT_MAX * 2 finite overflow. ---
                if esize == 32 {
                    let mut st = ArmState::zeroed();
                    st.fpcr = 0;
                    st.fpsr = 0;
                    let two: u64 = 0x4000_0000; // 2.0f32
                    let mut nlo = 0u64;
                    let mut nhi = 0u64;
                    let mut mlo = 0u64;
                    let mut mhi = 0u64;
                    for l in 0..lanes {
                        let bit = l * esize as usize;
                        if bit < 64 {
                            nlo |= fmax32 << bit;
                            mlo |= two << bit;
                        } else {
                            nhi |= fmax32 << (bit - 64);
                            mhi |= two << (bit - 64);
                        }
                    }
                    st.set_vreg(RN as usize, nlo, nhi);
                    st.set_vreg(RM as usize, mlo, mhi);
                    // Zero accumulator so result is the (overflowing) product.
                    st.set_vreg(RD as usize, 0, 0);
                    batch.push((format!("fcmla_idx_ovf_e{esize}_r{rot}_i{index}"), insn, st));
                }
            }
        }
    }

    run_fpsr_batch("simd_fcmla_indexed_fpsr_exceptions", batch);
}

// commit d0201befcbed temp: set simd indexed fp fpsr
#[test]
fn diff_simd_indexed_fp_fpsr_exceptions() {
    // (u, opcode, name): Advanced-SIMD vector-x-indexed-element FP ops.
    //   FMUL  (0,0b1001) -> fp_status_binop(Mul)
    //   FMULX (1,0b1001) -> fp_status_mulx
    //   FMLA  (0,0b0001) -> fp_status_fma
    //   FMLS  (0,0b0101) -> fp_status_fma (neg op1)
    // The fix routes the returned exception status into self.fpsr.
    let ops: &[(u32, u32, &str)] = &[
        (0, 0b1001, "fmul"),
        (1, 0b1001, "fmulx"),
        (0, 0b0001, "fmla"),
        (0, 0b0101, "fmls"),
    ];

    let mut batch: Vec<(String, u32, ArmState)> = Vec::new();

    for &(u, opcode, name) in ops {
        // size 0b10 = f32 (index 0..=3, Q either); size 0b11 = f64 (index 0..=1, Q=1 only)
        for &(size, qs, maxidx) in &[
            (0b10u32, &[0u32, 1][..], 4u32),
            (0b11u32, &[1u32][..], 2u32),
        ] {
            let f64op = size == 0b11;
            let lanes = if f64op { 2usize } else { 4usize };
            for &q in qs {
                for index in 0..maxidx {
                    let insn = enc_indexed(q, u, size, opcode, RM as u32, index);

                    for &initial_fpsr in &[0u64, 0x10] {
                        let mut st = ArmState::zeroed();
                        st.fpsr = initial_fpsr;
                        st.fpcr = 0;

                        // Choose inputs that trip a flag on the path the commit added:
                        //  - FMULX: sNaN operand => fp_status_mulx returns IOC.
                        //  - FMUL / FMLA / FMLS: huge * huge => inf result =>
                        //    fp_status_binop / fp_status_fma return OFC | IXC.
                        let (n_bits, m_bits, d_bits): (u64, u64, u64) = if name == "fmulx" {
                            if f64op {
                                // f64 signalling NaN in V[Rn].
                                (0x7FF0_0000_0000_0001u64, (2.0f64).to_bits(), 0u64)
                            } else {
                                // f32 signalling NaN in V[Rn].
                                (0x7F80_0001u64, (2.0f32).to_bits() as u64, 0u64)
                            }
                        } else if f64op {
                            // big * big overflows to +inf (FMLA/FMLS use addend 0).
                            ((1.0e308f64).to_bits(), (1.0e3f64).to_bits(), 0u64)
                        } else {
                            (
                                (3.0e38f32).to_bits() as u64,
                                (1.0e3f32).to_bits() as u64,
                                0u64,
                            )
                        };

                        // Broadcast the trigger value into every lane so whichever
                        // element index the encoding selects carries it.
                        let pack = |bits: u64| -> u128 {
                            let mut p: u128 = 0;
                            for l in 0..lanes {
                                let sh = if f64op { 64 * l } else { 32 * l };
                                p |= (bits as u128) << sh;
                            }
                            p
                        };
                        let np = pack(n_bits);
                        let mp = pack(m_bits);
                        let dp = pack(d_bits);
                        st.set_vreg(RN as usize, np as u64, (np >> 64) as u64);
                        st.set_vreg(RM as usize, mp as u64, (mp >> 64) as u64);
                        st.set_vreg(RD as usize, dp as u64, (dp >> 64) as u64);

                        batch.push((
                            format!("{name}_sz{size}_q{q}_idx{index}_fpsr{initial_fpsr:#x}"),
                            insn,
                            st,
                        ));
                    }
                }
            }
        }
    }

    run_fpsr_batch("simd_indexed_fp_fpsr_exceptions", batch);
}

// commit 733deaa5b2fa temp: set simd fp16 three-same fpsr
#[test]
fn diff_simd_fp16_three_same_fpsr() {
    // Splat one fp16 bit pattern across all 8 H lanes of a 128-bit reg
    // (4 per 64-bit word; for Q=0 only the low word's lanes are active).
    fn splat(h: u16) -> (u64, u64) {
        let mut w = 0u64;
        for e in 0..4 {
            w |= (h as u64) << (e * 16);
        }
        (w, w)
    }

    const INF: u16 = 0x7C00; // +inf
    const NINF: u16 = 0xFC00; // -inf
    const ONE: u16 = 0x3C00; // 1.0
    const TWO: u16 = 0x4000; // 2.0
    const ZERO: u16 = 0x0000; // +0.0
    const MAXN: u16 = 0x7BFF; // largest finite normal (~65504)
    const TINY: u16 = 0x0001; // smallest positive subnormal

    let mut batch: Vec<(String, u32, ArmState)> = Vec::new();

    // (label, u, a, opcode, n_lane, m_lane, acc_lane)
    // Bin paths read n=V[RN], m=V[RM] (acc unused).
    // Mla/Mls (opcode 0b001) accumulate into V[RD].
    let cases: &[(&str, u32, u32, u32, u16, u16, u16)] = &[
        // FADD (u=0,a=0,opc=010): inf + (-inf) -> IOC (invalid, opposite-sign inf sum)
        ("fadd_ioc", 0, 0, 0b010, INF, NINF, 0),
        // FADD: 1.0 + tiny subnormal -> IXC (inexact, rounds back to 1.0)
        ("fadd_ixc", 0, 0, 0b010, ONE, TINY, 0),
        // FSUB (u=0,a=1,opc=010): inf - inf -> IOC (same-sign inf difference)
        ("fsub_ioc", 0, 1, 0b010, INF, INF, 0),
        // FMULX (u=0,a=0,opc=011): max * max -> OFC|IXC via fp_status_mulx
        ("fmulx_ofc", 0, 0, 0b011, MAXN, MAXN, 0),
        // FRECPS (u=0,a=0,opc=111): exact = 2 - n*m = 2 - max*max -> OFC|IXC
        // via fp_status_recps_rsqrts (finite, non-zero, non-NaN operands).
        ("frecps_ofc", 0, 0, 0b111, MAXN, MAXN, 0),
        // FRSQRTS (u=0,a=1,opc=111): exact = (3 - n*m)/2 -> OFC|IXC
        ("frsqrts_ofc", 0, 1, 0b111, MAXN, MAXN, 0),
        // FMUL (u=1,a=0,opc=011): max * 2.0 -> OFC|IXC (overflow)
        ("fmul_ofc", 1, 0, 0b011, MAXN, TWO, 0),
        // FDIV (u=1,a=0,opc=111): 1.0 / 0.0 -> DZC (divide by zero)
        ("fdiv_dzc", 1, 0, 0b111, ONE, ZERO, 0),
        // FDIV: max / tiny -> OFC|IXC (overflow)
        ("fdiv_ofc", 1, 0, 0b111, MAXN, TINY, 0),
        // FABD (u=1,a=1,opc=010): |inf - inf| -> IOC
        ("fabd_ioc", 1, 1, 0b010, INF, INF, 0),
        // FMLA (u=0,a=0,opc=001): acc + n*m, 1.0 + max*max -> OFC|IXC via fp_status_fma
        ("fmla_ofc", 0, 0, 0b001, MAXN, MAXN, ONE),
        // FMLA: 0 * inf + finite -> IOC (invalid product) via fp_status_fma
        ("fmla_ioc", 0, 0, 0b001, INF, ZERO, ONE),
        // FMLS (u=0,a=1,opc=001): acc + (-n)*m, max*max magnitude -> OFC|IXC
        ("fmls_ofc", 0, 1, 0b001, MAXN, MAXN, ONE),
        // FMLS: 0 * inf -> IOC (invalid product)
        ("fmls_ioc", 0, 1, 0b001, INF, ZERO, ONE),
    ];

    for q in [0u32, 1] {
        for &(label, u, a, opcode, n, m, acc) in cases {
            let insn = enc_fp16_3s(q, u, a, opcode);
            for initial_fpsr in [0u64, 0x10] {
                let mut st = ArmState::zeroed();
                st.fpsr = initial_fpsr;
                st.fpcr = 0;
                let (nlo, nhi) = splat(n);
                let (mlo, mhi) = splat(m);
                let (alo, ahi) = splat(acc);
                st.set_vreg(RN as usize, nlo, nhi);
                st.set_vreg(RM as usize, mlo, mhi);
                st.set_vreg(RD as usize, alo, ahi);
                batch.push((format!("{label}_q{q}_fpsr{initial_fpsr:#x}"), insn, st));
            }
        }
    }

    run_fpsr_batch("simd_fp16_three_same_fpsr", batch);
}

// commit e134453b642b temp: set simd fp16 two-reg fpsr
#[test]
fn diff_simd_fp16_two_reg_fpsr() {
    // Replicate a 16-bit FP16 pattern across all 8 lanes of a 128-bit V reg.
    let rep = |p: u16| -> u64 { (p as u64) * 0x0001_0001_0001_0001u64 };

    // (u, a, opcode, fp16-input-bits, name) for the FP16 two-reg-misc table.
    // FP16 constants: -4.0=0xC400, 2.0=0x4000, +0.0=0x0000, -2.0=0xC000,
    // 2.5=0x4100, +inf=0x7C00 (out-of-range for FCVTZS).
    let cases: &[(u32, u32, u32, u16, &str)] = &[
        (1, 1, 0b11111, 0xC400, "fsqrt_neg_ioc"), // FSQRT(-4.0) -> IOC
        (1, 1, 0b11111, 0x4000, "fsqrt_irr_ixc"), // FSQRT(2.0) inexact -> IXC
        (0, 1, 0b11101, 0x0000, "frecpe_zero_dzc"), // FRECPE(+0.0) -> DZC
        (1, 1, 0b11101, 0xC000, "frsqrte_neg_ioc"), // FRSQRTE(-2.0) -> IOC
        (0, 1, 0b11011, 0x4100, "fcvtzs_frac_ixc"), // FCVTZS(2.5) -> IXC
        (0, 1, 0b11011, 0x7C00, "fcvtzs_inf_ioc"), // FCVTZS(+inf) -> IOC
        // SCVTF of an integer not representable in FP16's 11-bit mantissa:
        // 16385 (0x4001 as i16) rounds -> IXC.
        (0, 0, 0b11101, 0x4001, "scvtf_inexact_ixc"),
    ];

    let mut batch: Vec<(String, u32, ArmState)> = Vec::new();
    for &(u, a, opcode, bits, name) in cases {
        // Cover both 64-bit (q=0, 4 lanes) and 128-bit (q=1, 8 lanes) vectors.
        for q in 0..2u32 {
            let insn = enc_fp16_2r(q, u, a, opcode);
            for initial_fpsr in [0u64, 0x10] {
                let mut st = ArmState::zeroed();
                st.fpsr = initial_fpsr;
                st.fpcr = 0; // round-to-nearest, no FTZ, no alt handling.
                st.set_vreg(RN as usize, rep(bits), rep(bits));
                batch.push((format!("{name}_q{q}_fpsr{initial_fpsr:#x}"), insn, st));
            }
        }
    }
    run_fpsr_batch("simd_fp16_two_reg_fpsr", batch);
}

// commit c8b73c322aa0 temp: set special fp status flags
#[test]
fn diff_simd_three_same_fp_special_fpsr() {
    // enc_scalar_two_reg is added later in this branch; define it locally so the
    // test compiles at this commit.
    fn enc_scalar_two_reg(u: u32, size: u32, opcode: u32) -> u32 {
        (1 << 30)
            | (u << 29)
            | (0b11110 << 24)
            | (size << 22)
            | (0b10000 << 17)
            | (opcode << 12)
            | (0b10 << 10)
            | (RN << 5)
            | RD
    }
    let mut batch: Vec<(String, u32, ArmState)> = Vec::new();

    // sNaN / +0 / finite bit patterns per esize (ft: 0=f32, 1=f64).
    let snan = |ft: u32| -> u64 {
        match ft {
            0 => 0x7F80_0001u64,           // f32 sNaN
            _ => 0x7FF0_0000_0000_0001u64, // f64 sNaN
        }
    };
    let pzero = |_ft: u32| -> u64 { 0u64 };
    let two = |ft: u32| -> u64 {
        match ft {
            0 => (2.0f32).to_bits() as u64,
            _ => (2.0f64).to_bits(),
        }
    };

    // --- 1) FMULX with an sNaN operand => IOC (new fp_status_mulx path).
    // fp_status_mulx returns 0 for inf*0 (operands not finite), so an sNaN
    // input is the reliable IOC trigger. opcode 0b11011, U=0, a_bit=0 => size=ft.
    for &ft in &[0u32, 1] {
        let insn = enc_three_same(1, 0, ft, 0b11011); // Q=1, U=0, FMULX
        for initial_fpsr in [0u64, 0x10] {
            let mut st = ArmState::zeroed();
            st.fpsr = initial_fpsr;
            st.fpcr = 0;
            st.set_vreg(RN as usize, snan(ft), snan(ft));
            st.set_vreg(RM as usize, two(ft), two(ft));
            batch.push((
                format!("fmulx_t{ft}_snan_ioc_fpsr{initial_fpsr:#x}"),
                insn,
                st,
            ));
        }
    }

    // --- 2) FP compares with an sNaN operand => IOC (new CmEq/CmGe/CmGt/AcGe/AcGt branch).
    // (name, u, a_bit, opcode): FCMEQ(0,0,11100) FCMGE(1,0,11100) FCMGT(1,1,11100)
    //                           FACGE(1,0,11101) FACGT(1,1,11101)
    let cmp_variants: &[(&str, u32, u32, u32)] = &[
        ("fcmeq", 0, 0, 0b11100),
        ("fcmge", 1, 0, 0b11100),
        ("fcmgt", 1, 1, 0b11100),
        ("facge", 1, 0, 0b11101),
        ("facgt", 1, 1, 0b11101),
    ];
    for &(nm, u, a_bit, opcode) in cmp_variants {
        for &ft in &[0u32, 1] {
            let size = (a_bit << 1) | ft;
            let insn = enc_three_same(1, u, size, opcode); // Q=1 vector
            let mut st = ArmState::zeroed();
            st.fpsr = 0;
            st.fpcr = 0;
            st.set_vreg(RN as usize, snan(ft), snan(ft));
            st.set_vreg(RM as usize, two(ft), two(ft));
            batch.push((format!("{nm}_t{ft}_snan_ioc"), insn, st));
        }
    }

    // --- 3) FRECPS / FRSQRTS step => inexact/overflow (new recps_rsqrts path).
    // FRECPS(u=0,a_bit=0,11111)  FRSQRTS(u=0,a_bit=1,11111)
    //   f32: subnormal (tiny) op vs finite op => the new tiny-operand IXC branch.
    //   f64: huge*huge => step result overflows to +/-inf => OFC|IXC.
    let step_variants: &[(&str, u32, u32)] = &[("frecps", 0, 0b11111), ("frsqrts", 1, 0b11111)];
    for &(nm, a_bit, opcode) in step_variants {
        for &ft in &[0u32, 1] {
            let size = (a_bit << 1) | ft;
            let insn = enc_three_same(1, 0, size, opcode); // Q=1, U=0
            let (a_bits, b_bits) = match ft {
                // smallest f32 subnormal (tiny, non-zero) vs 1.0 (finite, non-zero)
                0 => (0x0000_0001u64, (1.0f32).to_bits() as u64),
                // 1e300 * 1e300 overflows the fused step to +/-inf in f64
                _ => ((1e300f64).to_bits(), (1e300f64).to_bits()),
            };
            let mut st = ArmState::zeroed();
            st.fpsr = 0;
            st.fpcr = 0;
            st.set_vreg(RN as usize, a_bits, a_bits);
            st.set_vreg(RM as usize, b_bits, b_bits);
            batch.push((format!("{nm}_t{ft}_step_status"), insn, st));
        }
    }

    // --- 4) FRECPE / FRSQRTE estimate => DZC on +0; IOC on negative FRSQRTE input
    //        (new fp_status_estimate path). two-reg: sz_hi=1 selects FP estimate.
    // FRECPE(u=0,opcode=11101)  FRSQRTE(u=1,opcode=11101)
    for &(nm, u) in &[("frecpe", 0u32), ("frsqrte", 1u32)] {
        for &ft in &[0u32, 1] {
            let size = (1 << 1) | ft; // sz_hi=1, sz=ft
            let insn = enc_two_reg(1, u, size, 0b11101); // Q=1 vector
            // 4a: +0 input => DZC (estimate of zero is +/-inf, divide-by-zero).
            let mut st0 = ArmState::zeroed();
            st0.fpsr = 0;
            st0.fpcr = 0;
            st0.set_vreg(RN as usize, pzero(ft), pzero(ft));
            batch.push((format!("{nm}_t{ft}_zero_dzc"), insn, st0));
            // 4b: negative finite input => IOC for FRSQRTE (sqrt of negative).
            let neg = match ft {
                0 => (-4.0f32).to_bits() as u64,
                _ => (-4.0f64).to_bits(),
            };
            let mut st1 = ArmState::zeroed();
            st1.fpsr = 0;
            st1.fpcr = 0;
            st1.set_vreg(RN as usize, neg, neg);
            batch.push((format!("{nm}_t{ft}_neg"), insn, st1));
        }
    }

    // --- 5) Scalar FRECPX with an sNaN input => IOC (new fp_is_snan_bits branch).
    // scalar two-reg: U=0, opcode=11111, sz_hi=1.
    for &ft in &[0u32, 1] {
        let size = (1 << 1) | ft;
        let insn = enc_scalar_two_reg(0, size, 0b11111); // FRECPX scalar
        let mut st = ArmState::zeroed();
        st.fpsr = 0;
        st.fpcr = 0;
        st.set_vreg(RN as usize, snan(ft), 0);
        batch.push((format!("frecpx_t{ft}_snan_ioc"), insn, st));
    }

    run_fpsr_batch("simd_three_same_fp_special_fpsr", batch);
}

// commit 0e946e078c05 temp: refine fp inexact status
#[test]
fn diff_fp_scalar_fpsr_fma_exact_zero() {
    // Targets the f64 exact-cancellation branch the commit added to
    // fp64_fma_exact (src/isa/arm/aarch64/cpu.rs): when an FMA's addend exactly
    // cancels op1*op2 so the result is +0.0, signed_mant_exp(result) was None,
    // so the pre-fix path `return false` and fp_status_fma reported a spurious
    // FPSR_IXC. The new `if fp64_is_zero(result)` branch recognises the exact
    // zero (lhs_a + lhs_p == 0) and returns true, matching the EL0 oracle which
    // raises no exception. Without the fix the interpreter's fpsr diverges.
    //
    // Scalar 3-source FP routes through fp_status_fma_with_fpcr(8, addend=aa,
    // op1=nn, op2=m, ...). enc_fp3(fp_type, o1, o0): op1=V[RN], op2=V[RM],
    // addend=V[RA]; (o1,o0)=(0,0)=FMADD, (0,1)=FMSUB. fpcr=0 (RNE, no FZ/AH).
    let mut batch: Vec<(String, u32, ArmState)> = Vec::new();

    // FMADD double: 2.0 * 3.0 + (-6.0) == +0.0 exactly.
    {
        let insn = enc_fp3(1, 0, 0); // FMADD double
        for initial_fpsr in [0, 0x10] {
            let mut st = ArmState::zeroed();
            st.fpsr = initial_fpsr;
            st.fpcr = 0;
            st.set_vreg(RN as usize, (2.0f64).to_bits(), 0); // op1
            st.set_vreg(RM as usize, (3.0f64).to_bits(), 0); // op2
            st.set_vreg(RA as usize, (-6.0f64).to_bits(), 0); // addend
            batch.push((
                format!("fmadd_d_exact_zero_fpsr{initial_fpsr:#x}"),
                insn,
                st,
            ));
        }
    }

    // FMADD double, larger magnitudes still exactly cancelling:
    // 1024.0 * 0.5 + (-512.0) == +0.0.
    {
        let insn = enc_fp3(1, 0, 0); // FMADD double
        let mut st = ArmState::zeroed();
        st.fpsr = 0;
        st.fpcr = 0;
        st.set_vreg(RN as usize, (1024.0f64).to_bits(), 0); // op1
        st.set_vreg(RM as usize, (0.5f64).to_bits(), 0); // op2
        st.set_vreg(RA as usize, (-512.0f64).to_bits(), 0); // addend
        batch.push(("fmadd_d_exact_zero_big".to_string(), insn, st));
    }

    // FMSUB double: addend - op1*op2 == +0.0 (r = a + (-n)*m). 6.0 - 2.0*3.0 == 0.
    // Exercises the same fp64_fma_exact zero branch via the negated-product form.
    {
        let insn = enc_fp3(1, 0, 1); // FMSUB double
        for initial_fpsr in [0, 0x10] {
            let mut st = ArmState::zeroed();
            st.fpsr = initial_fpsr;
            st.fpcr = 0;
            st.set_vreg(RN as usize, (2.0f64).to_bits(), 0); // op1 (negated internally)
            st.set_vreg(RM as usize, (3.0f64).to_bits(), 0); // op2
            st.set_vreg(RA as usize, (6.0f64).to_bits(), 0); // addend
            batch.push((
                format!("fmsub_d_exact_zero_fpsr{initial_fpsr:#x}"),
                insn,
                st,
            ));
        }
    }

    run_fpsr_batch("fp_scalar_fpsr_fma_exact_zero", batch);
}
